import type {
  AffordabilityCalculationSummary,
  EligibilitySummary,
  MaxPermissibleLoanSource,
  RequestedLoan,
  StressRate,
  Tenor,
  EffectiveTenorApplicant,
} from "@/types";
import { formatMoneyAmount } from "@/utils";

import { formatDbr, formatDbrWithCap, getEffectiveTenorSourceTag } from "../../../utils";

export type AffordabilitySummaryCardRow = {
  key: string;
  label: string;
  value: string;
  hint?: string;
  status?: "pass" | "fail";
  passLabel?: string;
  failLabel?: string;
  editableTenor?: Tenor;
  effectiveTenorApplicant?: EffectiveTenorApplicant;
  editableStressRate?: StressRate;
  editableRequestedAmount?: RequestedLoan;
  tag?: string;
};

const MAX_PERMISSIBLE_LOAN_SOURCE_LABELS: Record<MaxPermissibleLoanSource, string> = {
  CENTRAL_BANK: "Central bank",
  ANNUITY: "Annuity",
};

const AFFORDABILITY_FAIL_LABEL = "Above limit";

const buildBaseRows = (
  summary: EligibilitySummary,
  currency: string,
): AffordabilitySummaryCardRow[] => [
  {
    key: "total-earnings",
    label: "Total Income",
    value: formatMoneyAmount(summary.totalEarnings, currency),
  },
  {
    key: "total-liabilities",
    label: "Total liabilities",
    value: formatMoneyAmount(summary.totalLiabilities, currency),
  },
];

const buildRequestedAmountRows = (
  requestedAmount: number | null,
  currency: string,
  decision?: { status: "pass" | "fail"; passLabel: string; failLabel: string },
  editableRequestedAmount?: RequestedLoan,
): AffordabilitySummaryCardRow[] =>
  requestedAmount === null
    ? []
    : [
        {
          key: "requested-amount",
          label: "Requested amount",
          value: formatMoneyAmount(requestedAmount, currency),
          ...(editableRequestedAmount ? { editableRequestedAmount } : {}),
          ...(decision
            ? {
                status: decision.status,
                passLabel: decision.passLabel,
                failLabel: decision.failLabel,
              }
            : {}),
        },
      ];

const buildLegacyRows = ({
  summary,
  currency,
  requestedAmount,
}: {
  summary: EligibilitySummary;
  currency: string;
  requestedAmount: number | null;
}): AffordabilitySummaryCardRow[] => [
  ...buildBaseRows(summary, currency),
  {
    key: "dbr",
    label: "DBR",
    value: formatDbr(summary.dbr),
  },
  ...buildRequestedAmountRows(requestedAmount, currency),
];

const buildAffordabilityRows = ({
  summary,
  affordability,
  currency,
  requestedAmount,
}: {
  summary: EligibilitySummary;
  affordability: AffordabilityCalculationSummary;
  currency: string;
  requestedAmount: number | null;
}): AffordabilitySummaryCardRow[] => [
  ...buildBaseRows(summary, currency),
  ...buildRequestedAmountRows(
    requestedAmount,
    currency,
    {
      status: affordability.affordable ? "pass" : "fail",
      passLabel: "Affordable",
      failLabel: AFFORDABILITY_FAIL_LABEL,
    },
    affordability.requestedLoan,
  ),
  {
    key: "effective-tenor",
    label: "Effective tenor",
    value: "",
    editableTenor: affordability.tenor,
    ...(affordability.effectiveTenorApplicant
      ? { effectiveTenorApplicant: affordability.effectiveTenorApplicant }
      : {}),
    tag: getEffectiveTenorSourceTag(affordability.effectiveTenorBoundBy, affordability.tenor),
  },
  {
    key: "stress-rate",
    label: "Stress rate",
    value: "",
    editableStressRate: affordability.stressRate,
  },
  {
    key: "emi-capacity",
    label: "Max EMI possible",
    value: formatMoneyAmount(affordability.emiCapacity, currency),
  },
  ...(affordability.requestedLoanEmi != null
    ? [
        {
          key: "emi-requested-amount",
          label: "EMI (requested amount)",
          value: formatMoneyAmount(affordability.requestedLoanEmi, currency),
        },
      ]
    : []),
  {
    key: "dbr",
    label: affordability.newDbr != null ? "New DBR" : "DBR",
    value: formatDbrWithCap(affordability.newDbr ?? summary.dbr, affordability.maxDbrPercent),
    status: (affordability.newDbrWithinCap ?? affordability.dbrWithinCap) ? "pass" : "fail",
    passLabel: "Within cap",
    failLabel: AFFORDABILITY_FAIL_LABEL,
  },
  {
    key: "max-loan-annuity",
    label: "Max loan (annuity)",
    value: formatMoneyAmount(affordability.maxLoanAnnuity, currency),
  },
  {
    key: "central-bank-cap",
    label: "Central bank cap",
    value: formatMoneyAmount(affordability.centralBankCap, currency),
  },
  {
    key: "max-permissible-loan",
    label: "Max permissible loan",
    value: formatMoneyAmount(affordability.maxPermissibleLoan, currency),
    ...(affordability.maxPermissibleLoanSource
      ? { tag: MAX_PERMISSIBLE_LOAN_SOURCE_LABELS[affordability.maxPermissibleLoanSource] }
      : {}),
  },
];

export const buildAffordabilitySummaryRows = ({
  summary,
  currency,
  requestedAmount,
  showAffordabilityDecisions,
}: {
  summary: EligibilitySummary;
  currency: string;
  requestedAmount: number | null;
  showAffordabilityDecisions: boolean;
}): AffordabilitySummaryCardRow[] => {
  if (!showAffordabilityDecisions || summary.affordability == null) {
    return buildLegacyRows({ summary, currency, requestedAmount });
  }

  return buildAffordabilityRows({
    summary,
    affordability: summary.affordability,
    currency,
    requestedAmount,
  });
};
