import { TRANSACTION_TYPE_TO_LABEL } from "@/constants";
import type { BankApplication } from "@/types";

import { getMainApplicant } from "../utils/applicantUtils";
import { formatMainApplicantArchetypeForSubject } from "../utils/formatCustomerProfile";
import { formatPassportDisplayName } from "../utils/formatPassportDisplayName";

export const formatFabEmailSubject = (bankApplication: BankApplication): string => {
  const { bank, applicants, transactionType } = bankApplication;
  const mainApplicant = getMainApplicant(applicants);
  const mainName =
    formatPassportDisplayName(mainApplicant?.nameAsPerPassport) || (mainApplicant?.fullName ?? "");
  const transactionLabel =
    transactionType != null ? TRANSACTION_TYPE_TO_LABEL[transactionType] : "";

  return [
    "Huspy",
    bank.name,
    mainName,
    formatMainApplicantArchetypeForSubject(applicants),
    transactionLabel,
  ]
    .filter((part) => part !== "")
    .join(" - ");
};
