/** Square feet per square meter (1 m² = 10.7639 ft²) */
export const SQM_TO_SQFT = 10.7639;

export type NumberFormatOptions = {
  minimumFractionDigits?: number;
  maximumFractionDigits?: number;
};

/** Narrow display symbol for an ISO currency code (e.g. EUR → €, AED → AED). */
export function getCurrencyDisplaySymbol(currency: string | undefined): string | undefined {
  if (!currency) return undefined;
  try {
    return new Intl.NumberFormat("en", {
      style: "currency",
      currency,
      currencyDisplay: "narrowSymbol",
    })
      .formatToParts(0)
      .find((part) => part.type === "currency")?.value;
  } catch {
    return undefined;
  }
}

/** Locale-aware decimal number; "-" when there is no value. */
export function formatDecimal(
  value: number | undefined | null,
  locale?: string,
  options?: NumberFormatOptions,
): string {
  if (value === undefined || value === null || isNaN(value)) {
    return "-";
  }
  return new Intl.NumberFormat(locale, {
    style: "decimal",
    minimumFractionDigits: 1,
    maximumFractionDigits: 2,
    numberingSystem: "latn",
    ...options,
  }).format(value);
}

/**
 * Format an amount with an ISO currency code via Intl (e.g. EUR → "€200,000").
 * Defaults to whole currency units; pass fraction options when decimals are needed.
 */
export function formatCurrencyAmount(
  value: number | undefined | null,
  currency: string | undefined,
  locale = "en-US",
  options?: NumberFormatOptions,
): string {
  if (value === undefined || value === null || Number.isNaN(value)) return "-";

  const numberFormat: Intl.NumberFormatOptions = {
    maximumFractionDigits: 0,
    minimumFractionDigits: 0,
    numberingSystem: "latn",
    ...options,
  };

  if (!currency) {
    return new Intl.NumberFormat(locale, numberFormat).format(value);
  }

  try {
    return new Intl.NumberFormat(locale, {
      ...numberFormat,
      style: "currency",
      currency,
    }).format(value);
  } catch {
    return `${currency} ${new Intl.NumberFormat(locale, numberFormat).format(value)}`;
  }
}

const COMPACT_NUMBER_FORMAT: Intl.NumberFormatOptions = {
  notation: "compact",
  compactDisplay: "short",
  maximumFractionDigits: 2,
  minimumFractionDigits: 0,
  numberingSystem: "latn",
};

/** Compact number via Intl (e.g. 3500 → "3.5K", 1_500_000 → "1.5M"). */
export function formatCompact(
  value: number | undefined | null,
  locale = "en-US",
  options?: NumberFormatOptions,
): string {
  if (value === undefined || value === null || Number.isNaN(value)) return "-";
  return new Intl.NumberFormat(locale, { ...COMPACT_NUMBER_FORMAT, ...options }).format(value);
}

/**
 * Compact currency amount via Intl (e.g. EUR → "€1.46B", AED → "AED 4.25M").
 */
export function formatCurrencyAmountCompact(
  value: number | undefined | null,
  currency: string | undefined,
  locale = "en-US",
  options?: NumberFormatOptions,
): string {
  if (value === undefined || value === null || Number.isNaN(value)) return "-";

  if (!currency) {
    return formatCompact(value, locale, options);
  }

  try {
    return new Intl.NumberFormat(locale, {
      ...COMPACT_NUMBER_FORMAT,
      ...options,
      style: "currency",
      currency,
    }).format(value);
  } catch {
    return `${currency} ${formatCompact(value, locale, options)}`;
  }
}

/** Group/decimal separators the given locale uses for latin digits. */
function getNumberSeparators(locale?: string): { group: string; decimal: string } {
  const parts = new Intl.NumberFormat(locale, { numberingSystem: "latn" }).formatToParts(12345.6);
  return {
    group: parts.find((part) => part.type === "group")?.value ?? ",",
    decimal: parts.find((part) => part.type === "decimal")?.value ?? ".",
  };
}

/** Parse a number typed in the given locale's grouping/decimal format. */
export function parseLocaleNumber(value: string, locale?: string): number {
  if (!value || value.trim() === "") {
    return NaN;
  }

  const { group, decimal } = getNumberSeparators(locale);
  const cleaned = value.trim().split(group).join("").replace(decimal, ".");

  const parsed = parseFloat(cleaned);
  return isNaN(parsed) ? NaN : parsed;
}
