import * as direction from "@radix-ui/react-direction";
import * as dismissableLayer from "@radix-ui/react-dismissable-layer";
import * as focusGuards from "@radix-ui/react-focus-guards";
import * as focusScope from "@radix-ui/react-focus-scope";
import * as ariaHidden from "aria-hidden";
import * as removeScroll from "react-remove-scroll";

import { globalSingleton } from "./globalSingleton";

// Nothing imports this file directly — the huspy:radix-singletons plugin in
// vite.config.ts redirects these specifiers here. Radix keeps mutable module-level state
// in them (direction context, layer stack, focus stack, scroll lock), so duplicating
// them across entity bundles makes a provider in one bundle invisible to the next.
const dir = globalSingleton("singleton:@radix-ui/react-direction", () => direction);
const layer = globalSingleton(
  "singleton:@radix-ui/react-dismissable-layer",
  () => dismissableLayer,
);
const scope = globalSingleton("singleton:@radix-ui/react-focus-scope", () => focusScope);
const guards = globalSingleton("singleton:@radix-ui/react-focus-guards", () => focusGuards);
const scroll = globalSingleton("singleton:react-remove-scroll", () => removeScroll);
const hidden = globalSingleton("singleton:aria-hidden", () => ariaHidden);

export const DirectionProvider: typeof direction.DirectionProvider = dir.DirectionProvider;
export const useDirection: typeof direction.useDirection = dir.useDirection;

export const DismissableLayer = layer.DismissableLayer;
export const DismissableLayerBranch: typeof dismissableLayer.DismissableLayerBranch =
  layer.DismissableLayerBranch;
export const Branch: typeof dismissableLayer.Branch = layer.Branch;

export const FocusScope = scope.FocusScope;

export const FocusGuards = guards.FocusGuards;
export const useFocusGuards = guards.useFocusGuards;

export const RemoveScroll = scroll.RemoveScroll;

export const hideOthers = hidden.hideOthers;
export const inertOthers = hidden.inertOthers;
export const suppressOthers = hidden.suppressOthers;
export const supportsInert = hidden.supportsInert;

// `Root` is deliberately absent: all three Radix packages alias it to their own
// component, so a combined module cannot re-export it. Nothing imports it.
