import { KeyboardEvent, useRef, useState } from "react";

import { X } from "@huspy/shared-icons";
import { cn, Label, Popover, PopoverContent, RadioGroup, RadioGroupItem } from "@huspy/shared-ui";

import { FilterColumnTrigger } from "../FilterColumnTrigger";
import { FilterPopoverActions } from "../FilterPopoverActions";

type BankOption = {
  id: string;
  name: string;
};

type Props = {
  value: string;
  banks: BankOption[];
  onApply: (bankId: string) => void;
  onClear: () => void;
};

export function BankFilter({ value, banks, onApply, onClear }: Props) {
  const firstOptionRef = useRef<HTMLButtonElement>(null);
  const [open, setOpen] = useState(false);
  const [draft, setDraft] = useState(value);

  const handleOpenChange = (nextOpen: boolean) => {
    if (nextOpen) setDraft("");
    setOpen(nextOpen);
  };

  const handleApply = () => {
    onApply(draft);
    setOpen(false);
  };

  const handleClear = () => {
    onClear();
    setDraft("");
    setOpen(false);
  };

  const hasDraftChanged = draft !== "" && draft !== value;

  const handleKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    if (event.key === "Enter" && hasDraftChanged) {
      event.preventDefault();
      handleApply();
    }
  };

  const appliedBank = banks.find((bank) => bank.id === value);
  const selectableBanks = appliedBank ? banks.filter((bank) => bank.id !== value) : banks;
  return (
    <Popover open={open} onOpenChange={handleOpenChange}>
      <FilterColumnTrigger label="Bank" align="center" />

      <PopoverContent
        className="bg-popover w-64"
        side="bottom"
        align="center"
        onOpenAutoFocus={(event) => {
          if (!firstOptionRef.current) return;

          event.preventDefault();
          firstOptionRef.current.focus();
        }}
      >
        <div className="mb-3">
          {appliedBank && (
            <div className="flex items-center gap-2 rounded-md border border-border bg-muted px-2 py-1.5 mb-4">
              <span className="min-w-0 flex-1 text-sm font-semibold text-foreground">
                {appliedBank.name}
              </span>
              <button
                type="button"
                onClick={handleClear}
                className="text-muted-foreground hover:text-foreground shrink-0 cursor-pointer"
                aria-label="Clear bank filter"
              >
                <X className="size-3.5" />
              </button>
            </div>
          )}
          <RadioGroup
            value={draft}
            onValueChange={setDraft}
            onKeyDown={handleKeyDown}
            className="max-h-48 overflow-y-auto gap-0.5"
          >
            {selectableBanks.map((bank, index) => (
              <Label
                key={bank.id}
                htmlFor={`bank-filter-${bank.id}`}
                onFocus={(e) => {
                  e.currentTarget.scrollIntoView({ block: "nearest" });
                  setDraft(bank.id);
                }}
                className={cn(
                  "relative flex cursor-pointer items-center rounded-md px-2 py-2 text-sm font-normal",
                  "hover:bg-muted",
                  "has-data-[state=checked]:bg-primary/10 has-data-[state=checked]:hover:bg-primary/10",
                  "has-focus-visible:bg-primary/10 has-focus-visible:hover:bg-primary/10",
                )}
              >
                <RadioGroupItem
                  ref={index === 0 ? firstOptionRef : undefined}
                  value={bank.id}
                  id={`bank-filter-${bank.id}`}
                  className="sr-only"
                />
                {bank.name}
              </Label>
            ))}
          </RadioGroup>
        </div>

        <FilterPopoverActions
          onClear={handleClear}
          onApply={handleApply}
          canApply={hasDraftChanged}
        />
      </PopoverContent>
    </Popover>
  );
}
