import { useState, type FC, type SubmitEvent } from "react";

import { FloatingLabelInput, FloatingLabelSelect } from "@huspy/shared-agents";
import { cn, Tooltip, TooltipContent, TooltipTrigger } from "@huspy/shared-ui";
import { Scissors } from "@huspy/shared-icons";

import { Modal, ModalFooter, PillButton } from "@/components";
import { useDocument, useDocumentTypeCodesForBankApplication, useUpdateDocument } from "@/api";
import type { Applicant, FileItemWithDocumentId } from "@/types";

import { isPdfContentType } from "@/routes/BankApplication/components/ChecklistWorkspace/components/DocumentPreviewModal/utils";
import { getDocumentActionAvailability } from "@/routes/BankApplication/components/ChecklistWorkspace/utils/getDocumentActionAvailability";
import {
  resolveApplicantIdForDocumentLink,
  resolveDocumentApplicantIdPayload,
} from "@/routes/BankApplication/components/ChecklistWorkspace/utils";
import {
  getAssignToSelectOptions,
  getDocumentTypeSelectOptions,
  isApplicantLevelDocumentType,
  shouldShowAssignToSelect,
} from "@/routes/BankApplication/utils";

type Props = {
  isOpen: boolean;
  onOpenChange: (open: boolean) => void;
  bankApplicationId: string;
  applicants: Applicant[];
  file: FileItemWithDocumentId | null;
  initialDocumentType: string;
  initialAssignTo?: string;
  className?: string;
  /** Open the manual split flow for this file. */
  onBeginSplit?: () => void;
};

export const EditDocumentModal: FC<Props> = ({
  isOpen,
  onOpenChange,
  bankApplicationId,
  applicants,
  file,
  initialDocumentType,
  initialAssignTo,
  className,
  onBeginSplit,
}) => {
  const { data: documentTypeCodes = [] } =
    useDocumentTypeCodesForBankApplication(bankApplicationId);
  const { data: document } = useDocument(isOpen && file ? file.docServiceDocumentId : undefined);
  const updateDocument = useUpdateDocument();
  const soleApplicantId = applicants.length === 1 ? applicants[0]?.id : undefined;
  const [selectedDocumentType, setSelectedDocumentType] = useState(initialDocumentType);
  const [selectedApplicantId, setSelectedApplicantId] = useState(
    initialAssignTo ?? soleApplicantId ?? "",
  );
  const [fileName, setFileName] = useState(file?.fileName ?? "");
  const [submitError, setSubmitError] = useState<string | null>(null);
  const initialFileName = file?.fileName ?? "";

  const trimmedFileName = fileName.trim();
  const isDocumentTypeChanged = selectedDocumentType !== initialDocumentType;
  const showAssignTo = shouldShowAssignToSelect(
    selectedDocumentType,
    documentTypeCodes,
    applicants.length,
  );
  const isAssignToChanged = showAssignTo && selectedApplicantId !== initialAssignTo;
  const isFileNameChanged = trimmedFileName !== initialFileName;

  const handleOpenChange = (open: boolean) => {
    if (!open) {
      setSubmitError(null);
      updateDocument.reset();
    }
    onOpenChange(open);
  };

  const isDocumentTypeChangedToValidValue = isDocumentTypeChanged && selectedDocumentType !== "";
  const isChangingToCaseLevelDocumentType =
    isDocumentTypeChangedToValidValue &&
    !isApplicantLevelDocumentType(selectedDocumentType, documentTypeCodes);
  const isFileNameChangedToValidValue = isFileNameChanged && trimmedFileName.length > 0;
  const isFileNameEmpty = isFileNameChanged && trimmedFileName.length === 0;
  const needsApplicant = isApplicantLevelDocumentType(selectedDocumentType, documentTypeCodes);
  const resolvedApplicantId = resolveApplicantIdForDocumentLink(
    applicants,
    selectedApplicantId,
    selectedDocumentType,
    documentTypeCodes,
  );
  const isAssignToValid = !needsApplicant || !!resolvedApplicantId;

  const canSubmit =
    !!file &&
    isAssignToValid &&
    selectedDocumentType &&
    (isDocumentTypeChangedToValidValue || isFileNameChangedToValidValue || isAssignToChanged) &&
    !updateDocument.isPending;

  const handleSubmit = (e: SubmitEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!canSubmit || !file) return;

    setSubmitError(null);

    updateDocument.mutate(
      {
        documentId: file.id,
        bankApplicationId,
        payload: {
          ...(isDocumentTypeChangedToValidValue ? { type: selectedDocumentType } : {}),
          ...(isFileNameChangedToValidValue ? { fileName: trimmedFileName } : {}),
          ...resolveDocumentApplicantIdPayload({
            applicants,
            selectedApplicantId,
            selectedDocumentType,
            documentTypeCodes,
            includeApplicantId:
              isChangingToCaseLevelDocumentType || resolvedApplicantId !== undefined,
          }),
        },
      },
      {
        onSuccess: () => handleOpenChange(false),
        onError: (err) => {
          setSubmitError(err instanceof Error ? err.message : "Could not update document.");
        },
      },
    );
  };

  const canSplit = isPdfContentType(document?.contentType);

  const documentTypeOptions = getDocumentTypeSelectOptions(documentTypeCodes);
  const assignToOptions = getAssignToSelectOptions(applicants);

  const documentTypeAvailability = getDocumentActionAvailability(
    "editDocumentType",
    file?.processingStatus,
  );
  const isDocumentTypeFieldDisabled = updateDocument.isPending || documentTypeAvailability.disabled;

  return (
    <Modal
      isOpen={isOpen}
      onOpenChange={handleOpenChange}
      className={cn("sm:max-w-130!", className)}
      title="Edit document"
      description="Reclassify, reassign or rename"
    >
      <form className="flex min-h-0 flex-1 flex-col" onSubmit={handleSubmit}>
        <div className="min-h-0 flex-1 space-y-4 overflow-y-auto px-6 py-5">
          <div className="grid grid-cols-1 gap-3">
            {documentTypeAvailability.disabled ? (
              <Tooltip>
                <TooltipTrigger asChild>
                  <span className="inline-flex w-full">
                    <FloatingLabelSelect
                      label="Document type"
                      placeholder="Select document type"
                      value={selectedDocumentType}
                      disabled
                      onValueChange={() => {}}
                      options={documentTypeOptions}
                    />
                  </span>
                </TooltipTrigger>
                <TooltipContent>{documentTypeAvailability.tooltip}</TooltipContent>
              </Tooltip>
            ) : (
              <FloatingLabelSelect
                label="Document type"
                placeholder="Select document type"
                value={selectedDocumentType}
                disabled={isDocumentTypeFieldDisabled}
                onValueChange={(value) => {
                  setSelectedDocumentType(value);
                  if (!isApplicantLevelDocumentType(value, documentTypeCodes)) {
                    setSelectedApplicantId("");
                  } else if (soleApplicantId) {
                    setSelectedApplicantId(soleApplicantId);
                  }
                  setSubmitError(null);
                }}
                options={documentTypeOptions}
              />
            )}
            {showAssignTo && (
              <FloatingLabelSelect
                label="Assign to"
                placeholder="Select applicant"
                value={selectedApplicantId}
                disabled={updateDocument.isPending}
                onValueChange={(value) => {
                  setSelectedApplicantId(value);
                  setSubmitError(null);
                }}
                options={assignToOptions}
              />
            )}
            <FloatingLabelInput
              label="File name"
              className="h-14"
              value={fileName}
              disabled={updateDocument.isPending}
              error={isFileNameEmpty}
              errorMessage={isFileNameEmpty ? "File name is required" : undefined}
              onChange={(e) => {
                setFileName(e.target.value);
                setSubmitError(null);
              }}
            />
          </div>

          {submitError && (
            <p role="alert" className="text-sm text-destructive">
              {submitError}
            </p>
          )}
        </div>

        <ModalFooter className="justify-between">
          <div className="mr-auto">
            {onBeginSplit && file && canSplit && (
              <PillButton
                type="button"
                buttonRole="secondary"
                disabled={updateDocument.isPending}
                onClick={onBeginSplit}
              >
                <Scissors className="size-4" aria-hidden />
                Split pages
              </PillButton>
            )}
          </div>
          <div className="flex items-center gap-2">
            <PillButton
              type="button"
              buttonRole="secondary"
              disabled={updateDocument.isPending}
              onClick={() => handleOpenChange(false)}
            >
              Cancel
            </PillButton>
            <PillButton type="submit" disabled={!canSubmit}>
              Save
            </PillButton>
          </div>
        </ModalFooter>
      </form>
    </Modal>
  );
};
