/**
 * Fuzzy person-name matching, modeled on underwriting-service `PersonNameMatcher`, `NameMatcher`
 * and `TextNormalizer.personName`, so the FE and BE agree on what counts as the same person.
 */

/** Minimum similarity for two names to be treated as the same person. Tune on real ADIB forms. */
export const PERSON_NAME_MATCH_THRESHOLD = 0.85;

/** Honorifics and name particles that vary freely between documents for the same person. */
const DROPPED_NAME_TOKENS = new Set([
  "MR",
  "MRS",
  "MS",
  "MISS",
  "DR",
  "PROF",
  "ENG",
  "HE",
  "AL",
  "EL",
  "BIN",
  "BEN",
  "IBN",
  "BINT",
  "BINTE",
  "ABU",
  "ABD",
]);

const JARO_WINKLER_BOOST_THRESHOLD = 0.7;
const JARO_WINKLER_MAX_PREFIX = 4;
const JARO_WINKLER_SCALING_FACTOR = 0.1;

const normalizeBasic = (name: string): string =>
  name
    .normalize("NFD")
    .replace(/[\u0300-\u036f]+/g, "")
    .toUpperCase()
    .replace(/[^A-Z0-9 ]/g, " ")
    .replace(/\s+/g, " ")
    .trim();

/** Uppercases, strips diacritics and punctuation, and drops honorifics and particles. */
export const normalizePersonName = (name: string): string => {
  const basic = normalizeBasic(name);
  const kept = basic.split(" ").filter((token) => token && !DROPPED_NAME_TOKENS.has(token));
  return kept.length > 0 ? kept.join(" ") : basic;
};

const jaro = (left: string, right: string): number => {
  if (left === right) return 1;
  if (!left || !right) return 0;

  const matchDistance = Math.max(0, Math.floor(Math.max(left.length, right.length) / 2) - 1);
  const leftMatched: boolean[] = new Array<boolean>(left.length).fill(false);
  const rightMatched: boolean[] = new Array<boolean>(right.length).fill(false);

  let matches = 0;
  for (let i = 0; i < left.length; i += 1) {
    const start = Math.max(0, i - matchDistance);
    const end = Math.min(right.length - 1, i + matchDistance);
    for (let j = start; j <= end; j += 1) {
      if (!rightMatched[j] && left[i] === right[j]) {
        leftMatched[i] = true;
        rightMatched[j] = true;
        matches += 1;
        break;
      }
    }
  }
  if (matches === 0) return 0;

  let transpositions = 0;
  let rightIndex = 0;
  for (let i = 0; i < left.length; i += 1) {
    if (!leftMatched[i]) continue;
    while (!rightMatched[rightIndex]) rightIndex += 1;
    if (left[i] !== right[rightIndex]) transpositions += 1;
    rightIndex += 1;
  }

  return (
    (matches / left.length + matches / right.length + (matches - transpositions / 2) / matches) / 3
  );
};

/** Jaro-Winkler rewards a shared prefix, which is how Arabic name transliterations usually vary. */
const jaroWinkler = (left: string, right: string): number => {
  const jaroScore = jaro(left, right);
  if (jaroScore < JARO_WINKLER_BOOST_THRESHOLD) return jaroScore;

  let prefix = 0;
  const maxPrefix = Math.min(JARO_WINKLER_MAX_PREFIX, left.length, right.length);
  while (prefix < maxPrefix && left[prefix] === right[prefix]) prefix += 1;

  const scaling = Math.min(JARO_WINKLER_SCALING_FACTOR, 1 / Math.max(left.length, right.length));
  return jaroScore + scaling * prefix * (1 - jaroScore);
};

/**
 * Similarity of two whole person names, scored as the weakest aligned token pair. Tokens left over on
 * the longer name are ignored, so a shortened name still matches the long one, while two people who
 * share only a surname do not.
 */
export const personNameSimilarity = (left: string, right: string): number => {
  const leftTokens = normalizePersonName(left).split(" ").filter(Boolean);
  const rightTokens = normalizePersonName(right).split(" ").filter(Boolean);
  if (leftTokens.length === 0 || rightTokens.length === 0) return 0;

  const [shorter, longer] =
    leftTokens.length <= rightTokens.length ? [leftTokens, rightTokens] : [rightTokens, leftTokens];
  const unclaimed = [...longer];

  const scores = shorter.map((token) => {
    let bestIndex = 0;
    let best = jaroWinkler(token, unclaimed[0]);
    for (let index = 1; index < unclaimed.length; index += 1) {
      const score = jaroWinkler(token, unclaimed[index]);
      if (score > best) {
        best = score;
        bestIndex = index;
      }
    }
    unclaimed.splice(bestIndex, 1);
    return best;
  });

  return Math.min(...scores);
};
