import { ProcessingStatus } from "@/types";

import { PROCESSING_FAILURE_MESSAGES } from "@/routes/BankApplication/components/ChecklistWorkspace/constants";
import { getProcessingInProgressMessage } from "@/routes/BankApplication/components/ChecklistWorkspace/utils/getProcessingInProgressMessage";
import { isProcessingInProgress } from "@/utils";

const NEEDS_ATTENTION_PILL_FAILURE_STATUSES: ProcessingStatus[] = [
  "SPLIT_FAILED",
  "ROTATION_FAILED",
];

export const getNeedsAttentionPillFailureMessage = (
  processingStatus: ProcessingStatus | null | undefined,
): string | null => {
  if (!processingStatus || !NEEDS_ATTENTION_PILL_FAILURE_STATUSES.includes(processingStatus)) {
    return null;
  }

  return PROCESSING_FAILURE_MESSAGES[processingStatus] ?? null;
};

export const getNeedsAttentionIconTooltipText = (
  processingStatus: ProcessingStatus | null | undefined,
): string | null => {
  if (isProcessingInProgress(processingStatus)) {
    return getProcessingInProgressMessage(processingStatus);
  }

  // if ready or failure
  return "Could not determine the document type.";
};
