import { useMemo, useState } from "react";

import { cn } from "@huspy/shared-ui";

import { useBanks } from "@/api";
import { MortgageApplicationRow as MortgageApplicationRowT, PaginationMetadata } from "@/types";
import { useOpsQueueFilters } from "@/routes/OpsQueue/hooks";

import { ActiveFilterBar } from "./ActiveFilterBar";
import { MortgageApplicationRow } from "./MortgageApplication";
import { QueueHeaderStrip } from "./QueueHeaderStrip";
import { TableFooter } from "./TableFooter";

type Props = {
  mortgageApplicationRows: MortgageApplicationRowT[];
  metadata: PaginationMetadata;
  page: number;
  onPageChange: (page: number) => void;
  isRefreshing?: boolean;
};

export function MortgageApplicationsTable({
  mortgageApplicationRows,
  metadata,
  page,
  onPageChange,
  isRefreshing = false,
}: Props) {
  const { data: banksData } = useBanks();
  const [collapsedCaseIds, setCollapsedCaseIds] = useState<Record<string, boolean>>({});
  const {
    applicantName,
    selectedBankId,
    createdById,
    createdAtFrom,
    createdAtTo,
    hasActiveFilters,
    setApplicantNameFilter,
    clearApplicantNameFilter,
    setBankFilter,
    clearBankFilter,
    setCreatedAtFilter,
    clearCreatedAtFilter,
    setCreatedByFilter,
    clearCreatedByFilter,
    clearAllFilters,
  } = useOpsQueueFilters();

  const banks = useMemo(() => {
    return [...(banksData?.data ?? [])].sort((a, b) => a.name.localeCompare(b.name));
  }, [banksData]);

  const toggleCase = (mortgageApplicationId: string) =>
    setCollapsedCaseIds((prev) => ({
      ...prev,
      [mortgageApplicationId]: !prev[mortgageApplicationId],
    }));

  const emptyState = hasActiveFilters
    ? {
        title: "No applications found",
        description: "Try adjusting or clearing your filters",
      }
    : {
        title: "No applications yet",
        description: "Submitted applications will appear here",
      };

  return (
    <div
      className={cn(
        "rounded-2xl border border-solid border-border bg-card transition-opacity duration-200",
        isRefreshing && "pointer-events-none opacity-50",
      )}
      aria-busy={isRefreshing}
    >
      <QueueHeaderStrip
        banks={banks}
        applicantName={applicantName}
        selectedBankId={selectedBankId}
        createdById={createdById}
        createdAtFrom={createdAtFrom}
        createdAtTo={createdAtTo}
        onApplyApplicantName={setApplicantNameFilter}
        onClearApplicantName={clearApplicantNameFilter}
        onApplyBank={setBankFilter}
        onClearBank={clearBankFilter}
        onApplyCreatedAt={setCreatedAtFilter}
        onClearCreatedAt={clearCreatedAtFilter}
        onApplyCreatedBy={setCreatedByFilter}
        onClearCreatedBy={clearCreatedByFilter}
      />

      <ActiveFilterBar
        banks={banks}
        applicantName={applicantName}
        selectedBankId={selectedBankId}
        createdById={createdById}
        createdAtFrom={createdAtFrom}
        createdAtTo={createdAtTo}
        onClearApplicantName={clearApplicantNameFilter}
        onClearBank={clearBankFilter}
        onClearCreatedAt={clearCreatedAtFilter}
        onClearCreatedBy={clearCreatedByFilter}
        onClearAll={clearAllFilters}
      />

      {mortgageApplicationRows.map((mortgageApplication) => (
        <MortgageApplicationRow
          key={mortgageApplication.id}
          data={mortgageApplication}
          isExpanded={!collapsedCaseIds[mortgageApplication.id]}
          onToggle={() => toggleCase(mortgageApplication.id)}
        />
      ))}

      {mortgageApplicationRows.length === 0 && (
        <div className="border-b border-border py-14 text-center">
          <p className="text-sm font-semibold text-foreground">{emptyState.title}</p>
          <p className="mt-1 text-[13px] text-muted-foreground">{emptyState.description}</p>
        </div>
      )}

      <TableFooter
        page={page}
        pageCount={metadata.totalPages}
        totalCount={metadata.totalCount}
        pageSize={metadata.pageSize}
        disabled={isRefreshing}
        onPageChange={onPageChange}
      />
    </div>
  );
}
