import { Fragment, type FC } from "react";

import type { ExtractedFieldGroup } from "@/types";

import { buildGroupSections } from "../utils/buildGroupSections";

import { FlatGroupSection } from "./FlatGroupSection";
import { NestedGroupSection } from "./NestedGroupSection";

type Props = {
  groups: ExtractedFieldGroup[];
};

export const GroupFieldsSection: FC<Props> = ({ groups }) => {
  if (groups.length === 0) return null;

  return (
    <div className="space-y-6">
      {buildGroupSections(groups).map((section) => (
        <Fragment key={section.group.name}>
          {section.kind === "flat" && <FlatGroupSection group={section.group} />}
          {section.kind === "nested" && <NestedGroupSection section={section} />}
        </Fragment>
      ))}
    </div>
  );
};
