import type { FC } from "react";

import { cn } from "@huspy/shared-ui";

import type { RuleCheckSummary } from "./types";

type Props = {
  summary: RuleCheckSummary;
};

/** Unresolved-failure count pill for a checks tab; renders nothing when everything is clear. */
export const CheckTabBadge: FC<Props> = ({ summary }) => {
  const { blocking, advisory } = summary;
  const count = blocking || advisory;

  if (count === 0) return null;

  return (
    <span
      className={cn(
        "rounded-full px-1.5 text-[10px] font-semibold tabular-nums",
        blocking > 0 ? "bg-destructive/14 text-destructive" : "bg-warning/14 text-warning",
      )}
    >
      {count}
    </span>
  );
};
