import { useCallback } from "react";

import { useQueryClient } from "@tanstack/react-query";

import { BANK_APPLICATION_TAB_QUERY_KEYS, type BankApplicationTab } from "./constants";
import { useBankApplicationTab } from "./useBankApplicationTab";

/** Active tab state plus a change handler that refetches the tab's query immediately. */
export const useBankApplicationTabChange = (
  bankApplicationId: string | undefined,
): readonly [BankApplicationTab, (tab: BankApplicationTab) => void] => {
  const queryClient = useQueryClient();
  const [activeTab, setActiveTab] = useBankApplicationTab();

  const changeTab = useCallback(
    (tab: BankApplicationTab) => {
      setActiveTab(tab);

      if (bankApplicationId) {
        void queryClient.refetchQueries({
          queryKey: [BANK_APPLICATION_TAB_QUERY_KEYS[tab], bankApplicationId],
        });
      }
    },
    [bankApplicationId, queryClient, setActiveTab],
  );

  return [activeTab, changeTab];
};
