import type { ProcessingStatus } from "@/types";
import type { DocumentPreviewTarget } from "@/routes/BankApplication/components/ChecklistWorkspace/context/DocumentPreviewContext";

type PreviewableFile = {
  documentId: string;
  docServiceDocumentId: string;
  fileName: string;
  processingStatus: ProcessingStatus;
};

export const toDocumentPreviewTarget = (file: PreviewableFile): DocumentPreviewTarget => ({
  documentId: file.documentId,
  docServiceDocumentId: file.docServiceDocumentId,
  underwritingServiceFileName: file.fileName,
  processingStatus: file.processingStatus,
});
