import type { FC, KeyboardEvent } from "react";
import { Thumbnail } from "react-pdf";

import { cn } from "@huspy/shared-ui";

const THUMBNAIL_WIDTH = 148;

type Props = {
  page: number;
  isFocused: boolean;
  pageRotate?: number;
  onFocus: (page: number) => void;
};

export const DocumentPreviewThumbnail: FC<Props> = ({ page, isFocused, pageRotate, onFocus }) => {
  const handleKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      onFocus(page);
    }
  };

  return (
    <div
      role="button"
      tabIndex={0}
      onClick={() => onFocus(page)}
      onKeyDown={handleKeyDown}
      className={cn(
        "flex w-fit cursor-pointer flex-col items-center gap-1.5 rounded-md p-2 text-center",
        isFocused ? "bg-primary/10" : "hover:bg-muted/60",
      )}
    >
      <span
        className={cn(
          "pointer-events-none flex w-fit items-center justify-center overflow-hidden rounded border bg-white",
          isFocused ? "border-primary" : "border-border",
        )}
      >
        <Thumbnail
          pageNumber={page}
          width={THUMBNAIL_WIDTH}
          rotate={pageRotate}
          loading={null}
          className="flex w-full items-center justify-center no-underline"
        />
      </span>
      <span
        className={cn(
          "text-xs",
          isFocused ? "font-medium text-foreground" : "text-muted-foreground",
        )}
      >
        {page}
      </span>
    </div>
  );
};
