import { FC, useState } from "react";

import type { ApplicantDocumentGroup } from "@/types";

import { DocumentRow } from "../../DocumentRow";
import { TableHeader } from "../../TableHeader";
import { DocumentParentRow } from "./DocumentParentRow";
import { useChecklistFileReorder } from "./hooks/useChecklistFileReorder";
import { getDocumentGroupKey, getReorderGroupKey, getUniqueKeys } from "./utils";

type Props = {
  documentGroups: ApplicantDocumentGroup[];
  scope: string;
};

export const ApplicantDocumentTable: FC<Props> = ({ documentGroups, scope }) => {
  const { getReorderableRow } = useChecklistFileReorder(documentGroups);
  const [collapsedGroupKeys, setCollapsedGroupKeys] = useState<Record<string, boolean>>({});

  const toggleGroup = (groupKey: string) =>
    setCollapsedGroupKeys((prev) => ({ ...prev, [groupKey]: !prev[groupKey] }));

  const groupKeys = getUniqueKeys(documentGroups, (group) => getDocumentGroupKey(scope, group));

  return (
    <div>
      <TableHeader />

      <div className="space-y-0.5" role="list">
        {documentGroups.map((documentGroup, groupIndex) => {
          const hasChildren = documentGroup.documents.length > 0;
          const groupKey = groupKeys[groupIndex];
          const isExpanded = !collapsedGroupKeys[groupKey];
          const childKeys = getUniqueKeys(
            documentGroup.documents,
            (child) => `${documentGroup.type}-${child.type}-${child.matchedFile?.id ?? "missing"}`,
          );

          if (!hasChildren) {
            return <DocumentRow key={groupKey} data={documentGroup} variant="standalone" />;
          }

          return (
            <div key={groupKey} className="space-y-0.5">
              <DocumentParentRow
                matchedFile={documentGroup.matchedFile}
                processingStatus={documentGroup.processingStatus}
                documentType={documentGroup.type}
                isExpanded={isExpanded}
                onToggle={() => toggleGroup(groupKey)}
              />

              {isExpanded &&
                documentGroup.documents.map((child, childIndex) => {
                  const reorderGroupKey = getReorderGroupKey(documentGroup.type, child);
                  const fileId = child.matchedFile?.id;

                  return (
                    <DocumentRow
                      key={childKeys[childIndex]}
                      data={child}
                      variant="mergeChild"
                      reorderable={getReorderableRow(reorderGroupKey, fileId)}
                    />
                  );
                })}
            </div>
          );
        })}
      </div>
    </div>
  );
};
