import { useCallback, useMemo, useState } from "react";

import type { BankApplication, EligibilityChecks } from "@/types";
import { bankApplicationSessionStorageKeys } from "@/routes/BankApplication/utils";

import { readEmailTemplateDraft, writeEmailTemplateDraft } from "../utils";
import { generateEmailDraft } from "../generateEmailDraft";
import {
  EMPTY_EMAIL_TEMPLATE_DRAFT,
  type AdibApplicantContact,
  type EmailTemplateDraft,
  type EmailTemplateDraftStatus,
} from "../types";

type Params = {
  bankApplicationId: string | undefined;
  bankApplication: BankApplication | undefined;
  eligibilityChecks: EligibilityChecks | undefined;
  adibApplicantContact?: AdibApplicantContact;
  isReadyForEmailGeneration: boolean;
};

type DraftState = {
  storageKey: string | null;
  draft: EmailTemplateDraft;
  generated: EmailTemplateDraft | null;
};

const resolveStatus = (
  bankApplicationId: string | undefined,
  isReadyForEmailGeneration: boolean,
): EmailTemplateDraftStatus => {
  if (!bankApplicationId) return "idle";
  if (!isReadyForEmailGeneration) return "loading";
  return "filled";
};

const isSameDraft = (a: EmailTemplateDraft, b: EmailTemplateDraft): boolean =>
  a.subject === b.subject && a.body === b.body;

const createDraftStateForStorageKey = (storageKey: string | null): DraftState => {
  if (!storageKey) {
    return { storageKey: null, draft: EMPTY_EMAIL_TEMPLATE_DRAFT, generated: null };
  }

  const stored = readEmailTemplateDraft(storageKey);
  if (stored) {
    const draft = { subject: stored.subject, body: stored.body };
    // Entries saved before `generated` was tracked are treated as clean.
    return { storageKey, draft, generated: stored.generated ?? draft };
  }

  return { storageKey, draft: EMPTY_EMAIL_TEMPLATE_DRAFT, generated: null };
};

const persistState = (
  storageKey: string,
  draft: EmailTemplateDraft,
  generated: EmailTemplateDraft | null,
) => writeEmailTemplateDraft(storageKey, generated ? { ...draft, generated } : draft);

const adoptGeneratedDraft = (storageKey: string, generated: EmailTemplateDraft): DraftState => {
  persistState(storageKey, generated, generated);
  return { storageKey, draft: generated, generated };
};

export const useEmailTemplateDraft = ({
  bankApplicationId,
  bankApplication,
  eligibilityChecks,
  adibApplicantContact,
  isReadyForEmailGeneration,
}: Params) => {
  const storageKey = bankApplicationId
    ? bankApplicationSessionStorageKeys.emailTemplateDraft(bankApplicationId)
    : null;

  const [draftState, setDraftState] = useState<DraftState>(() =>
    createDraftStateForStorageKey(storageKey),
  );

  const freshDraft = useMemo(
    () =>
      isReadyForEmailGeneration && bankApplication
        ? generateEmailDraft({
            bankApplication,
            eligibilityChecks,
            adibApplicantContact,
            underwriterName: window.huspy.auth.user?.fullName ?? "",
          })
        : null,
    [isReadyForEmailGeneration, bankApplication, eligibilityChecks, adibApplicantContact],
  );

  const { generated } = draftState;
  const isDirty = !!generated && !isSameDraft(draftState.draft, generated);
  const isOutdated = !!freshDraft && (!generated || !isSameDraft(freshDraft, generated));

  if (storageKey !== draftState.storageKey) {
    setDraftState(createDraftStateForStorageKey(storageKey));
  } else if (storageKey && freshDraft && isOutdated && !isDirty) {
    setDraftState(adoptGeneratedDraft(storageKey, freshDraft));
  }

  const setSubject = useCallback((subject: string) => {
    setDraftState((current) => {
      const draft = { ...current.draft, subject };
      if (current.storageKey) persistState(current.storageKey, draft, current.generated);
      return { ...current, draft };
    });
  }, []);

  const setBody = useCallback((body: string) => {
    setDraftState((current) => {
      const draft = { ...current.draft, body };
      if (current.storageKey) persistState(current.storageKey, draft, current.generated);
      return { ...current, draft };
    });
  }, []);

  const refresh = useCallback(() => {
    if (!freshDraft || !storageKey) return;

    setDraftState(adoptGeneratedDraft(storageKey, freshDraft));
  }, [freshDraft, storageKey]);

  const status = resolveStatus(bankApplicationId, isReadyForEmailGeneration);

  return {
    draft: draftState.draft,
    status,
    isStale: isDirty && isOutdated,
    setSubject,
    setBody,
    refresh,
  };
};
