import { cn } from "@huspy/shared-ui";

import { Bank } from "@/types";

import { ApplicantNameFilter } from "./ApplicantNameFilter";
import { BankFilter } from "./BankFilter";
import { CreatedByFilter } from "./CreatedByFilter";
import { CreatedDateFilter } from "./CreatedDateFilter";
import { OPS_QUEUE_GRID, OPS_QUEUE_ROW_PADDING } from "./constants";

type Props = {
  banks: Bank[];
  applicantName: string;
  selectedBankId: string;
  createdById: string;
  createdAtFrom: string;
  createdAtTo: string;
  onApplyApplicantName: (name: string) => void;
  onClearApplicantName: () => void;
  onApplyBank: (bankId: string) => void;
  onClearBank: () => void;
  onApplyCreatedAt: (value: { from?: string; to?: string }) => void;
  onClearCreatedAt: () => void;
  onApplyCreatedBy: (userId: string) => void;
  onClearCreatedBy: () => void;
};

export function QueueHeaderStrip({
  banks,
  applicantName,
  selectedBankId,
  createdById,
  createdAtFrom,
  createdAtTo,
  onApplyApplicantName,
  onClearApplicantName,
  onApplyBank,
  onClearBank,
  onApplyCreatedAt,
  onClearCreatedAt,
  onApplyCreatedBy,
  onClearCreatedBy,
}: Props) {
  return (
    <div
      className={cn(
        "sticky top-0 z-10 grid h-11 items-center gap-3 rounded-t-[15px] border-b border-border bg-muted",
        OPS_QUEUE_GRID,
        OPS_QUEUE_ROW_PADDING,
      )}
    >
      <ApplicantNameFilter
        value={applicantName}
        onApply={onApplyApplicantName}
        onClear={onClearApplicantName}
      />

      <BankFilter
        value={selectedBankId}
        banks={banks}
        onApply={onApplyBank}
        onClear={onClearBank}
      />

      <span className="text-center text-sm font-semibold text-foreground">Loan amount</span>

      <CreatedDateFilter
        value={{ from: createdAtFrom || undefined, to: createdAtTo || undefined }}
        onApply={onApplyCreatedAt}
        onClear={onClearCreatedAt}
      />

      <CreatedByFilter value={createdById} onApply={onApplyCreatedBy} onClear={onClearCreatedBy} />
    </div>
  );
}
