import type { CreateMortgageApplicationFormApplicant } from "../types";

import { hasSelfEmployedApplicant } from "./hasSelfEmployedApplicant";

export const isCreateCaseDocLevelRequired = (
  applicants: CreateMortgageApplicationFormApplicant[],
  isCreateCaseDocLevelEnabled: boolean,
): boolean => isCreateCaseDocLevelEnabled && hasSelfEmployedApplicant(applicants);
