import { APPLICANT_ROLE_TO_LABEL } from "@/constants";
import type { Applicant } from "@/types";

export const getAssignToSelectOptions = (applicants: Applicant[]) =>
  applicants.map((applicant) => ({
    value: applicant.id,
    label: `${applicant.fullName} · ${APPLICANT_ROLE_TO_LABEL[applicant.role]}`,
  }));
