import { useState, type FC } from "react";

import { cn } from "@huspy/shared-ui";

import { useCreateManualLiability, useLiabilityTypes } from "@/api";
import type { EligibilityApplicant } from "@/types";
import { formatMoneyAmount } from "@/utils";

import {
  CALCULATION_ROW_GRID,
  CALCULATION_TABLE_ACTION_SLOT,
  CALCULATION_TABLE_ROW_SHELL,
  calculationTableFooterClassName,
} from "../../../constants";
import { useEligibilityChecksRoute } from "../../../hooks/useEligibilityChecksRoute";
import {
  AddEligibilityLineButton,
  AddLineButtonRow,
  AddLineRow,
  CalculationTableEmptyState,
  CalculationTableHeader,
  LiabilityCalculationRow,
} from "../../CalculationTable";

type Props = {
  activeApplicant: EligibilityApplicant;
};

export const LiabilitiesSection: FC<Props> = ({ activeApplicant }) => {
  const { bankApplicationId, currency, eligibilityChecks } = useEligibilityChecksRoute();
  const { data: liabilityTypes = [] } = useLiabilityTypes();
  const { mutateAsync: createLiability, isPending: isCreatingLiability } =
    useCreateManualLiability();
  const [isAddingLine, setIsAddingLine] = useState(false);

  if (!currency || !eligibilityChecks || !bankApplicationId) return null;

  const handleAddLiability = async ({
    description,
    amount,
    allocation,
  }: {
    description: string;
    amount: number;
    allocation: number;
  }) => {
    await createLiability({
      bankApplicationId,
      payload: {
        applicantId: activeApplicant.id,
        description,
        amount: amount.toFixed(2),
        allocation,
      },
    });
    setIsAddingLine(false);
  };

  return (
    <section>
      <div className="mb-3 flex flex-wrap items-center justify-between gap-3">
        <p className="text-sm font-semibold text-foreground">Liabilities</p>

        <span className="shrink-0 rounded-md bg-muted px-2 py-0.5 text-[10px] font-medium text-muted-foreground">
          Total monthly: {formatMoneyAmount(eligibilityChecks.summary.totalLiabilities, currency)}
        </span>
      </div>

      {activeApplicant.liabilities.length === 0 && !isAddingLine ? (
        <>
          <CalculationTableEmptyState
            title="No liabilities found"
            description="Liabilities from this applicant's documents will show here once they've been processed."
          />
          <div className="flex justify-center">
            <AddEligibilityLineButton label="Add liability" onClick={() => setIsAddingLine(true)} />
          </div>
        </>
      ) : (
        <>
          <CalculationTableHeader allocationLabel="Allocation" totalLabel="Counted" />

          <div role="list">
            {activeApplicant.liabilities.map((liability) => (
              <LiabilityCalculationRow
                key={liability.id}
                liabilityId={liability.id}
                description={liability.description}
                documentType={liability.documentType}
                liabilityType={liability.liabilityType}
                frequency={liability.frequency}
                allocation={liability.allocation}
                amount={liability.amount}
                amountOverride={liability.amountOverride}
                originalAmount={liability.originalAmount}
                fxRate={liability.fxRate}
                eligibleAmount={liability.eligibleAmount}
                documentFields={liability.documentFields}
                source={liability.source}
                typeOptions={liabilityTypes.length > 0 ? liabilityTypes : [liability.liabilityType]}
              />
            ))}

            {isAddingLine ? (
              <AddLineRow
                currency={currency}
                isPending={isCreatingLiability}
                onSubmit={handleAddLiability}
                onCancel={() => setIsAddingLine(false)}
              />
            ) : (
              <AddLineButtonRow label="Add liability" onClick={() => setIsAddingLine(true)} />
            )}
          </div>

          <div className={cn("mt-2", CALCULATION_TABLE_ROW_SHELL)}>
            <div className={cn(calculationTableFooterClassName, CALCULATION_ROW_GRID, "flex-1")}>
              <span className="text-xs font-semibold text-foreground">
                Total monthly liabilities — {activeApplicant.name}
              </span>
              <span />
              <span />
              <span />
              <span />
              <span className="text-center text-xs font-semibold tabular-nums text-foreground">
                {formatMoneyAmount(activeApplicant.totalLiabilities, currency)}
              </span>
            </div>
            <span className={CALCULATION_TABLE_ACTION_SLOT} aria-hidden />
          </div>
        </>
      )}
    </section>
  );
};
