import { cn } from "@huspy/shared-ui";

import {
  CHECK_VISUAL_STATE_ORDER,
  SUMMARY_BADGE_ACTIVE_CLASS,
  SUMMARY_BADGE_LABEL,
  SUMMARY_KEY_BY_VISUAL_STATE,
} from "./constants";
import type { CheckVisualState, RuleCheckSummary } from "./types";

type Props = {
  summary: RuleCheckSummary;
  activeFilters: CheckVisualState[];
  onToggleFilter: (state: CheckVisualState) => void;
};

export function SummaryBadges({ summary, activeFilters, onToggleFilter }: Props) {
  return (
    <div className="flex flex-wrap items-center gap-1.5">
      {CHECK_VISUAL_STATE_ORDER.map((state) => {
        const value = summary[SUMMARY_KEY_BY_VISUAL_STATE[state]];
        if (value === 0) return null;

        const isActive = activeFilters.includes(state);

        return (
          <button
            key={state}
            type="button"
            aria-pressed={isActive}
            onClick={() => onToggleFilter(state)}
            className={cn(
              "cursor-pointer rounded-full border border-solid px-2 py-0.5 text-[10px] font-semibold tabular-nums transition-colors",
              isActive
                ? SUMMARY_BADGE_ACTIVE_CLASS[state]
                : "border-border bg-transparent text-muted-foreground hover:text-foreground",
            )}
          >
            {value} {SUMMARY_BADGE_LABEL[state]}
          </button>
        );
      })}
    </div>
  );
}
