import { ChevronDown } from "@huspy/shared-icons";
import { cn, PopoverTrigger } from "@huspy/shared-ui";

type Props = {
  label: string;
  align?: "start" | "center" | "end";
};

export function FilterColumnTrigger({ label, align = "start" }: Props) {
  return (
    <PopoverTrigger asChild>
      <button
        type="button"
        className={cn(
          "flex w-full cursor-pointer items-center gap-1 border-0 bg-transparent p-0 shadow-none focus:outline-none focus-visible:ring-0",
          align === "end" && "justify-end",
          align === "center" && "translate-x-1 justify-center",
          align === "start" && "justify-start",
        )}
      >
        <span className="text-center text-sm font-semibold text-foreground">{label}</span>
        <ChevronDown className="mt-0.75 size-3.5 shrink-0" />
      </button>
    </PopoverTrigger>
  );
}
