import type { KeyboardEvent, MouseEvent } from "react";

import { File, Loader2, Pencil, Trash2 } from "@huspy/shared-icons";
import { cn, Tooltip, TooltipContent, TooltipTrigger } from "@huspy/shared-ui";

import { FileItemWithDocumentId } from "@/types";

import { formatShortDateTime, isProcessingInProgress } from "@/utils";
import { ProcessingFailurePill } from "@/routes/BankApplication/components/ChecklistWorkspace/components/ProcessingFailurePill";
import { RowActionButton } from "@/routes/BankApplication/components/ChecklistWorkspace/components/RowActionButton";
import { useEditDocument } from "@/routes/BankApplication/components/ChecklistWorkspace/context/EditDocumentContext";
import { useDocumentPreview } from "@/routes/BankApplication/components/ChecklistWorkspace/context/DocumentPreviewContext";
import { useRemoveFile } from "@/routes/BankApplication/components/ChecklistWorkspace/context/RemoveFileContext";
import { getDocumentActionAvailability } from "@/routes/BankApplication/components/ChecklistWorkspace/utils/getDocumentActionAvailability";
import { toDocumentPreviewTarget } from "@/routes/BankApplication/components/ChecklistWorkspace/utils/previewTarget";
import {
  ignoreRowClickProps,
  isRowClickIgnored,
} from "@/routes/BankApplication/components/ChecklistWorkspace/utils/rowClick";
import { getNeedsAttentionPillFailureMessage, getNeedsAttentionIconTooltipText } from "./utils";

type Props = {
  file: FileItemWithDocumentId;
};

export function NeedsAttentionFileRow({ file }: Props) {
  const { beginEdit } = useEditDocument();
  const { beginPreview } = useDocumentPreview();
  const { beginRemove } = useRemoveFile();
  const isProcessing = isProcessingInProgress(file.processingStatus);
  const pillFailureMessage = getNeedsAttentionPillFailureMessage(file.processingStatus);
  const iconTooltipText = getNeedsAttentionIconTooltipText(file.processingStatus);
  const editAvailability = getDocumentActionAvailability(
    "editAssigneeOrName",
    file.processingStatus,
  );
  const removeAvailability = getDocumentActionAvailability("remove", file.processingStatus);

  const openPreview = (event: MouseEvent<HTMLElement> | KeyboardEvent<HTMLElement>) => {
    if (isRowClickIgnored(event)) return;

    beginPreview(toDocumentPreviewTarget(file));
  };

  const handleKeyDown = (e: KeyboardEvent<HTMLElement>) => {
    if (e.key !== "Enter" && e.key !== " ") return;
    e.preventDefault();
    openPreview(e);
  };

  const statusIcon = isProcessing ? (
    <Loader2 className="size-4 shrink-0 animate-spin text-sky-600" aria-hidden />
  ) : (
    <File className="size-4 shrink-0 text-warning" aria-hidden />
  );

  return (
    <div
      role="button"
      tabIndex={0}
      onClick={openPreview}
      onKeyDown={handleKeyDown}
      className={cn(
        "flex items-center gap-3 rounded-xl border border-grey-60 bg-background px-3 py-2.5",
        "cursor-pointer hover:bg-muted",
      )}
    >
      {iconTooltipText ? (
        <Tooltip>
          <TooltipTrigger asChild>
            <span className="inline-flex">{statusIcon}</span>
          </TooltipTrigger>
          <TooltipContent>{iconTooltipText}</TooltipContent>
        </Tooltip>
      ) : (
        statusIcon
      )}

      <div className="flex min-w-0 flex-1 items-center gap-6">
        <div className="flex min-w-0 flex-col">
          <span title={file.fileName} className="truncate text-[13px] text-foreground">
            {file.fileName}
          </span>
          <span className="text-xs text-muted-foreground">
            {file.createdAt ? formatShortDateTime(file.createdAt) : "-"}
          </span>
        </div>

        {pillFailureMessage && <ProcessingFailurePill message={pillFailureMessage} />}
      </div>

      <div {...ignoreRowClickProps} className="flex shrink-0 items-center gap-0.5">
        <RowActionButton
          label="Edit document"
          icon={Pencil}
          disabled={editAvailability.disabled}
          disabledTooltip={editAvailability.disabled ? editAvailability.tooltip : undefined}
          onClick={() => beginEdit({ kind: "unclassified", file })}
        />

        <RowActionButton
          label="Remove file"
          icon={Trash2}
          variant="destructive"
          disabled={removeAvailability.disabled}
          disabledTooltip={removeAvailability.disabled ? removeAvailability.tooltip : undefined}
          onClick={() => beginRemove({ file })}
        />
      </div>
    </div>
  );
}
