import { ChevronRight } from "@huspy/shared-icons";
import {
  Badge,
  cn,
  Tooltip,
  TooltipContent,
  TooltipTrigger,
  Truncate,
  UserAvatar,
} from "@huspy/shared-ui";

import type { MortgageApplicationRow } from "@/types";
import { formatDayMonthYear, formatWholeMoneyAmountFromMinor } from "@/utils";

import { OPS_QUEUE_GRID, OPS_QUEUE_ROW_MIN_HEIGHT, OPS_QUEUE_ROW_PADDING } from "../constants";
import { BankApplicationRow } from "./BankApplicationRow";
import { getCaseSummaryValues } from "./utils";

type Props = {
  data: MortgageApplicationRow;
  isExpanded: boolean;
  onToggle: () => void;
};

export function MortgageApplicationRow({ data, isExpanded, onToggle }: Props) {
  const { loanAmount, loanCurrency, createdAt, creatorName } = getCaseSummaryValues(
    data.bankApplicationTableRows,
  );

  const hasMultipleApplicants = data.applicants.length > 1;
  return (
    <div className="border-b border-border">
      <button
        type="button"
        onClick={onToggle}
        aria-expanded={isExpanded}
        className={cn(
          "grid w-full cursor-pointer items-center gap-3 bg-card py-2.5 text-left hover:bg-muted",
          OPS_QUEUE_ROW_MIN_HEIGHT,
          isExpanded && "border-b border-grey-60",
          OPS_QUEUE_GRID,
          OPS_QUEUE_ROW_PADDING,
        )}
      >
        <span className="flex min-w-0 items-center gap-2.5">
          <ChevronRight
            className={cn(
              "size-4 shrink-0 text-muted-foreground transition-transform duration-160 ease-out",
              isExpanded && "rotate-90",
            )}
            aria-hidden
          />
          <UserAvatar
            name={data.mainApplicantFullName}
            className="size-7"
            fallbackClassName="bg-input text-[11px] font-semibold"
          />
          <div className="grid min-w-0 flex-1 grid-cols-[minmax(0,1fr)_auto] items-center gap-x-2.5">
            <Truncate text={data.mainApplicantFullName} className="min-w-0 text-sm font-semibold" />
            {hasMultipleApplicants && (
              <div className="shrink-0">
                <Tooltip>
                  <TooltipTrigger asChild>
                    <Badge
                      variant="secondary"
                      className="inline-flex shrink-0 justify-center rounded-2xl px-2 py-0 text-xs font-medium whitespace-nowrap text-muted-foreground"
                    >
                      Multiple applicants
                    </Badge>
                  </TooltipTrigger>
                  <TooltipContent className="max-w-75">
                    <ul className="flex flex-col gap-0.5 text-sm">
                      {data.applicants.map((applicant) => (
                        <li key={applicant.id}>{applicant.fullName}</li>
                      ))}
                    </ul>
                  </TooltipContent>
                </Tooltip>
              </div>
            )}
          </div>
        </span>

        <span />

        <span className="text-center text-[13px] font-medium tabular-nums">
          {loanAmount != null && loanCurrency
            ? formatWholeMoneyAmountFromMinor(loanAmount, loanCurrency)
            : "-"}
        </span>

        <span className="text-center text-xs tabular-nums">{formatDayMonthYear(createdAt)}</span>

        {creatorName ? (
          <span className="flex min-w-0 items-center justify-center gap-2">
            <UserAvatar
              name={creatorName}
              className="size-5.5"
              fallbackClassName="bg-input text-[9px] font-semibold"
            />
            <Truncate text={creatorName} className="min-w-0 text-xs" />
          </span>
        ) : (
          <span className="text-center text-xs">-</span>
        )}
      </button>

      {isExpanded &&
        data.bankApplicationTableRows.map((bankApplication) => (
          <BankApplicationRow key={bankApplication.id} data={bankApplication} />
        ))}
    </div>
  );
}
