import type { DocumentExtractedFields, ExtractedField } from "@/types";

type PatchableField = Pick<
  ExtractedField,
  "key" | "value" | "source" | "updatedById" | "updatedAt" | "reviewStatus"
>;

const mergePatchedFieldValue = <T extends PatchableField>(field: T, patch: ExtractedField): T => ({
  ...field,
  value: patch.value,
  source: patch.source,
  updatedById: patch.updatedById,
  updatedAt: patch.updatedAt,
  reviewStatus: patch.reviewStatus,
});

export const applyPatchedExtractedFields = (
  data: DocumentExtractedFields,
  patches: ExtractedField[],
): DocumentExtractedFields => {
  const patchesByKey = new Map(patches.map((patch) => [patch.key, patch]));

  const applyPatch = <T extends PatchableField>(field: T): T => {
    const patch = patchesByKey.get(field.key);
    return patch ? mergePatchedFieldValue(field, patch) : field;
  };

  return {
    ...data,
    fields: data.fields.map((field) => applyPatch(field)),
    groups: data.groups.map((group) => ({
      ...group,
      items: group.items.map((item) => ({
        ...item,
        fields: item.fields.map((field) => applyPatch(field)),
      })),
    })),
  };
};
