import { CircleCheck, CircleX, Loader2 } from "@huspy/shared-icons";
import { cn } from "@huspy/shared-ui";

export type ChecklistRowState = "received" | "missing" | "providedNotRequired" | "processing";

type Props = {
  state: ChecklistRowState;
  className?: string;
};

export const RowStatusIcon = ({ state, className }: Props) => {
  const iconClassName = cn("size-4 shrink-0", className);

  if (state === "processing") {
    return <Loader2 className={cn(iconClassName, "animate-spin text-sky-600")} aria-hidden />;
  }

  if (state === "missing") {
    return <CircleX className={cn(iconClassName, "text-destructive")} aria-hidden />;
  }

  return (
    <CircleCheck
      className={cn(iconClassName, state === "received" ? "text-success" : "text-grey-300")}
      aria-hidden
    />
  );
};
