import { useState, type FC } from "react";

import { cn, Input } from "@huspy/shared-ui";

import { calculationTableNumberInputNoSpinnerClassName } from "../../constants";
import { parseAllocationPercent } from "../../utils";

type Props = {
  value: number;
  disabled: boolean;
  onCommit: (allocation: number) => void | Promise<void>;
};

export const AllocationPercentInput: FC<Props> = ({ value, disabled, onCommit }) => {
  const [draft, setDraft] = useState(String(value));
  const [invalid, setInvalid] = useState(false);
  const [prevValue, setPrevValue] = useState(value);

  if (value !== prevValue) {
    setPrevValue(value);
    setDraft(String(value));
    setInvalid(false);
  }

  const handleBlur = async () => {
    const parsed = parseAllocationPercent(draft);
    if (parsed === null) {
      setDraft(String(value));
      setInvalid(true);
      return;
    }

    if (parsed === value) {
      setDraft(String(value));
      setInvalid(false);
      return;
    }

    setInvalid(false);
    setDraft(String(parsed));

    try {
      await onCommit(parsed);
    } catch {
      setDraft(String(value));
    }
  };

  return (
    <div className="flex items-center justify-center gap-1">
      <Input
        type="text"
        inputMode="numeric"
        value={draft}
        disabled={disabled}
        aria-invalid={invalid || undefined}
        onChange={(event) => {
          const next = event.target.value;

          if (next === "") {
            setDraft("");
            setInvalid(false);
            return;
          }

          if (!/^\d+$/.test(next)) return;

          const parsed = Number.parseInt(next, 10);
          if (parsed > 100) return;

          setDraft(next);
          setInvalid(false);
        }}
        onBlur={() => {
          void handleBlur();
        }}
        onKeyDown={(event) => {
          if (["-", "+", "e", "E", "."].includes(event.key)) {
            event.preventDefault();
            return;
          }

          if (event.key === "Enter") {
            event.currentTarget.blur();
          }
        }}
        className={cn(
          "ml-4 h-7 w-16 px-2 text-center text-[11px] tabular-nums selection:bg-revert selection:text-revert",
          calculationTableNumberInputNoSpinnerClassName,
        )}
      />
      <span className="text-xs text-muted-foreground">%</span>
    </div>
  );
};
