import { Container, LoadErrorMessage } from "@/components";

import {
  PageHeader,
  MortgageApplicationsTable,
  MortgageApplicationsTableSkeleton,
} from "./components";
import { useOpsQueueBankApplications } from "./hooks";

export function OpsQueue() {
  const { data, isPending, isError, isFetching, isSuccess, page, setPage } =
    useOpsQueueBankApplications();

  return (
    <Container>
      <PageHeader />

      {isPending && <MortgageApplicationsTableSkeleton />}

      {isError && (
        <LoadErrorMessage>Could not load applications. Please try again.</LoadErrorMessage>
      )}

      {isSuccess && (
        <MortgageApplicationsTable
          mortgageApplicationRows={data.data}
          metadata={data.metadata}
          page={page}
          onPageChange={setPage}
          isRefreshing={isFetching}
        />
      )}
    </Container>
  );
}
