import type { DocumentExtractedFields } from "@/types";

export type ExtractedFieldsViewState =
  | { kind: "loading" }
  | { kind: "error"; message: string }
  | { kind: "message"; message: string }
  | { kind: "form"; data: DocumentExtractedFields };

export type ExtractedFieldsStatusState = Exclude<ExtractedFieldsViewState, { kind: "form" }>;

type Params = {
  data: DocumentExtractedFields | undefined;
  isError: boolean;
};

/**
 * Single source of truth for what the modal body shows.
 * Cached data wins over `isError` so a failed background refetch never replaces the form.
 */
export const getExtractedFieldsViewState = ({
  data,
  isError,
}: Params): ExtractedFieldsViewState => {
  if (!data) {
    if (isError) return { kind: "error", message: "Could not load extracted fields." };
    return { kind: "loading" };
  }

  if (data.documentType === null) {
    return { kind: "message", message: "Classify this document before viewing extracted fields." };
  }

  switch (data.status) {
    case "PENDING":
      return { kind: "message", message: "Extraction is in progress. This may take a moment." };
    case "NOT_EXTRACTED":
      return { kind: "message", message: "Extraction has not started for this document yet." };
    case "FAILED":
      return { kind: "message", message: "Extraction failed. Try again later or contact support." };
    case "EXTRACTED":
      if (data.fields.length === 0 && data.groups.length === 0) {
        return { kind: "message", message: "No fields are configured for this document type." };
      }
      return { kind: "form", data };
  }
};
