import { createContext, useContext, type Context } from "react";

import { globalSingleton } from "./globalSingleton";

// Shared, or Provider and Consumer would be different createContext() instances per bundle.
const ScopeContainerContext: Context<HTMLElement | null> = globalSingleton(
  "ScopeContainerContext",
  () => createContext<HTMLElement | null>(null),
);

export const ScopeContainerProvider = ScopeContainerContext.Provider;
export const useScopeContainer = () => useContext(ScopeContainerContext);
