import { useFieldArray, useFormContext } from "react-hook-form";

import { Button } from "@huspy/shared-ui";
import { Plus } from "@huspy/shared-icons";

import { useBanks } from "@/api";

import { BankRow } from "./BankRow";
import { SectionHeader } from "../SectionHeader";
import { CreateMortgageApplicationFormValues } from "../../types";
import { getEmptyBankRow } from "../../utils";

type Props = {
  showDocLevel: boolean;
};

export const BanksSection = ({ showDocLevel }: Props) => {
  const { data: banksData } = useBanks();
  const {
    control,
    getValues,
    clearErrors,
    trigger,
    formState: { errors },
  } = useFormContext<CreateMortgageApplicationFormValues>();
  const { fields, append, remove } = useFieldArray({
    control,
    name: "banks",
  });
  if (!banksData) return null;
  const bankCatalog = banksData.data;
  const bankOptions = bankCatalog
    .map((bank) => ({
      value: bank.id,
      label: bank.name,
    }))
    .sort((a, b) => a.label.localeCompare(b.label));

  const revalidateBankRows = () => {
    const filledRowNames = getValues("banks").flatMap((bank, idx) =>
      bank.id ? ([`banks.${idx}.id`] as const) : [],
    );
    if (filledRowNames.length <= 0) return;
    void trigger(filledRowNames);
  };

  const handleAddBank = () => {
    clearErrors("banks");
    append(getEmptyBankRow());
    revalidateBankRows();
  };

  const handleRemoveBank = (idx: number) => {
    clearErrors("banks");
    remove(idx);
    revalidateBankRows();
  };

  return (
    <div className="pt-5">
      <SectionHeader title="Banks" number={3} />
      <div className="flex flex-col gap-3">
        {fields.map((field, idx) => (
          <BankRow
            key={field.id}
            idx={idx}
            bankCatalog={bankCatalog}
            bankOptions={bankOptions}
            showDocLevel={showDocLevel}
            onRemove={() => handleRemoveBank(idx)}
          />
        ))}

        {errors.banks?.message && (
          <p role="alert" className="text-destructive text-sm">
            {errors.banks.message}
          </p>
        )}

        <Button
          type="button"
          variant="ghost"
          size="sm"
          className="text-foreground h-auto w-fit gap-1 p-1 text-sm font-medium hover:bg-muted"
          onClick={handleAddBank}
        >
          <Plus className="size-3.5" />
          Add bank
        </Button>
      </div>
    </div>
  );
};
