import { cn } from "@huspy/shared-ui";

import { DOCUMENT_CHECKLIST_TABLE_GRID } from "./DocumentRow/constants";

const headerLabelClass = "text-xs font-semibold text-foreground-secondary";
const headers = ["Document", "File", "Updated"];

export function TableHeader() {
  return (
    <div className={cn("grid items-center gap-3 px-3 pb-2", DOCUMENT_CHECKLIST_TABLE_GRID)}>
      {headers.map((header) => (
        <span key={header} className={headerLabelClass}>
          {header}
        </span>
      ))}
      <span />
    </div>
  );
}
