import type { IncomeVerificationType } from "@/types";

/**
 * Keeps the candidate level when the bank supports it, otherwise falls back to
 * the bank's only supported level so single-option banks fill themselves in.
 */
export const resolveIncomeVerificationTypeForBank = (
  candidate: IncomeVerificationType | null,
  supportedDocLevels: IncomeVerificationType[],
): IncomeVerificationType | null => {
  if (candidate && supportedDocLevels.includes(candidate)) return candidate;
  return supportedDocLevels.length === 1 ? supportedDocLevels[0] : null;
};
