import type { Applicant, BankApplicationRow, MortgageApplicationRow } from "@/types";

const getYoungestBankApplicationCreatedAt = (rows: BankApplicationRow[]) =>
  Math.max(...rows.map((row) => new Date(row.createdAt).getTime()));

const compareBankApplicationTableRows = (a: BankApplicationRow, b: BankApplicationRow) =>
  a.bank.name.localeCompare(b.bank.name) || a.id.localeCompare(b.id);

const getMainApplicantFullName = (applicants: Applicant[]): string => {
  const mainName = applicants.find(({ role }) => role === "MAIN")?.fullName?.trim();
  if (mainName) return mainName;

  return applicants.map(({ fullName }) => fullName?.trim() ?? "").find(Boolean) ?? "";
};

const toMortgageApplicationRow = (
  id: string,
  mortgageApplication: BankApplicationRow["mortgageApplication"],
  bankApplicationTableRows: BankApplicationRow[],
): MortgageApplicationRow => {
  const { applicantFullName, applicants = [] } = mortgageApplication;

  return {
    id,
    mainApplicantFullName: getMainApplicantFullName(applicants) || applicantFullName,
    applicants,
    bankApplicationTableRows,
  };
};

const compareMortgageApplicationTableRows = (
  a: MortgageApplicationRow,
  b: MortgageApplicationRow,
) =>
  getYoungestBankApplicationCreatedAt(b.bankApplicationTableRows) -
    getYoungestBankApplicationCreatedAt(a.bankApplicationTableRows) || a.id.localeCompare(b.id);

export const toMortgageApplicationRows = (
  bankApplicationRows: BankApplicationRow[],
): MortgageApplicationRow[] => {
  const mortgageApplicationIdToBankApplications = new Map<string, BankApplicationRow[]>();

  for (const bankApplication of bankApplicationRows) {
    const mortgageApplicationId = bankApplication.mortgageApplication.id;
    const bankApplications = mortgageApplicationIdToBankApplications.get(mortgageApplicationId);
    if (bankApplications) {
      bankApplications.push(bankApplication);
    } else {
      mortgageApplicationIdToBankApplications.set(mortgageApplicationId, [bankApplication]);
    }
  }

  return Array.from(mortgageApplicationIdToBankApplications.entries())
    .map(([id, bankApplicationTableRows]) => {
      const { mortgageApplication } = bankApplicationTableRows[0];

      return toMortgageApplicationRow(
        id,
        mortgageApplication,
        [...bankApplicationTableRows].sort(compareBankApplicationTableRows),
      );
    })
    .sort(compareMortgageApplicationTableRows);
};
