import { useCallback, useEffect, useRef, useState } from "react";

import { useUploadDocumentFile } from "@/api";

import type { UploadedDocumentFile } from "./types";

import { getDocumentUploadErrorMessage } from "../utils";

type PendingDocumentUpload = {
  clientId: string;
  fileName: string;
};

export type DocumentUploadError = {
  id: string;
  message: string;
};

let nextDocumentUploadClientId = 0;

const createDocumentUploadClientId = () => `upload-${++nextDocumentUploadClientId}`;

export const useUploadDocumentFiles = () => {
  const uploadDocumentFileMutation = useUploadDocumentFile();
  const isActiveRef = useRef(true);
  const [pendingUploads, setPendingUploads] = useState<PendingDocumentUpload[]>([]);
  const [uploadErrors, setUploadErrors] = useState<DocumentUploadError[]>([]);

  useEffect(() => {
    isActiveRef.current = true;
    return () => {
      isActiveRef.current = false;
    };
  }, []);

  const uploadFiles = useCallback(
    (files: File[], onUploaded: (file: UploadedDocumentFile) => void) => {
      setUploadErrors([]);

      const newPending: PendingDocumentUpload[] = files.map((file) => ({
        clientId: createDocumentUploadClientId(),
        fileName: file.name,
      }));

      setPendingUploads((prev) => [...prev, ...newPending]);

      files.forEach((file, index) => {
        const { clientId } = newPending[index]!;

        void uploadDocumentFileMutation
          .mutateAsync(file)
          .then((doc) => {
            if (!isActiveRef.current) return;
            setPendingUploads((prev) => prev.filter((item) => item.clientId !== clientId));
            onUploaded({ documentId: doc.documentId, fileName: doc.name });
          })
          .catch((error: unknown) => {
            if (!isActiveRef.current) return;
            setPendingUploads((prev) => prev.filter((item) => item.clientId !== clientId));
            setUploadErrors((prev) => [
              ...prev,
              {
                id: clientId,
                message: `${file.name}: ${getDocumentUploadErrorMessage(error)}`,
              },
            ]);
          });
      });
    },
    [uploadDocumentFileMutation],
  );

  const clearUploadErrors = useCallback(() => setUploadErrors([]), []);

  return {
    pendingUploads,
    uploadErrors,
    isUploading: pendingUploads.length > 0,
    uploadFiles,
    clearUploadErrors,
  };
};
