import { getInitials } from "@huspy/shared-lib";
import { cn } from "../../shadcn/lib/utils";

import { Avatar, AvatarFallback, AvatarImage } from "../Avatar";

type UserAvatarProps = {
  name: string;
  image?: string | undefined;
  className?: string | undefined;
  fallbackClassName?: string | undefined;
};

export function UserAvatar({ name, image, className, fallbackClassName }: UserAvatarProps) {
  return (
    <Avatar className={cn("text-xs", className)} data-testid="user-avatar">
      {image && <AvatarImage src={image} alt={name} />}
      <AvatarFallback
        className={cn("bg-muted w-full font-semibold", fallbackClassName)}
        data-testid="user-avatar-fallback"
      >
        {getInitials(name)}
      </AvatarFallback>
    </Avatar>
  );
}
