import type {
  EarningType,
  EligibilityFrequency,
  EligibilityLineSource,
  LiabilityType,
} from "@/types";

export const ELIGIBILITY_FREQUENCY_LABELS = {
  MONTHLY: "Monthly",
  QUARTERLY: "Quarterly",
  BI_ANNUAL: "Bi-annual",
  ANNUAL: "Annual",
  AVERAGE: "Average",
} as const satisfies Record<EligibilityFrequency, string>;

export const EARNING_TYPE_LABELS = {
  FIXED_ITEM: "Fixed item",
  FLYING_ALLOWANCE: "Flying allowance",
  AIRFARE_ALLOWANCE: "Airfare allowance",
  INCENTIVE: "Incentive",
  HOUSING_ALLOWANCE: "Housing allowance",
  EDUCATION_ALLOWANCE: "Education allowance",
  RENTAL: "Rental income",
  OTHER: "Other",
} as const satisfies Record<EarningType, string>;

export const isEarningAllocationEditable = (
  earningType: EarningType,
  hasAmountOverride: boolean,
  frequency: EligibilityFrequency | null,
  source?: EligibilityLineSource,
): boolean => {
  if (source === "MANUAL") return !hasAmountOverride;

  return earningType === "OTHER" && !hasAmountOverride && frequency !== "MONTHLY";
};

export const getEarningAllocationTooltipText = (
  earningType: EarningType,
  hasAmountOverride: boolean,
  frequency: EligibilityFrequency | null,
  source?: EligibilityLineSource,
): string | undefined => {
  if (hasAmountOverride) {
    return "Allocation is fixed at 100% once the amount is manually overridden.";
  }

  if (source === "MANUAL") return undefined;

  if (isEarningAllocationEditable(earningType, hasAmountOverride, frequency, source)) {
    return undefined;
  }

  if (earningType === "FIXED_ITEM") {
    return "Fixed income is always counted at 100%.";
  }

  if (earningType === "OTHER" && frequency === "MONTHLY") {
    return "Allocation is fixed at 100% for monthly frequency.";
  }

  return "Allocation is set by bank policy for this income type. Change type to Other to override.";
};

