import { CreatedDateFilterValue } from "./types";

export const emptyDraft = (): CreatedDateFilterValue => ({ from: "", to: "" });

export const toDraft = (value: CreatedDateFilterValue): CreatedDateFilterValue => ({
  from: value.from ?? "",
  to: value.to ?? "",
});

// en-CA formats as YYYY-MM-DD from the date's local Y/M/D
export const toISODate = (date: Date): string => date.toLocaleDateString("en-CA");

export function fromISODate(value: string): Date {
  const [year, month, day] = value.split("-").map(Number);
  return new Date(year, month - 1, day);
}

export function formatDisplayDate(iso: string): string {
  return fromISODate(iso).toLocaleDateString("en-GB", {
    day: "numeric",
    month: "short",
    year: "numeric",
  });
}
