import type {
  BankPolicyCheckWaiver as BankPolicyCheckWaiverApi,
  BankPolicyComparison as BankPolicyComparisonApi,
  BankPolicyResponse,
} from "@/api/types";
import type { BankPolicyCheckWaiver, BankPolicyChecks, BankPolicyComparison } from "@/types";

export const toBankPolicyChecks = (dto: BankPolicyResponse): BankPolicyChecks => ({
  calculatedAt: dto.calculatedAt ?? null,
  checks: dto.data.map((check) => ({
    id: check.id,
    ruleCode: check.ruleCode,
    title: check.title,
    category: check.category,
    severity: check.severity,
    status: check.status,
    ordinal: check.ordinal ?? null,
    applicantId: check.applicantId ?? null,
    comparison: toComparison(check.comparison),
    waiver: toWaiver(check.waiver),
  })),
  skipped: (dto.skipped ?? []).map((skipped) => ({
    ruleCode: skipped.ruleCode,
    title: skipped.title,
    ordinal: skipped.ordinal ?? null,
    applicantId: skipped.applicantId ?? null,
    reason: skipped.reason,
  })),
});

const toComparison = (
  comparison: BankPolicyComparisonApi | null | undefined,
): BankPolicyComparison | null =>
  comparison
    ? {
        subjectValue: comparison.subjectValue ?? null,
        targetValue: comparison.targetValue ?? null,
        documentId: comparison.documentId ?? null,
        unit: comparison.unit ?? null,
      }
    : null;

const toWaiver = (
  waiver: BankPolicyCheckWaiverApi | null | undefined,
): BankPolicyCheckWaiver | null =>
  waiver
    ? {
        id: waiver.id,
        reason: waiver.reason ?? "",
        waivedBy: waiver.waivedById,
        waivedAt: waiver.waivedAt,
      }
    : null;
