import { useSplitSegmentField } from "./useSplitSegmentField";

type UseSplitDocumentAssigneesParams = {
  segmentStarts: number[];
  initialAssignTo?: string;
};

type UseSplitDocumentAssigneesResult = {
  assigneeFor: (startPage: number) => string;
  setAssigneeForSegment: (startPage: number, applicantId: string) => void;
  reset: () => void;
};

export const useSplitDocumentAssignees = ({
  segmentStarts,
  initialAssignTo,
}: UseSplitDocumentAssigneesParams): UseSplitDocumentAssigneesResult => {
  const { valueFor, setValueForSegment, reset } = useSplitSegmentField(
    segmentStarts,
    (): Record<number, string> => (initialAssignTo ? { 1: initialAssignTo } : {}),
  );

  return {
    assigneeFor: valueFor,
    setAssigneeForSegment: setValueForSegment,
    reset,
  };
};
