import {
  CHECK_CATEGORY_ORDER,
  CHECK_VISUAL_STATE_ORDER,
  SUMMARY_KEY_BY_VISUAL_STATE,
} from "./constants";
import type { CheckVisualState, RuleCheckGroup, RuleCheckLike, RuleCheckSummary } from "./types";

/** Checks whose rule was deactivated carry no ordinal, so they sort last. */
const byOrdinal = <T extends { ordinal: number | null }>(a: T, b: T): number =>
  (a.ordinal ?? Number.MAX_SAFE_INTEGER) - (b.ordinal ?? Number.MAX_SAFE_INTEGER);

/** Groups checks by category (fixed display order) and sorts each group by ordinal. */
export const groupChecksByCategory = <T extends RuleCheckLike>(checks: T[]): RuleCheckGroup<T>[] =>
  CHECK_CATEGORY_ORDER.map((category) => ({
    category,
    checks: checks.filter((check) => check.category === category).sort(byOrdinal),
  })).filter((group) => group.checks.length > 0);

export const summarizeChecks = <T extends RuleCheckLike>(checks: T[]): RuleCheckSummary => {
  const summary: RuleCheckSummary = {
    blocking: 0,
    waived: 0,
    advisory: 0,
    passed: 0,
  };

  for (const check of checks) {
    if (check.status === "PASS") summary.passed += 1;
    else if (check.waiver) summary.waived += 1;
    else if (check.severity === "BLOCKING") summary.blocking += 1;
    else summary.advisory += 1;
  }

  return summary;
};

/** Only blocking failures can be waived. */
export const isCheckWaivable = (check: Pick<RuleCheckLike, "status" | "severity">): boolean =>
  check.status === "FAIL" && check.severity === "BLOCKING";

export const getCheckVisualState = (
  check: Pick<RuleCheckLike, "status" | "severity" | "waiver">,
): CheckVisualState => {
  if (check.status === "PASS") return "pass";
  if (check.waiver) return "waived";
  return check.severity === "BLOCKING" ? "blockingFail" : "advisoryFail";
};

export const toggleCheckFilter = (
  filters: CheckVisualState[],
  state: CheckVisualState,
): CheckVisualState[] =>
  filters.includes(state) ? filters.filter((filter) => filter !== state) : [...filters, state];

export const resolveActiveFilters = (
  selected: CheckVisualState[],
  summary: RuleCheckSummary,
): CheckVisualState[] => {
  if (selected.length === 0) return selected;

  const available = CHECK_VISUAL_STATE_ORDER.filter(
    (state) => summary[SUMMARY_KEY_BY_VISUAL_STATE[state]] > 0,
  );
  const active = selected.filter((state) => available.includes(state));

  return active.length > 0 ? active : available;
};

export const filterChecksByVisualState = <T extends RuleCheckLike>(
  checks: T[],
  filters: CheckVisualState[],
): T[] => checks.filter((check) => filters.includes(getCheckVisualState(check)));

/** Whether a set of checks have unresolved failures (i.e. not waived and not passing). */
export const hasUnresolvedFailure = (checks: Pick<RuleCheckLike, "status" | "waiver">[]): boolean =>
  checks.some((check) => check.status === "FAIL" && !check.waiver);

/** Bottom edge of sticky headers that would cover content scrolled to the viewport top. */
export const getStickyTopOffset = (root: ParentNode = document): number => {
  let maxBottom = 0;

  for (const element of Array.from(root.querySelectorAll<HTMLElement>(".sticky"))) {
    const stickyTop = Number.parseFloat(getComputedStyle(element).top) || 0;
    const rect = element.getBoundingClientRect();
    const effectiveBottom = rect.top <= stickyTop + 1 ? rect.bottom : stickyTop + rect.height;

    maxBottom = Math.max(maxBottom, effectiveBottom);
  }

  return maxBottom;
};

export const scrollElementToViewUnderSticky = (
  element: HTMLElement,
  options: ScrollIntoViewOptions = { block: "start", behavior: "smooth" },
): void => {
  element.style.scrollMarginTop = `${getStickyTopOffset()}px`;
  element.scrollIntoView(options);
};
