import type { FC } from "react";

import { Loader2 } from "@huspy/shared-icons";

import type { ExtractedFieldsStatusState } from "../utils/getExtractedFieldsViewState";

type Props = {
  state: ExtractedFieldsStatusState;
};

export const ExtractedFieldsStatusView: FC<Props> = ({ state }) => {
  if (state.kind === "loading") {
    return (
      <div
        role="status"
        aria-live="polite"
        className="flex flex-col items-center justify-center gap-2 px-6 text-center text-muted-foreground min-h-48"
      >
        <Loader2 className="size-7 animate-spin" aria-hidden />
        <span className="text-xs">Loading extracted fields…</span>
      </div>
    );
  }

  if (state.kind === "error") {
    return (
      <div
        role="alert"
        className="flex flex-col items-center justify-center px-6 text-center text-sm text-destructive min-h-48"
      >
        {state.message}
      </div>
    );
  }

  return (
    <div className="px-6 py-5 min-h-48">
      <p className="text-sm text-muted-foreground">{state.message}</p>
    </div>
  );
};
