import { Bank } from "@/api";
import { MORTGAGE_TYPE_OPTIONS } from "@/constants";

import { getSupportedMortgageTypesForBankId } from "./getSupportedMortgageTypesForBankId";

export const getMortgageTypeOptionsForBankId = (bankId: string, banks: Bank[]) => {
  const supportedMortgageTypes = getSupportedMortgageTypesForBankId(bankId, banks);
  return MORTGAGE_TYPE_OPTIONS.filter((option) => supportedMortgageTypes.includes(option.value));
};
