import type { BankApplication, EligibilityChecks } from "@/types";

import { buildEmailBody } from "./buildEmailBody";
import { formatCaseDetailsBlock } from "./standardEmailTemplate/formatCaseDetailsBlock";
import { formatLoanTenorMonths } from "./standardEmailTemplate/formatEligibilityBlock";
import { formatStandardEmailSubject } from "./standardEmailTemplate/formatSubject";
import type { AdibApplicantContact, EmailTemplateDraft } from "./types";

export type GenerateStandardEmailDraftInput = {
  bankApplication: BankApplication;
  eligibilityChecks: EligibilityChecks | undefined;
  adibApplicantContact?: AdibApplicantContact;
  underwriterName: string;
};

export const generateStandardEmailDraft = ({
  bankApplication,
  eligibilityChecks,
  adibApplicantContact,
  underwriterName,
}: GenerateStandardEmailDraftInput): EmailTemplateDraft => {
  const loanTenorMonths = formatLoanTenorMonths(eligibilityChecks);

  return {
    subject: formatStandardEmailSubject(bankApplication),
    body: buildEmailBody({
      caseDetailsBlock: formatCaseDetailsBlock(
        bankApplication,
        loanTenorMonths,
        adibApplicantContact,
      ),
      bankApplication,
      eligibilityChecks,
      underwriterName,
    }),
  };
};
