import {
  EMPLOYMENT_TYPE_TO_LABEL,
  MORTGAGE_TYPE_TO_LABEL,
  TRANSACTION_TYPE_TO_LABEL,
} from "@/constants";
import type { ApplicantRole, BankApplication, EligibilityChecks } from "@/types";

import { formatFinanceAmount } from "../standardEmailTemplate/formatCaseDetailsBlock";
import { formatTotalIncome } from "../standardEmailTemplate/formatEligibilityBlock";
import {
  formatLtvForEmail,
  formatPropertyValueForEmail,
} from "../standardEmailTemplate/formatSnapshotFields";
import {
  formatApplicantNames,
  getApplicantsByRole,
  getMainApplicant,
} from "../utils/applicantUtils";
import { formatPassportDisplayName } from "../utils/formatPassportDisplayName";

const formatRoleNamesLine = (
  label: string,
  applicants: BankApplication["applicants"],
  role: ApplicantRole,
): string[] => {
  const holders = getApplicantsByRole(applicants, role);
  if (holders.length === 0) return [];

  return [`${label}: ${formatApplicantNames(holders)}`];
};

export const formatFabCaseDetailsBlock = (
  bankApplication: BankApplication,
  eligibilityChecks: EligibilityChecks | undefined,
  loanTenorMonths: string,
): string => {
  const { applicants, currency } = bankApplication;
  const mainApplicant = getMainApplicant(applicants);
  const transactionLabel =
    bankApplication.transactionType != null
      ? TRANSACTION_TYPE_TO_LABEL[bankApplication.transactionType]
      : "";
  const profileLabel = mainApplicant?.employmentType
    ? EMPLOYMENT_TYPE_TO_LABEL[mainApplicant.employmentType]
    : "";

  return [
    "Case details",
    `Applicant Name: ${formatPassportDisplayName(mainApplicant?.nameAsPerPassport)}`,
    ...formatRoleNamesLine(
      "Co-applicant Name (Income being considered)",
      applicants,
      "CO_APPLICANT",
    ),
    ...formatRoleNamesLine("Co-mortgagor Name (Income not considered)", applicants, "CO_BORROWER"),
    `Property Location (Emirate): ${bankApplication.propertyEmirate?.trim() ?? ""}`,
    "Arabic Speaker Required: ",
    `Profile: ${profileLabel}`,
    `Product Type: ${MORTGAGE_TYPE_TO_LABEL[bankApplication.type]}`,
    `Transaction Type: ${transactionLabel}`,
    `Estimated Property Value: ${formatPropertyValueForEmail(bankApplication.propertyValue, currency)}`,
    `Requested Loan Amount: ${formatFinanceAmount(bankApplication.amount, currency)}`,
    `LTV: ${formatLtvForEmail(bankApplication.ltvPercent)}`,
    "STL: ",
    `Rate of Interest: ${bankApplication.bankRateName?.trim() ?? ""}`,
    `Tenure (in months): ${loanTenorMonths}`,
    `Monthly Income: ${formatTotalIncome(eligibilityChecks, currency)}`,
    "Form F Signed: ",
  ].join("\n");
};
