import type { FC } from "react";

import type { ExtractedFieldGroupCell, ExtractedFieldGroupColumn } from "@/types";

import { useExtractedFieldsFieldBindings } from "../context/ExtractedFieldsFieldContext";
import {
  extractedFieldsGridClassName,
  extractedFieldsGridItemClassName,
} from "../utils/extractedFieldsGridClassName";
import { isJoinFieldKey } from "../utils/isJoinFieldKey";

import { ExtractedFieldInput } from "./ExtractedFieldInput";

type Props = {
  template: ExtractedFieldGroupColumn[];
  fields: ExtractedFieldGroupCell[];
};

export const ParentRowFields: FC<Props> = ({ template, fields }) => {
  const { draft, setFieldValue, validateField, fieldErrors, isSaving, isFieldChanged } =
    useExtractedFieldsFieldBindings();

  const columns = template.filter((column) => !isJoinFieldKey(column.fieldKey));

  if (columns.length === 0) return null;

  return (
    <div className={extractedFieldsGridClassName}>
      {columns.map((column) => {
        const field = fields.find((entry) => entry.fieldKey === column.fieldKey);
        if (!field) return null;

        return (
          <div key={field.key} className={extractedFieldsGridItemClassName}>
            <ExtractedFieldInput
              label={column.label}
              dataType={column.dataType}
              options={column.options}
              value={draft[field.key] ?? ""}
              onChange={(value) => setFieldValue(field.key, value)}
              onValidate={(value) => validateField(field.key, value)}
              disabled={isSaving}
              changed={isFieldChanged(field.key)}
              error={!!fieldErrors[field.key]}
              errorMessage={fieldErrors[field.key]}
            />
          </div>
        );
      })}
    </div>
  );
};
