import { AlertCircle, AlertTriangle, CheckCircle2, Loader } from "huspy-icons/react";
import { useSyncExternalStore, type CSSProperties } from "react";
import { Toaster as SonnerPrimitive, type ToasterProps } from "sonner";

import { cn } from "../../lib/utils";

const toastVariantClassNames = {
  success: "!text-success",
  error: "!text-destructive",
  warning: "!text-warning",
  info: "!text-foreground",
} as const;

function useDocumentTheme(): ToasterProps["theme"] {
  return useSyncExternalStore(
    (onStoreChange) => {
      const observer = new MutationObserver(onStoreChange);
      observer.observe(document.documentElement, {
        attributes: true,
        attributeFilter: ["class"],
      });
      return () => observer.disconnect();
    },
    () => (document.documentElement.classList.contains("dark") ? "dark" : "light"),
    () => "light",
  );
}

/**
 * Huspy-styled Sonner toaster ([shadcn Sonner](https://ui.shadcn.com/docs/components/radix/sonner)).
 * Mount once per section/space; call `toast` from `@huspy/shared-ui` anywhere below.
 */
function Sonner({ className, toastOptions, ...props }: ToasterProps) {
  const theme = useDocumentTheme();

  return (
    <SonnerPrimitive
      theme={theme}
      className={cn("toaster group", className)}
      icons={{
        success: <CheckCircle2 className="size-4" />,
        info: <AlertCircle className="size-4" />,
        warning: <AlertTriangle className="size-4" />,
        error: <AlertCircle className="size-4" />,
        loading: <Loader className="size-4 animate-spin" />,
      }}
      style={
        {
          "--normal-bg": "var(--popover)",
          "--normal-text": "var(--popover-foreground)",
          "--normal-border": "var(--border)",
        } as CSSProperties
      }
      toastOptions={{
        ...toastOptions,
        classNames: {
          ...toastVariantClassNames,
          ...toastOptions?.classNames,
        },
      }}
      {...props}
    />
  );
}

/** @deprecated Prefer `Sonner` — alias kept for existing imports. */
const Toaster = Sonner;

export { Sonner, Toaster };
export { toast } from "sonner";
