import { useState, type FC, type SubmitEvent } from "react";

import { FloatingLabelSelect } from "@huspy/shared-agents";
import { cn } from "@huspy/shared-ui";
import { FileText } from "@huspy/shared-icons";

import { useDocumentTypeCodesForBankApplication, useLinkDocumentToBankApplication } from "@/api";
import { Modal, ModalFooter, PillButton, DocumentMultiFileUploadDropzone } from "@/components";

import type { Applicant } from "@/types";
import { getAssignToSelectOptions } from "@/routes/BankApplication/utils";

import {
  ADD_DOCUMENT_FILE_ACCEPT,
  ADD_DOCUMENT_MAX_UPLOAD_SIZE_BYTES,
  ADD_DOCUMENT_MAX_UPLOAD_SIZE_LABEL,
} from "./constants";
import { AddDocumentUploadedFileCard } from "./AddDocumentUploadedFileCard";
import { getAddDocumentFormState } from "./utils/getAddDocumentFormState";
import { linkUploadedDocuments } from "./utils/linkUploadedDocuments";
import type { AddDocumentUploadFile } from "./utils/types";

const UPLOADED_FILE_ICON = (
  <FileText aria-hidden className="size-4 shrink-0 text-muted-foreground" strokeWidth={2} />
);

type Props = {
  isOpen: boolean;
  onOpenChange: (open: boolean) => void;
  bankApplicationId: string;
  applicants: Applicant[];
  initialApplicantId: string;
  /** Preselected type for every uploaded file, set when uploading into a missing row. */
  initialDocumentType?: string;
  className?: string;
};

export const AddDocumentModal: FC<Props> = ({
  isOpen,
  onOpenChange,
  bankApplicationId,
  applicants,
  initialApplicantId,
  initialDocumentType,
  className,
}) => {
  const { data: documentTypeCodes = [] } =
    useDocumentTypeCodesForBankApplication(bankApplicationId);
  const linkDocument = useLinkDocumentToBankApplication();
  const [selectedApplicantId, setSelectedApplicantId] = useState(initialApplicantId);
  const [uploadedFiles, setUploadedFiles] = useState<AddDocumentUploadFile[]>([]);
  const [isUploadingFiles, setIsUploadingFiles] = useState(false);
  const [submitError, setSubmitError] = useState<string | null>(null);
  const [hasAttemptedSubmit, setHasAttemptedSubmit] = useState(false);

  const {
    showApplicantSelect,
    allFilesHaveDocumentType,
    isApplicantValid,
    canSubmit,
    showAssignToError,
  } = getAddDocumentFormState({
    uploadedFiles,
    applicants,
    selectedApplicantId,
    documentTypeCodes,
    isUploadingFiles,
    isLinkPending: linkDocument.isPending,
    hasAttemptedSubmit,
  });

  const handleOpenChange = (open: boolean) => {
    if (!open) {
      setSelectedApplicantId(initialApplicantId);
      setUploadedFiles([]);
      setIsUploadingFiles(false);
      setSubmitError(null);
      setHasAttemptedSubmit(false);
      linkDocument.reset();
    }
    onOpenChange(open);
  };

  const setFileDocumentType = (documentId: string, documentType: string) => {
    setUploadedFiles((prev) =>
      prev.map((file) => (file.documentId === documentId ? { ...file, documentType } : file)),
    );
    setSubmitError(null);
  };

  const handleSubmit = async (event: SubmitEvent<HTMLFormElement>) => {
    event.preventDefault();
    setHasAttemptedSubmit(true);

    if (uploadedFiles.length === 0) return;
    if (!allFilesHaveDocumentType) {
      setSubmitError("Pick a document type for every file before adding.");
      return;
    }
    if (!isApplicantValid) {
      setSubmitError("Select an applicant before adding.");
      return;
    }
    if (!canSubmit) return;

    setSubmitError(null);

    const { linkedDocumentIds, error } = await linkUploadedDocuments({
      files: uploadedFiles,
      bankApplicationId,
      applicants,
      selectedApplicantId,
      documentTypeCodes,
      linkDocument: (variables) => linkDocument.mutateAsync(variables),
    });

    if (error) {
      setUploadedFiles((prev) =>
        prev.filter((file) => !linkedDocumentIds.includes(file.documentId)),
      );
      setSubmitError(error);
      return;
    }

    handleOpenChange(false);
  };

  const submitButtonLabel =
    uploadedFiles.length > 1 ? `Add ${uploadedFiles.length} documents` : "Add document";

  return (
    <Modal
      isOpen={isOpen}
      onOpenChange={handleOpenChange}
      className={cn("sm:max-w-155!", className)}
      title="Add documents"
      description={`PDF, PNG, JPG or WebP · up to ${ADD_DOCUMENT_MAX_UPLOAD_SIZE_LABEL} each`}
    >
      <form className="flex min-h-0 flex-1 flex-col" onSubmit={handleSubmit}>
        <div className="min-h-0 flex-1 space-y-4 overflow-y-auto px-6 py-5">
          <div className="grid grid-cols-1 gap-3">
            {showApplicantSelect && (
              <FloatingLabelSelect
                label="Assign to"
                placeholder="Select applicant"
                required
                value={selectedApplicantId}
                error={showAssignToError}
                errorMessage={showAssignToError ? "Select an applicant before adding." : undefined}
                onValueChange={(value) => {
                  setSelectedApplicantId(value);
                  setSubmitError(null);
                }}
                options={getAssignToSelectOptions(applicants)}
              />
            )}

            {isOpen && (
              <DocumentMultiFileUploadDropzone
                accept={ADD_DOCUMENT_FILE_ACCEPT}
                value={uploadedFiles}
                onUploaded={(file) => {
                  setUploadedFiles((prev) => [
                    ...prev,
                    { ...file, documentType: initialDocumentType ?? "" },
                  ]);
                  setSubmitError(null);
                }}
                onRemove={(documentId) => {
                  setUploadedFiles((prev) => prev.filter((file) => file.documentId !== documentId));
                }}
                onUploadingChange={setIsUploadingFiles}
                maxFileSizeBytes={ADD_DOCUMENT_MAX_UPLOAD_SIZE_BYTES}
                maxFileSizeLabel={ADD_DOCUMENT_MAX_UPLOAD_SIZE_LABEL}
                disabled={linkDocument.isPending}
                uploadPrompt="Upload files"
                uploadingPrompt="Uploading…"
                pickAriaLabel="Upload PDF or image files"
                helperText="Drop files here or click to browse"
                uploadedLeadingIcon={UPLOADED_FILE_ICON}
                renderUploadedFile={(file, { onRemove }) => {
                  const typedFile = file as AddDocumentUploadFile;

                  return (
                    <AddDocumentUploadedFileCard
                      fileName={typedFile.fileName}
                      leadingIcon={UPLOADED_FILE_ICON}
                      onRemove={onRemove}
                      removeDisabled={linkDocument.isPending}
                      documentType={typedFile.documentType}
                      onDocumentTypeChange={(value) =>
                        setFileDocumentType(typedFile.documentId, value)
                      }
                      documentTypeCodes={documentTypeCodes}
                      selectDisabled={linkDocument.isPending}
                      hasTypeError={hasAttemptedSubmit && typedFile.documentType === ""}
                    />
                  );
                }}
              />
            )}
          </div>

          {!!submitError && (
            <p role="alert" className="text-sm text-destructive">
              {submitError}
            </p>
          )}
        </div>

        <ModalFooter className="justify-between">
          <PillButton type="button" buttonRole="secondary" onClick={() => handleOpenChange(false)}>
            Cancel
          </PillButton>
          <PillButton type="submit" disabled={!canSubmit}>
            {submitButtonLabel}
          </PillButton>
        </ModalFooter>
      </form>
    </Modal>
  );
};
