import { useState } from "react";

import { DatePicker, type DatePickerRange, Popover, PopoverContent } from "@huspy/shared-ui";

import { FilterColumnTrigger } from "../FilterColumnTrigger";
import { FilterPopoverActions } from "../FilterPopoverActions";
import { CreatedDateFilterValue } from "./types";
import { emptyDraft, formatDisplayDate, fromISODate, toDraft, toISODate } from "./utils";

type Props = {
  value: CreatedDateFilterValue;
  onApply: (value: CreatedDateFilterValue) => void;
  onClear: () => void;
};

export function CreatedDateFilter({ value, onApply, onClear }: Props) {
  const [open, setOpen] = useState(false);
  const [draft, setDraft] = useState<CreatedDateFilterValue>(() => toDraft(value));

  const handleOpenChange = (nextOpen: boolean) => {
    if (nextOpen) setDraft(toDraft(value));
    setOpen(nextOpen);
  };

  const handleApply = () => {
    onApply({
      from: draft.from || undefined,
      to: draft.to || undefined,
    });
    setOpen(false);
  };

  const handleClear = () => {
    onClear();
    setDraft(emptyDraft());
    setOpen(false);
  };

  const handleCalendarSelect = (range: DatePickerRange | undefined) => {
    setDraft({
      from: range?.from ? toISODate(range.from) : "",
      to: range?.to ? toISODate(range.to) : "",
    });
  };

  const appliedDraft = toDraft(value);
  const hasDraftChanged = draft.from !== appliedDraft.from || draft.to !== appliedDraft.to;
  const isInvalid = Boolean(draft.from && draft.to && draft.from > draft.to);
  const canApply = hasDraftChanged && !isInvalid;
  const selectedRange = draft.from
    ? { from: fromISODate(draft.from), ...(draft.to && { to: fromISODate(draft.to) }) }
    : undefined;

  return (
    <Popover open={open} onOpenChange={handleOpenChange}>
      <FilterColumnTrigger label="Created at" align="center" />

      <PopoverContent className="bg-popover w-auto" side="bottom" align="center">
        <div className="mb-3 space-y-3">
          <div className="flex items-center gap-3">
            <div className="flex-1 rounded-md border px-3 py-1.5">
              <div className="text-muted-foreground text-xs font-medium">From</div>
              <div className="text-sm font-medium">
                {draft.from ? formatDisplayDate(draft.from) : "—"}
              </div>
            </div>
            <div className="flex-1 rounded-md border px-3 py-1.5">
              <div className="text-muted-foreground text-xs font-medium">To</div>
              <div className="text-sm font-medium">
                {draft.to ? formatDisplayDate(draft.to) : "—"}
              </div>
            </div>
          </div>

          <DatePicker
            mode="range"
            numberOfMonths={2}
            weekStartsOn={1}
            fixedWeeks
            defaultMonth={draft.from ? fromISODate(draft.from) : undefined}
            selected={selectedRange}
            onSelect={handleCalendarSelect}
          />

          {isInvalid && (
            <p className="text-destructive text-sm">From date cannot be after To date</p>
          )}
        </div>

        <FilterPopoverActions onClear={handleClear} onApply={handleApply} canApply={canApply} />
      </PopoverContent>
    </Popover>
  );
}
