import type { DocumentTypeCode, DocumentValidationCheck, DocumentValidationOperand } from "@/types";
import { formatDayMonthYear } from "@/utils";

import { getDocumentTypeLabel } from "@/routes/BankApplication/components/ChecklistWorkspace/components/DocumentRow/utils";

export const formatField = (value: string): string => {
  const normalized = value.toLowerCase().split("_").join(" ");
  return normalized.charAt(0).toUpperCase() + normalized.slice(1);
};

const formatOperandLabel = (
  operand: DocumentValidationOperand,
  documentTypeCodes: DocumentTypeCode[],
): string => {
  const documentTypeLabel = getDocumentTypeLabel(operand.documentType, documentTypeCodes);
  const formattedField = operand.field ? formatField(operand.field) : null;

  if (formattedField) return `${formattedField} on ${documentTypeLabel}`;
  return documentTypeLabel;
};

const formatOperandValue = (value: string): string => {
  if (/^\d{4}-\d{2}-\d{2}/.test(value) && !Number.isNaN(Date.parse(value))) {
    return formatDayMonthYear(value);
  }

  return value;
};

const formatOperand = (
  operand: DocumentValidationOperand,
  documentTypeCodes: DocumentTypeCode[],
): string => {
  const label = formatOperandLabel(operand, documentTypeCodes);
  if (!operand.value) return label;

  const valueText = formatOperandValue(operand.value);

  return `${label}: ${valueText}`;
};

/** Human-readable explanation of why a failing check failed; null when there is nothing to show. */
export const formatCheckComparison = (
  check: DocumentValidationCheck,
  documentTypeCodes: DocumentTypeCode[],
): string | null => {
  if (check.status !== "FAIL") return null;

  const { subject, target } = check.comparison ?? {};
  if (!subject) return null;

  const subjectText = formatOperand(subject, documentTypeCodes);
  if (!target) return subjectText;

  const targetText = formatOperand(target, documentTypeCodes);
  return `${subjectText} ≠ ${targetText}`;
};
