import { Link, useLocation } from "@huspy/fe";

import { cn, Truncate } from "@huspy/shared-ui";

import { BankApplicationRow } from "@/types";
import { ROUTE_BUILDERS } from "@/constants";

import { buildBankApplicationNavigationState } from "@/utils";

import { OPS_QUEUE_GRID, OPS_QUEUE_ROW_MIN_HEIGHT, OPS_QUEUE_ROW_PADDING } from "../constants";

type Props = {
  data: BankApplicationRow;
};

export function BankApplicationRow({ data }: Props) {
  const location = useLocation();

  return (
    <Link
      to={ROUTE_BUILDERS.toBankApplication(data.id)}
      state={buildBankApplicationNavigationState(location)}
      className={cn(
        "grid items-center gap-3 border-b border-grey-60 bg-background py-2.5 text-inherit no-underline last:border-b-0 hover:bg-muted hover:text-inherit",
        OPS_QUEUE_ROW_MIN_HEIGHT,
        OPS_QUEUE_GRID,
        OPS_QUEUE_ROW_PADDING,
      )}
      aria-label={`View ${data.bank.name} application`}
    >
      <span className="pl-8.5" />

      <Truncate
        text={data.bank.name}
        className="min-w-0 text-center text-xs font-semibold text-foreground"
      />

      <span />
      <span />
      <span />
    </Link>
  );
}
