import type { FC } from "react";

import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@huspy/shared-ui";

import type { EligibilityFrequency } from "@/types";

import {
  ELIGIBILITY_FREQUENCIES,
  ELIGIBILITY_FREQUENCY_LABELS,
  ghostSelectTriggerClassName,
} from "../../constants";

type Props = {
  value: EligibilityFrequency;
  disabled: boolean;
  onValueChange: (frequency: EligibilityFrequency) => void;
};

export const FrequencySelect: FC<Props> = ({ value, disabled, onValueChange }) => (
  <Select
    value={value}
    onValueChange={(nextValue) => onValueChange(nextValue as EligibilityFrequency)}
    disabled={disabled}
  >
    <SelectTrigger size="sm" className={ghostSelectTriggerClassName}>
      <SelectValue />
    </SelectTrigger>
    <SelectContent>
      {ELIGIBILITY_FREQUENCIES.map((frequency) => (
        <SelectItem key={frequency} value={frequency} className="text-xs">
          {ELIGIBILITY_FREQUENCY_LABELS[frequency]}
        </SelectItem>
      ))}
    </SelectContent>
  </Select>
);
