import { FC } from "react";

import type { BankApplication } from "@/types";
import { useDocument } from "@/api";
import { isChecklistStatusMockEnabled } from "@/api/utils/applyChecklistStatusMocks";

import { CaseDocumentsCard } from "./components/CaseDocumentsCard";
import { ApplicantDocumentsCard } from "./components/ApplicantDocumentsCard";
import { NeedsAttentionCard } from "./components/NeedsAttentionCard";
import { isPdfContentType } from "./components/DocumentPreviewModal/utils";
import { EditDocumentModal } from "./components/EditDocumentModal";
import { SplitDocumentModal, SplitModalState } from "./components/SplitDocumentModal";
import { DocumentPreviewModal } from "./components/DocumentPreviewModal";
import { RemoveFileModal } from "./components/RemoveFileModal";
import { ExtractedFieldsModal } from "./components/ExtractedFieldsModal";
import {
  EditDocumentProvider,
  editDocumentModalStateFromTarget,
  type EditDocumentTarget,
} from "./context/EditDocumentContext";
import {
  DocumentPreviewProvider,
  type DocumentPreviewTarget,
} from "./context/DocumentPreviewContext";
import { RemoveFileProvider, type RemoveFileTarget } from "./context/RemoveFileContext";
import {
  ExtractedFieldsProvider,
  type ExtractedFieldsTarget,
} from "./context/ExtractedFieldsContext";
import { AddDocumentProvider } from "./context/AddDocumentContext";
import { useModalTarget } from "./hooks/useModalTarget";

export type Props = {
  bankApplication: BankApplication;
  activeApplicantId: string;
  onActiveApplicantIdChange: (applicantId: string) => void;
  onAddDocument: (documentType?: string) => void;
};

export const ChecklistWorkspace: FC<Props> = ({
  bankApplication: { id, checklist, applicants },
  activeApplicantId,
  onActiveApplicantIdChange,
  onAddDocument,
}) => {
  const editModal = useModalTarget<EditDocumentTarget>();
  const previewModal = useModalTarget<DocumentPreviewTarget>();
  const removeModal = useModalTarget<RemoveFileTarget>();
  const extractedFieldsModal = useModalTarget<ExtractedFieldsTarget>();
  const splitModal = useModalTarget<SplitModalState>();

  const {
    file: editFile,
    initialDocumentType: editInitialDocumentType,
    initialAssignTo,
  } = editDocumentModalStateFromTarget(editModal.target);
  const isEditModalOpen = editModal.isOpen && editFile !== null;
  const { data: editDocumentDetail } = useDocument(
    isEditModalOpen ? editFile?.docServiceDocumentId : undefined,
  );

  const handleBeginSplit = () => {
    if (!editFile || !editModal.target || !isPdfContentType(editDocumentDetail?.contentType))
      return;

    splitModal.open({
      file: editFile,
      initialDocumentType: editInitialDocumentType || undefined,
      initialAssignTo,
    });
    editModal.close();
  };

  return (
    <>
      <AddDocumentProvider onBeginAddDocument={onAddDocument}>
        <RemoveFileProvider onBeginRemove={removeModal.open}>
          <EditDocumentProvider onBeginEdit={editModal.open}>
            <DocumentPreviewProvider onBeginPreview={previewModal.open}>
              <ExtractedFieldsProvider onBeginExtractedFields={extractedFieldsModal.open}>
                <div className="flex flex-col gap-5">
                  {isChecklistStatusMockEnabled() && (
                    <p className="rounded-lg border border-warning/40 bg-warning/10 px-3 py-2 text-xs text-foreground">
                      Checklist status mocks are active. Remove{" "}
                      <span className="font-mono">?mockChecklistStatuses=1</span> from the URL to
                      hide showcase rows.
                    </p>
                  )}
                  <ApplicantDocumentsCard
                    applicants={applicants}
                    applicantDocumentsGroups={checklist.applicantDocuments}
                    activeApplicantId={activeApplicantId}
                    onActiveApplicantIdChange={onActiveApplicantIdChange}
                  />
                  <CaseDocumentsCard caseDocuments={checklist.caseDocuments} />
                  <NeedsAttentionCard unclassifiedFiles={checklist.unclassifiedFiles} />
                </div>
              </ExtractedFieldsProvider>
            </DocumentPreviewProvider>
          </EditDocumentProvider>
        </RemoveFileProvider>
      </AddDocumentProvider>

      <DocumentPreviewModal
        key={previewModal.target?.documentId ?? "idle-preview"}
        bankApplicationId={id}
        isOpen={previewModal.isOpen}
        onOpenChange={previewModal.onOpenChange}
        previewTarget={previewModal.isOpen ? previewModal.target : null}
        onDocServiceDocumentIdChange={(docServiceDocumentId) => {
          previewModal.patch({ docServiceDocumentId });
        }}
      />

      <EditDocumentModal
        key={editFile?.id ?? "idle-edit"}
        isOpen={isEditModalOpen}
        onOpenChange={editModal.onOpenChange}
        bankApplicationId={id}
        applicants={applicants}
        file={isEditModalOpen ? editFile : null}
        initialDocumentType={editInitialDocumentType}
        initialAssignTo={initialAssignTo}
        onBeginSplit={handleBeginSplit}
      />

      <SplitDocumentModal
        key={splitModal.target?.file.id ?? "idle-split"}
        isOpen={splitModal.isOpen}
        onOpenChange={splitModal.onOpenChange}
        bankApplicationId={id}
        applicants={applicants}
        file={splitModal.target?.file ?? null}
        initialDocumentType={splitModal.target?.initialDocumentType}
        initialAssignTo={splitModal.target?.initialAssignTo}
      />

      <RemoveFileModal
        key={removeModal.target?.file.id ?? "idle-remove"}
        isOpen={removeModal.isOpen}
        onOpenChange={removeModal.onOpenChange}
        bankApplicationId={id}
        file={removeModal.target?.file ?? null}
      />

      <ExtractedFieldsModal
        key={extractedFieldsModal.target?.file.id ?? "idle-extracted-fields"}
        isOpen={extractedFieldsModal.isOpen}
        onOpenChange={extractedFieldsModal.onOpenChange}
        bankApplicationId={id}
        file={extractedFieldsModal.target?.file ?? null}
      />
    </>
  );
};
