import type { FC } from "react";

import { cn } from "@huspy/shared-ui";

import { ModalFooter, PillButton } from "@/components";

type Props = {
  statusMessage?: string;
  errorMessage?: string;
  onCancel: () => void;
  showConfirm?: boolean;
  canConfirm?: boolean;
  isSubmitting?: boolean;
  onConfirm?: () => void;
};

export const SplitModalFooter: FC<Props> = ({
  statusMessage,
  errorMessage,
  onCancel,
  showConfirm = false,
  canConfirm = false,
  isSubmitting = false,
  onConfirm,
}) => (
  <ModalFooter className={cn(showConfirm ? "items-center justify-between" : "justify-end")}>
    {errorMessage && <p className="text-xs text-destructive">{errorMessage}</p>}
    {!errorMessage && statusMessage && (
      <p className="text-xs text-muted-foreground">{statusMessage}</p>
    )}
    <div className="flex items-center gap-2">
      <PillButton type="button" buttonRole="secondary" onClick={onCancel} disabled={isSubmitting}>
        Cancel
      </PillButton>
      {showConfirm && (
        <PillButton type="button" disabled={!canConfirm || isSubmitting} onClick={onConfirm}>
          {isSubmitting ? "Splitting…" : "Confirm"}
        </PillButton>
      )}
    </div>
  </ModalFooter>
);
