import type { ExtractedFieldDataType } from "@/types";

/** Returns a user-facing validation message, or null when the value is valid. */
export const validateExtractedFieldValue = (
  value: string,
  dataType: ExtractedFieldDataType,
  options: string[] | null,
): string | null => {
  const trimmed = value.trim();
  if (trimmed.length === 0) return null;

  switch (dataType) {
    case "INTEGER":
      return /^-?\d+$/.test(trimmed) ? null : "Enter a whole number.";
    case "DECIMAL":
      return /^-?\d+(\.\d+)?$/.test(trimmed) ? null : "Enter a valid number.";
    case "DATE":
      return /^\d{4}-\d{2}-\d{2}$/.test(trimmed) && !Number.isNaN(Date.parse(trimmed))
        ? null
        : "Enter a valid date.";
    case "BOOLEAN":
      return trimmed === "true" || trimmed === "false" ? null : "Select Yes or No.";
    case "ENUM":
      if (!options?.length) return "No options configured for this field.";
      return options.includes(trimmed) ? null : "Select a valid option.";
    default:
      return null;
  }
};
