import { useCallback, useMemo, useState, type DragEvent } from "react";

import { useParams } from "@huspy/fe";
import { toast } from "@huspy/shared-ui";

import { useReorderDocumentFiles } from "@/api";
import type { ApplicantDocumentGroup } from "@/types";

import type {
  DropTarget,
  DraggedFile,
  ReorderableRow,
} from "@/routes/BankApplication/components/ChecklistWorkspace/components/DocumentRow/types";
import {
  buildReorderGroups,
  computeInsertionIndex,
  computeOrderRenames,
  getDropEdge,
  reorderFileList,
} from "@/routes/BankApplication/components/ChecklistWorkspace/components/ApplicantDocumentsCard/ApplicantDocumentTable/utils";
import { getDocumentActionAvailability } from "@/routes/BankApplication/components/ChecklistWorkspace/utils/getDocumentActionAvailability";

type UseChecklistFileReorderResult = {
  getReorderableRow: (groupKey: string, fileId: string | undefined) => ReorderableRow | undefined;
};

export const useChecklistFileReorder = (
  documents: ApplicantDocumentGroup[],
): UseChecklistFileReorderResult => {
  const { id: bankApplicationId } = useParams<{ id: string }>();
  const reorderFiles = useReorderDocumentFiles();
  const [dragged, setDragged] = useState<DraggedFile | null>(null);
  const [dropTarget, setDropTarget] = useState<DropTarget | null>(null);

  const reorderGroups = useMemo(() => buildReorderGroups(documents), [documents]);

  const clearDragState = useCallback(() => {
    setDragged(null);
    setDropTarget(null);
  }, []);

  const handleDrop = useCallback(
    async (groupKey: string, targetFileId: string) => {
      const source = dragged;
      const target = dropTarget;
      clearDragState();
      if (!source || source.groupKey !== groupKey || !bankApplicationId) return;
      if (source.fileId === targetFileId) return;

      const group = reorderGroups.get(groupKey);
      if (!group) return;

      const { files, applicantId } = group;
      const fromIndex = files.findIndex((file) => file.id === source.fileId);
      const targetIndex = files.findIndex((file) => file.id === targetFileId);
      if (fromIndex < 0 || targetIndex < 0) return;

      const toIndex = computeInsertionIndex(
        fromIndex,
        targetIndex,
        target?.edge,
        target?.fileId === targetFileId,
      );
      if (toIndex === null) return;

      const reordered = reorderFileList(files, fromIndex, toIndex);
      const renames = computeOrderRenames(reordered, applicantId);

      if (renames.length === 0) return;

      try {
        await reorderFiles.mutateAsync({
          bankApplicationId,
          groupKey,
          orderedFileIds: reordered.map((file) => file.id),
          renames,
        });
      } catch {
        toast.error("Failed to reorder documents.");
      }
    },
    [bankApplicationId, clearDragState, dragged, dropTarget, reorderGroups, reorderFiles],
  );

  const getReorderableRow = useCallback(
    (groupKey: string, fileId: string | undefined): ReorderableRow | undefined => {
      const group = reorderGroups.get(groupKey);
      if (!fileId || (group?.files.length ?? 0) <= 1) return undefined;

      const file = group?.files.find((groupFile) => groupFile.id === fileId);
      const reorderAvailability = getDocumentActionAvailability("reorder", file?.processingStatus);
      const draggable = !reorderFiles.isPending && !reorderAvailability.disabled;

      return {
        isDragging: dragged?.fileId === fileId,
        dropIndicator:
          dropTarget?.fileId === fileId && dragged?.fileId !== fileId ? dropTarget.edge : null,
        isPending: reorderFiles.isPending,
        dragHandle: {
          draggable,
          disabledTooltip: reorderAvailability.disabled ? reorderAvailability.tooltip : undefined,
          "aria-grabbed": dragged?.fileId === fileId,
          onDragStart: (e: DragEvent<HTMLDivElement>) => {
            if (!draggable) return;
            e.stopPropagation();
            setDragged({ groupKey, fileId });
          },
          onDragEnd: clearDragState,
        },
        onDragOver: (e: DragEvent<HTMLDivElement>) => {
          if (dragged?.groupKey !== groupKey) return;
          e.preventDefault();
          if (dragged.fileId === fileId) return;
          const edge = getDropEdge(e);
          setDropTarget((prev) =>
            prev?.fileId === fileId && prev.edge === edge ? prev : { fileId, edge },
          );
        },
        onDrop: () => handleDrop(groupKey, fileId),
      };
    },
    [clearDragState, dragged, dropTarget, reorderGroups, handleDrop, reorderFiles.isPending],
  );

  return { getReorderableRow };
};
