import { useState, type FC } from "react";

import { Input } from "@huspy/shared-ui";

import { formatMonthlyAmountDraft, isMonthlyAmountDraft, parseMonthlyAmount } from "../../utils";
import { LineCurrencyLabel } from "./LineCurrencyLabel";

type Props = {
  value: string;
  currency: string;
  isCurrencyUndetected: boolean;
  disabled: boolean;
  onCommit: (amount: number) => void | Promise<void>;
};

export const MonthlyAmountInput: FC<Props> = ({
  value,
  currency,
  isCurrencyUndetected,
  disabled,
  onCommit,
}) => {
  const savedAmount = parseMonthlyAmount(value) ?? 0;
  const [draft, setDraft] = useState(() => formatMonthlyAmountDraft(savedAmount));
  const [invalid, setInvalid] = useState(false);
  const [prevSavedAmount, setPrevSavedAmount] = useState(savedAmount);

  if (savedAmount !== prevSavedAmount) {
    setPrevSavedAmount(savedAmount);
    setDraft(formatMonthlyAmountDraft(savedAmount));
    setInvalid(false);
  }

  const revertToSaved = () => {
    setDraft(formatMonthlyAmountDraft(savedAmount));
    setInvalid(false);
  };

  const handleBlur = async () => {
    const parsed = parseMonthlyAmount(draft);
    if (parsed === null) {
      revertToSaved();
      setInvalid(true);
      return;
    }

    if (parsed === savedAmount) {
      revertToSaved();
      return;
    }

    setInvalid(false);

    try {
      await onCommit(parsed);
      revertToSaved();
    } catch {
      revertToSaved();
    }
  };

  return (
    <div className="flex items-center justify-center gap-1">
      <LineCurrencyLabel currency={currency} isUndetected={isCurrencyUndetected} />
      <Input
        type="text"
        inputMode="decimal"
        value={draft}
        disabled={disabled}
        aria-invalid={invalid || undefined}
        onChange={(event) => {
          const next = event.target.value;
          if (!isMonthlyAmountDraft(next)) return;

          setDraft(next);
          setInvalid(false);
        }}
        onBlur={() => {
          void handleBlur();
        }}
        onKeyDown={(event) => {
          if (event.key === "Enter") {
            event.currentTarget.blur();
          }
        }}
        className="h-7 w-24 px-2 text-center text-[11px] tabular-nums selection:bg-revert selection:text-revert"
      />
    </div>
  );
};
