import { useCallback, useMemo, useState } from "react";

import { toast } from "@huspy/shared-ui";

import {
  useCalculateBankPolicyChecks,
  useCalculateDocumentValidationChecks,
  useCalculateEligibilityChecks,
  usePatchDocumentExtractedFields,
} from "@/api";
import type { DocumentExtractedFields } from "@/types";

import type { ExtractedFieldsFieldBindings } from "../types";
import {
  buildExtractedFieldsDraft,
  getExtractedFieldValueByKey,
} from "../utils/buildExtractedFieldsDraft";
import { collectExtractedFieldErrors } from "../utils/collectExtractedFieldErrors";
import { serializeExtractedFieldValue } from "../utils/serializeExtractedFieldValue";

/** Eligibility checks only consume data extracted from these document types. */
const ELIGIBILITY_RELEVANT_DOCUMENT_TYPES = ["BANK_STATEMENT", "PAYSLIP"];

const BANK_POLICY_CHECKS_RECALC_ERROR =
  "Changes saved, but bank policy checks could not be refreshed. Recalculate them manually.";
const DOCUMENT_VALIDATION_CHECKS_RECALC_ERROR =
  "Changes saved, but document validation checks could not be refreshed. Recalculate them manually.";
const ELIGIBILITY_CHECKS_RECALC_ERROR =
  "Changes saved, but eligibility checks could not be refreshed. Recalculate them manually.";

type ExtractedFieldsDraft = {
  fieldBindings: ExtractedFieldsFieldBindings;
  save: () => void;
  saveError: string | null;
  hasChanges: boolean;
};

export const useExtractedFieldsDraft = (
  documentId: string,
  bankApplicationId: string,
  data: DocumentExtractedFields,
  onSaved: () => void,
): ExtractedFieldsDraft => {
  const patchFields = usePatchDocumentExtractedFields();
  const calculateBankPolicyChecks = useCalculateBankPolicyChecks();
  const calculateDocumentValidationChecks = useCalculateDocumentValidationChecks();
  const calculateEligibilityChecks = useCalculateEligibilityChecks();
  const serverDraft = useMemo(() => buildExtractedFieldsDraft(data), [data]);
  const [localOverrides, setLocalOverrides] = useState<Record<string, string>>({});
  const [fieldErrors, setFieldErrors] = useState<Record<string, string>>({});
  const [saveError, setSaveError] = useState<string | null>(null);

  const draft = useMemo(
    () => ({ ...serverDraft, ...localOverrides }),
    [localOverrides, serverDraft],
  );

  /** Edits that still differ from the saved value, so reverted fields are not sent. */
  const changedValues = useMemo(
    () =>
      Object.fromEntries(
        Object.entries(localOverrides).filter(
          ([key, value]) =>
            serializeExtractedFieldValue(value) !== getExtractedFieldValueByKey(data, key),
        ),
      ),
    [data, localOverrides],
  );

  const hasChanges = Object.keys(changedValues).length > 0;
  const isSaving = patchFields.isPending;

  const isFieldChanged = useCallback((key: string) => key in changedValues, [changedValues]);

  const setFieldValue = useCallback((key: string, value: string) => {
    setLocalOverrides((current) => ({ ...current, [key]: value }));
    setFieldErrors((current) => {
      if (!current[key]) return current;
      const next = { ...current };
      delete next[key];
      return next;
    });
  }, []);

  const validateField = useCallback(
    (key: string, value: string) => {
      const errors = collectExtractedFieldErrors(data, { [key]: value });
      setFieldErrors((current) => ({ ...current, ...errors }));
    },
    [data],
  );

  const save = useCallback(() => {
    if (!hasChanges || isSaving) return;

    const errors = collectExtractedFieldErrors(data, changedValues);
    setFieldErrors(errors);
    if (Object.keys(errors).length > 0) return;

    setSaveError(null);
    patchFields.mutate(
      {
        documentId,
        payload: {
          fields: Object.entries(changedValues).map(([key, value]) => ({
            key,
            value: serializeExtractedFieldValue(value),
          })),
        },
      },
      {
        onSuccess: () => {
          setLocalOverrides({});
          onSaved();

          calculateBankPolicyChecks.mutate(bankApplicationId, {
            onError: () => toast.error(BANK_POLICY_CHECKS_RECALC_ERROR),
          });
          calculateDocumentValidationChecks.mutate(bankApplicationId, {
            onError: () => toast.error(DOCUMENT_VALIDATION_CHECKS_RECALC_ERROR),
          });
          if (
            data.documentType &&
            ELIGIBILITY_RELEVANT_DOCUMENT_TYPES.includes(data.documentType)
          ) {
            calculateEligibilityChecks.mutate(bankApplicationId, {
              onError: () => toast.error(ELIGIBILITY_CHECKS_RECALC_ERROR),
            });
          }
        },
        onError: () => setSaveError("Could not save changes. Please try again."),
      },
    );
  }, [
    bankApplicationId,
    calculateBankPolicyChecks,
    calculateDocumentValidationChecks,
    calculateEligibilityChecks,
    changedValues,
    data,
    documentId,
    hasChanges,
    isSaving,
    onSaved,
    patchFields,
  ]);

  const fieldBindings = useMemo(
    () => ({ draft, setFieldValue, validateField, fieldErrors, isSaving, isFieldChanged }),
    [draft, fieldErrors, isFieldChanged, isSaving, setFieldValue, validateField],
  );

  return { fieldBindings, save, saveError, hasChanges };
};
