import { useState } from "react";

import { DEFAULT_CHECK_FILTERS } from "./constants";
import type { CheckVisualState, RuleCheckLike } from "./types";
import {
  filterChecksByVisualState,
  groupChecksByCategory,
  resolveActiveFilters,
  summarizeChecks,
  toggleCheckFilter,
} from "./utils";

export const useRuleCheckFilters = <T extends RuleCheckLike>(checks: T[]) => {
  const [selectedFilters, setSelectedFilters] = useState<CheckVisualState[]>(DEFAULT_CHECK_FILTERS);
  const summary = summarizeChecks(checks);
  const activeFilters = resolveActiveFilters(selectedFilters, summary);
  const groups = groupChecksByCategory(filterChecksByVisualState(checks, activeFilters));

  const toggleFilter = (state: CheckVisualState) => {
    setSelectedFilters(toggleCheckFilter(activeFilters, state));
  };

  return { summary, activeFilters, groups, toggleFilter };
};
