/**
 * Capitalizes only the first letter of a string
 * @param str - The string to capitalize
 * @returns The string with only the first letter capitalized
 * @example
 * capitalizeFirstLetter("hello world") // "Hello world"
 * capitalizeFirstLetter("HELLO WORLD") // "Hello world"
 * capitalizeFirstLetter("") // ""
 */
export function capitalizeFirstLetter(str: string | undefined): string | undefined {
  if (!str) return str;
  return str.charAt(0).toUpperCase() + str.replace(/_/g, " ").slice(1).toLowerCase();
}

export function toTitleCase(str: string | undefined): string | undefined {
  if (!str) return str;
  return str
    .replaceAll("_", " ")
    .toLowerCase()
    .replaceAll(/\b\w/g, (c) => c.toUpperCase());
}

/**
 * Converts a snake_case string to camelCase
 * @param str - The snake_case string to convert
 * @returns The string in camelCase format
 * @example
 * snakeToCamel("hello_world") // "helloWorld"
 * snakeToCamel("user_first_name") // "userFirstName"
 * snakeToCamel("") // ""
 * snakeToCamel("already_camelCase") // "alreadyCamelCase"
 */
export function snakeToCamel(str: string): string {
  if (!str) return "";

  const parts = str.toLowerCase().split("_").filter(Boolean);

  if (parts.length === 0) return "";

  return (
    parts[0] +
    parts
      .slice(1)
      .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
      .join("")
  );
}

/**
 * Filters a string to only include alphanumeric characters (letters and numbers)
 * @param value - The string to filter
 * @returns The string with only alphanumeric characters
 * @example
 * filterAlphanumeric("abc123!@#") // "abc123"
 * filterAlphanumeric("Unit-5A") // "Unit5A"
 * filterAlphanumeric("") // ""
 */
export function filterAlphanumeric(value: string): string {
  return value.replace(/[^a-zA-Z0-9]/g, "");
}

/**
 * Extracts the first word from a full name.
 * @example
 * firstName("Jane Doe") // "Jane"
 * firstName("  Alice  ") // "Alice"
 * firstName("") // ""
 */
export function firstName(name: string): string {
  return name.trim().split(/\s+/)[0] ?? name;
}

/**
 * Extracts initials from a name string
 * @param name - The name string to extract initials from
 * @param maxLength - Maximum length of initials to return (default: 2)
 * @returns The initials in uppercase, typically first and last initial if available
 * @example
 * getInitials("John Doe") // "JD"
 * getInitials("Mary Jane Watson") // "MW"
 * getInitials("Alice") // "AL"
 * getInitials("") // ""
 */
export function getInitials(name: string | undefined, maxLength = 2): string {
  if (!name) return "";
  // Remove all spaces and trim, then split by word boundaries if needed
  const cleanedName = name.replace(/\s+/g, " ").trim();
  if (!cleanedName) return "";
  const parts = cleanedName.split(/\s+/).filter(Boolean);
  if (parts.length >= 2) {
    const first = parts[0]?.[0];
    const last = parts[parts.length - 1]?.[0];
    if (first && last) {
      return (first + last).toUpperCase().slice(0, maxLength);
    }
  }
  return cleanedName.replace(/\s+/g, "").substring(0, maxLength).toUpperCase();
}

/**
 * Caps new text at maxLength.
 * Text that is already over the limit is left unchanged until the next value is shorter,
 * so the user can delete characters without the tail being cut off.
 */
export function applyTextLimit(current: string, next: string, maxLength: number): string {
  if (next.length <= maxLength) return next;
  if (current.length > maxLength && next.length < current.length) return next;
  if (current.length <= maxLength) return next.slice(0, maxLength);
  return current;
}
