import type { ChecklistRowState } from "./RowStatusIcon";
import type { FileItemWithDocumentId, ProcessingStatus } from "@/types";
import { isProcessingInProgress } from "@/utils";
import { DocumentTypeCode } from "@/types";
import { getProcessingInProgressMessage } from "@/routes/BankApplication/components/ChecklistWorkspace/utils/getProcessingInProgressMessage";

export const getChecklistRowState = (
  isRequired: boolean,
  matchedFile: FileItemWithDocumentId | null,
): ChecklistRowState => {
  if (isProcessingInProgress(matchedFile?.processingStatus)) return "processing";
  if (isRequired) return matchedFile !== null ? "received" : "missing";
  return "providedNotRequired";
};

export const getChecklistRowStatusTooltip = (
  rowState: ChecklistRowState,
  processingStatus: ProcessingStatus | null | undefined,
): string | null => {
  switch (rowState) {
    case "processing":
      return getProcessingInProgressMessage(processingStatus);
    case "missing":
      return "Missing";
    case "providedNotRequired":
      return "Uploaded, but not required";
    case "received":
      return "Uploaded";
    default:
      return null;
  }
};

export const getFileCellLabel = (state: ChecklistRowState, fileName: string | undefined) => {
  if (fileName) return fileName;
  return state === "missing" ? "Missing" : "";
};

/** Label for a document type code; falls back to the raw code if missing from the list. */
export const getDocumentTypeLabel = (documentType: string, documentTypeCodes: DocumentTypeCode[]) =>
  documentTypeCodes.find((c) => c.type === documentType)?.label ?? documentType;
