import type { FC } from "react";
import { useFormContext, useWatch } from "react-hook-form";

import { FloatingLabelInput, FloatingLabelSelect } from "@huspy/shared-agents";
import { Button } from "@huspy/shared-ui";
import { Trash2 } from "@huspy/shared-icons";

import type { Bank as BankCatalogEntry } from "@/api";
import type { IncomeVerificationType, MortgageType } from "@/types";

import { MAX_TENOR_MONTHS } from "../../constants";
import type { CreateMortgageApplicationFormValues } from "../../types";
import {
  getIncomeVerificationTypeOptionsForBankId,
  getMortgageTypeOptionsForBankId,
  getSupportedDocLevelsForBankId,
  resolveIncomeVerificationTypeForBank,
  resolveMortgageTypeForBank,
} from "../../utils";

type Props = {
  idx: number;
  bankCatalog: BankCatalogEntry[];
  bankOptions: { value: string; label: string }[];
  showDocLevel: boolean;
  onRemove: () => void;
};

export const BankRow: FC<Props> = ({ idx, bankCatalog, bankOptions, showDocLevel, onRemove }) => {
  const {
    control,
    setValue,
    clearErrors,
    formState: { errors },
  } = useFormContext<CreateMortgageApplicationFormValues>();

  const banks = useWatch({ control, name: "banks" });
  const bank = banks?.[idx];
  const bankId = bank?.id ?? "";
  const mortgageType = bank?.mortgageType;
  const incomeVerificationType = bank?.incomeVerificationType;
  const tenorMonths = bank?.tenorMonths ?? "";
  const rowErrors = errors.banks?.[idx];
  const tenorError = rowErrors?.tenorMonths;
  const mortgageTypeOptions = getMortgageTypeOptionsForBankId(bankId, bankCatalog);
  const incomeVerificationTypeOptions = showDocLevel
    ? getIncomeVerificationTypeOptionsForBankId(bankId, bankCatalog)
    : [];
  const isTenorDisabled = !bankId;

  const handleBankChange = (nextBankId: string) => {
    const selectedBank = bankCatalog.find((catalogBank) => catalogBank.id === nextBankId);
    if (!selectedBank) return;

    const supportedDocLevels = getSupportedDocLevelsForBankId(nextBankId, bankCatalog);
    setValue(
      `banks.${idx}`,
      {
        id: nextBankId,
        mortgageType: resolveMortgageTypeForBank(
          mortgageType ?? null,
          selectedBank.supportedMortgageTypes,
        ),
        incomeVerificationType: showDocLevel
          ? resolveIncomeVerificationTypeForBank(incomeVerificationType ?? null, supportedDocLevels)
          : null,
        tenorMonths: bank?.tenorMonths ?? "",
      },
      { shouldDirty: true, shouldValidate: true },
    );
  };

  const gridClassName = showDocLevel
    ? "grid grid-cols-[minmax(0,0.8fr)_minmax(0,1fr)_minmax(0,0.72fr)_7.5rem_auto] items-start gap-3"
    : "grid grid-cols-[minmax(0,1fr)_minmax(0,1fr)_7.5rem_auto] items-start gap-3";

  return (
    <div className={gridClassName}>
      <FloatingLabelSelect
        label="Bank"
        options={bankOptions}
        value={bankId}
        onValueChange={handleBankChange}
        error={!!rowErrors?.id}
        errorMessage={rowErrors?.id?.message}
      />
      <FloatingLabelSelect
        label="Mortgage Type"
        options={mortgageTypeOptions}
        value={mortgageType ?? ""}
        disabled={!bankId}
        onValueChange={(value) => {
          // Radix echoes an empty value from its hidden native select
          // before the option list catches up; never a real selection.
          if (!value) return;

          setValue(`banks.${idx}.mortgageType`, value as MortgageType, {
            shouldDirty: true,
            shouldValidate: true,
          });
        }}
        error={!!rowErrors?.mortgageType}
        errorMessage={rowErrors?.mortgageType?.message}
      />
      {showDocLevel && (
        <FloatingLabelSelect
          label="Doc level"
          options={incomeVerificationTypeOptions}
          className="min-w-0"
          value={incomeVerificationType ?? ""}
          disabled={!bankId}
          onValueChange={(value) => {
            if (!value) return;

            setValue(`banks.${idx}.incomeVerificationType`, value as IncomeVerificationType, {
              shouldDirty: true,
              shouldValidate: true,
            });
          }}
          error={!!rowErrors?.incomeVerificationType}
          errorMessage={rowErrors?.incomeVerificationType?.message}
        />
      )}
      <FloatingLabelInput
        label="Tenor (months)"
        type="text"
        inputMode="numeric"
        className="h-14"
        value={tenorMonths}
        disabled={isTenorDisabled}
        onChange={(e) => {
          clearErrors(`banks.${idx}.tenorMonths`);
          const digits = e.target.value.replace(/\D/g, "");
          const nextValue = digits === "" ? "" : String(Math.min(MAX_TENOR_MONTHS, Number(digits)));
          setValue(`banks.${idx}.tenorMonths`, nextValue, {
            shouldDirty: true,
            shouldValidate: true,
          });
        }}
        error={!!tenorError}
        errorMessage={tenorError?.message}
      />
      <div className="flex h-14 items-center">
        <Button
          type="button"
          variant="ghost"
          size="icon"
          className="text-muted-foreground hover:text-destructive h-10 w-10 shrink-0"
          onClick={onRemove}
          aria-label={`Remove bank ${idx + 1}`}
        >
          <Trash2 className="size-4" />
        </Button>
      </div>
    </div>
  );
};
