import type { FC, KeyboardEvent, MouseEvent } from "react";

import { GripVertical } from "@huspy/shared-icons";
import { cn, Tooltip, TooltipContent, TooltipTrigger } from "@huspy/shared-ui";

import { useParams } from "@huspy/fe";

import { useDocumentTypeCodesForBankApplication } from "@/api";
import type { DocumentChecklistRow } from "@/types";
import { formatShortDateTime } from "@/utils";
import { ProcessingFailurePill } from "@/routes/BankApplication/components/ChecklistWorkspace/components/ProcessingFailurePill";
import { getProcessingFailureMessage } from "@/routes/BankApplication/components/ChecklistWorkspace/utils/getProcessingFailureMessage";
import { useDocumentPreview } from "@/routes/BankApplication/components/ChecklistWorkspace/context/DocumentPreviewContext";
import { toDocumentPreviewTarget } from "@/routes/BankApplication/components/ChecklistWorkspace/utils/previewTarget";
import {
  ignoreRowClickProps,
  isRowClickIgnored,
} from "@/routes/BankApplication/components/ChecklistWorkspace/utils/rowClick";

import { DOCUMENT_CHECKLIST_TABLE_GRID } from "./constants";
import { DocumentRowActions } from "./DocumentRowActions";
import { ReorderableRowShell } from "./ReorderableRowShell";
import { RowStatusIcon } from "./RowStatusIcon";
import {
  getChecklistRowState,
  getChecklistRowStatusTooltip,
  getDocumentTypeLabel,
  getFileCellLabel,
} from "./utils";
import type { DocumentRowVariant, ReorderableRow } from "./types";

type Props = {
  data: DocumentChecklistRow;
  variant: DocumentRowVariant;
  /** Present when the document can be drag-reordered against its siblings. */
  reorderable?: ReorderableRow;
};

export const DocumentRow: FC<Props> = ({ data, variant, reorderable }) => {
  const { id: bankApplicationId } = useParams<{ id: string }>();
  const { beginPreview } = useDocumentPreview();
  const { data: documentTypeCodes = [] } = useDocumentTypeCodesForBankApplication(
    bankApplicationId,
    {
      includeMergeTargets: true,
    },
  );
  const { matchedFile, type, isRequired } = data;

  const rowState = getChecklistRowState(isRequired, matchedFile);
  const documentTypeLabel = getDocumentTypeLabel(type, documentTypeCodes);
  const fileLabel = getFileCellLabel(rowState, matchedFile?.fileName);
  const statusTooltipText = getChecklistRowStatusTooltip(rowState, matchedFile?.processingStatus);
  const pillFailureMessage =
    variant === "mergeChild" && matchedFile?.processingStatus === "MERGE_FAILED"
      ? null
      : getProcessingFailureMessage(matchedFile?.processingStatus);

  const openPreview = (event: MouseEvent<HTMLElement> | KeyboardEvent<HTMLElement>) => {
    if (!matchedFile || isRowClickIgnored(event)) return;
    beginPreview(toDocumentPreviewTarget(matchedFile));
  };

  return (
    <ReorderableRowShell reorderable={reorderable}>
      <div
        role={matchedFile ? "button" : undefined}
        tabIndex={matchedFile ? 0 : undefined}
        onClick={matchedFile ? openPreview : undefined}
        onKeyDown={
          matchedFile
            ? (event) => {
                if (event.key !== "Enter" && event.key !== " ") return;

                event.preventDefault();
                openPreview(event);
              }
            : undefined
        }
        className={cn(
          "group grid items-center gap-3 rounded-lg px-3 py-2 hover:bg-muted",
          matchedFile && "cursor-pointer",
          DOCUMENT_CHECKLIST_TABLE_GRID,
        )}
      >
        <div
          className={cn("flex min-w-0 items-center gap-2", {
            "ml-7": variant === "standalone",
            "ml-11 border-l-2 border-grey-60 pl-3.25": variant === "mergeChild",
          })}
        >
          {reorderable &&
            (() => {
              const dragHandle = (
                <div
                  {...ignoreRowClickProps}
                  draggable={reorderable.dragHandle.draggable}
                  onDragStart={reorderable.dragHandle.onDragStart}
                  onDragEnd={reorderable.dragHandle.onDragEnd}
                  className={cn(
                    "-ml-5 flex w-3 shrink-0 touch-none items-center justify-center opacity-0 group-hover:opacity-100",
                    reorderable.dragHandle.draggable && "cursor-grab active:cursor-grabbing",
                  )}
                >
                  <GripVertical className="size-3 text-muted-foreground" aria-hidden />
                </div>
              );

              if (reorderable.dragHandle.draggable || !reorderable.dragHandle.disabledTooltip) {
                return dragHandle;
              }

              return (
                <Tooltip>
                  <TooltipTrigger asChild>{dragHandle}</TooltipTrigger>
                  <TooltipContent>{reorderable.dragHandle.disabledTooltip}</TooltipContent>
                </Tooltip>
              );
            })()}

          {statusTooltipText ? (
            <Tooltip>
              <TooltipTrigger asChild>
                <span className="inline-flex">
                  <RowStatusIcon state={rowState} />
                </span>
              </TooltipTrigger>
              <TooltipContent>{statusTooltipText}</TooltipContent>
            </Tooltip>
          ) : (
            <RowStatusIcon state={rowState} />
          )}

          <span className="min-w-0 truncate text-[13px] text-foreground">{documentTypeLabel}</span>

          {pillFailureMessage && <ProcessingFailurePill message={pillFailureMessage} />}
        </div>

        <div className="flex min-w-0 items-center gap-2">
          <span
            title={matchedFile?.fileName}
            className={cn(
              "min-w-0 truncate text-xs",
              matchedFile
                ? "text-grey-700"
                : rowState === "missing"
                  ? "text-muted-foreground"
                  : "text-grey-300",
            )}
          >
            {fileLabel}
          </span>
        </div>

        <span className="text-xs tabular-nums text-muted-foreground">
          {matchedFile ? formatShortDateTime(matchedFile.updatedAt) : "—"}
        </span>

        <DocumentRowActions data={data} />
      </div>
    </ReorderableRowShell>
  );
};
