import type { FC } from "react";

import { DocumentPreviewThumbnail } from "./DocumentPreviewThumbnail";

type Props = {
  pageCount: number;
  isPdfError: boolean;
  focusedPage: number;
  pageRotate?: number;
  onFocusPage: (page: number) => void;
};

export const DocumentPreviewThumbnailList: FC<Props> = ({
  pageCount,
  isPdfError,
  focusedPage,
  pageRotate,
  onFocusPage,
}) => {
  if (isPdfError) {
    return (
      <p role="alert" className="px-2 py-10 text-center text-xs text-destructive">
        Couldn&apos;t read the document pages.
      </p>
    );
  }

  return (
    <div className="space-y-1">
      {Array.from({ length: pageCount }, (_, index) => {
        const page = index + 1;

        return (
          <DocumentPreviewThumbnail
            key={page}
            page={page}
            isFocused={focusedPage === page}
            pageRotate={pageRotate}
            onFocus={onFocusPage}
          />
        );
      })}
    </div>
  );
};
