import type { FC } from "react";

import type { ExtractedFieldGroupColumn } from "@/types";

import type { ParentRow } from "../utils/buildGroupSections";
import { getSingularGroupLabel } from "../utils/getSingularGroupLabel";

import { ChildRowsSection } from "./ChildRowsSection";
import { ParentRowFields } from "./ParentRowFields";

type Props = {
  groupLabel: string;
  position: number;
  template: ExtractedFieldGroupColumn[];
  parentRow: ParentRow;
};

export const ParentRowCard: FC<Props> = ({ groupLabel, position, template, parentRow }) => {
  return (
    <article className="space-y-4 rounded-lg border border-border bg-card p-4">
      <header className="flex items-center gap-2 border-b border-border pb-3">
        <span
          aria-hidden
          className="flex size-6 shrink-0 items-center justify-center rounded-full bg-muted text-xs font-medium text-muted-foreground"
        >
          {position}
        </span>
        <h4 className="text-sm font-medium text-foreground">{getSingularGroupLabel(groupLabel)}</h4>
      </header>

      <ParentRowFields template={template} fields={parentRow.row.fields} />

      {parentRow.childRows.map((childRows) => (
        <ChildRowsSection
          key={childRows.group.name}
          group={childRows.group}
          rows={childRows.rows}
        />
      ))}
    </article>
  );
};
