import type { SyntheticEvent } from "react";
import { useEffect, useMemo, useRef } from "react";
import { FormProvider, useForm, useWatch } from "react-hook-form";

import { useFlag } from "@huspy/fe";

import { ModalFooter, PillButton } from "@/components";
import { useCreateMortgageApplication, useBanks } from "@/api";

import type { CreateMortgageApplicationFormValues } from "./types";
import {
  createCrossFieldResolver,
  isCreateCaseDocLevelRequired,
  isCreateMortgageApplicationFormComplete,
  toCreateMortgageApplicationPayload,
  validateCreateMortgageApplicationForm,
} from "./utils";
import { defaultValues } from "./defaultValues";
import { OpportunityLookupSection } from "./components/OpportunityLookupSection/OpportunityLookupSection";
import { CaseDetailsSection } from "./components/CaseDetailsSection/CaseDetailsSection";
import { ApplicantsSection } from "./components/ApplicantsSection/ApplicantsSection";
import { BanksSection } from "./components/BanksSection/BanksSection";
import { DocumentsSection } from "./components/DocumentsSection/DocumentsSection";
import { CREATE_CASE_DOC_LEVEL_FLAG } from "./constants";
export type Props = {
  onOpenChange: (open: boolean) => void;
};

export function CreateMortgageApplicationForm({ onOpenChange }: Props) {
  const createMortgageApplication = useCreateMortgageApplication();
  const { data: banksData } = useBanks();
  const bankCatalog = useMemo(() => banksData?.data ?? [], [banksData?.data]);
  const isCreateCaseDocLevelEnabled = useFlag(CREATE_CASE_DOC_LEVEL_FLAG);
  const resolver = useMemo(
    () => createCrossFieldResolver(bankCatalog, isCreateCaseDocLevelEnabled),
    [bankCatalog, isCreateCaseDocLevelEnabled],
  );
  const methods = useForm<CreateMortgageApplicationFormValues>({
    mode: "onChange",
    reValidateMode: "onChange",
    resolver,
    defaultValues,
  });

  const {
    control,
    formState: { errors },
    getValues,
    setValue,
    setError,
    clearErrors,
    trigger,
  } = methods;
  const [opportunityDetails, applicants, banks, documentId] = useWatch({
    control,
    name: ["opportunityDetails", "applicants", "banks", "documentId"],
  });

  useEffect(() => {
    if (bankCatalog.length === 0) return;

    getValues("banks").forEach((bank, idx) => {
      if (bank.id) {
        void trigger(`banks.${idx}.id`);
      }
    });
  }, [opportunityDetails?.propertyStatus, bankCatalog, getValues, trigger]);

  const showDocLevel = isCreateCaseDocLevelRequired(applicants ?? [], isCreateCaseDocLevelEnabled);
  const previousShowDocLevelRef = useRef(showDocLevel);

  useEffect(() => {
    if (previousShowDocLevelRef.current === showDocLevel) return;

    previousShowDocLevelRef.current = showDocLevel;
    if (showDocLevel) return;

    getValues("banks").forEach((_, idx) => {
      setValue(`banks.${idx}.incomeVerificationType`, null, {
        shouldDirty: true,
        shouldValidate: true,
      });
    });
  }, [getValues, showDocLevel, setValue]);

  useEffect(() => {
    void trigger();
  }, [isCreateCaseDocLevelEnabled, trigger]);

  useEffect(() => {
    if (bankCatalog.length === 0) return;

    getValues("applicants").forEach((applicant, idx) => {
      if (applicant.relationshipType) {
        void trigger(`applicants.${idx}.relationshipType`);
      }
    });
  }, [banks, bankCatalog, getValues, trigger]);

  const handleSubmit = (e: SyntheticEvent<HTMLFormElement>) => {
    e.preventDefault();
    const values = getValues();
    if (
      !validateCreateMortgageApplicationForm(
        values,
        setError,
        clearErrors,
        bankCatalog,
        isCreateCaseDocLevelEnabled,
      )
    )
      return;
    const payload = toCreateMortgageApplicationPayload(values, isCreateCaseDocLevelEnabled);
    createMortgageApplication.mutate(payload, {
      onSuccess: () => onOpenChange(false),
      onError: (err) => {
        setError("root", {
          message:
            err instanceof Error ? err.message : "Could not create the mortgage application.",
        });
      },
    });
  };

  const canSubmit =
    isCreateMortgageApplicationFormComplete(
      { opportunityDetails, applicants, banks, documentId },
      bankCatalog,
      isCreateCaseDocLevelEnabled,
    ) && !createMortgageApplication.isPending;
  return (
    <FormProvider {...methods}>
      <form className="flex min-h-0 flex-1 flex-col gap-0" onSubmit={handleSubmit}>
        <div className="min-h-0 flex-1 space-y-1 overflow-y-auto px-6 py-5">
          <OpportunityLookupSection />
          <CaseDetailsSection />
          <ApplicantsSection />
          <BanksSection showDocLevel={showDocLevel} />
          <DocumentsSection />
        </div>

        {errors.root?.message && (
          <p role="alert" className="px-6 text-sm text-destructive">
            {errors.root.message}
          </p>
        )}

        <ModalFooter className="justify-between">
          <PillButton type="button" buttonRole="secondary" onClick={() => onOpenChange(false)}>
            Cancel
          </PillButton>
          <PillButton type="submit" disabled={!canSubmit}>
            Create
          </PillButton>
        </ModalFooter>
      </form>
    </FormProvider>
  );
}
