/** Poll frequently while a bank application tab is on screen, and back off while it isn't. */
const ACTIVE_TAB_REFETCH_INTERVAL_MS = 5000;
const INACTIVE_TAB_REFETCH_INTERVAL_MS = 60000;

export type UseBankApplicationsParams = {
  page: number;
  applicantName?: string;
  bankId?: string;
  createdAtFrom?: string;
  createdAtTo?: string;
  createdById?: string;
};

export const useBankApplications = ({
  page,
  applicantName,
  bankId,
  createdAtFrom,
  createdAtTo,
  createdById,
}: UseBankApplicationsParams) => {
  const trimmedApplicationName = applicantName?.trim();
  const trimmedBankId = bankId?.trim();
  const trimmedCreatedById = createdById?.trim();
  const trimmedCreatedAtFrom = createdAtFrom?.trim() || undefined;
  const trimmedCreatedAtTo = createdAtTo?.trim() || undefined;

  return useQuery<MortgageApplicationsPage>({
    queryKey: [
      "bankApplications",
      page,
      trimmedApplicationName,
      trimmedBankId,
      trimmedCreatedAtFrom,
      trimmedCreatedAtTo,
      trimmedCreatedById,
    ],
    queryFn: async ({ signal }) => {
      const response = await getCreditOpsBankApplications(
        {
          page,
          size: BANK_APPLICATIONS_DEFAULT_PAGE_SIZE,
          ...(trimmedApplicationName ? { applicantName: trimmedApplicationName } : {}),
          ...(trimmedBankId ? { bankId: trimmedBankId } : {}),
          ...(trimmedCreatedAtFrom ? { createdAtFrom: trimmedCreatedAtFrom } : {}),
          ...(trimmedCreatedAtTo ? { createdAtTo: trimmedCreatedAtTo } : {}),
          ...(trimmedCreatedById ? { createdById: trimmedCreatedById } : {}),
        },
        { signal },
      );

      return {
        data: toMortgageApplicationRows(response.data),
        metadata: response.metadata,
      };
    },
    placeholderData: keepPreviousData,
  });
};

