export const useBankApplication = (id: string | undefined) => {
  const location = useLocation();
  const [searchParams] = useSearchParams();
  const useMockEligibilityChecks = isMockEligibilityChecksEnabled(searchParams);
  const [activeTab] = useBankApplicationTab();

  return useQuery<BankApplication>({
    queryKey: ["bankApplication", id, useMockEligibilityChecks],
    enabled: !!id,
    queryFn: async () => {
      const bankApplicationPageData = await getBankApplicationPageData(id!);
      return applyMockEligibilityChecksBankApplication(
        applyChecklistStatusMocks(toBankApplication(bankApplicationPageData)),
        searchParams,
      );
    },
    refetchInterval: (query) => {
      const match = location.pathname.match(/\/bank-applications\/([^/]+)/);
      const activeId = match?.[1];
      if (activeId !== query.queryKey[1]) return false;

      if (query.state.data?.unzipInProgress) return 1000;

      return activeTab === "checklist"
        ? ACTIVE_TAB_REFETCH_INTERVAL_MS
        : INACTIVE_TAB_REFETCH_INTERVAL_MS;
    },
  });
};

