const DOCUMENT_UPLOAD_POLL_INTERVAL_MS = 1000;

type UseDocumentOptions = {
  pollUntilUploaded?: boolean;
};

export const useDocument = (documentId: string | undefined, options?: UseDocumentOptions) =>
  useQuery<DocumentDetailResponse>({
    queryKey: ["document", documentId],
    queryFn: ({ signal }) => getDocument(documentId!, { signal }),
    enabled: !!documentId,
    refetchInterval: (query) => {
      if (!options?.pollUntilUploaded) return false;
      const data = query.state.data;
      if (!data) return DOCUMENT_UPLOAD_POLL_INTERVAL_MS;
      return data.isUploaded ? false : DOCUMENT_UPLOAD_POLL_INTERVAL_MS;
    },
  });

