/**
 * Document type codes for a bank application.
 * Every bank application is tied to one bank.
`bankId` comes from cached `useBankApplication` data.
Pass `includeMergeTargets` where labels are resolved (it adds KYC and *_CUMULATIVE); leave it
off for document type pickers so merge targets stay unselectable.
*/
export const useDocumentTypeCodesForBankApplication = (
  bankApplicationId: string | undefined,
  { includeMergeTargets = false }: { includeMergeTargets?: boolean } = {},
) => {
  const { data: bankApplicationData } = useBankApplication(bankApplicationId);
  const bankId = bankApplicationData?.bank.id;

  return useQuery<DocumentTypeCode[]>({
    queryKey: ["documentTypeCodes", bankId, { includeMergeTargets }],
    enabled: !!bankId,
    queryFn: async () => {
      const { data } = await getDocumentTypeCodes({ bankId: bankId!, includeMergeTargets });
      return sortDocumentTypeCodesByScope(data.map(toDocumentTypeCode));
    },
  });
};

