export type ReorderDocumentFilesVariables = {
  bankApplicationId: string;
  groupKey: string;
  orderedFileIds: string[];
  renames: DocumentRename[];
};

const reorderDocumentFilesWithRollback = async (renames: DocumentRename[]) => {
  const results = await Promise.allSettled(
    renames.map(({ documentId, fileName, applicantId }) =>
      updateDocument(documentId, { fileName, applicantId }),
    ),
  );

  const hasFailure = results.some((result) => result.status === "rejected");
  if (!hasFailure) return;

  const succeededRenames = renames.filter((_, index) => results[index].status === "fulfilled");

  if (succeededRenames.length > 0) {
    await Promise.allSettled(
      succeededRenames.map(({ documentId, previousFileName, applicantId }) =>
        updateDocument(documentId, { fileName: previousFileName, applicantId }),
      ),
    );
  }

  throw new Error("Failed to reorder documents.");
};

/** Renames files with order prefixes; the backend sorts by filename, which drives merge order. */
export const useReorderDocumentFiles = () => {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: ({ renames }: ReorderDocumentFilesVariables) =>
      reorderDocumentFilesWithRollback(renames),
    onMutate: async (variables) => {
      const { bankApplicationId } = variables;
      await queryClient.cancelQueries({ queryKey: ["bankApplication", bankApplicationId] });

      const previous = queryClient.getQueryData<BankApplication>([
        "bankApplication",
        bankApplicationId,
      ]);

      if (previous) {
        queryClient.setQueryData(
          ["bankApplication", bankApplicationId],
          applyOptimisticChecklistReorder(
            previous,
            variables.groupKey,
            variables.orderedFileIds,
            variables.renames,
          ),
        );
      }

      return { previous };
    },
    onError: (_error, variables, context) => {
      if (context?.previous) {
        queryClient.setQueryData(
          ["bankApplication", variables.bankApplicationId],
          context.previous,
        );
      }
    },
    onSettled: (_data, _error, variables) => {
      void queryClient.invalidateQueries({
        queryKey: ["bankApplication", variables.bankApplicationId],
      });
    },
  });
};

