export const useEligibilityChecks = (bankApplicationId: string | undefined) => {
  const [searchParams] = useSearchParams();
  const useMock = isMockEligibilityChecksEnabled(searchParams);
  const [activeTab] = useBankApplicationTab();

  return useQuery<EligibilityChecks>({
    queryKey: ["eligibilityChecks", bankApplicationId, useMock],
    queryFn: async ({ signal }) => {
      if (useMock) {
        return mockEligibilityChecks;
      }

      const response = await getEligibilityChecks(bankApplicationId!, { signal });
      return toEligibilityChecks(response);
    },
    enabled: !!bankApplicationId,
    retry: shouldRetryEligibilityChecks,
    refetchInterval: (query) => {
      if (query.state.status === "error") return false;

      return activeTab === "eligibility-checks"
        ? ACTIVE_TAB_REFETCH_INTERVAL_MS
        : INACTIVE_TAB_REFETCH_INTERVAL_MS;
    },
  });
};

