import type { FC } from "react";

import type { Checklist } from "@/types";
import { getChecklistCounts } from "@/routes/BankApplication/utils";

type Props = {
  checklist: Checklist;
};

export const ChecklistTabBadge: FC<Props> = ({ checklist }) => {
  const { missing } = getChecklistCounts(checklist);

  if (missing === 0) return null;

  return (
    <span className="rounded-full bg-destructive/14 px-1.5 text-[10px] font-semibold text-destructive tabular-nums">
      {missing}
    </span>
  );
};
