import { createContext, type FC, type ReactNode, useContext, useMemo } from "react";

import type { FileItemWithDocumentId } from "@/types";

export type ExtractedFieldsTarget = {
  file: FileItemWithDocumentId;
};

type ExtractedFieldsContextValue = {
  beginExtractedFields: (target: ExtractedFieldsTarget) => void;
};

const ExtractedFieldsContext = createContext<ExtractedFieldsContextValue | null>(null);

type ProviderProps = {
  children: ReactNode;
  onBeginExtractedFields: (target: ExtractedFieldsTarget) => void;
};

export const ExtractedFieldsProvider: FC<ProviderProps> = ({
  children,
  onBeginExtractedFields,
}) => {
  const value = useMemo(
    () => ({
      beginExtractedFields: onBeginExtractedFields,
    }),
    [onBeginExtractedFields],
  );

  return (
    <ExtractedFieldsContext.Provider value={value}>{children}</ExtractedFieldsContext.Provider>
  );
};

export const useExtractedFields = (): ExtractedFieldsContextValue => {
  const ctx = useContext(ExtractedFieldsContext);
  if (!ctx) {
    throw new Error("useExtractedFields must be used within ExtractedFieldsProvider");
  }
  return ctx;
};
