import type { FieldError, FieldErrors, Resolver } from "react-hook-form";

import { PROPERTY_STATUS_TO_LABEL } from "@/constants";
import type { Bank } from "@/api";

import type {
  CreateMortgageApplicationFormIssue,
  CreateMortgageApplicationFormValues,
} from "@/routes/OpsQueue/components/CreateMortgageApplicationModal/CreateMortgageApplicationForm/types";
import { TRANSACTION_TYPE_TO_PROPERTY_STATUSES } from "@/routes/OpsQueue/components/CreateMortgageApplicationModal/CreateMortgageApplicationForm/constants";

import { getSupportedDocLevelsForBankId } from "./getSupportedDocLevelsForBankId";
import { getSupportedMortgageTypesForBankId } from "./getSupportedMortgageTypesForBankId";
import { getSupportedPropertyStatusesForBankId } from "./getSupportedPropertyStatusesForBankId";
import { getSupportedRelationshipTypesForBankId } from "./getSupportedRelationshipTypesForBankId";
import { isCreateCaseDocLevelRequired } from "./isCreateCaseDocLevelRequired";

const setFieldErrorAtPath = (errors: FieldErrors, path: string, message: string) => {
  const segments = path.split(".");
  let current: Record<string, unknown> | unknown[] = errors as Record<string, unknown>;

  for (let i = 0; i < segments.length; i++) {
    const segment = segments[i]!;
    const isLast = i === segments.length - 1;

    if (isLast) {
      (current as Record<string, unknown>)[segment] = {
        type: "validate",
        message,
      } satisfies FieldError;
      return;
    }

    const nextIsArrayIndex = /^\d+$/.test(segments[i + 1] ?? "");

    if (Array.isArray(current)) {
      const arrayIndex = Number(segment);
      while (current.length <= arrayIndex) {
        current.push({});
      }
      if (current[arrayIndex] == null || typeof current[arrayIndex] !== "object") {
        current[arrayIndex] = {};
      }
      current = current[arrayIndex] as Record<string, unknown>;
      continue;
    }

    const record = current as Record<string, unknown>;
    if (!(segment in record) || record[segment] == null) {
      record[segment] = nextIsArrayIndex ? [] : {};
    }
    current = record[segment] as Record<string, unknown> | unknown[];
  }
};

const issuesToFieldErrors = (issues: CreateMortgageApplicationFormIssue[]): FieldErrors => {
  const errors: FieldErrors = {};
  for (const issue of issues) {
    setFieldErrorAtPath(errors, issue.name, issue.message);
  }
  return errors;
};

export const collectCrossFieldIssues = (
  values: CreateMortgageApplicationFormValues,
  bankCatalog: Bank[] = [],
  isCreateCaseDocLevelEnabled = false,
): CreateMortgageApplicationFormIssue[] => {
  const { opportunityDetails, applicants, banks } = values;
  const issues: CreateMortgageApplicationFormIssue[] = [];

  if (
    opportunityDetails.transactionType &&
    opportunityDetails.propertyStatus &&
    !TRANSACTION_TYPE_TO_PROPERTY_STATUSES[opportunityDetails.transactionType].includes(
      opportunityDetails.propertyStatus,
    )
  ) {
    issues.push({
      name: "opportunityDetails.propertyStatus",
      message: "Property status is not allowed for this transaction type",
    });
  }

  if (bankCatalog.length === 0) return issues;

  banks.forEach((bank, idx) => {
    if (!bank.id) return;

    if (opportunityDetails.propertyStatus) {
      const supportedPropertyStatuses = getSupportedPropertyStatusesForBankId(bank.id, bankCatalog);
      if (!supportedPropertyStatuses.includes(opportunityDetails.propertyStatus)) {
        issues.push({
          name: `banks.${idx}.id`,
          message: `Not available for ${PROPERTY_STATUS_TO_LABEL[opportunityDetails.propertyStatus]} properties`,
        });
      }
    }

    if (!bank.mortgageType) return;

    const supportedMortgageTypes = getSupportedMortgageTypesForBankId(bank.id, bankCatalog);
    if (!supportedMortgageTypes.includes(bank.mortgageType)) {
      issues.push({
        name: `banks.${idx}.mortgageType`,
        message: "Mortgage type is not available for this bank",
      });
    }

    if (
      isCreateCaseDocLevelRequired(applicants, isCreateCaseDocLevelEnabled) &&
      bank.incomeVerificationType
    ) {
      const supportedDocLevels = getSupportedDocLevelsForBankId(bank.id, bankCatalog);
      if (
        supportedDocLevels.length > 0 &&
        !supportedDocLevels.includes(bank.incomeVerificationType)
      ) {
        issues.push({
          name: `banks.${idx}.incomeVerificationType`,
          message: "Doc level is not available for this bank",
        });
      }
    }
  });

  applicants.forEach((applicant, idx) => {
    if (!applicant.relationshipType) return;

    const conflictingBankNames = banks
      .filter((bank) => bank.id)
      .filter((bank) => {
        const supportedRelationshipTypes = getSupportedRelationshipTypesForBankId(
          bank.id!,
          bankCatalog,
        );
        return !supportedRelationshipTypes.includes(applicant.relationshipType!);
      })
      .map((bank) => bankCatalog.find((catalogBank) => catalogBank.id === bank.id)?.name)
      .filter((name): name is string => name != null);

    if (conflictingBankNames.length > 0) {
      issues.push({
        name: `applicants.${idx}.relationshipType`,
        message: `Not supported by ${conflictingBankNames.join(", ")}`,
      });
    }
  });

  return issues;
};

export const createCrossFieldResolver =
  (
    bankCatalog: Bank[],
    isCreateCaseDocLevelEnabled = false,
  ): Resolver<CreateMortgageApplicationFormValues> =>
  async (values) => {
    const issues = collectCrossFieldIssues(values, bankCatalog, isCreateCaseDocLevelEnabled);

    if (issues.length === 0) return { values, errors: {} };
    return { values: {}, errors: issuesToFieldErrors(issues) };
  };
