const MINOR_UNITS_PER_MAJOR = 100;

export const toMajorUnits = (amountMinor: number): number => amountMinor / MINOR_UNITS_PER_MAJOR;

/** Rounds away floating-point noise so the API always receives an integer. */
export const toMinorUnits = (amountMajor: number): number =>
  Math.round(amountMajor * MINOR_UNITS_PER_MAJOR);
