import type { ComponentProps, FC } from "react";

import { Button, cn } from "@huspy/shared-ui";

const pillClassNameByRole = {
  primary:
    "h-9.5 gap-1.5 rounded-full px-5 text-[13px] font-semibold disabled:bg-grey-60 disabled:text-grey-400 disabled:opacity-100",
  secondary:
    "h-9.5 gap-1.5 rounded-full border border-solid border-border bg-card px-5 text-[13px] font-semibold text-foreground hover:bg-grey-60",
  destructive: "h-9.5 gap-1.5 rounded-full px-5 text-[13px] font-semibold",
} as const;

type PillButtonRole = keyof typeof pillClassNameByRole;

type Props = Omit<ComponentProps<typeof Button>, "variant"> & {
  buttonRole?: PillButtonRole;
};

const variantByRole: Record<PillButtonRole, ComponentProps<typeof Button>["variant"]> = {
  primary: undefined,
  secondary: "outline",
  destructive: "destructive",
};

export const PillButton: FC<Props> = ({ buttonRole = "primary", className, ...props }) => (
  <Button
    variant={variantByRole[buttonRole]}
    className={cn(pillClassNameByRole[buttonRole], className)}
    {...props}
  />
);
