import type { FC } from "react";

import { ChevronRight } from "@huspy/shared-icons";
import { cn } from "@huspy/shared-ui";

type Props = {
  expanded: boolean;
  onToggle: () => void;
  visible: boolean;
  disabled?: boolean;
};

export const ExpandToggle: FC<Props> = ({ expanded, onToggle, visible, disabled = false }) =>
  visible ? (
    <button
      type="button"
      onClick={onToggle}
      disabled={disabled}
      aria-expanded={expanded}
      aria-label={expanded ? "Collapse details" : "Expand details"}
      className={cn(
        "flex size-5 shrink-0 items-center justify-center rounded text-muted-foreground",
        disabled ? "cursor-not-allowed" : "cursor-pointer hover:text-foreground",
      )}
    >
      <ChevronRight
        className={cn("size-4 transition-transform duration-160 ease-out", expanded && "rotate-90")}
        aria-hidden
      />
    </button>
  ) : (
    <span className="size-5 shrink-0" />
  );
