import { useLayoutEffect, useState } from "react";

import { Route, Routes } from "@huspy/fe";

import { ROUTES } from "@/constants";
import { useEmailTemplateDraftLogoutCleanup } from "@/routes/BankApplication/components/EmailTemplateTab/hooks/useEmailTemplateDraftLogoutCleanup";
import { OpsQueue, BankApplication, RedirectToOpsQueue } from "@/routes";

const SECTION_LOCALE = "en-US";

export function MortgagesHomeMvpSectionContent() {
  useEmailTemplateDraftLogoutCleanup();

  const [isLocaleSynced, setIsLocaleSynced] = useState(false);

  useLayoutEffect(() => {
    const setEnglishLocale = async () => {
      await globalThis.huspy.translations.setLocale(SECTION_LOCALE);
      setIsLocaleSynced(true);
    };
    void setEnglishLocale();
  }, []);

  if (!isLocaleSynced) return null;

  return (
    <Routes>
      <Route path={ROUTES.opsQueue} element={<OpsQueue />} />
      <Route path={ROUTES.bankApplication} element={<BankApplication />} />
      <Route path="*" element={<RedirectToOpsQueue />} />
    </Routes>
  );
}
