import { useCallback, useMemo, useState } from "react";

const pruneToSegmentStarts = (
  valueByStart: Record<number, string>,
  segmentStarts: number[],
): Record<number, string> => {
  const activeStarts = new Set(segmentStarts);
  return Object.fromEntries(
    Object.entries(valueByStart).filter(([start]) => activeStarts.has(Number(start))),
  ) as Record<number, string>;
};

type UseSplitSegmentFieldResult = {
  valueFor: (startPage: number) => string;
  setValueForSegment: (startPage: number, value: string) => void;
  reset: () => void;
};

export const useSplitSegmentField = (
  segmentStarts: number[],
  createInitial: () => Record<number, string>,
): UseSplitSegmentFieldResult => {
  const [valueByStart, setValueByStart] = useState(createInitial);

  const activeValueByStart = useMemo(
    () => pruneToSegmentStarts(valueByStart, segmentStarts),
    [valueByStart, segmentStarts],
  );

  const valueFor = useCallback(
    (startPage: number) => activeValueByStart[startPage] ?? "",
    [activeValueByStart],
  );

  const setValueForSegment = useCallback(
    (startPage: number, value: string) => {
      setValueByStart((prev) => ({
        ...pruneToSegmentStarts(prev, segmentStarts),
        [startPage]: value,
      }));
    },
    [segmentStarts],
  );

  const reset = useCallback(() => {
    setValueByStart({});
  }, []);

  return { valueFor, setValueForSegment, reset };
};
