import type { ReactNode } from "react";

import { cn } from "@huspy/shared-ui";

import type { ReorderableRow } from "./types";

type Props = {
  reorderable?: ReorderableRow;
  children: ReactNode;
};

export const ReorderableRowShell = ({ reorderable, children }: Props) => (
  <div
    role={reorderable ? "listitem" : undefined}
    onDragOver={reorderable?.onDragOver}
    onDrop={
      reorderable
        ? (e) => {
            e.preventDefault();
            reorderable.onDrop();
          }
        : undefined
    }
    className={cn(
      reorderable && "relative",
      reorderable?.isDragging && "opacity-40",
      reorderable?.isPending && "pointer-events-none opacity-60",
    )}
  >
    {reorderable?.dropIndicator && (
      <span
        className={cn(
          "pointer-events-none absolute inset-x-1 h-0.5 rounded-full bg-primary",
          reorderable.dropIndicator === "before" ? "-top-px" : "-bottom-px",
        )}
      />
    )}
    {children}
  </div>
);
