import React, { useRef, useLayoutEffect, useState } from "react";

import { cn } from "../../shadcn/lib/utils";
import { Tooltip, TooltipContent, TooltipTrigger } from "../Tooltip";

export type TruncateProps = {
  /**
   * The content to display and potentially truncate.
   * If a ReactElement is provided, it will be rendered as-is without truncation.
   */
  text: string | React.ReactElement;
  /**
   * Additional CSS classes to apply to the container
   */
  className?: string;
  /**
   * Maximum number of lines before truncation (default: 1)
   */
  maxLines?: number;
};

/**
 * Truncate component that displays text with truncation.
 * If the text overflows, it shows a tooltip with the full text.
 * If a ReactElement is provided, it renders it as-is without truncation.
 */
export const Truncate = ({ text, className, maxLines = 1 }: TruncateProps) => {
  const textRef = useRef<HTMLSpanElement>(null);
  const [isTruncated, setIsTruncated] = useState(false);
  const isReactElement = React.isValidElement(text);

  useLayoutEffect(() => {
    // Skip truncation check for React elements
    if (isReactElement) return;

    const checkTruncation = () => {
      if (textRef.current) {
        const element = textRef.current;
        const isOverflowing =
          element.scrollWidth > element.clientWidth || element.scrollHeight > element.clientHeight;
        setIsTruncated(isOverflowing);
      }
    };

    checkTruncation();

    window.addEventListener("resize", checkTruncation);

    const resizeObserver = new ResizeObserver(checkTruncation);
    const currentRef = textRef.current;
    if (currentRef) {
      resizeObserver.observe(currentRef);
    }

    return () => {
      window.removeEventListener("resize", checkTruncation);
      resizeObserver.disconnect();
    };
  }, [text, maxLines, isReactElement]);

  // If text is already a ReactElement, return it as-is
  if (isReactElement) {
    return <>{text}</>;
  }

  const getTruncationStyles = (
    maxLines: number,
  ): { className?: string; style?: React.CSSProperties } => {
    if (maxLines <= 1) {
      return {
        className: cn("block truncate", className),
      };
    }

    return {
      className: cn("block", className),
      style: {
        display: "-webkit-box",
        WebkitLineClamp: maxLines,
        WebkitBoxOrient: "vertical",
        overflow: "hidden",
      },
    };
  };

  return (
    <Tooltip>
      <TooltipTrigger asChild>
        <span ref={textRef} {...getTruncationStyles(maxLines)}>
          {text}
        </span>
      </TooltipTrigger>
      {isTruncated && (
        <TooltipContent onClick={(e) => e.stopPropagation()} className="max-w-[300px] break-words">
          {text}
        </TooltipContent>
      )}
    </Tooltip>
  );
};

export default Truncate;
