import { FC } from "react";

import type { DocumentChecklistRow } from "@/types";
import { bankApplicationCardTitleClassName } from "@/routes/BankApplication/constants";

import { BankApplicationCard } from "../../../BankApplicationCard";
import { DocumentRow } from "../DocumentRow";
import { TableHeader } from "../TableHeader";

type Props = {
  caseDocuments: DocumentChecklistRow[];
};

export const CaseDocumentsCard: FC<Props> = ({ caseDocuments }) => {
  if (caseDocuments.length === 0) return null;
  return (
    <BankApplicationCard>
      <div className="mb-4">
        <p className={bankApplicationCardTitleClassName}>Case Documents</p>
      </div>

      <div>
        <TableHeader />
        <div className="space-y-0.5" role="list">
          {caseDocuments.map((document) => (
            <DocumentRow
              key={`${document.type}-${document.matchedFile?.id ?? "unmatched"}`}
              variant="flat"
              data={document}
            />
          ))}
        </div>
      </div>
    </BankApplicationCard>
  );
};
