import type { Applicant, DocumentTypeCode } from "@/types";
import {
  isApplicantLevelDocumentType,
  shouldShowAssignToSelect,
} from "@/routes/BankApplication/utils/documentTypeAssignment";
import { resolveApplicantIdForDocumentLink } from "@/routes/BankApplication/components/ChecklistWorkspace/utils";
import { AddDocumentUploadFile } from "./types";

type GetAddDocumentFormStateInput = {
  uploadedFiles: AddDocumentUploadFile[];
  applicants: Applicant[];
  selectedApplicantId: string;
  documentTypeCodes: DocumentTypeCode[];
  isUploadingFiles: boolean;
  isLinkPending: boolean;
  hasAttemptedSubmit: boolean;
};

export type AddDocumentFormState = {
  showApplicantSelect: boolean;
  allFilesHaveDocumentType: boolean;
  isApplicantValid: boolean;
  canSubmit: boolean;
  showAssignToError: boolean;
};

export const getAddDocumentFormState = ({
  uploadedFiles,
  applicants,
  selectedApplicantId,
  documentTypeCodes,
  isUploadingFiles,
  isLinkPending,
  hasAttemptedSubmit,
}: GetAddDocumentFormStateInput): AddDocumentFormState => {
  const showApplicantSelect = uploadedFiles.some((file) =>
    shouldShowAssignToSelect(file.documentType, documentTypeCodes, applicants.length),
  );

  const anyApplicantLevelFile = uploadedFiles.some((file) =>
    isApplicantLevelDocumentType(file.documentType, documentTypeCodes),
  );

  const resolvedApplicantId = anyApplicantLevelFile
    ? resolveApplicantIdForDocumentLink(
        applicants,
        selectedApplicantId,
        uploadedFiles.find((file) =>
          isApplicantLevelDocumentType(file.documentType, documentTypeCodes),
        )?.documentType ?? "",
        documentTypeCodes,
      )
    : undefined;

  const allFilesHaveDocumentType = uploadedFiles.every((file) => file.documentType !== "");
  const isApplicantValid = !anyApplicantLevelFile || !!resolvedApplicantId;

  const canSubmit =
    uploadedFiles.length > 0 &&
    allFilesHaveDocumentType &&
    isApplicantValid &&
    !isUploadingFiles &&
    !isLinkPending;

  const showAssignToError = hasAttemptedSubmit && anyApplicantLevelFile && !isApplicantValid;

  return {
    showApplicantSelect,
    allFilesHaveDocumentType,
    isApplicantValid,
    canSubmit,
    showAssignToError,
  };
};
