import type { FC } from "react";

import { ZoomIn, ZoomOut } from "@huspy/shared-icons";
import { Button, cn } from "@huspy/shared-ui";

type Props = {
  canZoomIn: boolean;
  canZoomOut: boolean;
  onZoomIn: () => void;
  onZoomOut: () => void;
  onReset: () => void;
  className?: string;
};

export const PdfPreviewZoomControls: FC<Props> = ({
  canZoomIn,
  canZoomOut,
  onZoomIn,
  onZoomOut,
  onReset,
  className,
}) => (
  <div
    className={cn(
      "flex flex-col items-center gap-1 rounded-lg border border-border bg-popover/95 p-1 shadow-md",
      className,
    )}
  >
    <Button
      type="button"
      variant="ghost"
      onClick={onZoomIn}
      disabled={!canZoomIn}
      className="size-8 px-0"
      aria-label="Zoom in"
    >
      <ZoomIn className="size-4" />
    </Button>
    <Button
      type="button"
      variant="ghost"
      onClick={onZoomOut}
      disabled={!canZoomOut}
      className="size-8 px-0"
      aria-label="Zoom out"
    >
      <ZoomOut className="size-4" />
    </Button>
    <div className="h-px w-full bg-border" />
    <Button type="button" variant="ghost" onClick={onReset} className="h-8 px-2 text-xs">
      Reset
    </Button>
  </div>
);
