import * as React from "react";

import { cn } from "@huspy/shared-ui";

type FloatingLabelProps = {
  label: string;
  required?: boolean | undefined;
  isFloating: boolean;
  error?: boolean | undefined;
  /**
   * Position style for the non-floating state.
   * - "center": vertically centered (for single-line inputs)
   * - "top": positioned near top (for multiline textareas)
   */
  variant?: "center" | "top";
  className?: string;
  /**
   * Render as div instead of label (for cases where label semantics aren't appropriate)
   */
  as?: "label" | "div";
  /**
   * htmlFor attribute for the label element (only applies when as="label")
   */
  htmlFor?: string;
};

export const FloatingLabel: React.FC<FloatingLabelProps> = ({
  label,
  required,
  isFloating,
  error,
  variant = "center",
  className,
  as: Component = "label",
  htmlFor,
}) => {
  const nonFloatingPosition =
    variant === "center" ? "top-1/2 -translate-y-1/2 text-base" : "top-4 text-base";

  const labelProps = Component === "label" && htmlFor ? { htmlFor } : undefined;

  return (
    <Component
      {...labelProps}
      className={cn(
        "text-muted-foreground pointer-events-none absolute left-4 z-10 transition-all duration-200 ease-out",
        isFloating ? "top-2 text-xs" : nonFloatingPosition,
        error && "text-destructive",
        className,
      )}
    >
      {label}
      {required && (
        <span className="text-destructive ml-0.5" aria-hidden="true">
          *
        </span>
      )}
    </Component>
  );
};
