import type { FC } from "react";

import { useBankPolicyChecks } from "@/api";

import { CheckTabBadge, summarizeChecks } from "../RuleChecksCard";

type Props = {
  bankApplicationId: string;
};

/** Unresolved-failure count for the Bank Policy Checks tab; renders nothing when everything is clear. */
export const BankPolicyTabBadge: FC<Props> = ({ bankApplicationId }) => {
  const { data } = useBankPolicyChecks(bankApplicationId);
  return <CheckTabBadge summary={summarizeChecks(data?.checks ?? [])} />;
};
