import type { BankApplication, EligibilityChecks } from "@/types";

import { buildEmailBody } from "./buildEmailBody";
import { formatFabCaseDetailsBlock } from "./fabEmailTemplate/formatFabCaseDetailsBlock";
import { formatFabEmailSubject } from "./fabEmailTemplate/formatFabSubject";
import { formatLoanTenorMonths } from "./standardEmailTemplate/formatEligibilityBlock";
import type { EmailTemplateDraft } from "./types";

export type GenerateFabEmailDraftInput = {
  bankApplication: BankApplication;
  eligibilityChecks: EligibilityChecks | undefined;
  underwriterName: string;
};

export const generateFabEmailDraft = ({
  bankApplication,
  eligibilityChecks,
  underwriterName,
}: GenerateFabEmailDraftInput): EmailTemplateDraft => ({
  subject: formatFabEmailSubject(bankApplication),
  body: buildEmailBody({
    caseDetailsBlock: formatFabCaseDetailsBlock(
      bankApplication,
      eligibilityChecks,
      formatLoanTenorMonths(eligibilityChecks),
    ),
    bankApplication,
    eligibilityChecks,
    underwriterName,
  }),
});
