import { createContext, type FC, type ReactNode, useContext, useMemo } from "react";

import type { ProcessingStatus } from "@/types";

export type DocumentPreviewTarget = {
  /** Underwriting `documents.id` — stable across rotation; used for rotate API calls. */
  documentId: string;
  /** Doc-service id — changes after each rotation; used for preview fetches. */
  docServiceDocumentId: string;
  underwritingServiceFileName: string;
  /** Snapshot at the time preview opened; gates the rotate control. */
  processingStatus: ProcessingStatus;
};

type DocumentPreviewContextValue = {
  beginPreview: (target: DocumentPreviewTarget) => void;
};

const DocumentPreviewContext = createContext<DocumentPreviewContextValue | null>(null);

type ProviderProps = {
  children: ReactNode;
  onBeginPreview: (target: DocumentPreviewTarget) => void;
};

export const DocumentPreviewProvider: FC<ProviderProps> = ({ children, onBeginPreview }) => {
  const value = useMemo(
    () => ({
      beginPreview: onBeginPreview,
    }),
    [onBeginPreview],
  );

  return (
    <DocumentPreviewContext.Provider value={value}>{children}</DocumentPreviewContext.Provider>
  );
};

export const useDocumentPreview = (): DocumentPreviewContextValue => {
  const ctx = useContext(DocumentPreviewContext);
  if (!ctx) {
    throw new Error("useDocumentPreview must be used within DocumentPreviewProvider");
  }
  return ctx;
};
