import { toast } from "@huspy/shared-ui";

import type { Applicant, DocumentTypeCode, DocumentValidationCheck } from "@/types";
import { useUndoDocumentValidationCheckWaiver } from "@/api";

import { CheckRowShell, getCheckVisualState, isCheckWaivable } from "../RuleChecksCard";
import { formatCheckComparison } from "./utils";

type Props = {
  check: DocumentValidationCheck;
  applicants: Applicant[];
  bankApplicationId: string;
  documentTypeCodes: DocumentTypeCode[];
  onWaive: () => void;
};

export function DocumentValidationCheckRow({
  check,
  applicants,
  bankApplicationId,
  documentTypeCodes,
  onWaive,
}: Props) {
  const undoWaiver = useUndoDocumentValidationCheckWaiver();
  const applicant = applicants.find(({ id }) => id === check.applicantId);

  return (
    <CheckRowShell
      title={check.status === "FAIL" ? check.failTitle : check.title}
      applicantName={applicants.length > 1 ? applicant?.fullName : undefined}
      visualState={getCheckVisualState(check)}
      comparisonText={formatCheckComparison(check, documentTypeCodes)}
      waiver={check.waiver}
      isWaivable={isCheckWaivable(check)}
      onWaive={onWaive}
      onUnwaive={() =>
        undoWaiver.mutate(
          { bankApplicationId, checkId: check.id },
          { onError: () => toast.error("Failed to unwaive the check.") },
        )
      }
      isUnwaivePending={undoWaiver.isPending}
    />
  );
}
