import type { FC, SubmitEvent } from "react";

import { ModalFooter, PillButton } from "@/components";
import type { DocumentExtractedFields } from "@/types";

import { ExtractedFieldsFieldProvider } from "../context/ExtractedFieldsFieldContext";
import { useExtractedFieldsDraft } from "../hooks/useExtractedFieldsDraft";

import { GroupFieldsSection } from "./GroupFieldsSection";
import { ScalarFieldsSection } from "./ScalarFieldsSection";
type Props = {
  documentId: string;
  bankApplicationId: string;
  data: DocumentExtractedFields;
  onClose: () => void;
};

export const ExtractedFieldsForm: FC<Props> = ({
  documentId,
  bankApplicationId,
  data,
  onClose,
}) => {
  const { fieldBindings, save, saveError, hasChanges } = useExtractedFieldsDraft(
    documentId,
    bankApplicationId,
    data,
    onClose,
  );
  const { isSaving } = fieldBindings;

  const handleSubmit = (event: SubmitEvent<HTMLFormElement>) => {
    event.preventDefault();
    save();
  };

  return (
    <ExtractedFieldsFieldProvider value={fieldBindings}>
      <form className="flex min-h-0 flex-1 flex-col" onSubmit={handleSubmit}>
        <div className="min-h-0 flex-1 space-y-6 overflow-y-auto px-6 py-5">
          <ScalarFieldsSection fields={data.fields} />
          <GroupFieldsSection groups={data.groups} />
        </div>

        <ModalFooter>
          {!!saveError && (
            <p role="alert" className="mr-auto text-sm text-destructive">
              {saveError}
            </p>
          )}
          <PillButton type="button" buttonRole="secondary" disabled={isSaving} onClick={onClose}>
            Cancel
          </PillButton>
          <PillButton type="submit" disabled={!hasChanges || isSaving}>
            Save
          </PillButton>
        </ModalFooter>
      </form>
    </ExtractedFieldsFieldProvider>
  );
};
