import type { FC, ReactNode } from "react";

import { cn } from "@huspy/shared-ui";

import { BANK_APPLICATION_TAB_LABELS, type BankApplicationTab } from "./constants";

type Props = {
  value: BankApplicationTab;
  onValueChange: (tab: BankApplicationTab) => void;
  tabs: readonly BankApplicationTab[];
  badges?: Partial<Record<BankApplicationTab, ReactNode>>;
};

export const BankApplicationTabs: FC<Props> = ({ value, onValueChange, tabs, badges }) => (
  <div
    role="tablist"
    aria-label="Bank application sections"
    className="-mb-3.25 flex items-stretch gap-1 self-stretch"
  >
    {tabs.map((tab) => {
      const isActive = tab === value;

      return (
        <button
          key={tab}
          type="button"
          role="tab"
          aria-selected={isActive}
          onClick={() => onValueChange(tab)}
          className={cn(
            "flex cursor-pointer items-center gap-1.5 rounded-t-xl border border-b-0 border-solid px-4 text-[13px] font-medium",
            isActive
              ? "border-border bg-card text-foreground"
              : "border-transparent text-muted-foreground hover:text-foreground",
          )}
        >
          {BANK_APPLICATION_TAB_LABELS[tab]}
          {badges?.[tab]}
        </button>
      );
    })}
  </div>
);
