import type { ReactNode } from "react";

import { FloatingLabelSelect } from "@huspy/shared-agents";
import { cn } from "@huspy/shared-ui";

import { DocumentUploadFileCard, DocumentUploadFileRow } from "@/components/DocumentUpload";

import { getDocumentTypeSelectOptions } from "@/routes/BankApplication/utils";
import { DocumentTypeCode } from "@/types";

type Props = {
  fileName: string;
  leadingIcon: ReactNode;
  onRemove: () => void;
  removeDisabled?: boolean;
  documentType: string;
  onDocumentTypeChange: (value: string) => void;
  documentTypeCodes: DocumentTypeCode[];
  selectDisabled?: boolean;
  hasTypeError?: boolean;
};

export function AddDocumentUploadedFileCard({
  fileName,
  leadingIcon,
  onRemove,
  removeDisabled = false,
  documentType,
  onDocumentTypeChange,
  documentTypeCodes,
  selectDisabled = false,
  hasTypeError = false,
}: Props) {
  return (
    <DocumentUploadFileCard className={cn("space-y-2", hasTypeError && "border-destructive")}>
      <DocumentUploadFileRow
        leadingIcon={leadingIcon}
        fileName={fileName}
        onRemove={onRemove}
        removeDisabled={removeDisabled}
      />
      <FloatingLabelSelect
        label="Document type"
        placeholder="Select document type"
        required
        value={documentType}
        disabled={selectDisabled}
        onValueChange={onDocumentTypeChange}
        options={getDocumentTypeSelectOptions(documentTypeCodes)}
      />
    </DocumentUploadFileCard>
  );
}
