import { ProcessingStatus } from "@/types";
import { isProcessingFailed } from "@/utils";

import { PROCESSING_FAILURE_MESSAGES } from "../constants";

export const getProcessingFailureMessage = (
  processingStatus: ProcessingStatus | null | undefined,
): string | null => {
  if (!processingStatus || !isProcessingFailed(processingStatus)) return null;
  if (processingStatus === "CLASSIFICATION_FAILED") return null;
  return PROCESSING_FAILURE_MESSAGES[processingStatus] ?? "Processing failed.";
};
