import { useState } from "react";

import { Search } from "@huspy/shared-icons";
import { Input, Popover, PopoverContent } from "@huspy/shared-ui";

import { FilterColumnTrigger } from "../FilterColumnTrigger";
import { FilterPopoverActions } from "../FilterPopoverActions";

type Props = {
  value: string;
  onApply: (value: string) => void;
  onClear: () => void;
};

export function ApplicantNameFilter({ value, onApply, onClear }: Props) {
  const [open, setOpen] = useState(false);
  const [draft, setDraft] = useState(value);

  const handleOpenChange = (nextOpen: boolean) => {
    if (nextOpen) setDraft(value);
    setOpen(nextOpen);
  };

  const handleApply = () => {
    onApply(draft.trim());
    setOpen(false);
  };

  const handleClear = () => {
    onClear();
    setDraft("");
    setOpen(false);
  };

  const normalizedDraft = draft.trim();
  const hasDraftChanged = normalizedDraft !== value;
  const canApply = hasDraftChanged;

  return (
    <Popover open={open} onOpenChange={handleOpenChange}>
      <FilterColumnTrigger label="Applicant" />

      <PopoverContent className="bg-popover w-64" side="bottom" align="start">
        <div className="relative mb-3">
          <Search
            className="text-muted-foreground pointer-events-none absolute top-1/2 left-3 size-3.5 -translate-y-1/2"
            aria-hidden
          />
          <Input
            type="text"
            value={draft}
            onChange={(e) => setDraft(e.target.value)}
            placeholder="Search by applicant name…"
            className="bg-background pl-8"
            aria-label="Applicant name"
            onKeyDown={(e) => {
              if (e.key === "Enter" && canApply) {
                handleApply();
              }
            }}
          />
        </div>

        <FilterPopoverActions onClear={handleClear} onApply={handleApply} canApply={canApply} />
      </PopoverContent>
    </Popover>
  );
}
