import type { CreateMortgageApplicationPayload, Applicant } from "@/api";

import type {
  CreateMortgageApplicationFormApplicant,
  CreateMortgageApplicationFormValues,
} from "@/routes/OpsQueue/components/CreateMortgageApplicationModal/CreateMortgageApplicationForm/types";

import { isCreateCaseDocLevelRequired } from "./isCreateCaseDocLevelRequired";
import { normalizeCreateMortgageApplicationFormValues } from "./normalizeCreateMortgageApplicationFormValues";

const toApplicant = (applicant: CreateMortgageApplicationFormApplicant): Applicant => {
  const applicantRole = applicant.applicantRole!;
  const withResidency = {
    firstName: applicant.firstName,
    lastName: applicant.lastName,
    employmentType: applicant.employmentType!,
    residencyType: applicant.residencyType!,
  };

  switch (applicantRole) {
    case "CO_APPLICANT":
      return {
        ...withResidency,
        applicantRole: "CO_APPLICANT",
        relationshipType: applicant.relationshipType!,
      };
    case "CO_BORROWER":
      return {
        ...withResidency,
        applicantRole: "CO_BORROWER",
        relationshipType: applicant.relationshipType!,
      };
    default:
      return {
        ...withResidency,
        applicantRole: "MAIN",
      };
  }
};

export const toCreateMortgageApplicationPayload = (
  values: CreateMortgageApplicationFormValues,
  isCreateCaseDocLevelEnabled = false,
): CreateMortgageApplicationPayload => {
  const { opportunityDetails, applicants, banks, documentId } =
    normalizeCreateMortgageApplicationFormValues(values);
  const { loanAmount, transactionType, propertyType, propertyStatus, opportunityId } =
    opportunityDetails;
  const includeIncomeVerificationType = isCreateCaseDocLevelRequired(
    applicants,
    isCreateCaseDocLevelEnabled,
  );
  return {
    opportunityDetails: {
      transactionType: transactionType!,
      propertyType: propertyType!,
      propertyStatus: propertyStatus!,
      loanAmount: Number(loanAmount),
      ...(opportunityId ? { opportunityId } : {}),
    },
    applicants: applicants.map(toApplicant),
    banks: banks.map(({ id, mortgageType, incomeVerificationType, tenorMonths }) => ({
      id,
      mortgageType: mortgageType!,
      tenorMonths: Number(tenorMonths),
      ...(includeIncomeVerificationType ? { incomeVerificationType: incomeVerificationType! } : {}),
    })),
    documentId: documentId!,
  };
};
