import { cn } from "../../shadcn/lib/utils";

const REQUIRED_INDICATOR = "*";
type RequiredIndicatorProps = {
  isRequired?: boolean;
  className?: string;
};

export const RequiredIndicator = ({ isRequired = false, className }: RequiredIndicatorProps) => {
  if (!isRequired) return null;
  return <span className={cn("text-destructive ml-0.5", className)}>{REQUIRED_INDICATOR}</span>;
};
