import { FC } from "react";

import { cn, UserAvatar } from "@huspy/shared-ui";

import type { Applicant, ApplicantDocumentGroup } from "@/types";
import { getGroupCounts } from "@/routes/BankApplication/utils";

import { getDocumentGroupsForApplicant } from "../utils";

type Props = {
  applicants: Applicant[];
  applicantDocumentGroups: ApplicantDocumentGroup[];
  value: string;
  onValueChange: (applicantId: string) => void;
};

export const ApplicantTabs: FC<Props> = ({
  applicants,
  applicantDocumentGroups,
  value,
  onValueChange,
}) => (
  <div className="flex flex-wrap items-center gap-1.5">
    {applicants.map((applicant) => {
      const isActive = applicant.id === value;
      const { mandatory, received } = getGroupCounts(
        getDocumentGroupsForApplicant(applicantDocumentGroups, applicant.id),
      );

      return (
        <button
          key={applicant.id}
          type="button"
          aria-pressed={isActive}
          onClick={() => onValueChange(applicant.id)}
          className={cn(
            "flex h-7 cursor-pointer items-center gap-1.5 rounded-full pr-1.5 pl-1 text-[13px]",
            isActive
              ? "bg-foreground text-background dark:bg-secondary dark:text-secondary-foreground"
              : "border border-solid border-border bg-card text-foreground hover:bg-muted",
          )}
        >
          <UserAvatar
            name={applicant.fullName}
            className="size-5"
            fallbackClassName="bg-input text-[9px] font-semibold text-grey-700"
          />

          <span className="font-medium">{applicant.fullName}</span>

          <span
            className={cn(
              "rounded-full px-1.5 text-[10px] font-semibold tabular-nums",
              isActive
                ? "bg-background/20 text-background dark:bg-foreground/15 dark:text-foreground"
                : "bg-muted text-foreground",
            )}
          >
            {`${received}/${mandatory}`}
          </span>
        </button>
      );
    })}
  </div>
);
