import { X } from "@huspy/shared-icons";

import { useInternalUserById } from "@/api";
import { formatInternalUserDisplayName } from "@/api/userRequests";
import { Bank } from "@/types";

type Props = {
  banks: Bank[];
  applicantName: string;
  selectedBankId: string;
  createdById: string;
  createdAtFrom: string;
  createdAtTo: string;
  onClearApplicantName: () => void;
  onClearBank: () => void;
  onClearCreatedAt: () => void;
  onClearCreatedBy: () => void;
  onClearAll: () => void;
};

type Pill = {
  key: string;
  label: string;
  onRemove: () => void;
};

export function ActiveFilterBar({
  banks,
  applicantName,
  selectedBankId,
  createdById,
  createdAtFrom,
  createdAtTo,
  onClearApplicantName,
  onClearBank,
  onClearCreatedAt,
  onClearCreatedBy,
  onClearAll,
}: Props) {
  const { data: createdByUser } = useInternalUserById(createdById || undefined);

  const pills: Pill[] = [];

  if (applicantName) {
    pills.push({
      key: "applicantName",
      label: `Applicant: ${applicantName}`,
      onRemove: onClearApplicantName,
    });
  }

  if (selectedBankId) {
    const bankName = banks.find((bank) => bank.id === selectedBankId)?.name ?? selectedBankId;
    pills.push({ key: "bankId", label: `Bank: ${bankName}`, onRemove: onClearBank });
  }

  if (createdAtFrom || createdAtTo) {
    pills.push({
      key: "createdAt",
      label: `Created at: ${createdAtFrom || "any"} → ${createdAtTo || "any"}`,
      onRemove: onClearCreatedAt,
    });
  }

  if (createdById) {
    const userName = createdByUser ? formatInternalUserDisplayName(createdByUser) : createdById;
    pills.push({
      key: "createdById",
      label: `Created by: ${userName}`,
      onRemove: onClearCreatedBy,
    });
  }

  if (pills.length === 0) return null;

  return (
    <div className="sticky top-11 z-10 flex flex-wrap items-center gap-2 border-b border-grey-60 bg-background px-5 py-2.5">
      {pills.map(({ key, label, onRemove }) => (
        <span
          key={key}
          className="flex h-7 items-center gap-1 rounded-full bg-grey-60 pr-1.5 pl-3 text-xs text-foreground"
        >
          {label}
          <button
            type="button"
            onClick={onRemove}
            className="cursor-pointer rounded-full text-muted-foreground hover:text-foreground"
            aria-label={`Remove filter ${label}`}
          >
            <X className="size-4" />
          </button>
        </span>
      ))}

      <button
        type="button"
        onClick={onClearAll}
        className="cursor-pointer text-xs font-semibold text-foreground-secondary hover:text-foreground"
      >
        Clear all
      </button>
    </div>
  );
}
