import type { Bank, GetBanksResponse } from "@/api/types/getBanks";
import type { RelationshipType } from "@/types";

/** Selectable relationship types — CHILD is legacy-only and excluded from every bank list. */
const ALL_SELECTABLE_RELATIONSHIP_TYPES = [
  "PARENT",
  "SIBLING",
  "SPOUSE",
  "SON",
  "DAUGHTER",
  "OTHER",
] as const satisfies readonly RelationshipType[];

const normalizeBankName = (name: string) => name.trim().toLowerCase();

/** Mirrors underwriting-service bank seed files until BE is deployed to dev. */
const SUPPORTED_RELATIONSHIP_TYPES_BY_BANK_NAME: Record<string, RelationshipType[]> = {
  "arab bank": ["SPOUSE", "OTHER"],
  enbd: ["PARENT", "SIBLING", "SON", "SPOUSE", "OTHER"],
  hsbc: ["SIBLING", "SON", "DAUGHTER", "SPOUSE", "OTHER"],
  nbf: ["PARENT", "SON", "DAUGHTER", "SPOUSE", "OTHER"],
};

const getSupportedRelationshipTypesForBank = (
  bank: Pick<Bank, "name" | "supportedRelationshipTypes">,
) => {
  if (bank.supportedRelationshipTypes?.length) {
    return bank.supportedRelationshipTypes;
  }

  return (
    SUPPORTED_RELATIONSHIP_TYPES_BY_BANK_NAME[normalizeBankName(bank.name)] ?? [
      ...ALL_SELECTABLE_RELATIONSHIP_TYPES,
    ]
  );
};

export const enrichBanksResponse = (response: GetBanksResponse): GetBanksResponse => ({
  ...response,
  data: response.data.map((bank) => ({
    ...bank,
    supportedRelationshipTypes: getSupportedRelationshipTypesForBank(bank),
  })),
});
