import { useSearchParams } from "@huspy/fe";

import {
  APPLICANT_NAME_PARAM,
  BANK_ID_PARAM,
  CREATED_AT_FROM_PARAM,
  CREATED_AT_TO_PARAM,
  CREATED_BY_ID_PARAM,
  PAGE_PARAM,
} from "@/routes/OpsQueue/constants";

export const useOpsQueueFilters = () => {
  const [searchParams, setSearchParams] = useSearchParams();
  const selectedBankId = searchParams.get(BANK_ID_PARAM) ?? "";
  const applicantName = searchParams.get(APPLICANT_NAME_PARAM) ?? "";
  const createdById = searchParams.get(CREATED_BY_ID_PARAM) ?? "";
  const createdAtFrom = searchParams.get(CREATED_AT_FROM_PARAM) ?? "";
  const createdAtTo = searchParams.get(CREATED_AT_TO_PARAM) ?? "";

  const updateParams = (mutate: (next: URLSearchParams) => void) => {
    setSearchParams(
      (prev) => {
        const next = new URLSearchParams(prev);
        mutate(next);
        next.delete(PAGE_PARAM);

        return next.toString() === prev.toString() ? prev : next;
      },
      { replace: true },
    );
  };

  const setOrDelete = (next: URLSearchParams, key: string, value: string) => {
    if (value) {
      next.set(key, value);
    } else {
      next.delete(key);
    }
  };

  const setBankFilter = (bankId: string) =>
    updateParams((next) => setOrDelete(next, BANK_ID_PARAM, bankId));

  const clearBankFilter = () => updateParams((next) => next.delete(BANK_ID_PARAM));

  const setCreatedAtFilter = ({ from, to }: { from?: string; to?: string }) =>
    updateParams((next) => {
      setOrDelete(next, CREATED_AT_FROM_PARAM, from ?? "");
      setOrDelete(next, CREATED_AT_TO_PARAM, to ?? "");
    });

  const clearCreatedAtFilter = () =>
    updateParams((next) => {
      next.delete(CREATED_AT_FROM_PARAM);
      next.delete(CREATED_AT_TO_PARAM);
    });

  const setApplicantNameFilter = (name: string) =>
    updateParams((next) => setOrDelete(next, APPLICANT_NAME_PARAM, name.trim()));

  const clearApplicantNameFilter = () => updateParams((next) => next.delete(APPLICANT_NAME_PARAM));

  const setCreatedByFilter = (userId: string) =>
    updateParams((next) => setOrDelete(next, CREATED_BY_ID_PARAM, userId.trim()));

  const clearCreatedByFilter = () => updateParams((next) => next.delete(CREATED_BY_ID_PARAM));

  const clearAllFilters = () =>
    updateParams((next) => {
      next.delete(APPLICANT_NAME_PARAM);
      next.delete(BANK_ID_PARAM);
      next.delete(CREATED_AT_FROM_PARAM);
      next.delete(CREATED_AT_TO_PARAM);
      next.delete(CREATED_BY_ID_PARAM);
    });

  return {
    applicantName,
    selectedBankId,
    createdById,
    createdAtFrom,
    createdAtTo,
    hasActiveFilters:
      !!selectedBankId || !!applicantName || !!createdById || !!(createdAtFrom || createdAtTo),
    setApplicantNameFilter,
    clearApplicantNameFilter,
    setBankFilter,
    clearBankFilter,
    setCreatedAtFilter,
    clearCreatedAtFilter,
    setCreatedByFilter,
    clearCreatedByFilter,
    clearAllFilters,
  };
};
