import { FC, useCallback, useEffect, useLayoutEffect, useRef } from "react";

import { useFlag, useParams } from "@huspy/fe";

import { Container, LoadErrorMessage } from "@/components";
import { useBankApplication, useDocumentTypeCodesForBankApplication } from "@/api";
import { useSessionStorage } from "@/hooks";

import {
  AddDocumentModal,
  AddDocumentModalState,
  BankApplicationTabs,
  BankPolicyChecksCard,
  BankPolicyTabBadge,
  EligibilityChecksTab,
  EmailTemplateTab,
  ChecklistProgressCard,
  ChecklistProgressCardSkeleton,
  ChecklistTabBadge,
  ChecklistWorkspace,
  ChecklistWorkspaceSkeleton,
  DocumentValidationCard,
  DocumentValidationTabBadge,
  Header,
  HeaderSkeleton,
  BANK_APPLICATION_TABS,
  DEFAULT_BANK_APPLICATION_TAB,
  EMAIL_TEMPLATE_TAB_FLAG,
  useBankApplicationTabChange,
} from "./components";
import { useModalTarget } from "./components/ChecklistWorkspace/hooks/useModalTarget";
import { getMainApplicant, bankApplicationSessionStorageKeys } from "./utils";

export const BankApplication: FC = () => {
  const { id: bankApplicationId } = useParams<{ id: string }>();
  const [activeApplicantId, setActiveApplicantId] = useSessionStorage<string | null>(
    bankApplicationSessionStorageKeys.activeApplicant(bankApplicationId ?? ""),
    null,
  );
  const [activeTab, changeTab] = useBankApplicationTabChange(bankApplicationId);
  const isEmailTemplateTabEnabled = useFlag(EMAIL_TEMPLATE_TAB_FLAG);
  const isInitialActiveTabRef = useRef(true);

  useLayoutEffect(() => {
    if (isInitialActiveTabRef.current) {
      isInitialActiveTabRef.current = false;
      return;
    }

    window.scrollTo({ top: 0, left: 0, behavior: "auto" });
  }, [activeTab]);

  useEffect(() => {
    if (!isEmailTemplateTabEnabled && activeTab === "email-template") {
      changeTab(DEFAULT_BANK_APPLICATION_TAB);
    }
  }, [activeTab, changeTab, isEmailTemplateTabEnabled]);

  const {
    open: openAddDocumentModalState,
    isOpen: isAddDocumentModalOpen,
    onOpenChange: onAddDocumentModalOpenChange,
    target: addDocumentModalTarget,
  } = useModalTarget<AddDocumentModalState>();

  const {
    data: bankApplicationData,
    isPending: isPendingBankApplication,
    isError: isErrorBankApplication,
    isSuccess: isSuccessBankApplication,
  } = useBankApplication(bankApplicationId);

  const { isPending: isPendingDocumentTypeCodes, isError: isErrorDocumentTypeCodes } =
    useDocumentTypeCodesForBankApplication(
      isSuccessBankApplication ? bankApplicationId : undefined,
      { includeMergeTargets: true },
    );

  const isPendingPage =
    isPendingBankApplication ||
    (isSuccessBankApplication &&
      (isPendingDocumentTypeCodes || bankApplicationData.unzipInProgress));
  const isErrorDocumentTypeCodesPage = isSuccessBankApplication && isErrorDocumentTypeCodes;

  const applicants = bankApplicationData?.applicants ?? [];
  const openAddDocumentModal = useCallback(
    (initialDocumentType?: string) => {
      openAddDocumentModalState({ initialDocumentType });
    },
    [openAddDocumentModalState],
  );

  const visibleTabs = BANK_APPLICATION_TABS.filter(
    (tab) => tab !== "email-template" || isEmailTemplateTabEnabled,
  );
  const mainApplicantId = getMainApplicant(applicants)?.id ?? "";
  const resolvedApplicantId =
    activeApplicantId && applicants.some(({ id }) => id === activeApplicantId)
      ? activeApplicantId
      : mainApplicantId;
  return (
    <Container>
      <div className="flex flex-col gap-5">
        {isPendingPage && (
          <>
            <HeaderSkeleton />
            <ChecklistProgressCardSkeleton />
            <ChecklistWorkspaceSkeleton />
          </>
        )}

        {isErrorBankApplication && (
          <LoadErrorMessage>Could not load application. Please try again.</LoadErrorMessage>
        )}

        {isSuccessBankApplication && !isPendingPage && (
          <>
            <Header
              bankApplicationData={bankApplicationData}
              onAddDocuments={() => openAddDocumentModal()}
              tabs={
                <BankApplicationTabs
                  value={activeTab}
                  onValueChange={changeTab}
                  tabs={visibleTabs}
                  badges={{
                    checklist: <ChecklistTabBadge checklist={bankApplicationData.checklist} />,
                    "document-validation": (
                      <DocumentValidationTabBadge bankApplicationId={bankApplicationData.id} />
                    ),
                    "bank-policy": (
                      <BankPolicyTabBadge bankApplicationId={bankApplicationData.id} />
                    ),
                  }}
                />
              }
            />

            {isErrorDocumentTypeCodesPage ? (
              <LoadErrorMessage>Could not load document types. Please try again.</LoadErrorMessage>
            ) : (
              <div className="flex min-w-0 flex-col gap-5">
                {activeTab === "checklist" && (
                  <>
                    <ChecklistProgressCard checklist={bankApplicationData.checklist} />

                    <ChecklistWorkspace
                      bankApplication={bankApplicationData}
                      activeApplicantId={resolvedApplicantId}
                      onActiveApplicantIdChange={setActiveApplicantId}
                      onAddDocument={openAddDocumentModal}
                    />
                  </>
                )}

                {activeTab === "document-validation" && (
                  <DocumentValidationCard
                    bankApplicationId={bankApplicationData.id}
                    applicants={applicants}
                  />
                )}

                {activeTab === "bank-policy" && (
                  <BankPolicyChecksCard
                    bankApplicationId={bankApplicationData.id}
                    applicants={applicants}
                  />
                )}

                {activeTab === "eligibility-checks" && <EligibilityChecksTab />}

                {isEmailTemplateTabEnabled && activeTab === "email-template" && (
                  <EmailTemplateTab />
                )}
              </div>
            )}

            <AddDocumentModal
              key={`${resolvedApplicantId}-${addDocumentModalTarget?.initialDocumentType ?? "any"}`}
              bankApplicationId={bankApplicationData.id}
              applicants={applicants}
              initialApplicantId={resolvedApplicantId}
              initialDocumentType={addDocumentModalTarget?.initialDocumentType}
              isOpen={isAddDocumentModalOpen}
              onOpenChange={onAddDocumentModalOpenChange}
            />
          </>
        )}
      </div>
    </Container>
  );
};
