import type { FC } from "react";

import { cn } from "@huspy/shared-ui";
import { Loader2 } from "@huspy/shared-icons";

import { MIN_HEIGHT_CLASS } from "../../constants";

type Props = {
  label: string;
  isError?: boolean;
};

export const CenteredStatus: FC<Props> = ({ label, isError = false }) => (
  <div
    role={isError ? "alert" : "status"}
    aria-live="polite"
    className={cn(
      "flex flex-1 flex-col items-center justify-center gap-2 px-6 text-center",
      MIN_HEIGHT_CLASS,
      isError ? "text-destructive" : "text-muted-foreground",
    )}
  >
    {!isError && <Loader2 className="size-7 animate-spin" aria-hidden />}
    <span className={cn("text-xs", isError && "text-sm")}>{label}</span>
  </div>
);
