import type { KeyboardEvent, MouseEvent } from "react";

import { ChevronRight, Loader2 } from "@huspy/shared-icons";
import { cn, Tooltip, TooltipContent, TooltipTrigger } from "@huspy/shared-ui";

import { useParams } from "@huspy/fe";

import { useDocumentTypeCodesForBankApplication } from "@/api";
import { formatShortDateTime } from "@/utils";
import { getProcessingFailureMessage } from "@/routes/BankApplication/components/ChecklistWorkspace/utils/getProcessingFailureMessage";
import { getProcessingInProgressMessage } from "@/routes/BankApplication/components/ChecklistWorkspace/utils/getProcessingInProgressMessage";
import { FileItemWithDocumentId, ProcessingStatus } from "@/types";
import { useDocumentPreview } from "@/routes/BankApplication/components/ChecklistWorkspace/context/DocumentPreviewContext";
import { toDocumentPreviewTarget } from "@/routes/BankApplication/components/ChecklistWorkspace/utils/previewTarget";
import {
  ignoreRowClickProps,
  isRowClickIgnored,
} from "@/routes/BankApplication/components/ChecklistWorkspace/utils/rowClick";
import { DOCUMENT_CHECKLIST_TABLE_GRID } from "@/routes/BankApplication/components/ChecklistWorkspace/components/DocumentRow/constants";
import { getDocumentTypeLabel } from "@/routes/BankApplication/components/ChecklistWorkspace/components/DocumentRow/utils";

type Props = {
  matchedFile: FileItemWithDocumentId | null;
  processingStatus: ProcessingStatus;
  documentType: string;
  isExpanded: boolean;
  onToggle: () => void;
};

export function DocumentParentRow({
  matchedFile,
  processingStatus,
  documentType,
  isExpanded,
  onToggle,
}: Props) {
  const { id: bankApplicationId } = useParams<{ id: string }>();
  const { data: documentTypeCodes = [] } = useDocumentTypeCodesForBankApplication(
    bankApplicationId,
    {
      includeMergeTargets: true,
    },
  );
  const { beginPreview } = useDocumentPreview();
  const isMerged = matchedFile !== null;
  const isMergeFailed = processingStatus === "MERGE_FAILED";
  const mergeStatusTooltipText = isMergeFailed
    ? getProcessingFailureMessage("MERGE_FAILED")
    : isMerged
      ? "Child documents have been merged into one file."
      : "Child documents have not been merged yet.";
  const processingMessage = getProcessingInProgressMessage(processingStatus);
  // Children's processingStatus propagates to the parent on BE.
  // But FE should only show processing icon if one of the children is merging
  // or when its own matched document is rotating.
  const isProcessing =
    processingStatus === "MERGE_IN_PROGRESS" ||
    matchedFile?.processingStatus === "ROTATION_IN_PROGRESS";

  const openPreview = (event: MouseEvent<HTMLElement> | KeyboardEvent<HTMLElement>) => {
    if (!matchedFile || isRowClickIgnored(event)) return;
    beginPreview(toDocumentPreviewTarget(matchedFile));
  };

  return (
    <div
      role={matchedFile ? "button" : undefined}
      tabIndex={matchedFile ? 0 : undefined}
      onClick={matchedFile ? openPreview : undefined}
      onKeyDown={
        matchedFile
          ? (event) => {
              if (event.key !== "Enter" && event.key !== " ") return;

              event.preventDefault();
              openPreview(event);
            }
          : undefined
      }
      className={cn(
        "grid items-center gap-3 rounded-lg bg-background px-3 py-3 hover:bg-muted",
        matchedFile && "cursor-pointer",
        DOCUMENT_CHECKLIST_TABLE_GRID,
      )}
    >
      <div className="flex min-w-0 items-center gap-2">
        <button
          {...ignoreRowClickProps}
          type="button"
          onClick={onToggle}
          aria-expanded={isExpanded}
          aria-label={`${isExpanded ? "Collapse" : "Expand"} ${getDocumentTypeLabel(documentType, documentTypeCodes)}`}
          className="flex size-5 shrink-0 cursor-pointer items-center justify-center rounded text-muted-foreground hover:text-foreground"
        >
          <ChevronRight
            className={cn(
              "size-4 transition-transform duration-160 ease-out",
              isExpanded && "rotate-90",
            )}
            aria-hidden
          />
        </button>

        {isProcessing && processingMessage && (
          <Tooltip>
            <TooltipTrigger asChild>
              <span className="inline-flex">
                <Loader2 className="size-4 shrink-0 animate-spin text-sky-600" aria-hidden />
              </span>
            </TooltipTrigger>
            <TooltipContent>{processingMessage}</TooltipContent>
          </Tooltip>
        )}

        <span className="min-w-0 truncate text-[13px] font-semibold text-foreground">
          {getDocumentTypeLabel(documentType, documentTypeCodes)}
        </span>

        <Tooltip>
          <TooltipTrigger asChild>
            <span
              {...ignoreRowClickProps}
              className={cn(
                "shrink-0 rounded-full px-2 py-0.5 text-[10px] font-semibold",
                isMergeFailed
                  ? "bg-warning/14 text-warning"
                  : isMerged
                    ? "bg-success/14 text-success"
                    : "bg-muted text-muted-foreground",
              )}
            >
              {isMergeFailed ? "Merge failed" : isMerged ? "Merged" : "Not merged"}
            </span>
          </TooltipTrigger>
          <TooltipContent>{mergeStatusTooltipText}</TooltipContent>
        </Tooltip>
      </div>

      <span title={matchedFile?.fileName} className="min-w-0 truncate text-xs text-grey-700">
        {matchedFile?.fileName ?? "—"}
      </span>

      <span className="text-xs tabular-nums text-muted-foreground">
        {matchedFile ? formatShortDateTime(matchedFile.updatedAt) : "—"}
      </span>

      <span />
    </div>
  );
}
