import { FC } from "react";

import type { Applicant, ApplicantDocumentGroup } from "@/types";
import { bankApplicationCardTitleClassName } from "@/routes/BankApplication/constants";

import { BankApplicationCard } from "../../../BankApplicationCard";
import { ApplicantTabs } from "./ApplicantTabs";
import { ApplicantInfoBadges } from "./ApplicantInfoBadges";
import { ApplicantDocumentTable } from "./ApplicantDocumentTable";
import { getDocumentGroupsForApplicant } from "./utils";

type Props = {
  applicants: Applicant[];
  applicantDocumentsGroups: ApplicantDocumentGroup[];
  activeApplicantId: string;
  onActiveApplicantIdChange: (applicantId: string) => void;
};

export const ApplicantDocumentsCard: FC<Props> = ({
  applicants,
  applicantDocumentsGroups,
  activeApplicantId,
  onActiveApplicantIdChange,
}) => {
  const activeApplicant = applicants.find(({ id }) => id === activeApplicantId);
  return (
    <BankApplicationCard>
      <div className="mb-4 flex flex-wrap items-center gap-x-4 gap-y-2">
        <div className="flex shrink-0 items-center">
          <p className={bankApplicationCardTitleClassName}>Applicant Documents</p>
        </div>

        <ApplicantTabs
          applicants={applicants}
          applicantDocumentGroups={applicantDocumentsGroups}
          value={activeApplicantId}
          onValueChange={onActiveApplicantIdChange}
        />
      </div>

      {activeApplicant && <ApplicantInfoBadges applicant={activeApplicant} />}

      <ApplicantDocumentTable
        documentGroups={getDocumentGroupsForApplicant(applicantDocumentsGroups, activeApplicantId)}
        scope={activeApplicantId}
      />
    </BankApplicationCard>
  );
};
