import * as React from "react";

import { cn } from "@huspy/shared-ui";

import { useFloatingLabelState, FloatingLabel, FieldError, SupportingText } from "../FloatingLabel";

type FloatingLabelTextareaProps = {
  label: string;
  supportingText?: string;
  error?: boolean;
  errorMessage?: string;
} & Omit<React.TextareaHTMLAttributes<HTMLTextAreaElement>, "placeholder">;

const FloatingLabelTextarea = React.forwardRef<HTMLTextAreaElement, FloatingLabelTextareaProps>(
  (
    { className, label, required, supportingText, error, errorMessage, value, rows = 3, ...props },
    ref,
  ) => {
    const { setIsFocused, isFloating } = useFloatingLabelState({ value });

    return (
      <div className="w-full">
        <div className="relative">
          <FloatingLabel
            label={label}
            required={required}
            isFloating={isFloating}
            error={error}
            variant="top"
          />

          {/* Textarea */}
          <textarea
            ref={ref}
            value={value}
            rows={rows}
            onFocus={(e) => {
              setIsFocused(true);
              props.onFocus?.(e);
            }}
            onBlur={(e) => {
              setIsFocused(false);
              props.onBlur?.(e);
            }}
            className={cn(
              "border-input bg-muted ring-offset-background flex w-full rounded-xl border px-4 pt-7 pb-3 text-base font-medium transition-all duration-200",
              "focus-visible:border-black focus-visible:outline-none",
              "disabled:cursor-not-allowed disabled:opacity-50",
              "min-h-[100px] resize-none",
              error && "border-destructive",
              className,
            )}
            {...props}
          />
        </div>

        {supportingText && !errorMessage && <SupportingText text={supportingText} />}

        {errorMessage && <FieldError message={errorMessage} />}
      </div>
    );
  },
);

FloatingLabelTextarea.displayName = "FloatingLabelTextarea";

export { FloatingLabelTextarea };
