import { useState, type FC } from "react";

import { cn } from "@huspy/shared-ui";

import { useCreateManualEarning, useEarningTypes } from "@/api";
import type { EligibilityApplicant } from "@/types";
import { formatMoneyAmount } from "@/utils";

import {
  CALCULATION_ROW_GRID,
  CALCULATION_TABLE_ACTION_SLOT,
  CALCULATION_TABLE_ROW_SHELL,
  calculationTableFooterClassName,
  REFERENCE_ONLY_TOOLTIP,
} from "../../../constants";
import { useEligibilityChecksRoute } from "../../../hooks/useEligibilityChecksRoute";
import {
  isReferenceOnlyEarning,
  isUncountedStatementSalary,
  needsPayslipsForSalary,
} from "../../../utils";
import {
  AddEligibilityLineButton,
  AddLineButtonRow,
  AddLineRow,
  CalculationTableEmptyState,
  CalculationTableHeader,
  EarningCalculationRow,
} from "../../CalculationTable";

type Props = {
  activeApplicant: EligibilityApplicant;
};

export const IncomeSection: FC<Props> = ({ activeApplicant }) => {
  const { bankApplicationId, currency, eligibilityChecks } = useEligibilityChecksRoute();
  const { data: earningTypes = [] } = useEarningTypes();
  const { mutateAsync: createEarning, isPending: isCreatingEarning } = useCreateManualEarning();
  const [isAddingLine, setIsAddingLine] = useState(false);

  if (!currency || !eligibilityChecks || !bankApplicationId) return null;

  const showPayslipsNeeded = needsPayslipsForSalary(activeApplicant.earnings);

  const handleAddEarning = async ({
    description,
    amount,
    allocation,
  }: {
    description: string;
    amount: number;
    allocation: number;
  }) => {
    await createEarning({
      bankApplicationId,
      payload: {
        applicantId: activeApplicant.id,
        description,
        amount: amount.toFixed(2),
        allocation,
      },
    });
    setIsAddingLine(false);
  };

  return (
    <section>
      <div className="mb-3 flex flex-wrap items-center justify-between gap-3">
        <p className="text-sm font-semibold text-foreground">Income</p>

        <span className="shrink-0 rounded-md bg-muted px-2 py-0.5 text-[10px] font-medium text-muted-foreground">
          Combined eligible income:{" "}
          {formatMoneyAmount(eligibilityChecks.summary.totalEarnings, currency)}
        </span>
      </div>

      {activeApplicant.earnings.length === 0 && !isAddingLine ? (
        <>
          <CalculationTableEmptyState
            title="No income found"
            description="Income from this applicant's documents will show here once they've been processed."
          />
          <div className="flex justify-center">
            <AddEligibilityLineButton label="Add income" onClick={() => setIsAddingLine(true)} />
          </div>
        </>
      ) : (
        <>
          <CalculationTableHeader allocationLabel="Allocation" totalLabel="Eligible" />

          <div role="list">
            {activeApplicant.earnings.map((earning) => {
              const isUncounted = isUncountedStatementSalary(earning);
              const isReferenceOnly = isReferenceOnlyEarning(earning);
              const isExcluded = isUncounted || isReferenceOnly;

              return (
                <EarningCalculationRow
                  key={earning.id}
                  earningId={earning.id}
                  description={earning.description}
                  documentType={earning.documentType}
                  earningType={earning.earningType}
                  frequency={earning.frequency}
                  allocation={earning.allocation}
                  amount={earning.amount}
                  amountOverride={earning.amountOverride}
                  originalAmount={earning.originalAmount}
                  fxRate={earning.fxRate}
                  eligibleAmount={earning.eligibleAmount}
                  numOfPayslips={earning.numOfPayslips}
                  maxPeriods={earning.maxPeriods}
                  documentFields={earning.documentFields}
                  statusLabel={isExcluded ? "Excluded" : undefined}
                  statusTooltipText={
                    isReferenceOnly
                      ? REFERENCE_ONLY_TOOLTIP
                      : isUncounted
                        ? "The salary credits in the bank statements are not consistent enough to count as fixed income."
                        : undefined
                  }
                  referenceOnly={isReferenceOnly}
                  source={earning.source}
                  typeOptions={earningTypes.length > 0 ? earningTypes : [earning.earningType]}
                />
              );
            })}

            {isAddingLine ? (
              <AddLineRow
                currency={currency}
                isPending={isCreatingEarning}
                onSubmit={handleAddEarning}
                onCancel={() => setIsAddingLine(false)}
              />
            ) : (
              <AddLineButtonRow label="Add income" onClick={() => setIsAddingLine(true)} />
            )}
          </div>

          {showPayslipsNeeded && (
            <p className="mt-2 rounded-lg bg-muted/40 px-3 py-2 text-[11px] text-muted-foreground">
              Salary credits were found in the bank statements, but they are not consistent, so they
              are not counted. Add payslips for this applicant to calculate eligible income.
            </p>
          )}

          <div className={cn("mt-2", CALCULATION_TABLE_ROW_SHELL)}>
            <div className={cn(calculationTableFooterClassName, CALCULATION_ROW_GRID, "flex-1")}>
              <span className="text-xs font-semibold text-foreground">
                Eligible income — {activeApplicant.name}
              </span>
              <span />
              <span />
              <span />
              <span />
              <span className="text-center text-xs font-semibold tabular-nums text-foreground">
                {formatMoneyAmount(activeApplicant.totalEarnings, currency)}
              </span>
            </div>
            <span className={CALCULATION_TABLE_ACTION_SLOT} aria-hidden />
          </div>
        </>
      )}
    </section>
  );
};
