import type { DocumentExtractedFields, ExtractedFieldDataType } from "@/types";

export const buildExtractedFieldsDraft = (
  data: DocumentExtractedFields,
): Record<string, string> => {
  const draft: Record<string, string> = {};

  for (const field of data.fields) {
    draft[field.key] = field.value ?? "";
  }

  for (const group of data.groups) {
    for (const item of group.items) {
      for (const field of item.fields) {
        draft[field.key] = field.value ?? "";
      }
    }
  }

  return draft;
};

export const getExtractedFieldValueByKey = (
  data: DocumentExtractedFields,
  key: string,
): string | null => {
  const scalarField = data.fields.find((field) => field.key === key);
  if (scalarField) return scalarField.value;

  for (const group of data.groups) {
    for (const item of group.items) {
      const groupField = item.fields.find((field) => field.key === key);
      if (groupField) return groupField.value;
    }
  }

  return null;
};

export type ExtractedFieldMeta = {
  dataType: ExtractedFieldDataType;
  options: string[] | null;
};

export const getExtractedFieldMetaByKey = (
  data: DocumentExtractedFields,
  key: string,
): ExtractedFieldMeta | null => {
  const scalarField = data.fields.find((field) => field.key === key);
  if (scalarField) {
    return { dataType: scalarField.dataType, options: scalarField.options };
  }

  for (const group of data.groups) {
    for (const item of group.items) {
      const groupField = item.fields.find((field) => field.key === key);
      if (!groupField) continue;

      const template = group.template.find((column) => column.fieldKey === groupField.fieldKey);
      return {
        dataType: template?.dataType ?? "TEXT",
        options: template?.options ?? null,
      };
    }
  }

  return null;
};
