import * as React from "react";

type UseFloatingLabelStateOptions = {
  value: string | number | readonly string[] | undefined;
};

type UseFloatingLabelStateReturn = {
  isFocused: boolean;
  setIsFocused: React.Dispatch<React.SetStateAction<boolean>>;
  hasValue: boolean;
  isFloating: boolean;
};

export function useFloatingLabelState({
  value,
}: UseFloatingLabelStateOptions): UseFloatingLabelStateReturn {
  const [isFocused, setIsFocused] = React.useState(false);
  const hasValue = value !== undefined && value !== "";
  const isFloating = isFocused || hasValue;

  return {
    isFocused,
    setIsFocused,
    hasValue,
    isFloating,
  };
}
