import { AxiosRequestConfig } from "axios";

import { Options } from "./types";

export const getAxiosConfig = (options?: Options): AxiosRequestConfig => {
  const baseURL = options?.baseURL ?? window.huspy?.services?.underwriting?.v1;
  return {
    ...(baseURL ? { baseURL } : {}),
    ...(options?.signal ? { signal: options.signal } : {}),
  };
};
