import type { FC } from "react";

import { usePatchBankApplicationTenor, useResetBankApplicationTenor } from "@/api";
import type { Tenor, EffectiveTenorApplicant } from "@/types";

import { formatEffectiveTenorApplicantSubtext, getEffectiveTenorMonths } from "../../utils";
import { OverrideClearButton } from "../CalculationTable/OverrideClearButton";
import { useEligibilityChecksRoute } from "../../hooks/useEligibilityChecksRoute";
import { TenorMonthsInput } from "./TenorMonthsInput";

type Props = {
  label: string;
  tenor: Tenor;
  effectiveTenorApplicant?: EffectiveTenorApplicant;
  sourceTag?: string;
};

export const EffectiveTenorRow: FC<Props> = ({
  label,
  tenor,
  effectiveTenorApplicant,
  sourceTag,
}) => {
  const { bankApplication } = useEligibilityChecksRoute();
  const { mutateAsync: patchTenor, isPending: isPatchingTenor } = usePatchBankApplicationTenor();
  const { mutateAsync: resetTenor, isPending: isResettingTenor } = useResetBankApplicationTenor();

  if (!bankApplication) return null;

  const isOverridden = tenor.overriddenTenorMonths != null;
  const displayTenorMonths = getEffectiveTenorMonths(tenor);
  const isPending = isPatchingTenor || isResettingTenor;

  return (
    <div className="flex items-center justify-between flex-1 gap-3 px-2 py-2">
      <div className="flex min-w-0 flex-1 flex-col gap-0.5">
        <div className="flex items-center gap-1.5">
          <span className="text-sm font-medium text-foreground">{label}</span>
          {sourceTag && (
            <span className="rounded-full bg-muted px-1.5 py-0.5 text-xs font-semibold text-muted-foreground">
              {sourceTag}
            </span>
          )}
        </div>
        {effectiveTenorApplicant && (
          <span className="text-xs text-muted-foreground">
            {formatEffectiveTenorApplicantSubtext(effectiveTenorApplicant, tenor)}
          </span>
        )}
      </div>

      <div className="flex shrink-0 items-center gap-1">
        <TenorMonthsInput
          value={displayTenorMonths}
          disabled={isPending}
          onCommit={async (value) => {
            await patchTenor({
              bankApplicationId: bankApplication.id,
              payload: { tenorMonths: value },
            });
          }}
        />
        <span className="text-xs text-muted-foreground">months</span>
        {isOverridden && (
          <OverrideClearButton
            disabled={isPending}
            ariaLabel="Reset to calculated tenor"
            tooltip="Manually overridden. Click to reset to the calculated tenor."
            onClear={async () => {
              await resetTenor(bankApplication.id);
            }}
          />
        )}
      </div>
    </div>
  );
};
