import type { FC } from "react";

import type {
  PageSegment,
  SelectOption,
} from "@/routes/BankApplication/components/ChecklistWorkspace/components/SplitDocumentModal/types";
import { CenteredStatus } from "@/routes/BankApplication/components/ChecklistWorkspace/components/SplitDocumentModal/components/CenteredStatus";
import { SplitSegmentGroup } from "@/routes/BankApplication/components/ChecklistWorkspace/components/SplitDocumentModal/components/SplitSegmentGroup";
import { DocumentTypeCode } from "@/types";

type Props = {
  pageCount: number;
  isPdfLoading: boolean;
  isPdfError: boolean;
  segments: PageSegment[];
  focusedPage: number;
  typeOptions: SelectOption[];
  assignToOptions: SelectOption[];
  documentTypeCodes: DocumentTypeCode[];
  applicantCount: number;
  typeFor: (startPage: number) => string;
  assigneeFor: (startPage: number) => string;
  removedStarts: Set<number>;
  onTypeChange: (startPage: number, documentType: string) => void;
  onAssigneeChange: (startPage: number, applicantId: string) => void;
  onFocusPage: (page: number) => void;
  onAddCut: (afterPage: number) => void;
  onRemoveCut: (afterPage: number) => void;
  onToggleRemoved: (startPage: number) => void;
  showValidationErrors?: boolean;
};

export const SplitPageList: FC<Props> = ({
  pageCount,
  isPdfLoading,
  isPdfError,
  segments,
  focusedPage,
  typeOptions,
  assignToOptions,
  documentTypeCodes,
  applicantCount,
  typeFor,
  assigneeFor,
  removedStarts,
  onTypeChange,
  onAssigneeChange,
  onFocusPage,
  onAddCut,
  onRemoveCut,
  onToggleRemoved,
  showValidationErrors = false,
}) => {
  if (isPdfLoading && pageCount === 0) {
    return <CenteredStatus label="Reading pages…" />;
  }

  if (isPdfError) {
    return (
      <p role="alert" className="px-2 py-10 text-center text-xs text-destructive">
        Couldn&apos;t read the document pages.
      </p>
    );
  }

  return (
    <>
      <p className="mb-3 text-xs text-muted-foreground">
        This file has {pageCount} {pageCount === 1 ? "page" : "pages"}. Group them into the
        documents they should become, set a type and assignee for each, and click a page to preview
        it.
      </p>

      <div className="space-y-2">
        {segments.map((segment, segmentIndex) => (
          <SplitSegmentGroup
            key={segment.start}
            segment={segment}
            segmentIndex={segmentIndex}
            focusedPage={focusedPage}
            selectedType={typeFor(segment.start)}
            selectedAssignee={assigneeFor(segment.start)}
            typeOptions={typeOptions}
            assignToOptions={assignToOptions}
            documentTypeCodes={documentTypeCodes}
            applicantCount={applicantCount}
            isRemoved={removedStarts.has(segment.start)}
            onTypeChange={onTypeChange}
            onAssigneeChange={onAssigneeChange}
            onFocusPage={onFocusPage}
            onAddCut={onAddCut}
            onRemoveCut={onRemoveCut}
            onToggleRemoved={onToggleRemoved}
            showValidationErrors={showValidationErrors}
          />
        ))}
      </div>
    </>
  );
};
