import type { BankApplication, ExtractedFieldGroup, ExtractedFieldGroupRow } from "@/types";

import type { AdibApplicantContact } from "../types";
import { PERSON_NAME_MATCH_THRESHOLD, personNameSimilarity } from "./personNameMatching";

const ADIB_HOME_FINANCE_APPLICATION_DOCUMENT_TYPE = "ADIB_HOME_FINANCE_APPLICATION";
const APPLICANTS_GROUP_NAME = "applicants";

const EMPTY_CONTACT: AdibApplicantContact = { mobileNumber: "", email: "" };

/** Case-level ADIB form document id, or undefined for non-ADIB cases / when it is not uploaded. */
export const getAdibHomeFinanceDocumentId = (
  bankApplication: BankApplication | undefined,
): string | undefined => {
  if (bankApplication?.bank.name !== "ADIB") return undefined;

  return bankApplication.checklist.caseDocuments.find(
    (row) => row.type === ADIB_HOME_FINANCE_APPLICATION_DOCUMENT_TYPE,
  )?.matchedFile?.documentId;
};

const findCellValue = (row: ExtractedFieldGroupRow, fieldKey: string): string =>
  row.fields.find((cell) => cell.fieldKey === fieldKey)?.value?.trim() ?? "";

const getRowName = (row: ExtractedFieldGroupRow): string =>
  `${findCellValue(row, "first_name")} ${findCellValue(row, "last_name")}`;

/** The single best-scoring row at or above the threshold; undefined on a tie or no confident match. */
const pickBestMatchingRow = (
  rows: ExtractedFieldGroupRow[],
  passportName: string,
): ExtractedFieldGroupRow | undefined => {
  const ranked = rows
    .map((row) => ({ row, score: personNameSimilarity(getRowName(row), passportName) }))
    .sort((a, b) => b.score - a.score);

  const [best, runnerUp] = ranked;
  if (!best || best.score < PERSON_NAME_MATCH_THRESHOLD) return undefined;
  if (runnerUp && runnerUp.score === best.score) return undefined;
  return best.row;
};

/**
 * The form lists one row per applicant. Picks the row whose name best matches the main applicant's
 * passport name, so another applicant's contact details are never used.
 */
export const pickAdibApplicantContactFields = (
  groups: ExtractedFieldGroup[],
  passportName: string | null | undefined,
): AdibApplicantContact => {
  if (!passportName?.trim()) return EMPTY_CONTACT;

  const applicantRows = groups.find((group) => group.name === APPLICANTS_GROUP_NAME)?.items ?? [];
  const matchedRow = pickBestMatchingRow(applicantRows, passportName);
  if (!matchedRow) return EMPTY_CONTACT;

  return {
    mobileNumber: findCellValue(matchedRow, "mobile_number"),
    email: findCellValue(matchedRow, "email"),
  };
};
