import { type FC } from "react";

import {
  usePatchEligibilityCheckLiability,
  useDropEligibilityCheckLiabilityAmountOverride,
} from "@/api";
import type { PatchEligibilityCheckLiabilityPayload } from "@/api";
import type {
  DocumentField,
  EligibilityFrequency,
  EligibilityLineSource,
  LiabilityType,
  Money,
} from "@/types";

import { CalculationRow } from "./CalculationRow";
import { TypeSelect } from "./TypeSelect";
import {
  getLiabilityAllocationTooltipText,
  isLiabilityAllocationEditable,
  LIABILITY_TYPE_LABELS,
} from "../../constants";
import { useRemoveEligibilityLine } from "../../context/RemoveEligibilityLineContext";
import { useEligibilityChecksRoute } from "../../hooks/useEligibilityChecksRoute";
import { resolveTypeOptions } from "../../utils";

type Props = {
  liabilityId: string;
  description: string;
  documentType: string;
  liabilityType: LiabilityType;
  frequency: EligibilityFrequency | null;
  allocation: number;
  amount: Money;
  originalAmount?: Money;
  fxRate: string | null;
  amountOverride: string | null;
  eligibleAmount: Money;
  documentFields: DocumentField[];
  source: EligibilityLineSource;
  typeOptions: LiabilityType[];
};

export const LiabilityCalculationRow: FC<Props> = ({
  liabilityId,
  description,
  documentType,
  liabilityType,
  frequency,
  allocation,
  amount,
  originalAmount,
  fxRate,
  amountOverride,
  eligibleAmount,
  documentFields,
  source,
  typeOptions,
}) => {
  const { bankApplication } = useEligibilityChecksRoute();
  const { beginRemove } = useRemoveEligibilityLine();
  const { mutateAsync, isPending, variables } = usePatchEligibilityCheckLiability();
  const {
    mutateAsync: dropAmountOverride,
    isPending: isDroppingOverride,
    variables: dropVariables,
  } = useDropEligibilityCheckLiabilityAmountOverride();
  const isSaving =
    (isPending && variables?.liabilityId === liabilityId) ||
    (isDroppingOverride && dropVariables?.liabilityId === liabilityId);
  const isManual = source === "MANUAL";
  const isOther = liabilityType === "OTHER";
  const hasAmountOverride = amountOverride != null;

  if (!bankApplication) return null;

  const patch = async (payload: PatchEligibilityCheckLiabilityPayload) => {
    await mutateAsync({
      bankApplicationId: bankApplication.id,
      liabilityId,
      payload,
    });
  };

  const clearAmountOverride = async () => {
    await dropAmountOverride({ bankApplicationId: bankApplication.id, liabilityId });
  };

  return (
    <CalculationRow
      description={description}
      descriptionEditable={isManual}
      onDescriptionChange={
        isManual ? (nextDescription) => patch({ description: nextDescription }) : undefined
      }
      documentType={documentType}
      source={source}
      documentFields={documentFields}
      emptyDocumentFieldsMessage="No transaction details available for this liability."
      disabled={isSaving}
      typeSelect={
        <TypeSelect
          value={liabilityType}
          options={resolveTypeOptions(liabilityType, typeOptions)}
          labels={LIABILITY_TYPE_LABELS}
          disabled={isSaving || isManual}
          onValueChange={(value) => {
            if (value !== liabilityType) void patch({ liabilityType: value as LiabilityType });
          }}
        />
      }
      frequency={isManual ? "MONTHLY" : hasAmountOverride ? null : frequency}
      frequencyEditable={!isManual && !hasAmountOverride && liabilityType !== "FIXED_ITEM"}
      onFrequencyChange={(value) => {
        if (frequency !== null && value !== frequency) void patch({ frequency: value });
      }}
      allocation={hasAmountOverride ? 100 : allocation}
      allocationEditable={isLiabilityAllocationEditable(
        liabilityType,
        hasAmountOverride,
        frequency,
        source,
      )}
      allocationTooltipText={getLiabilityAllocationTooltipText(
        liabilityType,
        hasAmountOverride,
        frequency,
        source,
      )}
      onAllocationChange={(value) => patch({ allocation: value })}
      amount={amountOverride ?? String(amount.value)}
      amountEditable={isOther}
      onAmountChange={isOther ? (amount) => patch({ amount }) : undefined}
      amountOverridden={hasAmountOverride}
      onClearAmountOverride={hasAmountOverride ? clearAmountOverride : undefined}
      eligibleAmount={eligibleAmount}
      originalCurrency={originalAmount?.currency ?? null}
      amountCurrency={amount.currency}
      fxRate={fxRate}
      onRemove={
        source === "MANUAL"
          ? () => beginRemove({ kind: "liability", lineId: liabilityId, description })
          : undefined
      }
    />
  );
};
