import { RELATIONSHIP_TYPE_TO_LABEL } from "@/constants";
import type { Applicant, ApplicantRole } from "@/types";

export const getApplicantsByRole = (applicants: Applicant[], role: ApplicantRole): Applicant[] =>
  applicants.filter((applicant) => applicant.role === role);

export const getMainApplicant = (applicants: Applicant[]): Applicant | undefined =>
  applicants.find((applicant) => applicant.role === "MAIN");

export const formatApplicantNames = (applicants: Applicant[]): string =>
  applicants
    .map((applicant) => applicant.fullName)
    .filter(Boolean)
    .join(", ");

export const formatApplicantRelationships = (applicants: Applicant[]): string =>
  applicants
    .map((applicant) =>
      applicant.relationshipType ? RELATIONSHIP_TYPE_TO_LABEL[applicant.relationshipType] : "",
    )
    .filter(Boolean)
    .join(", ");

export const formatCoApplicantNamesForSubject = (applicants: Applicant[]): string => {
  const coApplicantNames = formatApplicantNames(getApplicantsByRole(applicants, "CO_APPLICANT"));
  const coBorrowerNames = formatApplicantNames(getApplicantsByRole(applicants, "CO_BORROWER"));

  if (coApplicantNames && coBorrowerNames) {
    return `${coApplicantNames} / ${coBorrowerNames}`;
  }

  return coApplicantNames || coBorrowerNames;
};
