import { useCallback, useState, type FC } from "react";

import { cn } from "@huspy/shared-ui";

import {
  getDocumentPreviewErrorMessage,
  useDocument,
  useDocumentPreviewUrl,
  useRotateDocument,
} from "@/api";
import { openUrlInNewTab } from "@/utils";
import { Modal, PillButton, CustomSkeleton } from "@/components";
import type { DocumentPreviewTarget } from "@/routes/BankApplication/components/ChecklistWorkspace/context/DocumentPreviewContext";
import { PdfPreviewRotateControls } from "@/routes/BankApplication/components/ChecklistWorkspace/components/PdfPreviewRotateControls";
import { getDocumentActionAvailability } from "@/routes/BankApplication/components/ChecklistWorkspace/utils/getDocumentActionAvailability";

import { PdfDocumentPreview } from "./PdfDocumentPreview";
import { PreviewPaneLoadingOverlay } from "./PreviewPaneLoadingOverlay";
import {
  isImageContentType,
  isInlinePreviewSupported,
  isPdfContentType,
  pendingRotationToApiAngle,
  rotatePendingLeft,
  rotatePendingRight,
  type PendingRotation,
} from "./utils";

type Props = {
  bankApplicationId: string;
  isOpen: boolean;
  onOpenChange: (open: boolean) => void;
  previewTarget: DocumentPreviewTarget | null;
  onDocServiceDocumentIdChange: (docServiceDocumentId: string) => void;
};

export const DocumentPreviewModal: FC<Props> = ({
  bankApplicationId,
  isOpen,
  onOpenChange,
  previewTarget,
  onDocServiceDocumentIdChange,
}) => {
  const [pendingRotation, setPendingRotation] = useState<PendingRotation>(0);
  const [loadedPreviewUrl, setLoadedPreviewUrl] = useState<string | null>(null);
  const docServiceDocumentId = previewTarget?.docServiceDocumentId;
  const isPreviewActive = isOpen && !!docServiceDocumentId;

  const {
    data: document,
    isLoading: isDocumentLoading,
    isError: isDocumentError,
  } = useDocument(isPreviewActive ? docServiceDocumentId : undefined, {
    pollUntilUploaded: isPreviewActive,
  });

  const isDocumentUploaded = document?.isUploaded === true;
  const isWaitingForUpload =
    isPreviewActive && !isDocumentError && !isDocumentLoading && !!document && !isDocumentUploaded;

  const {
    data: previewUrl,
    isLoading: isPreviewUrlLoading,
    isError: isPreviewUrlError,
    error: previewUrlError,
  } = useDocumentPreviewUrl(docServiceDocumentId, isPreviewActive && isDocumentUploaded);

  const {
    mutateAsync: rotateDocument,
    isPending: isSavingRotation,
    isError: isRotateError,
    reset: resetRotate,
  } = useRotateDocument();

  const handleOpenChange = useCallback(
    (open: boolean) => {
      if (!open) {
        setPendingRotation(0);
        setLoadedPreviewUrl(null);
        resetRotate();
      }
      onOpenChange(open);
    },
    [onOpenChange, resetRotate],
  );

  const handlePdfLoadingChange = useCallback(
    (isLoading: boolean) => {
      if (!isLoading && previewUrl) {
        setLoadedPreviewUrl(previewUrl);
      }
    },
    [previewUrl],
  );

  const handleSaveRotation = async () => {
    const angle = pendingRotationToApiAngle(pendingRotation);
    if (!angle || !previewTarget?.documentId || isSavingRotation) return;

    resetRotate();
    const nextDocServiceDocumentId = await rotateDocument({
      documentId: previewTarget.documentId,
      angle,
      bankApplicationId,
    });
    setPendingRotation(0);
    onDocServiceDocumentIdChange(nextDocServiceDocumentId);
  };

  const isMetadataLoading =
    isDocumentLoading || isWaitingForUpload || isPreviewUrlLoading || isSavingRotation;
  const isError = isDocumentError || isPreviewUrlError;
  const isPdfPreview = isPdfContentType(document?.contentType);
  const isShowInlinePreview =
    !!previewUrl && !isError && isInlinePreviewSupported(document?.contentType);
  const isPdfRendering =
    isShowInlinePreview && isPdfPreview && !!previewUrl && previewUrl !== loadedPreviewUrl;
  const isPreviewPaneLoading = isMetadataLoading || isPdfRendering;

  const previewErrorMessage = isPreviewUrlError
    ? getDocumentPreviewErrorMessage(previewUrlError)
    : "Failed to load document preview.";
  const loadingLabel = isSavingRotation
    ? "Saving rotation…"
    : isWaitingForUpload
      ? "Preparing document…"
      : "Loading preview…";
  const fileName = document?.name ?? "";
  const contentType = document?.contentType;
  const hasPendingRotation = pendingRotation !== 0;
  const showFooterOpenInNewTab =
    isPreviewPaneLoading || (!!previewUrl && !isError && isShowInlinePreview);
  const rotateAvailability = getDocumentActionAvailability(
    "rotate",
    previewTarget?.processingStatus,
  );

  return (
    <Modal
      isOpen={isOpen}
      onOpenChange={handleOpenChange}
      title="Document preview"
      description={previewTarget?.underwritingServiceFileName}
      className="sm:max-w-[67.2rem]!"
    >
      <div className="flex min-h-[min(72vh,38.4rem)] flex-1 flex-col px-6 py-5">
        <div
          className={cn(
            "bg-muted/50 relative flex min-h-0 flex-1 flex-col overflow-hidden rounded-lg border border-border",
            !isPdfPreview && "items-center justify-center",
          )}
          aria-busy={isPreviewPaneLoading}
        >
          {isPreviewPaneLoading && <PreviewPaneLoadingOverlay label={loadingLabel} />}

          {isError && (
            <p role="alert" className="px-4 text-center text-sm text-destructive">
              {isDocumentError ? "Failed to load document preview." : previewErrorMessage}
            </p>
          )}

          {isShowInlinePreview && isPdfPreview && (
            <PdfDocumentPreview
              key={previewUrl}
              previewUrl={previewUrl}
              rotation={pendingRotation}
              onPdfLoadingChange={handlePdfLoadingChange}
              rotateControls={{
                canSave: hasPendingRotation,
                isSaving: isSavingRotation,
                onRotateLeft: () => setPendingRotation((current) => rotatePendingLeft(current)),
                onRotateRight: () => setPendingRotation((current) => rotatePendingRight(current)),
                onResetRotation: () => setPendingRotation(0),
                onSave: () => void handleSaveRotation(),
                disabled: rotateAvailability.disabled,
                disabledTooltip: rotateAvailability.disabled
                  ? rotateAvailability.tooltip
                  : undefined,
              }}
            />
          )}

          {isShowInlinePreview && isImageContentType(contentType) && (
            <div className="relative flex h-full w-full items-center justify-center">
              <img
                src={previewUrl}
                alt={fileName}
                className="max-h-full max-w-full object-contain"
                style={{ transform: `rotate(${pendingRotation}deg)` }}
                loading="lazy"
                decoding="async"
              />
              <PdfPreviewRotateControls
                className="absolute bottom-2 right-2 z-10"
                canSave={hasPendingRotation}
                isSaving={isSavingRotation}
                onRotateLeft={() => setPendingRotation((current) => rotatePendingLeft(current))}
                onRotateRight={() => setPendingRotation((current) => rotatePendingRight(current))}
                onResetRotation={() => setPendingRotation(0)}
                onSave={() => void handleSaveRotation()}
                disabled={rotateAvailability.disabled}
                disabledTooltip={
                  rotateAvailability.disabled ? rotateAvailability.tooltip : undefined
                }
              />
            </div>
          )}

          {!!previewUrl &&
            !isError &&
            !isDocumentLoading &&
            !isInlinePreviewSupported(contentType) && (
              <div className="flex flex-col items-center gap-3 px-4 text-center">
                <p className="text-sm text-muted-foreground">
                  Inline preview is not available for this file type.
                </p>
                <PillButton
                  type="button"
                  buttonRole="secondary"
                  onClick={() => openUrlInNewTab(previewUrl)}
                >
                  Open in new tab
                </PillButton>
              </div>
            )}
        </div>

        {isRotateError && (
          <p role="alert" className="mt-3 text-sm text-destructive">
            Failed to save document rotation.
          </p>
        )}

        {showFooterOpenInNewTab && (
          <div className="mt-4 flex items-center justify-end">
            {isPreviewPaneLoading ? (
              <div
                className="flex h-9.5 items-center rounded-full border border-solid border-border bg-card px-5"
                aria-busy
                aria-label="Loading action"
              >
                <CustomSkeleton className="h-3.5 w-25" />
              </div>
            ) : (
              <PillButton
                type="button"
                buttonRole="secondary"
                onClick={() => openUrlInNewTab(previewUrl!)}
              >
                Open in new tab
              </PillButton>
            )}
          </div>
        )}
      </div>
    </Modal>
  );
};
