import { TRANSACTION_TYPE_TO_LABEL } from "@/constants";
import type { BankApplication } from "@/types";
import { formatMoneyAmount } from "@/utils";

import {
  formatApplicantNames,
  formatApplicantRelationships,
  getApplicantsByRole,
  getMainApplicant,
} from "../utils/applicantUtils";
import type { AdibApplicantContact } from "../types";
import { formatCustomerProfileLine } from "../utils/formatCustomerProfile";
import { formatPassportDisplayName } from "../utils/formatPassportDisplayName";
import { formatLtvForEmail, formatPropertyValueForEmail } from "./formatSnapshotFields";

export const formatFinanceAmount = (amount: number | null, currency: string | null): string => {
  if (amount == null || currency == null) return "";
  return formatMoneyAmount(amount, currency);
};

const formatCoApplicantLines = (applicants: BankApplication["applicants"]): string[] => {
  const coApplicants = getApplicantsByRole(applicants, "CO_APPLICANT");
  if (coApplicants.length === 0) return [];

  return [
    `Co-applicant Name: ${formatApplicantNames(coApplicants)}`,
    `Relationship with Co-applicant: ${formatApplicantRelationships(coApplicants)}`,
  ];
};

const formatCoBorrowerLines = (applicants: BankApplication["applicants"]): string[] => {
  const coBorrowers = getApplicantsByRole(applicants, "CO_BORROWER");
  if (coBorrowers.length === 0) return [];

  return [
    `Co-borrower Name: ${formatApplicantNames(coBorrowers)}`,
    `Relationship with Co-borrower: ${formatApplicantRelationships(coBorrowers)}`,
  ];
};

const formatSharedCaseDetailsTail = (
  bankApplication: BankApplication,
  loanTenorMonths: string,
  transactionLabel: string,
): string[] => [
  `Finance Amount: ${formatFinanceAmount(bankApplication.amount, bankApplication.currency)}`,
  `Transaction Type: ${transactionLabel}`,
  `Customer's Profile: ${formatCustomerProfileLine(bankApplication.applicants)}`,
  `Product (Rate of Interest): ${bankApplication.bankRateName?.trim() ?? ""}`,
  `Loan Tenor (in months): ${loanTenorMonths}`,
  `LTV: ${formatLtvForEmail(bankApplication.ltvPercent)}`,
];

export const formatCaseDetailsBlock = (
  bankApplication: BankApplication,
  loanTenorMonths: string,
  adibApplicantContact?: AdibApplicantContact,
): string => {
  const mainApplicant = getMainApplicant(bankApplication.applicants);
  const transactionLabel =
    bankApplication.transactionType != null
      ? TRANSACTION_TYPE_TO_LABEL[bankApplication.transactionType]
      : "";
  const isAdib = bankApplication.bank.name === "ADIB";

  const lines = [
    "Case details",
    `Customer's Name as per Passport: ${formatPassportDisplayName(
      mainApplicant?.nameAsPerPassport,
    )}`,
    ...(isAdib
      ? [
          `Customer's Mobile Number as per Home Finance Application Form: ${adibApplicantContact?.mobileNumber ?? ""}`,
          `Customer's Email Address: ${adibApplicantContact?.email ?? ""}`,
        ]
      : []),
    ...formatCoApplicantLines(bankApplication.applicants),
    ...formatCoBorrowerLines(bankApplication.applicants),
    ...(isAdib
      ? [
          `Property Value: ${formatPropertyValueForEmail(
            bankApplication.propertyValue,
            bankApplication.currency,
          )}`,
        ]
      : []),
    ...formatSharedCaseDetailsTail(bankApplication, loanTenorMonths, transactionLabel),
  ];

  return lines.join("\n");
};
