import { useSplitSegmentField } from "./useSplitSegmentField";

type UseSplitDocumentTypesParams = {
  segmentStarts: number[];
  initialDocumentType?: string;
};

type UseSplitDocumentTypesResult = {
  typeFor: (startPage: number) => string;
  setTypeForSegment: (startPage: number, documentType: string) => void;
  reset: () => void;
};

export const useSplitDocumentTypes = ({
  segmentStarts,
  initialDocumentType,
}: UseSplitDocumentTypesParams): UseSplitDocumentTypesResult => {
  const { valueFor, setValueForSegment, reset } = useSplitSegmentField(
    segmentStarts,
    (): Record<number, string> => (initialDocumentType ? { 1: initialDocumentType } : {}),
  );

  return {
    typeFor: valueFor,
    setTypeForSegment: setValueForSegment,
    reset,
  };
};
