import { useSearchParams } from "@huspy/fe";

import { useBankApplications } from "@/api";

import {
  APPLICANT_NAME_PARAM,
  BANK_ID_PARAM,
  CREATED_AT_FROM_PARAM,
  CREATED_AT_TO_PARAM,
  CREATED_BY_ID_PARAM,
  PAGE_PARAM,
} from "@/routes/OpsQueue/constants";

const getPageFromSearchParams = (searchParams: URLSearchParams): number => {
  const page = Number(searchParams.get(PAGE_PARAM) ?? "0");
  return Number.isFinite(page) && page >= 0 ? page : 0;
};

export const useOpsQueueBankApplications = () => {
  const [searchParams, setSearchParams] = useSearchParams();
  const applicantName = searchParams.get(APPLICANT_NAME_PARAM) || undefined;
  const createdById = searchParams.get(CREATED_BY_ID_PARAM) || undefined;
  const bankId = searchParams.get(BANK_ID_PARAM) || undefined;
  const createdAtFrom = searchParams.get(CREATED_AT_FROM_PARAM) || undefined;
  const createdAtTo = searchParams.get(CREATED_AT_TO_PARAM) || undefined;
  const page = getPageFromSearchParams(searchParams);

  const bankApplications = useBankApplications({
    page,
    applicantName,
    createdById,
    bankId,
    createdAtFrom,
    createdAtTo,
  });

  const setPage = (nextPage: number) => {
    setSearchParams(
      (prev) => {
        const next = new URLSearchParams(prev);

        if (nextPage <= 0) {
          next.delete(PAGE_PARAM);
        } else {
          next.set(PAGE_PARAM, String(nextPage));
        }

        return next.toString() === prev.toString() ? prev : next;
      },
      { replace: true },
    );
  };

  return {
    ...bankApplications,
    page,
    setPage,
    applicantName,
    createdById,
    bankId,
    createdAtFrom,
    createdAtTo,
  };
};
