import type { ComponentType } from "react";

import { cn, Tooltip, TooltipContent, TooltipTrigger } from "@huspy/shared-ui";

type Props = {
  label: string;
  icon: ComponentType<{ className?: string; "aria-hidden"?: boolean }>;
  iconClassName?: string;
  onClick: () => void;
  disabled?: boolean;
  /** Shown instead of `label` on hover when `disabled` is true, e.g. why the action is unavailable. */
  disabledTooltip?: string;
  variant?: "default" | "destructive";
};

export function RowActionButton({
  label,
  icon: Icon,
  iconClassName,
  onClick,
  disabled,
  disabledTooltip,
  variant = "default",
}: Props) {
  const tooltip = disabled && disabledTooltip ? disabledTooltip : label;

  return (
    <Tooltip>
      <TooltipTrigger asChild>
        {/* disabled buttons don't fire pointer events needed for the tooltip trigger, so this span keeps hover working. */}
        <span className={cn("inline-flex", disabled && "pointer-events-auto")}>
          <button
            type="button"
            aria-label={label}
            disabled={disabled}
            className={cn(
              "flex size-7 shrink-0 cursor-pointer items-center justify-center rounded-lg text-muted-foreground",
              "focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:outline-none",
              "disabled:pointer-events-none disabled:opacity-50",
              variant === "destructive"
                ? "hover:bg-destructive/12 hover:text-destructive"
                : "hover:bg-grey-60 hover:text-foreground",
            )}
            onClick={onClick}
          >
            <Icon className={cn("size-4 shrink-0", iconClassName)} aria-hidden />
          </button>
        </span>
      </TooltipTrigger>
      <TooltipContent>{tooltip}</TooltipContent>
    </Tooltip>
  );
}
