import { FC } from "react";

import type { Checklist } from "@/types";

import { getChecklistCounts } from "@/routes/BankApplication/utils";
import { bankApplicationCardTitleClassName } from "@/routes/BankApplication/constants";

import { BankApplicationCard } from "../BankApplicationCard";
import { LegendItem } from "./LegendItem";

type Props = {
  checklist: Checklist;
};

export const ChecklistProgressCard: FC<Props> = ({ checklist }) => {
  const { mandatory, received, missing, optional } = getChecklistCounts(checklist);
  const progress = mandatory === 0 ? 0 : (received / mandatory) * 100;

  return (
    <BankApplicationCard>
      <div className="mb-4 flex items-center justify-between gap-3">
        <p className={bankApplicationCardTitleClassName}>Checklist Progress</p>
        <span className="text-xs tabular-nums text-foreground-secondary">
          {`${received} of ${mandatory} required received`}
        </span>
      </div>

      <div
        className="h-1.5 w-full overflow-hidden rounded-full bg-grey-60"
        role="progressbar"
        aria-valuemin={0}
        aria-valuemax={mandatory}
        aria-valuenow={received}
        aria-label={`${received} of ${mandatory} required documents received`}
      >
        <div className="h-full rounded-full bg-success" style={{ width: `${progress}%` }} />
      </div>

      <div className="mt-3 flex flex-wrap items-center gap-4 text-xs text-foreground-secondary">
        <LegendItem dotClassName="bg-success" label={`${received} received`} />
        <LegendItem dotClassName="bg-destructive" label={`${missing} missing`} />
        <LegendItem dotClassName="bg-grey-300" label={`${optional} optional`} />
      </div>
    </BankApplicationCard>
  );
};
