import type { PropertyStatus, TransactionType } from "@/types";

import { getAllowedPropertyStatuses } from "./getAllowedPropertyStatuses";

export const getSinglePropertyStatus = (
  transactionType: TransactionType,
): PropertyStatus | null => {
  const allowedPropertyStatuses = getAllowedPropertyStatuses(transactionType);
  return allowedPropertyStatuses.length === 1 ? allowedPropertyStatuses[0] : null;
};
