import type { Applicant } from "@/types";

const APPLICANT_NAME_SEPARATOR = " & ";

export const joinApplicantNames = (applicants: Applicant[]): string =>
  [
    ...applicants.filter(({ role }) => role === "MAIN"),
    ...applicants.filter(({ role }) => role !== "MAIN"),
  ]
    .map(({ fullName }) => fullName?.trim() ?? "")
    .filter(Boolean)
    .join(APPLICANT_NAME_SEPARATOR);
