import { formatMoneyAmount } from "@/utils";

export const formatLtvForEmail = (ltvPercent: number | null | undefined): string => {
  if (ltvPercent == null) return "";
  const formatted = ltvPercent.toFixed(2).replace(/\.?0+$/, "");
  return `${formatted}%`;
};

export const formatPropertyValueForEmail = (
  propertyValue: number | null | undefined,
  currency: string | null,
): string => {
  if (propertyValue == null || currency == null) return "";
  return formatMoneyAmount(propertyValue, currency);
};
