import { useState } from "react";

export type UseSessionStorageOptions<T = unknown> = {
  storageFormat?: "json" | "raw";
  readValue?: (item: string | null, initialValue: T) => T;
};

function parseStoredValue<T>(
  item: string | null,
  initialValue: T,
  storageFormat: "json" | "raw",
): T {
  if (item === null) {
    return initialValue;
  }
  if (storageFormat === "raw") {
    return item as T;
  }
  return JSON.parse(item) as T;
}

function resolveStored<T>(
  item: string | null,
  initialValue: T,
  storageFormat: "json" | "raw",
  readValue: ((item: string | null, initialValue: T) => T) | undefined,
): T {
  if (readValue) {
    return readValue(item, initialValue);
  }
  return parseStoredValue(item, initialValue, storageFormat);
}

/** Persists state in sessionStorage for the current tab (survives refresh, cleared when tab closes). */
export function useSessionStorage<T>(
  key: string,
  initialValue: T,
  options?: UseSessionStorageOptions<T>,
): [T, (value: T | ((val: T) => T)) => void] {
  const storageFormat = options?.storageFormat ?? "json";

  const [storedValue, setStoredValue] = useState<T>(() => {
    if (typeof window === "undefined") {
      return initialValue;
    }
    try {
      const item = globalThis.sessionStorage.getItem(key);
      return resolveStored(item, initialValue, storageFormat, options?.readValue);
    } catch {
      return initialValue;
    }
  });

  const setValue = (value: T | ((val: T) => T)) => {
    try {
      const valueToStore = value instanceof Function ? value(storedValue) : value;
      setStoredValue(valueToStore);
      if (typeof window !== "undefined") {
        const serialized =
          storageFormat === "raw"
            ? String(valueToStore as unknown as string | number | boolean)
            : JSON.stringify(valueToStore);
        globalThis.sessionStorage.setItem(key, serialized);
      }
    } catch {
      // Do nothing
    }
  };

  return [storedValue, setValue];
}
