import { useAssetUrl, useNavigate } from "@huspy/fe";
import { UserAvatar } from "@huspy/shared-ui";

import { ROUTES } from "@/constants";

const LOGO_BLACK = "images/logos/huspy-logo-black_v1.svg";

export function AppBar() {
  const logoUrl = useAssetUrl(LOGO_BLACK);
  const navigate = useNavigate();
  const userName = window.huspy.auth.user?.fullName?.trim();

  return (
    <header className="flex h-14 items-center justify-between border-b border-border bg-card px-6">
      <button
        type="button"
        onClick={() => navigate(ROUTES.opsQueue)}
        className="flex cursor-pointer items-center gap-3"
      >
        <img src={logoUrl} alt="Huspy" className="h-4.5 w-auto object-contain" />
        <span className="h-5 w-px bg-border" aria-hidden />
        <span className="select-none text-md font-semibold">Credit Ops</span>
      </button>

      {userName && (
        <div className="flex items-center gap-2.5">
          <span className="text-sm">{userName}</span>
          <UserAvatar
            name={userName}
            className="size-7"
            fallbackClassName="bg-input text-[11px] font-semibold text-grey-700"
          />
        </div>
      )}
    </header>
  );
}
