import type { BankApplication, EligibilityChecks } from "@/types";

export const MOCK_ELIGIBILITY_CHECKS_PARAM = "mockEligibilityChecks";

/** Requested amount used with ?mockEligibilityChecks so loan affordability can be assessed in dev. */
export const MOCK_REQUESTED_AMOUNT = 2_000_000;

export const isMockEligibilityChecksEnabled = (searchParams: URLSearchParams): boolean =>
  searchParams.has(MOCK_ELIGIBILITY_CHECKS_PARAM);

export const applyMockEligibilityChecksBankApplication = (
  bankApplication: BankApplication,
  searchParams: URLSearchParams,
): BankApplication =>
  isMockEligibilityChecksEnabled(searchParams)
    ? { ...bankApplication, amount: MOCK_REQUESTED_AMOUNT }
    : bankApplication;

