import { EMAIL_TEMPLATE_DRAFT_SESSION_STORAGE_PREFIX } from "@/routes/BankApplication/utils";

import type { StoredEmailTemplateDraft } from "../types";

export const readEmailTemplateDraft = (storageKey: string): StoredEmailTemplateDraft | null => {
  try {
    const item = globalThis.sessionStorage.getItem(storageKey);
    if (item === null) return null;
    return JSON.parse(item) as StoredEmailTemplateDraft;
  } catch {
    return null;
  }
};

export const writeEmailTemplateDraft = (
  storageKey: string,
  draft: StoredEmailTemplateDraft,
): void => {
  try {
    globalThis.sessionStorage.setItem(storageKey, JSON.stringify(draft));
  } catch {
    // Do nothing
  }
};

export const clearAllEmailTemplateDraftsFromSessionStorage = (): void => {
  try {
    const storage = globalThis.sessionStorage;
    const keysToRemove: string[] = [];

    for (let index = 0; index < storage.length; index += 1) {
      const key = storage.key(index);
      if (key?.startsWith(EMAIL_TEMPLATE_DRAFT_SESSION_STORAGE_PREFIX)) {
        keysToRemove.push(key);
      }
    }

    for (const key of keysToRemove) {
      storage.removeItem(key);
    }
  } catch {
    // Do nothing
  }
};
