import type { FC } from "react";

import { cn, UserAvatar } from "@huspy/shared-ui";

import type { EligibilityApplicant } from "@/types";

type Props = {
  applicants: EligibilityApplicant[];
  activeApplicantId: string;
  onActiveApplicantIdChange: (applicantId: string) => void;
};

export const ApplicantTabs: FC<Props> = ({
  applicants,
  activeApplicantId,
  onActiveApplicantIdChange,
}) => (
  <div className="flex flex-wrap items-center gap-1.5">
    {applicants.map((applicant) => {
      const isActive = applicant.id === activeApplicantId;

      return (
        <button
          key={applicant.id}
          type="button"
          aria-pressed={isActive}
          onClick={() => onActiveApplicantIdChange(applicant.id)}
          className={cn(
            "flex h-7 cursor-pointer items-center gap-1.5 rounded-full pr-2.5 pl-1 text-[13px]",
            isActive
              ? "bg-foreground text-background dark:bg-secondary dark:text-secondary-foreground"
              : "border border-solid border-border bg-card text-foreground hover:bg-muted",
          )}
        >
          <UserAvatar
            name={applicant.name}
            className="size-5"
            fallbackClassName="bg-input text-[9px] font-semibold text-grey-700"
          />

          <span className="font-medium">{applicant.name}</span>
        </button>
      );
    })}
  </div>
);
