import { useWaiveBankPolicyCheck } from "@/api";
import type { BankPolicyCheck } from "@/types";

import { WaiveCheckModal as SharedWaiveCheckModal } from "../RuleChecksCard";

type Props = {
  isOpen: boolean;
  onOpenChange: (open: boolean) => void;
  bankApplicationId: string;
  check: BankPolicyCheck | null;
};

export function WaiveCheckModal({ isOpen, onOpenChange, bankApplicationId, check }: Props) {
  const waiveCheck = useWaiveBankPolicyCheck();

  return (
    <SharedWaiveCheckModal
      isOpen={isOpen}
      onOpenChange={onOpenChange}
      checkTitle={check?.title}
      isPending={waiveCheck.isPending}
      onReset={() => waiveCheck.reset()}
      onSubmit={(reason, { onSuccess, onError }) => {
        if (!check) return;

        waiveCheck.mutate(
          { bankApplicationId, checkId: check.id, reason },
          {
            onSuccess,
            onError: (err) =>
              onError(err instanceof Error ? err.message : "Could not waive check."),
          },
        );
      }}
    />
  );
}
