import { useFieldArray, useFormContext } from "react-hook-form";

import { Plus } from "@huspy/shared-icons";
import { Button } from "@huspy/shared-ui";

import { SectionHeader } from "@/routes/OpsQueue/components/CreateMortgageApplicationModal/CreateMortgageApplicationForm/components";
import { CreateMortgageApplicationFormValues } from "@/routes/OpsQueue/components/CreateMortgageApplicationModal/CreateMortgageApplicationForm/types";
import { getEmptyApplicantRow } from "@/routes/OpsQueue/components/CreateMortgageApplicationModal/CreateMortgageApplicationForm/utils";

import { Applicant } from "./Applicant";
import { canAddAdditionalApplicant, getAdditionalApplicantDisplayNumber } from "./utils";

export const ApplicantsSection = () => {
  const { control, clearErrors } = useFormContext<CreateMortgageApplicationFormValues>();
  const {
    fields: applicantFields,
    append,
    remove,
  } = useFieldArray({
    control,
    name: "applicants",
  });
  const canAddApplicant = canAddAdditionalApplicant(applicantFields);

  const handleAddApplicant = () => {
    if (!canAddApplicant) return;

    clearErrors("applicants");
    append(getEmptyApplicantRow());
  };

  const handleRemoveApplicant = (idx: number) => () => {
    clearErrors("applicants");
    remove(idx);
  };

  return (
    <div className="pt-5">
      <SectionHeader title="Applicant" number={2} />

      {applicantFields.map((field, idx) => (
        <Applicant
          key={field.id}
          idx={idx}
          displayNumber={getAdditionalApplicantDisplayNumber(applicantFields, idx)}
          onRemove={handleRemoveApplicant(idx)}
        />
      ))}

      {canAddApplicant && (
        <div className="mt-4">
          <Button
            type="button"
            variant="ghost"
            className="h-auto w-fit gap-1 p-1 text-sm font-medium text-foreground hover:bg-muted"
            onClick={handleAddApplicant}
          >
            <Plus className="size-3.5" />
            Add applicant
          </Button>
        </div>
      )}
    </div>
  );
};
