import { useState, type FC, type ReactNode } from "react";

import { Trash2 } from "@huspy/shared-icons";
import { cn, Tooltip, TooltipContent, TooltipTrigger } from "@huspy/shared-ui";

import { useDocumentTypeCodesForBankApplication } from "@/api";
import type {
  DocumentField,
  EarningType,
  EligibilityFrequency,
  EligibilityLineSource,
  Money,
} from "@/types";
import { getDocumentTypeLabel } from "@/routes/BankApplication/components/ChecklistWorkspace/components/DocumentRow/utils";
import { RowActionButton } from "@/routes/BankApplication/components/ChecklistWorkspace/components/RowActionButton";

import {
  CALCULATION_ROW_GRID,
  CALCULATION_TABLE_ACTION_SLOT,
  CALCULATION_TABLE_ROW_GRID_CLASSNAME,
  CALCULATION_TABLE_ROW_SHELL,
  CALCULATION_TABLE_ROW_SURFACE_SHELL_CLASSNAME,
  EXCLUDED_STATUS_BADGE_CLASSNAME,
  LINE_SOURCE_BADGE_CLASSNAME,
  MANUAL_LINE_SOURCE_LABEL,
} from "../../constants";
import { useEligibilityChecksRoute } from "../../hooks/useEligibilityChecksRoute";
import { formatDecimalAmount, formatEligibleLineAmount } from "../../utils";
import { AllocationPercentInput } from "./AllocationPercentInput";
import { LineCurrencyLabel } from "./LineCurrencyLabel";
import { OverrideClearButton } from "./OverrideClearButton";
import { DescriptionInput } from "./DescriptionInput";
import { DocumentFieldsPanel } from "./DocumentFieldsPanel";
import { ExpandToggle } from "./ExpandToggle";
import { FrequencySelect } from "./FrequencySelect";
import { MonthlyAmountInput } from "./MonthlyAmountInput";

type Props = {
  description: string;
  descriptionEditable?: boolean;
  onDescriptionChange?: (description: string) => void | Promise<void>;
  documentType: string;
  source?: EligibilityLineSource;
  documentFields: DocumentField[];
  /** When set, the row stays expandable without document fields and shows this message instead. */
  emptyDocumentFieldsMessage?: string;
  statusLabel?: string;
  statusTooltipText?: string;
  typeSelect: ReactNode;
  frequency: EligibilityFrequency | null;
  onFrequencyChange: (frequency: EligibilityFrequency) => void;
  frequencyEditable?: boolean;
  allocation: number;
  onAllocationChange: (allocation: number) => void | Promise<void>;
  allocationEditable?: boolean;
  allocationTooltipText?: string;
  amount: string;
  amountEditable?: boolean;
  onAmountChange?: (amount: number) => void | Promise<void>;
  amountOverridden?: boolean;
  onClearAmountOverride?: () => void | Promise<void>;
  eligibleAmount: Money;
  /** Currency of the original amount; null when the line is already in the bank application currency. */
  originalCurrency: string | null;
  /** Currency of `amount`; null when it could not be detected. */
  amountCurrency: string | null;
  fxRate: string | null;
  numOfPayslips?: number | null;
  maxPeriods?: number | null;
  earningType?: EarningType;
  disabled: boolean;
  /** Shown for context only: dimmed, with every cell except description and monthly amount empty. */
  referenceOnly?: boolean;
  onRemove?: () => void;
};

const descriptionTextClassName = "min-w-0 truncate text-[13px] font-medium text-foreground";

const emptyCell = <span className="text-xs text-muted-foreground">—</span>;

export const CalculationRow: FC<Props> = ({
  description,
  descriptionEditable = false,
  onDescriptionChange,
  documentType,
  source,
  documentFields,
  emptyDocumentFieldsMessage,
  statusLabel,
  statusTooltipText,
  typeSelect,
  frequency,
  onFrequencyChange,
  frequencyEditable = true,
  allocation,
  onAllocationChange,
  allocationEditable = true,
  allocationTooltipText,
  amount,
  amountEditable = false,
  onAmountChange,
  amountOverridden = false,
  onClearAmountOverride,
  eligibleAmount,
  originalCurrency,
  amountCurrency,
  fxRate,
  numOfPayslips,
  maxPeriods,
  earningType,
  disabled,
  referenceOnly = false,
  onRemove,
}) => {
  const { bankApplicationId, currency } = useEligibilityChecksRoute();
  const isCurrencyUndetected = amountCurrency == null;
  const { data: documentTypeCodes = [] } = useDocumentTypeCodesForBankApplication(
    bankApplicationId,
    {
      includeMergeTargets: true,
    },
  );
  const [expanded, setExpanded] = useState(false);
  const hasDocumentFields = documentFields.length > 0;
  const isExpandable = hasDocumentFields || emptyDocumentFieldsMessage != null;

  if (!currency) return null;

  const lineSourceLabel =
    source === "MANUAL"
      ? MANUAL_LINE_SOURCE_LABEL
      : documentType
        ? getDocumentTypeLabel(documentType, documentTypeCodes)
        : null;

  return (
    <div className={cn((disabled || referenceOnly) && "opacity-60")}>
      <div className={CALCULATION_TABLE_ROW_SHELL}>
        <div
          className={cn(CALCULATION_TABLE_ROW_SURFACE_SHELL_CLASSNAME, "flex-col items-stretch")}
        >
          <div className="flex items-center gap-1">
            <div className={cn(CALCULATION_TABLE_ROW_GRID_CLASSNAME, CALCULATION_ROW_GRID)}>
              <div className="flex min-w-0 items-center gap-2">
                <ExpandToggle
                  expanded={expanded}
                  onToggle={() => setExpanded((prev) => !prev)}
                  visible={referenceOnly || (source !== "MANUAL" && isExpandable)}
                  disabled={referenceOnly}
                />

                <div className="min-w-0 flex-1">
                  <div className="flex min-w-0 items-center gap-2">
                    {descriptionEditable && onDescriptionChange ? (
                      <div className="min-w-0 flex-1">
                        <DescriptionInput
                          value={description}
                          disabled={disabled}
                          onCommit={onDescriptionChange}
                        />
                      </div>
                    ) : (
                      <span className={descriptionTextClassName} title={description}>
                        {description}
                      </span>
                    )}

                    {statusLabel &&
                      (statusTooltipText ? (
                        <Tooltip>
                          <TooltipTrigger asChild>
                            <span className={cn(EXCLUDED_STATUS_BADGE_CLASSNAME, "cursor-help")}>
                              {statusLabel}
                            </span>
                          </TooltipTrigger>
                          <TooltipContent>{statusTooltipText}</TooltipContent>
                        </Tooltip>
                      ) : (
                        <span className={EXCLUDED_STATUS_BADGE_CLASSNAME}>{statusLabel}</span>
                      ))}
                  </div>

                  {lineSourceLabel && (
                    <span className={LINE_SOURCE_BADGE_CLASSNAME}>{lineSourceLabel}</span>
                  )}
                </div>
              </div>

              <div className="text-center">{referenceOnly ? emptyCell : typeSelect}</div>

              <div className="text-center">
                {referenceOnly || frequency === null ? (
                  <span className="text-xs text-muted-foreground">—</span>
                ) : (
                  <FrequencySelect
                    value={frequency}
                    disabled={disabled || !frequencyEditable}
                    onValueChange={onFrequencyChange}
                  />
                )}
              </div>

              <div className="flex items-center justify-center gap-1">
                {amountEditable && onAmountChange ? (
                  <MonthlyAmountInput
                    value={amount}
                    currency={currency}
                    isCurrencyUndetected={isCurrencyUndetected}
                    disabled={disabled}
                    onCommit={onAmountChange}
                  />
                ) : (
                  <>
                    <LineCurrencyLabel currency={currency} isUndetected={isCurrencyUndetected} />
                    <span className="text-xs tabular-nums text-foreground">
                      {formatDecimalAmount(amount)}
                    </span>
                  </>
                )}
                {amountOverridden && onClearAmountOverride && (
                  <OverrideClearButton
                    disabled={disabled}
                    ariaLabel="Reset to calculated amount"
                    onClear={onClearAmountOverride}
                  />
                )}
              </div>

              {referenceOnly ? (
                <div className="text-center">{emptyCell}</div>
              ) : allocationEditable ? (
                <AllocationPercentInput
                  value={allocation}
                  disabled={disabled}
                  onCommit={onAllocationChange}
                />
              ) : (
                <div className="text-center cursor-default">
                  {allocationTooltipText ? (
                    <Tooltip>
                      <TooltipTrigger asChild>
                        <span className="text-xs tabular-nums text-foreground">{`${allocation}%`}</span>
                      </TooltipTrigger>
                      <TooltipContent>{allocationTooltipText}</TooltipContent>
                    </Tooltip>
                  ) : (
                    <span className="text-xs tabular-nums text-foreground">{`${allocation}%`}</span>
                  )}
                </div>
              )}

              <span className="text-center text-xs font-medium tabular-nums text-foreground">
                {referenceOnly ? emptyCell : formatEligibleLineAmount(eligibleAmount, currency)}
              </span>
            </div>

            {onRemove ? (
              <RowActionButton
                label="Remove"
                icon={Trash2}
                variant="destructive"
                disabled={disabled}
                onClick={onRemove}
              />
            ) : (
              <span className={CALCULATION_TABLE_ACTION_SLOT} aria-hidden />
            )}
          </div>

          {expanded && !hasDocumentFields && emptyDocumentFieldsMessage != null && (
            <p className="-mx-2 mt-1.5 border-t border-border/40 px-2 pt-1.5 text-[11px] text-muted-foreground">
              {emptyDocumentFieldsMessage}
            </p>
          )}

          {expanded && hasDocumentFields && (
            <DocumentFieldsPanel
              documentFields={documentFields}
              documentType={documentType}
              frequency={frequency}
              amount={amount}
              originalCurrency={originalCurrency}
              currency={amountCurrency ?? currency}
              fxRate={fxRate}
              numOfPayslips={numOfPayslips}
              maxPeriods={maxPeriods}
              earningType={earningType}
            />
          )}
        </div>
      </div>
    </div>
  );
};
