import { useEffect } from "react";

type UseKeyboardNavigationParams = {
  isEnabled: boolean;
  currentPage: number;
  maxPage: number;
  onNavigate: (page: number) => void;
};

export const useKeyboardNavigation = ({
  isEnabled,
  currentPage,
  maxPage,
  onNavigate,
}: UseKeyboardNavigationParams): void => {
  useEffect(() => {
    if (!isEnabled) return;

    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === "ArrowDown" && currentPage < maxPage) {
        event.preventDefault();
        onNavigate(currentPage + 1);
      } else if (event.key === "ArrowUp" && currentPage > 1) {
        event.preventDefault();
        onNavigate(currentPage - 1);
      }
    };

    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [isEnabled, currentPage, maxPage, onNavigate]);
};
