import type { BankPolicyCheck } from "@/types";
import { formatDayMonthYear } from "@/utils";

import { getCountryName } from "./countryNames";

const NATIONALITY_RULE_CODES = new Set(["NATIONALITY_RESTRICTED", "NATIONALITY_ALLOWED"]);

/** Title for a nationality check, naming the applicant's actual nationality on both outcomes;
 * the default title for every other check. */
export const formatCheckTitle = (check: BankPolicyCheck): string => {
  const subjectValue = check.comparison?.subjectValue;
  if (!NATIONALITY_RULE_CODES.has(check.ruleCode) || !subjectValue) {
    return check.title;
  }

  const countryName = getCountryName(subjectValue);
  if (check.status === "FAIL")
    return `Applicant's nationality (${countryName}) is restricted by this bank.`;
  if (check.status === "PASS") return `Applicant's nationality (${countryName}) is supported.`;
  return check.title;
};

const formatComparisonValue = (value: string, unit: string | null): string => {
  if (/^\d{4}-\d{2}-\d{2}/.test(value) && !Number.isNaN(Date.parse(value))) {
    return formatDayMonthYear(value);
  }

  if (unit) return `${value} ${unit}`;
  return value;
};

/** Human-readable explanation of why a failing check failed; null when there is nothing to show. */
export const formatCheckComparison = (check: BankPolicyCheck): string | null => {
  if (check.status !== "FAIL") return null;

  const { subjectValue, targetValue, unit } = check.comparison ?? {};
  if (!subjectValue && !targetValue) return null;

  const subjectText = subjectValue ? formatComparisonValue(subjectValue, unit ?? null) : null;
  const targetText = targetValue ? formatComparisonValue(targetValue, unit ?? null) : null;

  if (subjectText && targetText) return `${subjectText} ≠ ${targetText}`;
  return subjectText ?? targetText;
};
