import { ProcessingStatus } from "@/types";
import { isProcessingInProgress } from "@/utils";

export const getProcessingInProgressMessage = (
  processingStatus: ProcessingStatus | null | undefined,
): string | null => {
  if (!isProcessingInProgress(processingStatus)) return null;

  switch (processingStatus) {
    case "CLASSIFICATION_IN_PROGRESS":
      return "Classification is in progress";
    case "EXTRACTION_IN_PROGRESS":
      return "Extraction is in progress";
    case "ROTATION_IN_PROGRESS":
      return "Rotation is in progress";
    case "SPLIT_IN_PROGRESS":
      return "Split is in progress";
    case "MERGE_IN_PROGRESS":
      return "Merge is in progress";
    default:
      return "Document is being processed";
  }
};
