import type { BankApplication, EligibilityChecks } from "@/types";

import { formatCaseNoteLines } from "./standardEmailTemplate/formatCaseNotesBlock";
import { formatEligibilityBlock } from "./standardEmailTemplate/formatEligibilityBlock";

type BuildEmailBodyInput = {
  caseDetailsBlock: string;
  bankApplication: BankApplication;
  eligibilityChecks: EligibilityChecks | undefined;
  underwriterName: string;
};

/** Shared frame around a template's case details: greeting, eligibility, case notes and sign-off. */
export const buildEmailBody = ({
  caseDetailsBlock,
  bankApplication,
  eligibilityChecks,
  underwriterName,
}: BuildEmailBodyInput): string => {
  const caseNoteLines = formatCaseNoteLines(eligibilityChecks, bankApplication.currency);
  const bodyParts = [
    "Hi team,",
    "",
    "Requesting you to process the following case:",
    "",
    caseDetailsBlock,
    "",
    formatEligibilityBlock(eligibilityChecks, bankApplication.currency),
  ];

  if (caseNoteLines.length > 0) {
    bodyParts.push("", "Case Notes", ...caseNoteLines);
  }

  bodyParts.push("", "Thanks & Regards,", underwriterName);

  return bodyParts.join("\n");
};
