import { useState, type FC } from "react";

import { CircleAlert, RefreshCw } from "@huspy/shared-icons";
import { Banner, Input, Label, Textarea } from "@huspy/shared-ui";

import { LoadErrorMessage } from "@/components";
import { bankApplicationCardTitleClassName } from "@/routes/BankApplication/constants";
import { RowActionButton } from "@/routes/BankApplication/components/ChecklistWorkspace/components/RowActionButton";

import { BankApplicationCard } from "../BankApplicationCard";
import { EmailTemplateCopyButton } from "./components/EmailTemplateCopyButton";
import { EmailTemplateSendButton } from "./components/EmailTemplateSendButton";
import { RefreshEmailTemplateDialog } from "./components/RefreshEmailTemplateDialog";
import { EmailTemplateTabSkeleton } from "./EmailTemplateTabSkeleton";
import { useEmailTemplateTabRoute } from "./hooks/useEmailTemplateTabRoute";

export const EmailTemplateTab: FC = () => {
  const {
    draft,
    status,
    isStale,
    setSubject,
    setBody,
    refresh,
    isPendingBankApplication,
    isPendingEligibilityChecks,
    isErrorBankApplication,
  } = useEmailTemplateTabRoute();
  const [isRefreshDialogOpen, setIsRefreshDialogOpen] = useState(false);

  if (isPendingBankApplication || isPendingEligibilityChecks || status === "loading") {
    return <EmailTemplateTabSkeleton />;
  }

  if (isErrorBankApplication) {
    return (
      <BankApplicationCard padding="empty">
        <LoadErrorMessage>Could not load application. Please try again.</LoadErrorMessage>
      </BankApplicationCard>
    );
  }

  return (
    <>
      <BankApplicationCard className="flex flex-col gap-5">
        <div className="flex flex-wrap items-center justify-between gap-3">
          <h2 className={bankApplicationCardTitleClassName}>Email draft</h2>
          <RowActionButton
            label="Refresh"
            icon={RefreshCw}
            onClick={() => setIsRefreshDialogOpen(true)}
          />
        </div>

        {isStale && (
          <Banner variant="alert" icon={<CircleAlert aria-hidden />}>
            <p className="mb-0.5 text-sm font-semibold leading-snug">
              Case details have changed since this draft was generated
            </p>
            <p className="text-[13px] font-medium leading-snug">
              Refresh to pick up the latest data. Your edits will be replaced.
            </p>
          </Banner>
        )}

        <div className="flex flex-col gap-2">
          <div className="flex items-center justify-between gap-3">
            <Label htmlFor="email-template-subject">Subject</Label>
            <EmailTemplateCopyButton value={draft.subject} fieldLabel="subject" />
          </div>
          <Input
            id="email-template-subject"
            value={draft.subject}
            onChange={(event) => setSubject(event.target.value)}
          />
        </div>

        <div className="flex flex-col gap-2">
          <div className="flex items-center justify-between gap-3">
            <Label htmlFor="email-template-body">Body</Label>
            <div className="flex items-center gap-2">
              <EmailTemplateCopyButton value={draft.body} fieldLabel="body" />
              <EmailTemplateSendButton subject={draft.subject} body={draft.body} />
            </div>
          </div>
          <Textarea
            id="email-template-body"
            value={draft.body}
            onChange={(event) => setBody(event.target.value)}
            rows={16}
            className="min-h-64 resize-y"
          />
        </div>
      </BankApplicationCard>

      <RefreshEmailTemplateDialog
        isOpen={isRefreshDialogOpen}
        onOpenChange={setIsRefreshDialogOpen}
        onConfirm={refresh}
      />
    </>
  );
};
