import type { FC } from "react";

import { Button } from "@huspy/shared-ui";

import { buildGmailComposeUrl, GMAIL_COMPOSE_URL_MAX_LENGTH } from "../utils";

type Props = {
  subject: string;
  body: string;
};

export const EmailTemplateSendButton: FC<Props> = ({ subject, body }) => {
  const isDraftEmpty = subject === "" && body === "";
  const composeUrl = buildGmailComposeUrl({ subject, body });
  const isUrlTooLong = composeUrl.length > GMAIL_COMPOSE_URL_MAX_LENGTH;

  return (
    <Button
      type="button"
      variant="secondary"
      size="sm"
      disabled={isDraftEmpty || isUrlTooLong}
      title={
        isUrlTooLong
          ? "Email is too long to open in Gmail. Copy the subject and body instead."
          : undefined
      }
      onClick={() => window.open(composeUrl, "_blank", "noopener,noreferrer")}
    >
      Send
    </Button>
  );
};
