import type { FC } from "react";
import { useFormContext, useWatch } from "react-hook-form";

import { FloatingLabelInput, FloatingLabelSelect } from "@huspy/shared-agents";
import { Button, Separator } from "@huspy/shared-ui";

import type { ApplicantRole, EmploymentType, RelationshipType, ResidencyType } from "@/types";
import {
  APPLICANT_ROLE_OPTIONS,
  EMPLOYMENT_TYPE_OPTIONS,
  RELATIONSHIP_TYPE_OPTIONS,
  RESIDENCY_TYPE_OPTIONS,
} from "@/constants";
import { CreateMortgageApplicationFormValues } from "@/routes/OpsQueue/components/CreateMortgageApplicationModal/CreateMortgageApplicationForm/types";

import { getAdditionalApplicantLabel } from "./utils";

type Props = {
  idx: number;
  displayNumber: number;
  onRemove: () => void;
};

export const Applicant: FC<Props> = ({ idx, displayNumber, onRemove }) => {
  const {
    control,
    setValue,
    clearErrors,
    formState: { errors },
  } = useFormContext<CreateMortgageApplicationFormValues>();

  const applicant = useWatch({ control, name: `applicants.${idx}` });
  const applicantRole = applicant?.applicantRole;
  const applicantRoleError = errors.applicants?.[idx]?.applicantRole;

  const firstName = applicant?.firstName ?? "";
  const firstNameError = errors.applicants?.[idx]?.firstName;

  const lastName = applicant?.lastName ?? "";
  const lastNameError = errors.applicants?.[idx]?.lastName;

  const employmentType = applicant?.employmentType;
  const employmentTypeError = errors.applicants?.[idx]?.employmentType;

  const residencyType = applicant?.residencyType;
  const residencyTypeError = errors.applicants?.[idx]?.residencyType;

  const relationshipType = applicant?.relationshipType;
  const relationshipTypeError = errors.applicants?.[idx]?.relationshipType;

  const isMainApplicant = applicantRole === "MAIN";
  return (
    <>
      {!isMainApplicant && (
        <>
          <Separator className="mt-4.5 mb-2" />

          <div className="flex items-center justify-between mb-1">
            <p className="text-xs text-muted-foreground">
              {getAdditionalApplicantLabel(applicantRole, displayNumber)}
            </p>
            <Button
              type="button"
              variant="ghost"
              onClick={onRemove}
              className="h-6 text-destructive hover:text-destructive"
            >
              Remove
            </Button>
          </div>
        </>
      )}

      <div className="grid grid-cols-2 gap-3">
        <FloatingLabelInput
          label="First name"
          value={firstName}
          onChange={(e) => {
            clearErrors(`applicants.${idx}.firstName`);
            setValue(`applicants.${idx}.firstName`, e.target.value, {
              shouldDirty: true,
              shouldValidate: true,
            });
          }}
          error={!!firstNameError}
          errorMessage={firstNameError?.message}
          className="h-14"
        />
        <FloatingLabelInput
          label="Last name"
          value={lastName}
          onChange={(e) => {
            clearErrors(`applicants.${idx}.lastName`);
            setValue(`applicants.${idx}.lastName`, e.target.value, {
              shouldDirty: true,
              shouldValidate: true,
            });
          }}
          error={!!lastNameError}
          errorMessage={lastNameError?.message}
          className="h-14"
        />
        <FloatingLabelSelect
          label="Employment type"
          options={EMPLOYMENT_TYPE_OPTIONS}
          value={employmentType ?? ""}
          onValueChange={(value) => {
            clearErrors(`applicants.${idx}.employmentType`);
            setValue(`applicants.${idx}.employmentType`, value as EmploymentType, {
              shouldDirty: true,
              shouldValidate: true,
            });
          }}
          error={!!employmentTypeError}
          errorMessage={employmentTypeError?.message}
        />
        <FloatingLabelSelect
          label="Residency"
          options={RESIDENCY_TYPE_OPTIONS}
          value={residencyType ?? ""}
          onValueChange={(value) => {
            clearErrors(`applicants.${idx}.residencyType`);
            setValue(`applicants.${idx}.residencyType`, value as ResidencyType, {
              shouldDirty: true,
              shouldValidate: true,
            });
          }}
          error={!!residencyTypeError}
          errorMessage={residencyTypeError?.message}
        />
        {!isMainApplicant && (
          <FloatingLabelSelect
            label="Applicant Role"
            options={APPLICANT_ROLE_OPTIONS}
            value={applicantRole ?? ""}
            onValueChange={(value) => {
              clearErrors(`applicants.${idx}.applicantRole`);
              setValue(`applicants.${idx}.applicantRole`, value as ApplicantRole, {
                shouldDirty: true,
                shouldValidate: true,
              });
              if (value === "MAIN") {
                clearErrors(`applicants.${idx}.relationshipType`);
                setValue(`applicants.${idx}.relationshipType`, null, {
                  shouldDirty: true,
                  shouldValidate: true,
                });
              }
            }}
            error={!!applicantRoleError}
            errorMessage={applicantRoleError?.message}
          />
        )}
        {!isMainApplicant && (
          <FloatingLabelSelect
            label="Relationship"
            options={RELATIONSHIP_TYPE_OPTIONS}
            value={relationshipType ?? ""}
            onValueChange={(value) => {
              clearErrors(`applicants.${idx}.relationshipType`);
              setValue(`applicants.${idx}.relationshipType`, value as RelationshipType, {
                shouldDirty: true,
                shouldValidate: true,
              });
            }}
            error={!!relationshipTypeError}
            errorMessage={relationshipTypeError?.message}
          />
        )}
      </div>
    </>
  );
};
