import type { FC } from "react";

import type { ExtractedFieldGroup, ExtractedFieldGroupRow } from "@/types";

import { GroupTable } from "./GroupTable";

type Props = {
  group: ExtractedFieldGroup;
  rows: ExtractedFieldGroupRow[];
  /** Orphan rows show their join column so it can be corrected. */
  showJoinColumns?: boolean;
  useLocalRowNumbers?: boolean;
};

export const ChildRowsSection: FC<Props> = ({
  group,
  rows,
  showJoinColumns = false,
  useLocalRowNumbers = true,
}) => {
  if (rows.length === 0) return null;

  return (
    <section className="space-y-3">
      <h5 className="text-xs font-medium uppercase tracking-wide text-muted-foreground">
        {group.label}
      </h5>
      <GroupTable
        group={group}
        items={rows}
        showJoinColumns={showJoinColumns}
        useLocalRowNumbers={useLocalRowNumbers}
      />
    </section>
  );
};
