import type { FC } from "react";

import { Button } from "@huspy/shared-ui";

import { Modal, ModalFooter } from "@/components";

type Props = {
  isOpen: boolean;
  onOpenChange: (open: boolean) => void;
  onConfirm: () => void;
};

export const RefreshEmailTemplateDialog: FC<Props> = ({ isOpen, onOpenChange, onConfirm }) => (
  <Modal
    isOpen={isOpen}
    onOpenChange={onOpenChange}
    title="Refresh email draft?"
    description="This replaces the subject and body with values generated from the latest case data. Your edits will be lost."
  >
    <ModalFooter className="gap-2 px-6 pb-6 sm:justify-end">
      <Button type="button" variant="secondary" onClick={() => onOpenChange(false)}>
        Cancel
      </Button>
      <Button
        type="button"
        onClick={() => {
          onConfirm();
          onOpenChange(false);
        }}
      >
        Refresh
      </Button>
    </ModalFooter>
  </Modal>
);
