import { KeyboardEvent, useEffect, useRef, useState } from "react";

import { Search, X } from "@huspy/shared-icons";
import {
  cn,
  Input,
  Label,
  Popover,
  PopoverContent,
  RadioGroup,
  RadioGroupItem,
} from "@huspy/shared-ui";

import { useInternalUserById, useInternalUsers } from "@/api";
import { formatInternalUserDisplayName } from "@/api/userRequests";

import { FilterColumnTrigger } from "../FilterColumnTrigger";
import { FilterPopoverActions } from "../FilterPopoverActions";

import { INTERNAL_USER_SEARCH_DEBOUNCE_MS, INTERNAL_USER_SEARCH_MIN_LENGTH } from "./constants";

type Props = {
  value: string;
  onApply: (userId: string) => void;
  onClear: () => void;
};

export function CreatedByFilter({ value, onApply, onClear }: Props) {
  const inputRef = useRef<HTMLInputElement>(null);
  const [open, setOpen] = useState(false);
  const [draft, setDraft] = useState(value);
  const [search, setSearch] = useState("");
  const [debouncedSearch, setDebouncedSearch] = useState("");

  const { data: selectedUser } = useInternalUserById(value || undefined);
  const { data: searchResults, isFetching, isError } = useInternalUsers(debouncedSearch, open);

  useEffect(() => {
    if (!open) return;

    const timeoutId = window.setTimeout(() => {
      setDebouncedSearch(search.trim());
      setDraft("");
    }, INTERNAL_USER_SEARCH_DEBOUNCE_MS);

    return () => window.clearTimeout(timeoutId);
  }, [open, search]);

  const handleOpenChange = (nextOpen: boolean) => {
    if (nextOpen) {
      setDraft("");
    } else {
      setSearch("");
      setDebouncedSearch("");
    }
    setOpen(nextOpen);
  };

  const handleApply = () => {
    onApply(draft);
    setOpen(false);
  };

  const handleClear = () => {
    onClear();
    setDraft("");
    setSearch("");
    setDebouncedSearch("");
    setOpen(false);
  };

  const canApply = draft !== "" && draft !== value;

  const handleKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    if (event.key === "Enter" && canApply) {
      event.preventDefault();
      handleApply();
    }
  };

  const trimmedSearch = search.trim();
  const trimmedDebouncedSearch = debouncedSearch.trim();
  const users = searchResults?.content ?? [];
  const selectableUsers = selectedUser && value ? users.filter((user) => user.id !== value) : users;

  const showMinLengthHint =
    open && trimmedSearch.length > 0 && trimmedSearch.length < INTERNAL_USER_SEARCH_MIN_LENGTH;
  const showEmptyResults =
    open &&
    trimmedDebouncedSearch.length >= INTERNAL_USER_SEARCH_MIN_LENGTH &&
    !isFetching &&
    !isError &&
    users.length === 0;

  return (
    <Popover open={open} onOpenChange={handleOpenChange}>
      <FilterColumnTrigger label="Created by" align="center" />

      <PopoverContent
        className="bg-popover w-72"
        side="bottom"
        align="center"
        onOpenAutoFocus={(event) => {
          event.preventDefault();
          inputRef.current?.focus();
        }}
      >
        <div className="mb-3">
          {selectedUser && value && (
            <div className="mb-4 flex items-center gap-2 rounded-md border border-border bg-muted px-2 py-1.5">
              <span className="min-w-0 flex-1 text-sm font-semibold text-foreground">
                {formatInternalUserDisplayName(selectedUser)}
              </span>
              <button
                type="button"
                onClick={handleClear}
                className="text-muted-foreground hover:text-foreground shrink-0 cursor-pointer"
                aria-label="Clear created by filter"
              >
                <X className="size-3.5" />
              </button>
            </div>
          )}

          <div className="relative mb-3">
            <Search
              className="text-muted-foreground pointer-events-none absolute top-1/2 left-3 size-3.5 -translate-y-1/2"
              aria-hidden
            />
            <Input
              ref={inputRef}
              type="text"
              value={search}
              onChange={(e) => {
                setSearch(e.target.value);
                setDraft("");
              }}
              placeholder="Search users…"
              className="bg-background pl-8"
              aria-label="Search users"
            />
          </div>

          {showMinLengthHint && (
            <p className="text-muted-foreground px-1 py-2 text-sm">
              Type at least {INTERNAL_USER_SEARCH_MIN_LENGTH} characters to search
            </p>
          )}

          {isFetching && trimmedDebouncedSearch.length >= INTERNAL_USER_SEARCH_MIN_LENGTH && (
            <p className="text-muted-foreground px-1 py-2 text-sm">Searching…</p>
          )}

          {isError && (
            <p className="text-muted-foreground px-1 py-2 text-sm">Unable to load users</p>
          )}

          {showEmptyResults && (
            <p className="text-muted-foreground px-1 py-2 text-sm">No users found</p>
          )}

          {selectableUsers.length > 0 && (
            <RadioGroup
              value={draft}
              onValueChange={setDraft}
              onKeyDown={handleKeyDown}
              className="max-h-48 overflow-y-auto gap-0.5"
            >
              {selectableUsers.map((user) => (
                <Label
                  key={user.id}
                  htmlFor={`created-by-filter-${user.id}`}
                  onFocus={(event) => {
                    event.currentTarget.scrollIntoView({ block: "nearest" });
                    setDraft(user.id);
                  }}
                  className={cn(
                    "relative flex cursor-pointer items-center rounded-md px-2 py-2 text-sm font-normal",
                    "hover:bg-muted",
                    "has-data-[state=checked]:bg-primary/10 has-data-[state=checked]:hover:bg-primary/10",
                    "has-focus-visible:bg-primary/10 has-focus-visible:hover:bg-primary/10",
                  )}
                >
                  <RadioGroupItem
                    value={user.id}
                    id={`created-by-filter-${user.id}`}
                    className="sr-only"
                  />
                  {formatInternalUserDisplayName(user)}
                </Label>
              ))}
            </RadioGroup>
          )}
        </div>

        <FilterPopoverActions onClear={handleClear} onApply={handleApply} canApply={canApply} />
      </PopoverContent>
    </Popover>
  );
}
