import { useState, type FC } from "react";

import { Input } from "@huspy/shared-ui";

import { parseTenorMonths } from "../../utils";

type Props = {
  value: number;
  disabled: boolean;
  onCommit: (tenorMonths: number) => void | Promise<void>;
};

export const TenorMonthsInput: FC<Props> = ({ value, disabled, onCommit }) => {
  const [draft, setDraft] = useState(String(value));
  const [invalid, setInvalid] = useState(false);
  const [prevValue, setPrevValue] = useState(value);

  if (value !== prevValue) {
    setPrevValue(value);
    setDraft(String(value));
    setInvalid(false);
  }

  const handleBlur = async () => {
    const parsed = parseTenorMonths(draft);
    if (parsed === null) {
      setDraft(String(value));
      setInvalid(true);
      return;
    }

    if (parsed === value) {
      setDraft(String(value));
      setInvalid(false);
      return;
    }

    setInvalid(false);
    setDraft(String(parsed));

    try {
      await onCommit(parsed);
    } catch {
      setDraft(String(value));
    }
  };

  return (
    <Input
      type="text"
      inputMode="numeric"
      value={draft}
      disabled={disabled}
      aria-label="Effective tenor in months"
      aria-invalid={invalid || undefined}
      onChange={(event) => {
        const next = event.target.value;

        if (next === "") {
          setDraft("");
          setInvalid(false);
          return;
        }

        if (!/^\d+$/.test(next)) return;

        const parsed = Number.parseInt(next, 10);
        if (parsed > 300) return;

        setDraft(next);
        setInvalid(false);
      }}
      onBlur={() => {
        void handleBlur();
      }}
      onKeyDown={(event) => {
        if (["-", "+", "e", "E", "."].includes(event.key)) {
          event.preventDefault();
          return;
        }

        if (event.key === "Enter") {
          event.currentTarget.blur();
        }
      }}
      className="h-8 w-12 px-1.5 text-center text-sm font-medium tabular-nums selection:bg-revert selection:text-revert"
    />
  );
};
