import type { ReactNode } from "react";

import {
  cn,
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@huspy/shared-ui";

type Props = {
  isOpen: boolean;
  onOpenChange: (open: boolean) => void;
  title: string;
  description?: ReactNode;
  className?: string;
  children: ReactNode;
};

export function Modal({ isOpen, onOpenChange, title, description, className, children }: Props) {
  return (
    <Dialog open={isOpen} onOpenChange={onOpenChange}>
      <DialogContent
        {...(!description ? { "aria-describedby": undefined } : {})}
        onEscapeKeyDown={() => onOpenChange(false)}
        className={cn(
          "flex max-h-[85vh] flex-col gap-0 overflow-hidden rounded-3xl p-0 sm:max-w-2xl!",
          className,
        )}
      >
        <div className="flex min-h-0 flex-1 flex-col gap-0">
          <DialogHeader className="flex shrink-0 flex-col gap-0 px-6 pt-6 pb-4 text-center sm:text-left">
            <DialogTitle className="leading-heading text-[17px] font-semibold text-foreground">
              {title}
            </DialogTitle>
            {!!description && (
              <DialogDescription className="mt-1 text-xs text-foreground-secondary">
                {description}
              </DialogDescription>
            )}
          </DialogHeader>
          {children}
        </div>
      </DialogContent>
    </Dialog>
  );
}
