import { useState, type FC } from "react";

import { Modal, ModalFooter, PillButton } from "@/components";
import { useDeleteEarning, useDeleteLiability } from "@/api";

import type { RemoveEligibilityLineTarget } from "../../context/RemoveEligibilityLineContext";

type Props = {
  isOpen: boolean;
  onOpenChange: (open: boolean) => void;
  bankApplicationId: string;
  target: RemoveEligibilityLineTarget | null;
};

const getCopy = (kind: RemoveEligibilityLineTarget["kind"] | undefined) => {
  if (kind === "liability") {
    return {
      title: "Remove liability line?",
      description: "This liability line will be removed.",
    };
  }

  return {
    title: "Remove income line?",
    description: "This income line will be removed.",
  };
};

export const RemoveLineModal: FC<Props> = ({ isOpen, onOpenChange, bankApplicationId, target }) => {
  const deleteEarning = useDeleteEarning();
  const deleteLiability = useDeleteLiability();
  const [submitError, setSubmitError] = useState<string | null>(null);

  const isPending = deleteEarning.isPending || deleteLiability.isPending;
  const { title, description } = getCopy(target?.kind);

  const handleOpenChange = (open: boolean) => {
    if (!open) {
      setSubmitError(null);
      deleteEarning.reset();
      deleteLiability.reset();
    }
    onOpenChange(open);
  };

  const handleRemove = () => {
    if (!target) return;

    setSubmitError(null);

    const onSuccess = () => handleOpenChange(false);
    const onError = (err: unknown) => {
      setSubmitError(err instanceof Error ? err.message : "Could not remove line.");
    };

    if (target.kind === "earning") {
      deleteEarning.mutate({ bankApplicationId, earningId: target.lineId }, { onSuccess, onError });
      return;
    }

    deleteLiability.mutate(
      { bankApplicationId, liabilityId: target.lineId },
      { onSuccess, onError },
    );
  };

  return (
    <Modal
      isOpen={isOpen}
      onOpenChange={handleOpenChange}
      className="sm:max-w-md!"
      title={title}
      description={description}
    >
      {submitError && (
        <p role="alert" className="px-6 pb-2 text-sm text-destructive">
          {submitError}
        </p>
      )}

      <ModalFooter className="justify-between">
        <PillButton
          type="button"
          buttonRole="secondary"
          onClick={() => handleOpenChange(false)}
          disabled={isPending}
        >
          Cancel
        </PillButton>
        <PillButton
          type="button"
          buttonRole="destructive"
          onClick={handleRemove}
          disabled={!target || isPending}
        >
          Remove
        </PillButton>
      </ModalFooter>
    </Modal>
  );
};
