import { cn } from "@huspy/shared-ui";
import { Loader2, Upload } from "@huspy/shared-icons";

type Props = {
  onClick: () => void;
  disabled?: boolean;
  isUploading?: boolean;
  prompt: string;
  uploadingPrompt?: string;
  helperText?: string;
  pickAriaLabel?: string;
  hasError?: boolean;
};

export function DocumentUploadDropzoneButton({
  onClick,
  disabled = false,
  isUploading = false,
  prompt,
  uploadingPrompt = "Uploading…",
  helperText,
  pickAriaLabel,
  hasError = false,
}: Props) {
  const label = isUploading ? uploadingPrompt : prompt;

  return (
    <button
      type="button"
      disabled={disabled}
      onClick={onClick}
      aria-label={pickAriaLabel ?? prompt}
      aria-busy={isUploading}
      className={cn(
        "flex w-full cursor-pointer flex-col items-center gap-1 rounded-2xl border border-dashed border-grey-200 bg-background p-7 text-muted-foreground transition-colors hover:bg-muted",
        hasError && "border-destructive",
        disabled && "cursor-not-allowed opacity-80",
      )}
    >
      {isUploading ? (
        <Loader2 aria-hidden className="size-6 shrink-0 animate-spin" strokeWidth={2} />
      ) : (
        <Upload className="size-6 shrink-0" strokeWidth={2} />
      )}
      <span className="text-[13px] font-semibold text-foreground">{label}</span>
      {helperText ? <span className="text-xs text-foreground-secondary">{helperText}</span> : null}
    </button>
  );
}
