import type { Applicant, DocumentTypeCode } from "@/types";
import { resolveDocumentApplicantIdPayload } from "@/routes/BankApplication/components/ChecklistWorkspace/utils";

import type { AddDocumentUploadFile } from "./types";

type LinkDocument = (variables: {
  bankApplicationId: string;
  documentServiceDocumentId: string;
  applicantId?: string | null;
  type?: string;
}) => Promise<unknown>;

type LinkUploadedDocumentsInput = {
  files: AddDocumentUploadFile[];
  bankApplicationId: string;
  applicants: Applicant[];
  selectedApplicantId: string;
  documentTypeCodes: DocumentTypeCode[];
  linkDocument: LinkDocument;
};

export type LinkUploadedDocumentsResult = {
  linkedDocumentIds: string[];
  error: string | null;
};

export const linkUploadedDocuments = async ({
  files,
  bankApplicationId,
  applicants,
  selectedApplicantId,
  documentTypeCodes,
  linkDocument,
}: LinkUploadedDocumentsInput): Promise<LinkUploadedDocumentsResult> => {
  const results = await Promise.allSettled(
    files.map(async (file) => {
      const applicantPayload = resolveDocumentApplicantIdPayload({
        applicants,
        selectedApplicantId,
        selectedDocumentType: file.documentType,
        documentTypeCodes,
      });

      await linkDocument({
        bankApplicationId,
        documentServiceDocumentId: file.documentId,
        ...applicantPayload,
        type: file.documentType,
      });

      return file.documentId;
    }),
  );

  const linkedDocumentIds = results.flatMap((result) =>
    result.status === "fulfilled" ? [result.value] : [],
  );

  const failedCount = files.length - linkedDocumentIds.length;
  if (failedCount === 0) {
    return { linkedDocumentIds, error: null };
  }

  const firstRejection = results.find(
    (result): result is PromiseRejectedResult => result.status === "rejected",
  );
  const rejectionMessage =
    firstRejection?.reason instanceof Error
      ? firstRejection.reason.message
      : "Could not add documents.";

  if (failedCount === files.length) {
    return { linkedDocumentIds, error: rejectionMessage };
  }

  return {
    linkedDocumentIds,
    error: `${failedCount} of ${files.length} documents could not be added.`,
  };
};
