import type { KeyboardEvent, MouseEvent } from "react";

const ROW_CLICK_IGNORE_ATTR = "data-row-click-ignore";

/** Spread onto row children that must not trigger the row-level click. */
export const ignoreRowClickProps = { [ROW_CLICK_IGNORE_ATTR]: "" } as const;

export const isRowClickIgnored = (event: MouseEvent<HTMLElement> | KeyboardEvent<HTMLElement>) =>
  event.target instanceof Element && event.target.closest(`[${ROW_CLICK_IGNORE_ATTR}]`) !== null;
