import type { FC } from "react";

import { usePatchBankApplicationStressRate, useResetBankApplicationStressRate } from "@/api";
import type { StressRate } from "@/types";

import { OverrideClearButton } from "../CalculationTable/OverrideClearButton";
import { useEligibilityChecksRoute } from "../../hooks/useEligibilityChecksRoute";
import { StressRatePercentInput } from "./StressRatePercentInput";

type Props = {
  label: string;
  stressRate: StressRate;
};

export const StressRateRow: FC<Props> = ({ label, stressRate }) => {
  const { bankApplication } = useEligibilityChecksRoute();
  const { mutateAsync: patchStressRate, isPending: isPatchingStressRate } =
    usePatchBankApplicationStressRate();
  const { mutateAsync: resetStressRate, isPending: isResettingStressRate } =
    useResetBankApplicationStressRate();

  if (!bankApplication) return null;

  const isOverridden = stressRate.overriddenStressRatePercent != null;
  const displayStressRatePercent =
    stressRate.overriddenStressRatePercent ?? stressRate.stressRatePercent;
  const isPending = isPatchingStressRate || isResettingStressRate;

  return (
    <div className="flex items-center justify-between flex-1 gap-3 px-2 py-2">
      <span className="min-w-0 flex-1 text-sm font-medium text-foreground">{label}</span>

      <div className="flex shrink-0 items-center gap-1">
        <StressRatePercentInput
          value={displayStressRatePercent}
          disabled={isPending}
          onCommit={async (value) => {
            await patchStressRate({
              bankApplicationId: bankApplication.id,
              payload: { stressRatePercent: value },
            });
          }}
        />
        {isOverridden && (
          <OverrideClearButton
            disabled={isPending}
            ariaLabel="Reset to calculated stress rate"
            tooltip="Manually overridden. Click to reset to the calculated stress rate."
            onClear={async () => {
              await resetStressRate(bankApplication.id);
            }}
          />
        )}
      </div>
    </div>
  );
};
