import { createContext, type FC, type ReactNode, useContext, useMemo } from "react";

import type { DocumentChecklistRow, FileItemWithDocumentId } from "@/types";

import {
  DocumentAssignment,
  getInitialAssignToApplicantId,
} from "@/routes/BankApplication/components/ChecklistWorkspace/components/EditDocumentModal/constants";

export type { DocumentAssignment };

export type EditDocumentTarget =
  | {
      kind: "classified";
      document: DocumentChecklistRow & { matchedFile: FileItemWithDocumentId };
      assignment: DocumentAssignment;
    }
  | { kind: "unclassified"; file: FileItemWithDocumentId };

type EditDocumentContextValue = {
  beginEdit: (target: EditDocumentTarget) => void;
};

const EditDocumentContext = createContext<EditDocumentContextValue | null>(null);

type ProviderProps = {
  children: ReactNode;
  onBeginEdit: (target: EditDocumentTarget) => void;
};

export const EditDocumentProvider: FC<ProviderProps> = ({ children, onBeginEdit }) => {
  const value = useMemo(
    () => ({
      beginEdit: onBeginEdit,
    }),
    [onBeginEdit],
  );

  return <EditDocumentContext.Provider value={value}>{children}</EditDocumentContext.Provider>;
};

export const useEditDocument = (): EditDocumentContextValue => {
  const ctx = useContext(EditDocumentContext);
  if (!ctx) {
    throw new Error("useEditDocument must be used within EditDocumentProvider");
  }
  return ctx;
};

export const editDocumentModalStateFromTarget = (
  target: EditDocumentTarget | null,
): {
  file: FileItemWithDocumentId | null;
  initialDocumentType: string;
  initialAssignTo: string | undefined;
} => {
  if (!target) {
    return { file: null, initialDocumentType: "", initialAssignTo: undefined };
  }

  if (target.kind === "classified") {
    return {
      file: target.document.matchedFile,
      initialDocumentType: target.document.type,
      initialAssignTo: getInitialAssignToApplicantId(target.assignment),
    };
  }

  return {
    file: target.file,
    initialDocumentType: "",
    initialAssignTo: undefined,
  };
};
