import { Button, cn, toast } from "@huspy/shared-ui";
import { Package, Plus, FileStack } from "@huspy/shared-icons";

import { ApiError } from "@/api/client";
import { useMergeBankApplication, usePrepareBankApplicationZipDownload } from "@/api";
import { openUrlInNewTab } from "@/utils";
const pill = "h-9.5 gap-1.5 rounded-full px-4 text-[13px] font-semibold";
const secondaryPill = cn(
  pill,
  "border border-solid border-border bg-card text-foreground hover:bg-grey-60",
);

type Props = {
  bankApplicationId: string;
  onAddDocuments: () => void;
};

export function HeaderActions({ bankApplicationId, onAddDocuments }: Props) {
  const mergeBankApplication = useMergeBankApplication();
  const prepareBankApplicationZipDownload = usePrepareBankApplicationZipDownload();

  const handleMergeAll = async () => {
    try {
      // The notification text is an abstraction — the mutation only triggers the process.
      toast.info("Merging documents...");
      await mergeBankApplication.mutateAsync(bankApplicationId);
    } catch (error) {
      if (error instanceof ApiError && error.status === 422) {
        toast.error("Documents still processing. Try again in a moment.");
        return;
      }

      toast.error("Failed to merge documents.");
    }
  };

  const handleGeneratePackage = async () => {
    try {
      toast.info("Preparing ZIP package...");
      const { downloadUrl } =
        await prepareBankApplicationZipDownload.mutateAsync(bankApplicationId);
      openUrlInNewTab(downloadUrl);
      toast.success("ZIP package generated successfully.");
    } catch {
      toast.error("Failed to generate ZIP package.");
    }
  };

  const isAddDocumentsDisabled =
    prepareBankApplicationZipDownload.isPending || mergeBankApplication.isPending;

  return (
    <div className="flex shrink-0 items-center gap-2">
      <Button
        variant="ghost"
        className={secondaryPill}
        disabled={isAddDocumentsDisabled}
        onClick={onAddDocuments}
      >
        <Plus className="size-4" />
        Add documents
      </Button>

      <Button
        variant="ghost"
        className={secondaryPill}
        disabled={mergeBankApplication.isPending}
        onClick={handleMergeAll}
      >
        <FileStack className="size-4" />
        Merge all
      </Button>

      <Button
        className={pill}
        disabled={prepareBankApplicationZipDownload.isPending}
        onClick={handleGeneratePackage}
      >
        <Package className="size-4" />
        Generate package
      </Button>
    </div>
  );
}
