import type { FC, ReactNode } from "react";

import { cn } from "@huspy/shared-ui";

type Props = {
  label: string;
  value: ReactNode;
  hint?: string;
  tag?: string;
  status?: "pass" | "fail";
  passLabel?: string;
  failLabel?: string;
  emphasized?: boolean;
};

export const AffordabilitySummaryRow: FC<Props> = ({
  label,
  value,
  hint,
  tag,
  status,
  passLabel,
  failLabel = "Above limit",
  emphasized = false,
}) => (
  <div className="flex w-full flex-1 items-center justify-between gap-3 px-2 py-2">
    <div className="min-w-0 flex-1">
      <span
        className={cn(
          "text-foreground",
          emphasized ? "text-sm font-semibold" : "text-sm font-medium",
        )}
      >
        {label}
      </span>
      {hint && <p className="mt-0.5 text-[10px] leading-snug text-muted-foreground">{hint}</p>}
    </div>

    <div className="flex shrink-0 items-center gap-1.5">
      {tag && (
        <span className="rounded-full bg-muted px-1.5 py-0.5 text-xs font-semibold text-muted-foreground">
          {tag}
        </span>
      )}
      {status === "fail" && (
        <span
          className="rounded-full bg-warning/14 px-1.5 py-0.5 text-xs font-semibold text-warning"
          aria-hidden
        >
          {failLabel}
        </span>
      )}
      {status === "pass" && passLabel && (
        <span
          className="rounded-full bg-success/14 px-1.5 py-0.5 text-xs font-semibold text-success"
          aria-hidden
        >
          {passLabel}
        </span>
      )}
      <span
        className={cn(
          "tabular-nums text-foreground",
          emphasized ? "text-sm font-semibold" : "text-sm font-medium",
        )}
      >
        {value}
      </span>
    </div>
  </div>
);
