import { useState, type FC } from "react";

import { Input } from "@huspy/shared-ui";

import {
  formatStressRatePercentDraft,
  isStressRatePercentDraft,
  parseStressRatePercent,
} from "../../utils";

type Props = {
  value: number | null;
  disabled: boolean;
  onCommit: (stressRatePercent: number | null) => void | Promise<void>;
};

const isSameStressRatePercent = (left: number | null, right: number | null): boolean => {
  if (left === null || right === null) return left === right;

  return Math.abs(left - right) < 1e-9;
};

export const StressRatePercentInput: FC<Props> = ({ value, disabled, onCommit }) => {
  const [draft, setDraft] = useState(() => formatStressRatePercentDraft(value));
  const [invalid, setInvalid] = useState(false);
  const [prevValue, setPrevValue] = useState(value);

  if (!isSameStressRatePercent(value, prevValue)) {
    setPrevValue(value);
    setDraft(formatStressRatePercentDraft(value));
    setInvalid(false);
  }

  const revertToSaved = () => {
    setDraft(formatStressRatePercentDraft(value));
    setInvalid(false);
  };

  const handleBlur = async () => {
    const trimmed = draft.trim();

    if (trimmed === "") {
      if (value === 0) {
        revertToSaved();
        return;
      }

      setInvalid(false);
      setDraft("0");

      try {
        await onCommit(0);
      } catch {
        revertToSaved();
      }

      return;
    }

    const parsed = parseStressRatePercent(trimmed);
    if (parsed === null) {
      revertToSaved();
      setInvalid(true);
      return;
    }

    if (isSameStressRatePercent(parsed, value)) {
      revertToSaved();
      return;
    }

    setInvalid(false);
    setDraft(formatStressRatePercentDraft(parsed));

    try {
      await onCommit(parsed);
    } catch {
      revertToSaved();
    }
  };

  return (
    <div className="flex items-center justify-end gap-1">
      <Input
        type="text"
        inputMode="decimal"
        value={draft}
        disabled={disabled}
        aria-label="Stress rate"
        aria-invalid={invalid || undefined}
        onChange={(event) => {
          const next = event.target.value;
          if (!isStressRatePercentDraft(next)) return;

          if (next !== "" && next !== ".") {
            const asNumber = Number.parseFloat(next);
            if (Number.isFinite(asNumber) && asNumber > 100) return;
          }

          setDraft(next);
          setInvalid(false);
        }}
        onBlur={() => {
          void handleBlur();
        }}
        onKeyDown={(event) => {
          if (["-", "+", "e", "E"].includes(event.key)) {
            event.preventDefault();
            return;
          }

          if (event.key === "Enter") {
            event.currentTarget.blur();
          }
        }}
        className="h-8 w-12 px-1.5 text-center text-sm font-medium tabular-nums selection:bg-revert selection:text-revert"
      />
      <span className="text-xs text-muted-foreground">%</span>
    </div>
  );
};
