import { Button } from "@huspy/shared-ui";

type Props = {
  onClear: () => void;
  onApply: () => void;
  canApply?: boolean;
};

export function FilterPopoverActions({ onClear, onApply, canApply = false }: Props) {
  return (
    <div className="flex gap-2 border-t pt-2">
      <Button size="sm" variant="secondary" onClick={onClear} className="flex-1" type="button">
        Clear
      </Button>
      <Button size="sm" onClick={onApply} disabled={!canApply} className="flex-1" type="button">
        Apply
      </Button>
    </div>
  );
}
