import type { DocumentTypeScope } from "@/api";
import { DocumentTypeCode } from "@/types";

const DOCUMENT_TYPE_SCOPE_ORDER: Record<DocumentTypeScope, number> = {
  BANK_SPECIFIC: 0,
  GENERIC: 1,
};

/** Bank-specific types first, then generic; alphabetical by label within each scope. */
export const sortDocumentTypeCodesByScope = (
  documentTypeCodes: DocumentTypeCode[],
): DocumentTypeCode[] =>
  [...documentTypeCodes].sort((a, b) => {
    const scopeOrder = DOCUMENT_TYPE_SCOPE_ORDER[a.scope] - DOCUMENT_TYPE_SCOPE_ORDER[b.scope];
    return scopeOrder !== 0 ? scopeOrder : a.label.localeCompare(b.label);
  });
