export const isPdfContentType = (contentType: string | undefined): boolean =>
  !!contentType && contentType.toLowerCase().includes("pdf");

export const isImageContentType = (contentType: string | undefined): boolean =>
  !!contentType && contentType.toLowerCase().startsWith("image/");

export const isInlinePreviewSupported = (contentType: string | undefined): boolean =>
  isPdfContentType(contentType) || isImageContentType(contentType);

export type PendingRotation = 0 | 90 | 180 | 270;

export type PdfDisplayRotation = 0 | 90 | 180 | 270;

export const toPdfDisplayRotation = (degrees: number): PdfDisplayRotation =>
  (((degrees % 360) + 360) % 360) as PdfDisplayRotation;

/** Returns undefined when pendingRotation is 0 so react-pdf uses the PDF's intrinsic /Rotate. */
export const combinePdfRotation = (
  intrinsicRotate: number,
  pendingRotation: PendingRotation,
): PdfDisplayRotation | undefined => {
  if (pendingRotation === 0) return undefined;
  return toPdfDisplayRotation(intrinsicRotate + pendingRotation);
};

export const rotatePendingRight = (rotation: PendingRotation): PendingRotation =>
  ((rotation + 90) % 360) as PendingRotation;

export const rotatePendingLeft = (rotation: PendingRotation): PendingRotation =>
  ((rotation + 270) % 360) as PendingRotation;

export const pendingRotationToApiAngle = (
  rotation: PendingRotation,
): "ROTATE_90" | "ROTATE_180" | "ROTATE_270" | null => {
  switch (rotation) {
    case 90:
      return "ROTATE_90";
    case 180:
      return "ROTATE_180";
    case 270:
      return "ROTATE_270";
    default:
      return null;
  }
};
