import type { FC } from "react";

import { cn } from "@huspy/shared-ui";

import {
  usePatchBankApplicationRequestedAmount,
  useResetBankApplicationRequestedAmount,
} from "@/api";
import type { RequestedLoan } from "@/types";

import { OverrideClearButton } from "../CalculationTable/OverrideClearButton";
import { useEligibilityChecksRoute } from "../../hooks/useEligibilityChecksRoute";
import { RequestedAmountInput } from "./RequestedAmountInput";

type Props = {
  label: string;
  requestedLoan: RequestedLoan;
  currency: string;
  status?: "pass" | "fail";
  passLabel?: string;
  failLabel?: string;
  emphasized?: boolean;
};

export const RequestedAmountRow: FC<Props> = ({
  label,
  requestedLoan,
  currency,
  status,
  passLabel,
  failLabel = "Above limit",
  emphasized = false,
}) => {
  const { bankApplication } = useEligibilityChecksRoute();
  const { mutateAsync: patchRequestedAmount, isPending: isPatching } =
    usePatchBankApplicationRequestedAmount();
  const { mutateAsync: resetRequestedAmount, isPending: isResetting } =
    useResetBankApplicationRequestedAmount();

  if (!bankApplication) return null;

  const isOverridden = requestedLoan.overriddenRequestedLoanAmount != null;
  const displayAmount =
    requestedLoan.overriddenRequestedLoanAmount ??
    requestedLoan.requestedLoanAmount ??
    bankApplication.amount ??
    0;
  const isPending = isPatching || isResetting;

  return (
    <div className="flex items-center justify-between flex-1 gap-3 px-2 py-2">
      <span
        className={cn(
          "min-w-0 flex-1 text-sm text-foreground",
          emphasized ? "font-semibold" : "font-medium",
        )}
      >
        {label}
      </span>

      <div className="flex shrink-0 items-center gap-1.5">
        {status === "fail" && (
          <span
            className="rounded-full bg-warning/14 px-1.5 py-0.5 text-xs font-semibold text-warning"
            aria-hidden
          >
            {failLabel}
          </span>
        )}
        {status === "pass" && passLabel && (
          <span
            className="rounded-full bg-success/14 px-1.5 py-0.5 text-xs font-semibold text-success"
            aria-hidden
          >
            {passLabel}
          </span>
        )}
        <RequestedAmountInput
          value={displayAmount}
          currency={currency}
          disabled={isPending}
          onCommit={async (value) => {
            await patchRequestedAmount({
              bankApplicationId: bankApplication.id,
              payload: { requestedLoanAmount: value },
            });
          }}
        />
        {isOverridden && (
          <OverrideClearButton
            disabled={isPending}
            ariaLabel="Reset to application amount"
            tooltip="Manually overridden. Click to reset to the application amount."
            onClear={async () => {
              await resetRequestedAmount(bankApplication.id);
            }}
          />
        )}
      </div>
    </div>
  );
};
