import type {
  Applicant,
  ApplicantDocumentGroup,
  ApplicantDocumentRow,
  BankApplication,
  FileItemWithDocumentId,
} from "@/types";

export type DocumentRename = {
  documentId: string;
  fileName: string;
  previousFileName: string;
  applicantId: string;
};

export const getReorderGroupKey = (
  groupType: string,
  entry: Pick<ApplicantDocumentRow, "type"> & { applicant?: Applicant },
) => `${groupType}::${entry.type}::${entry.applicant?.id ?? ""}`;

export const applyChecklistRenames = (
  data: BankApplication,
  renames: DocumentRename[],
): BankApplication => {
  if (renames.length === 0) return data;

  const renameById = new Map(renames.map((rename) => [rename.documentId, rename.fileName]));

  const updateFile = (file: FileItemWithDocumentId | null): FileItemWithDocumentId | null => {
    if (!file) return file;
    const fileName = renameById.get(file.id);
    return fileName ? { ...file, fileName } : file;
  };

  const updateDocumentRow = (row: ApplicantDocumentRow): ApplicantDocumentRow => ({
    ...row,
    matchedFile: updateFile(row.matchedFile),
  });

  const updateGroup = (group: ApplicantDocumentGroup): ApplicantDocumentGroup => ({
    ...group,
    matchedFile: updateFile(group.matchedFile),
    documents: group.documents.map(updateDocumentRow),
  });

  return {
    ...data,
    checklist: {
      ...data.checklist,
      applicantDocuments: data.checklist.applicantDocuments.map(updateGroup),
      unclassifiedFiles: data.checklist.unclassifiedFiles.map((file) => updateFile(file) ?? file),
    },
  };
};

/** Reorders sibling checklist rows within each affected group to match `orderedFileIds`. */
export const reorderChecklistGroupChildren = (
  data: BankApplication,
  groupKey: string,
  orderedFileIds: string[],
): BankApplication => ({
  ...data,
  checklist: {
    ...data.checklist,
    applicantDocuments: data.checklist.applicantDocuments.map((group) => {
      const hasGroupEntry = group.documents.some(
        (entry) => getReorderGroupKey(group.type, entry) === groupKey,
      );
      if (!hasGroupEntry) return group;

      const groupEntryById = new Map(
        group.documents
          .filter(
            (entry) => getReorderGroupKey(group.type, entry) === groupKey && entry.matchedFile,
          )
          .map((entry) => [entry.matchedFile!.id, entry]),
      );

      const reorderedGroupEntries = orderedFileIds
        .map((id) => groupEntryById.get(id))
        .filter((entry): entry is ApplicantDocumentRow => entry !== undefined);

      let groupReplaced = false;
      const documents = group.documents.flatMap((entry) => {
        if (getReorderGroupKey(group.type, entry) !== groupKey) return [entry];
        if (groupReplaced) return [];
        groupReplaced = true;
        return reorderedGroupEntries;
      });

      return { ...group, documents };
    }),
  },
});

export const applyOptimisticChecklistReorder = (
  data: BankApplication,
  groupKey: string,
  orderedFileIds: string[],
  renames: DocumentRename[],
): BankApplication =>
  reorderChecklistGroupChildren(applyChecklistRenames(data, renames), groupKey, orderedFileIds);
