import type { DocumentExtractedFields } from "@/types";

import { getExtractedFieldMetaByKey } from "./buildExtractedFieldsDraft";
import { validateExtractedFieldValue } from "./validateExtractedFieldValue";

/** Validation messages by field key for the given draft values. Unknown keys are skipped. */
export const collectExtractedFieldErrors = (
  data: DocumentExtractedFields,
  values: Record<string, string>,
): Record<string, string> => {
  const errors: Record<string, string> = {};

  for (const [key, value] of Object.entries(values)) {
    const meta = getExtractedFieldMetaByKey(data, key);
    if (!meta) continue;

    const validationError = validateExtractedFieldValue(value, meta.dataType, meta.options);
    if (validationError) errors[key] = validationError;
  }

  return errors;
};
