import type { FC } from "react";

import type { ExtractedFieldGroup } from "@/types";

import { GroupTable } from "./GroupTable";

type Props = {
  group: ExtractedFieldGroup;
};

export const FlatGroupSection: FC<Props> = ({ group }) => (
  <section className="space-y-3">
    <h3 className="text-sm font-medium text-foreground">{group.label}</h3>
    {group.items.length === 0 && (
      <p className="text-sm text-muted-foreground">No rows extracted yet.</p>
    )}
    {group.items.length > 0 && <GroupTable group={group} />}
  </section>
);
