import {
  APPLICANT_ROLE_TO_LABEL,
  EMPLOYMENT_TYPE_TO_LABEL,
  RESIDENCY_TYPE_TO_LABEL,
} from "@/constants";
import { Applicant } from "@/types";

type Props = {
  applicant: Applicant;
};

export const ApplicantInfoBadges = ({ applicant }: Props) => {
  const badges = [
    APPLICANT_ROLE_TO_LABEL[applicant.role],
    applicant.employmentType && EMPLOYMENT_TYPE_TO_LABEL[applicant.employmentType],
    applicant.residencyType && RESIDENCY_TYPE_TO_LABEL[applicant.residencyType],
  ].filter(Boolean);

  return (
    <div className="mb-4 flex flex-wrap gap-1.5">
      {badges.map((badge) => (
        <span
          key={badge}
          className="rounded-full bg-muted px-2.5 py-0.5 text-[11px] text-foreground-secondary"
        >
          {badge}
        </span>
      ))}
    </div>
  );
};
