import type { TransactionType } from "@/types";
import { PROPERTY_STATUS_OPTIONS } from "@/constants";

import { getAllowedPropertyStatuses } from "./getAllowedPropertyStatuses";

export const getPropertyStatusOptionsForTransactionType = (
  transactionType: TransactionType | null,
) => {
  if (!transactionType) return PROPERTY_STATUS_OPTIONS;
  const allowedPropertyStatuses = getAllowedPropertyStatuses(transactionType);
  return PROPERTY_STATUS_OPTIONS.filter((option) => allowedPropertyStatuses.includes(option.value));
};
