const ROTATE_TASK_POLL_INTERVAL_MS = 1000;
const ROTATE_TASK_POLL_MAX_ATTEMPTS = 120;

const isRotateTaskFailed = (status: string) => status.toUpperCase() === "FAILED";

const isRotateTaskSucceeded = (status: string) => status.toUpperCase() === "COMPLETED";

export const rotateDocument = async (
  documentId: string,
  angle: DocumentRotateAngle,
  options?: Options,
): Promise<RotateDocumentResponse> => {
  const { data } = await api.post<RotateDocumentResponse>(
    `documents/${documentId}/rotate`,
    { angle },
    getAxiosConfig(options),
  );
  return data;
};

export const getDocumentRotateTask = async (
  taskId: string,
  options?: Options,
): Promise<DocumentRotateTaskResponse> => {
  const { data } = await api.get<DocumentRotateTaskResponse>(
    `document-rotate-tasks/${taskId}`,
    getAxiosConfig(options),
  );
  return data;
};

export const waitForDocumentRotateTaskCompleted = async (
  taskId: string,
  options?: Options,
): Promise<DocumentRotateTaskResponse> => {
  const signal = options?.signal;

  for (let i = 0; i < ROTATE_TASK_POLL_MAX_ATTEMPTS; i++) {
    if (signal?.aborted) throw new ApiError("Aborted");

    const task = await getDocumentRotateTask(taskId, options);

    if (isRotateTaskFailed(task.status)) {
      throw new ApiError(task.failureReason ?? `Document rotate task failed (${task.status})`);
    }

    if (isRotateTaskSucceeded(task.status)) {
      if (!task.rotatedDocServiceDocumentId) {
        throw new ApiError("Document rotate task completed without a rotated document id");
      }
      return task;
    }

    await sleep(ROTATE_TASK_POLL_INTERVAL_MS, signal);
  }

  throw new ApiError("Timed out waiting for document rotate to finish");
};

export const rotateDocumentAndWait = async (
  documentId: string,
  angle: DocumentRotateAngle,
  options?: Options,
): Promise<DocumentRotateTaskResponse> => {
  const { rotateTaskId } = await rotateDocument(documentId, angle, options);
  return waitForDocumentRotateTaskCompleted(rotateTaskId, options);
};

