import { ChevronLeft, ChevronRight } from "@huspy/shared-icons";
import { cn } from "@huspy/shared-ui";

type Props = {
  page: number;
  pageCount: number;
  totalCount: number;
  pageSize: number;
  disabled?: boolean;
  onPageChange: (page: number) => void;
};

const pageButton =
  "flex size-8 cursor-pointer items-center justify-center rounded-full border border-solid border-border bg-card text-foreground hover:bg-grey-60 disabled:cursor-not-allowed disabled:opacity-40 disabled:hover:bg-card";

export function TableFooter({
  page,
  pageCount,
  totalCount,
  pageSize,
  disabled = false,
  onPageChange,
}: Props) {
  const startItem = totalCount === 0 ? 0 : page * pageSize + 1;
  const endItem = Math.min((page + 1) * pageSize, totalCount);
  const rangeLabel =
    totalCount === 0 ? "No results" : `${startItem}–${endItem} of ${totalCount} applications`;

  return (
    <div className="flex items-center justify-between rounded-b-[15px] bg-muted px-5 py-3">
      <span className="text-xs tabular-nums text-foreground-secondary">{rangeLabel}</span>

      <div className="flex items-center gap-2">
        <button
          type="button"
          className={cn(pageButton)}
          disabled={disabled || page === 0 || pageCount === 0}
          onClick={() => onPageChange(page - 1)}
          aria-label="Go to previous page"
        >
          <ChevronLeft className="size-4" />
        </button>

        <span className="text-xs tabular-nums text-foreground-secondary">
          {`${Math.min(page + 1, Math.max(pageCount, 1))} / ${Math.max(pageCount, 1)}`}
        </span>

        <button
          type="button"
          className={cn(pageButton)}
          disabled={disabled || page + 1 >= pageCount || pageCount === 0}
          onClick={() => onPageChange(page + 1)}
          aria-label="Go to next page"
        >
          <ChevronRight className="size-4" />
        </button>
      </div>
    </div>
  );
}
