import { type FC } from "react";

import { cn } from "@huspy/shared-ui";

import { bankApplicationCardTitleClassName } from "@/routes/BankApplication/constants";

import { BankApplicationCard } from "../../../BankApplicationCard";
import { buildAffordabilitySummaryRows, type AffordabilitySummaryCardRow } from "./utils";
import { useEligibilityChecksRoute } from "../../hooks/useEligibilityChecksRoute";
import { getAffordabilityVerdict, hasAffordabilitySummary } from "../../utils";
import { AffordabilitySummaryBanner } from "./AffordabilitySummaryBanner";
import { AffordabilitySummaryRow } from "./AffordabilitySummaryRow";
import { EffectiveTenorRow } from "./EffectiveTenorRow";
import { RequestedAmountRow } from "./RequestedAmountRow";
import { StressRateRow } from "./StressRateRow";

const detailRowClassName =
  "flex items-center border-b border-border/40 last:border-b-0 [&:nth-last-child(2):nth-child(odd)]:border-b-0";
const outcomeRowClassName = "col-span-2 mt-2 rounded-lg bg-muted/60";

const renderSummaryRow = (
  row: AffordabilitySummaryCardRow,
  currency: string,
  emphasized = false,
) => {
  if (row.editableRequestedAmount != null) {
    return (
      <RequestedAmountRow
        label={row.label}
        requestedLoan={row.editableRequestedAmount}
        currency={currency}
        status={row.status}
        passLabel={row.passLabel}
        failLabel={row.failLabel}
        emphasized={emphasized}
      />
    );
  }

  if (row.editableTenor != null) {
    return (
      <EffectiveTenorRow
        label={row.label}
        tenor={row.editableTenor}
        effectiveTenorApplicant={row.effectiveTenorApplicant}
        sourceTag={row.tag}
      />
    );
  }

  if (row.editableStressRate != null) {
    return <StressRateRow label={row.label} stressRate={row.editableStressRate} />;
  }

  return (
    <AffordabilitySummaryRow
      label={row.label}
      value={row.value}
      hint={row.hint}
      tag={row.tag}
      status={row.status}
      passLabel={row.passLabel}
      failLabel={row.failLabel}
      emphasized={emphasized}
    />
  );
};

export const AffordabilitySummaryCard: FC = () => {
  const { currency, requestedAmount, eligibilityChecks } = useEligibilityChecksRoute();

  if (!currency || !eligibilityChecks) return null;

  const { summary } = eligibilityChecks;
  const showAffordabilityDecisions = hasAffordabilitySummary(summary);
  const rows = buildAffordabilitySummaryRows({
    summary,
    currency,
    requestedAmount,
    showAffordabilityDecisions,
  });
  const verdict = showAffordabilityDecisions
    ? getAffordabilityVerdict(summary.affordability, requestedAmount)
    : null;

  return (
    <BankApplicationCard padding="compact">
      <div className="mb-4">
        <span className={bankApplicationCardTitleClassName}>Affordability Summary</span>
      </div>

      {verdict && <AffordabilitySummaryBanner verdict={verdict} />}

      <div
        className={cn("rounded-xl border border-border bg-card p-3 shadow-none", verdict && "mt-3")}
      >
        <div className="grid grid-cols-2 gap-x-8">
          {rows.map((row) => (
            <div
              key={row.key}
              className={cn(
                detailRowClassName,
                row.key === "max-permissible-loan" && outcomeRowClassName,
              )}
            >
              {renderSummaryRow(row, currency, row.key === "max-permissible-loan")}
            </div>
          ))}
        </div>
      </div>
    </BankApplicationCard>
  );
};
