import type { ComponentProps, FC, ReactNode } from "react";

import { Card, CardContent, cn } from "@huspy/shared-ui";

import { bankApplicationCardClassName } from "../../constants";

export type BankApplicationCardPadding = "compact" | "default" | "empty" | "none";

const contentPaddingClassName: Record<BankApplicationCardPadding, string> = {
  compact: "px-5 py-3.5",
  default: "px-5 py-4.5",
  empty: "flex flex-col items-center gap-2 px-5 py-12 text-center",
  none: "gap-0 p-0",
};

type Props = {
  children: ReactNode;
  padding?: BankApplicationCardPadding;
  className?: string;
  cardClassName?: string;
} & Omit<ComponentProps<typeof Card>, "children" | "className">;

export const BankApplicationCard: FC<Props> = ({
  children,
  padding = "default",
  className,
  cardClassName,
  ...cardProps
}) => (
  <Card className={cn(bankApplicationCardClassName, cardClassName)} {...cardProps}>
    <CardContent className={cn(contentPaddingClassName[padding], className)}>
      {children}
    </CardContent>
  </Card>
);
