import { formatFxConversionTooltipText } from "./constants";

const AMOUNT_FORMAT_OPTIONS = {
  minimumFractionDigits: 2,
  maximumFractionDigits: 2,
} as const;

export const parseDecimalAmount = (amount: string): number => {
  const value = Number.parseFloat(amount);
  return Number.isFinite(value) ? value : 0;
};

/** Formats a decimal amount without a currency prefix, e.g. for compact evidence chips. */
export const formatDecimalAmount = (amount: string): string =>
  formatDecimal(parseDecimalAmount(amount), "en-AE", AMOUNT_FORMAT_OPTIONS);

export const formatDecimalMoney = (amount: string, currency: string): string =>
  formatMoneyAmount(parseDecimalAmount(amount), currency);

export const formatEligibleLineAmount = (
  eligibleAmount: Money,
  fallbackCurrency: string,
): string => {
  if (!Number.isFinite(eligibleAmount.value)) return "-";

  const currency = eligibleAmount.currency ?? fallbackCurrency;
  return formatMoneyAmount(eligibleAmount.value, currency);
};

/** Parses a monthly amount in the inclusive range 0+. */
export const parseMonthlyAmount = (value: string): number | null => {
  const trimmed = value.trim();
  if (trimmed === "") return null;

  const parsed = Number.parseFloat(trimmed);
  if (!Number.isFinite(parsed) || parsed < 0) return null;

  return parsed;
};

const MONTHLY_AMOUNT_DRAFT_PATTERN = /^\d*\.?\d*$/;

/** Whether a draft string is empty or a valid in-progress monthly amount. */
export const isMonthlyAmountDraft = (value: string): boolean =>
  value === "" || MONTHLY_AMOUNT_DRAFT_PATTERN.test(value);

/** Formats a saved monthly amount for display in the editable input. */
export const formatMonthlyAmountDraft = (amount: number): string =>
  Number.isFinite(amount) ? amount.toFixed(2) : "0.00";

/** Parses a whole-number percentage in the inclusive range 0–100. */
export const parseAllocationPercent = (value: string): number | null => {
  const trimmed = value.trim();
  if (trimmed === "" || !/^\d+$/.test(trimmed)) return null;

  const parsed = Number.parseInt(trimmed, 10);
  if (!Number.isFinite(parsed) || parsed < 0 || parsed > 100) return null;

  return parsed;
};

/** UAE regulatory maximum mortgage tenor (25 years). */
export const MAX_REGULATORY_TENOR_MONTHS = 300;

/** Parses a whole-number tenor in months within the inclusive range 1–300. */
export const parseTenorMonths = (value: string): number | null => {
  const trimmed = value.trim();
  if (trimmed === "" || !/^\d+$/.test(trimmed)) return null;

  const parsed = Number.parseInt(trimmed, 10);
  if (!Number.isFinite(parsed) || parsed < 1 || parsed > MAX_REGULATORY_TENOR_MONTHS) return null;

  return parsed;
};

export const formatDbr = (dbr: number): string => `${dbr.toFixed(1)}%`;

export const formatDbrWithCap = (dbr: number, maxDbrPercent: number): string =>
  `${formatDbr(dbr)} / ${maxDbrPercent}% cap`;

const STRESS_RATE_PERCENT_DRAFT_PATTERN = /^\d*\.?\d{0,5}$/;

/** Whether a draft string is empty or a valid in-progress stress rate percent. */
export const isStressRatePercentDraft = (value: string): boolean =>
  value === "" || STRESS_RATE_PERCENT_DRAFT_PATTERN.test(value);

/** Formats a saved stress rate percent for display in the editable input. */
export const formatStressRatePercentDraft = (stressRatePercent: number | null): string => {
  if (stressRatePercent === null) return "0";

  return stressRatePercent.toFixed(5).replace(/\.?0+$/, "");
};

/** Parses a stress rate percent in the inclusive range [0, 100]. Returns null when invalid. */
export const parseStressRatePercent = (value: string): number | null => {
  const trimmed = value.trim();
  if (trimmed === "" || trimmed === ".") return null;

  if (!/^\d+(\.\d+)?$/.test(trimmed)) return null;

  const parsed = Number.parseFloat(trimmed);
  if (!Number.isFinite(parsed) || parsed < 0 || parsed > 100) return null;

  const [, fraction = ""] = trimmed.split(".");
  if (fraction.length > 5) return null;

  return parsed;
};

export const formatStressRatePercent = (stressRatePercent: number | null): string => {
  if (stressRatePercent === null) return "-";

  return `${stressRatePercent.toFixed(2).replace(/\.?0+$/, "")}%`;
};

export const formatTenorMonths = (months: number): string => {
  const years = Math.floor(months / 12);
  const remainingMonths = months % 12;

  if (years === 0) {
    return `${months} months`;
  }

  const yearsLabel =
    remainingMonths === 0 ? `${years} years` : `${years} years ${remainingMonths} months`;

  return `${months} months (${yearsLabel})`;
};

const EFFECTIVE_TENOR_BOUND_BY_LABELS: Record<EffectiveTenorBoundBy, string> = {
  REQUESTED: "requested tenor",
  REGULATORY_MAX: "25-year regulatory maximum",
  HOUSEHOLD_MAX: "household age limit",
  MANUAL: "manual override",
};

const EFFECTIVE_TENOR_SOURCE_TAG_LABELS: Record<EffectiveTenorBoundBy, string> = {
  REGULATORY_MAX: "Max",
  REQUESTED: "Requested",
  HOUSEHOLD_MAX: "Age limit",
  MANUAL: "Manual",
};

/** A manual override wins; otherwise the tightest of the requested, regulatory, and household tenors. */
export const getEffectiveTenorMonths = (tenor: Tenor): number =>
  tenor.overriddenTenorMonths ??
  Math.min(tenor.requestedTenorMonths, tenor.regulatorTenorMonths, tenor.householdTenorMonths);

const MONTHS_PER_YEAR = 12;

const formatAge = (totalMonths: number): string =>
  `${Math.floor(totalMonths / MONTHS_PER_YEAR)}y ${totalMonths % MONTHS_PER_YEAR}m`;

/** e.g. "Co-borrower | Current: 59y 3m | Maturity: 79y 3m". Maturity follows the effective tenor live. */
export const formatEffectiveTenorApplicantSubtext = (
  { role, currentAge }: EffectiveTenorApplicant,
  tenor: Tenor,
): string => {
  const currentAgeMonths = currentAge.years * MONTHS_PER_YEAR + currentAge.months;

  return [
    APPLICANT_ROLE_TO_LABEL[role],
    `Current: ${formatAge(currentAgeMonths)}`,
    `Maturity: ${formatAge(currentAgeMonths + getEffectiveTenorMonths(tenor))}`,
  ].join(" | ");
};

export const formatEffectiveTenorBoundBy = (boundBy: EffectiveTenorBoundBy): string =>
  EFFECTIVE_TENOR_BOUND_BY_LABELS[boundBy];

export const formatEffectiveTenorSourceTag = (boundBy: EffectiveTenorBoundBy): string =>
  EFFECTIVE_TENOR_SOURCE_TAG_LABELS[boundBy];

export const getEffectiveTenorSourceTag = (
  boundBy: EffectiveTenorBoundBy,
  tenor: Tenor,
): string => {
  if (tenor.overriddenTenorMonths != null && boundBy !== "MANUAL") {
    return EFFECTIVE_TENOR_SOURCE_TAG_LABELS.MANUAL;
  }

  return formatEffectiveTenorSourceTag(boundBy);
};

export const getEffectiveTenorHint = (boundBy: EffectiveTenorBoundBy): string | undefined => {
  if (boundBy === "REQUESTED" || boundBy === "MANUAL") {
    return undefined;
  }

  return `Limited by ${formatEffectiveTenorBoundBy(boundBy)}`;
};

export type AffordabilityVerdictVariant = "success" | "error";

export type AffordabilityVerdict = {
  variant: AffordabilityVerdictVariant;
  title: string;
  description?: string;
};

export const hasAffordabilitySummary = (
  summary: EligibilitySummary,
): summary is EligibilitySummary & { affordability: AffordabilityCalculationSummary } =>
  summary.affordability != null;

export const hasUndetectedCurrency = (eligibilityChecks: EligibilityChecks): boolean =>
  eligibilityChecks.applicants.some(
    (applicant) =>
      applicant.earnings.some((earning) => earning.amount.currency == null) ||
      applicant.liabilities.some((liability) => liability.amount.currency == null),
  );

export const getAffordabilityVerdict = (
  affordability: Pick<
    AffordabilityCalculationSummary,
    "dbrWithinCap" | "newDbrWithinCap" | "affordable"
  >,
  requestedAmount: number | null,
): AffordabilityVerdict | null => {
  const canAssessLoan = requestedAmount !== null;
  const dbrOverCap = !(affordability.newDbrWithinCap ?? affordability.dbrWithinCap);
  const loanOverMax = canAssessLoan && !affordability.affordable;

  if (!dbrOverCap && !canAssessLoan) {
    return null;
  }

  if (!dbrOverCap && affordability.affordable) {
    return {
      variant: "success",
      title: "Affordable",
      description: "New DBR and requested amount are within the limit.",
    };
  }

  if (dbrOverCap && loanOverMax) {
    return {
      variant: "error",
      title: "Not affordable",
      description: "New DBR and requested amount are above the limit.",
    };
  }

  if (dbrOverCap) {
    return {
      variant: "error",
      title: "New DBR is above the limit",
    };
  }

  if (loanOverMax) {
    return {
      variant: "error",
      title: "Requested amount is above the limit",
    };
  }

  return null;
};

const ISO_DATE_PATTERN = /^(\d{4})-(\d{2})-\d{2}$/;

const parseDocumentFieldIsoDate = (isoDate: string): { year: number; month: number } | null => {
  const match = ISO_DATE_PATTERN.exec(isoDate);
  if (!match) return null;

  return { year: Number(match[1]), month: Number(match[2]) };
};

const toMonthIndex = (isoDate: string): number | null => {
  const parsed = parseDocumentFieldIsoDate(isoDate);
  if (!parsed) return null;

  return parsed.year * 12 + (parsed.month - 1);
};

const formatMonthFromIndex = (monthIndex: number): string => {
  const year = Math.floor(monthIndex / 12);
  const month = (monthIndex % 12) + 1;
  const date = new Date(year, month - 1, 1);

  return date.toLocaleDateString("en-GB", { month: "short" });
};

/** Formats an ISO date as a month and year label, e.g. "Jan 2026". */
export const formatDocumentFieldMonthYear = (isoDate: string): string => {
  const parsed = parseDocumentFieldIsoDate(isoDate);
  if (!parsed) return isoDate;

  return `${formatMonthFromIndex(parsed.year * 12 + (parsed.month - 1))} ${parsed.year}`;
};

export const formatDocumentFieldGapMonthRange = (
  startMonthIndex: number,
  endMonthIndex: number,
): string => {
  const start = formatMonthFromIndex(startMonthIndex);
  const end = formatMonthFromIndex(endMonthIndex);

  return startMonthIndex === endMonthIndex ? start : `${start}–${end}`;
};

const getMissingMonthIndices = (previousDate: string, nextDate: string): number[] => {
  const previousIndex = toMonthIndex(previousDate);
  const nextIndex = toMonthIndex(nextDate);
  if (previousIndex === null || nextIndex === null || nextIndex <= previousIndex + 1) {
    return [];
  }

  const missing: number[] = [];
  for (let index = previousIndex + 1; index < nextIndex; index += 1) {
    missing.push(index);
  }

  return missing;
};

const groupMissingMonthsByYear = (
  monthIndices: number[],
): { year: number; startIndex: number; endIndex: number }[] => {
  if (monthIndices.length === 0) return [];

  const groups: { year: number; startIndex: number; endIndex: number }[] = [];
  let groupStart = monthIndices[0];
  let groupEnd = monthIndices[0];
  let groupYear = Math.floor(monthIndices[0] / 12);

  for (let index = 1; index < monthIndices.length; index += 1) {
    const monthIndex = monthIndices[index];
    const year = Math.floor(monthIndex / 12);

    if (year === groupYear) {
      groupEnd = monthIndex;
      continue;
    }

    groups.push({ year: groupYear, startIndex: groupStart, endIndex: groupEnd });
    groupStart = monthIndex;
    groupEnd = monthIndex;
    groupYear = year;
  }

  groups.push({ year: groupYear, startIndex: groupStart, endIndex: groupEnd });

  return groups;
};

export type DocumentFieldTimelineItem =
  | { type: "field"; field: DocumentField }
  | { type: "gap"; label: string; year: number };

/** Builds a chronologically ordered timeline with collapsed month gaps. */
export const buildDocumentFieldsTimeline = (
  documentFields: DocumentField[],
): DocumentFieldTimelineItem[] => {
  const sortedFields = [...documentFields].sort((left, right) =>
    left.date.localeCompare(right.date),
  );
  if (sortedFields.length === 0) return [];

  const timeline: DocumentFieldTimelineItem[] = [];

  sortedFields.forEach((field, index) => {
    if (index > 0) {
      const missingMonths = getMissingMonthIndices(sortedFields[index - 1].date, field.date);

      for (const group of groupMissingMonthsByYear(missingMonths)) {
        timeline.push({
          type: "gap",
          label: formatDocumentFieldGapMonthRange(group.startIndex, group.endIndex),
          year: group.year,
        });
      }
    }

    timeline.push({ type: "field", field });
  });

  return timeline;
};

const sumDocumentFieldAmounts = (documentFields: DocumentField[]): number =>
  documentFields.reduce((total, field) => total + field.amount.value, 0);

const getAveragePeriodLabel = (documentType: string, earningType?: EarningType): string => {
  // an incentive always divides by 6 months, even when fewer payslips were provided
  if (earningType === "INCENTIVE") return "months";

  return documentType === "BANK_STATEMENT" ? "statement periods" : "payslip periods";
};

export const getExcludedFromPeriodWindowTooltipText = (
  maxPeriods: number,
  documentType: string,
): string =>
  `Not included in the average. Outside the last ${maxPeriods} ${getAveragePeriodLabel(documentType)}.`;

/**
 * The API returns every matched document field regardless of maxPeriods, re-extracted fresh on each read, while the
 * backend's AVERAGE amount is calculated from only the most recent `maxPeriods` calendar months. Restricting to that
 * same window (ending at the latest field's month) keeps the hint's sum consistent with the displayed amount even
 * when a gap pushes an older field out of the window despite fitting within `maxPeriods` entries.
 */
const filterFieldsWithinPeriodWindow = (
  sortedFields: DocumentField[],
  maxPeriods: number | null | undefined,
): DocumentField[] => {
  if (maxPeriods == null || maxPeriods <= 0 || sortedFields.length === 0) return sortedFields;

  const latestMonthIndex = toMonthIndex(sortedFields[sortedFields.length - 1].date);
  if (latestMonthIndex == null) return sortedFields;

  const windowStartIndex = latestMonthIndex - maxPeriods + 1;

  return sortedFields.filter((field) => {
    const monthIndex = toMonthIndex(field.date);
    return monthIndex != null && monthIndex >= windowStartIndex;
  });
};

/**
 * Dates of document fields that count towards the maxPeriods window. Returns null when every field
 * is inside the window so callers can skip excluded-field styling.
 */
export const getPeriodWindowCountedFieldDates = (
  documentFields: DocumentField[],
  maxPeriods: number | null | undefined,
): Set<string> | null => {
  if (maxPeriods == null || maxPeriods <= 0 || documentFields.length === 0) return null;

  const sortedFields = [...documentFields].sort((left, right) =>
    left.date.localeCompare(right.date),
  );
  const windowedFields = filterFieldsWithinPeriodWindow(sortedFields, maxPeriods);
  if (windowedFields.length === sortedFields.length) return null;

  return new Set(windowedFields.map((field) => field.date));
};

const getExplicitAveragePeriodCount = (
  numOfPayslips: number | null | undefined,
  maxPeriods: number | null | undefined,
): number | null => {
  const payslips = numOfPayslips != null && numOfPayslips > 0 ? numOfPayslips : null;
  const periods = maxPeriods != null && maxPeriods > 0 ? maxPeriods : null;

  if (payslips != null && periods != null) return Math.min(payslips, periods);
  return payslips ?? periods;
};

/** Infers the AVERAGE divisor when numOfPayslips is unavailable. */
const inferAverageDivisor = (sum: number, result: number, itemCount: number): number => {
  if (result === 0) return itemCount;

  const inferred = sum / result;
  const rounded = Math.round(inferred);

  if (Math.abs(inferred - rounded) <= 0.015) {
    return rounded;
  }

  return itemCount;
};

const getAverageDivisor = (
  sum: number,
  itemCount: number,
  amount: string,
  originalCurrency: string | null,
  numOfPayslips: number | null | undefined,
  maxPeriods: number | null | undefined,
): number => {
  const explicitPeriodCount = getExplicitAveragePeriodCount(numOfPayslips, maxPeriods);
  if (explicitPeriodCount != null) return explicitPeriodCount;

  const inferResult =
    originalCurrency != null ? (itemCount > 0 ? sum / itemCount : 0) : parseDecimalAmount(amount);

  return inferAverageDivisor(sum, inferResult, itemCount);
};

const computeNativeFormulaResult = (
  frequency: EligibilityFrequency,
  windowedFields: DocumentField[],
  amount: string,
  originalCurrency: string | null,
  numOfPayslips: number | null | undefined,
  maxPeriods: number | null | undefined,
): number => {
  const sum = sumDocumentFieldAmounts(windowedFields);
  const itemCount = windowedFields.length;

  switch (frequency) {
    case "MONTHLY":
      return itemCount > 0 ? windowedFields[itemCount - 1].amount.value : 0;
    case "QUARTERLY":
      return sum / 3;
    case "BI_ANNUAL":
      return sum / 6;
    case "ANNUAL":
      return sum / 12;
    case "AVERAGE":
      return (
        sum / getAverageDivisor(sum, itemCount, amount, originalCurrency, numOfPayslips, maxPeriods)
      );
  }
};

const formatFormulaResult = (
  frequency: EligibilityFrequency,
  windowedFields: DocumentField[],
  amount: string,
  originalCurrency: string | null,
  convertedCurrency: string,
  numOfPayslips: number | null | undefined,
  maxPeriods: number | null | undefined,
): string => {
  if (originalCurrency == null) {
    return formatDecimalAmount(amount);
  }

  const nativeResult = computeNativeFormulaResult(
    frequency,
    windowedFields,
    amount,
    originalCurrency,
    numOfPayslips,
    maxPeriods,
  );

  return `${formatDecimalAmount(String(nativeResult))} ${originalCurrency} → ${convertedCurrency} ${formatDecimalAmount(amount)}`;
};

export type DocumentFieldsCalculationHintParts = {
  prefix: string;
  conversion: string;
  fxRateTooltip: string | null;
};

const buildDocumentFieldsCalculationHintPartsFromFormula = (
  formulaPrefix: string,
  formattedResult: string,
  originalCurrency: string | null,
  convertedCurrency: string,
  fxRate: string | null,
): DocumentFieldsCalculationHintParts => {
  if (originalCurrency == null) {
    return {
      prefix: `${formulaPrefix}${formattedResult}`,
      conversion: "",
      fxRateTooltip: null,
    };
  }

  return {
    prefix: formulaPrefix,
    conversion: formattedResult,
    fxRateTooltip:
      fxRate != null && fxRate !== ""
        ? formatFxConversionTooltipText(fxRate, originalCurrency, convertedCurrency)
        : null,
  };
};

/** Describes how document evidence maps to the monthly amount for the selected frequency. */
export const buildDocumentFieldsCalculationHintParts = (
  frequency: EligibilityFrequency | null,
  documentFields: DocumentField[],
  amount: string,
  documentType: string,
  numOfPayslips?: number | null,
  maxPeriods?: number | null,
  originalCurrency: string | null = null,
  convertedCurrency = "",
  fxRate: string | null = null,
  earningType?: EarningType,
): DocumentFieldsCalculationHintParts | null => {
  if (documentFields.length === 0 || frequency === null) return null;

  const sortedFields = [...documentFields].sort((left, right) =>
    left.date.localeCompare(right.date),
  );
  const windowedFields = filterFieldsWithinPeriodWindow(sortedFields, maxPeriods);
  const sum = sumDocumentFieldAmounts(windowedFields);
  const formattedSum = formatDecimalAmount(String(sum));
  const formattedResult = formatFormulaResult(
    frequency,
    windowedFields,
    amount,
    originalCurrency,
    convertedCurrency,
    numOfPayslips,
    maxPeriods,
  );
  const itemCount = windowedFields.length;

  switch (frequency) {
    case "MONTHLY":
      return buildDocumentFieldsCalculationHintPartsFromFormula(
        `latest of ${itemCount} = `,
        formattedResult,
        originalCurrency,
        convertedCurrency,
        fxRate,
      );
    case "QUARTERLY":
      return buildDocumentFieldsCalculationHintPartsFromFormula(
        `sum ${formattedSum} ÷ 3 = `,
        formattedResult,
        originalCurrency,
        convertedCurrency,
        fxRate,
      );
    case "BI_ANNUAL":
      return buildDocumentFieldsCalculationHintPartsFromFormula(
        `sum ${formattedSum} ÷ 6 = `,
        formattedResult,
        originalCurrency,
        convertedCurrency,
        fxRate,
      );
    case "ANNUAL":
      return buildDocumentFieldsCalculationHintPartsFromFormula(
        `sum ${formattedSum} ÷ 12 = `,
        formattedResult,
        originalCurrency,
        convertedCurrency,
        fxRate,
      );
    case "AVERAGE": {
      const divisor = getAverageDivisor(
        sum,
        itemCount,
        amount,
        originalCurrency,
        numOfPayslips,
        maxPeriods,
      );
      const explicitPeriodCount = getExplicitAveragePeriodCount(numOfPayslips, maxPeriods);

      if (explicitPeriodCount == null && divisor === itemCount) {
        return buildDocumentFieldsCalculationHintPartsFromFormula(
          `average ${formattedSum} ÷ ${divisor} = `,
          formattedResult,
          originalCurrency,
          convertedCurrency,
          fxRate,
        );
      }

      return buildDocumentFieldsCalculationHintPartsFromFormula(
        `sum ${formattedSum} ÷ ${divisor} ${getAveragePeriodLabel(documentType, earningType)} = `,
        formattedResult,
        originalCurrency,
        convertedCurrency,
        fxRate,
      );
    }
  }
};

/** Describes how document evidence maps to the monthly amount for the selected frequency. */
export const formatDocumentFieldsCalculationHint = (
  frequency: EligibilityFrequency | null,
  documentFields: DocumentField[],
  amount: string,
  documentType: string,
  numOfPayslips?: number | null,
  maxPeriods?: number | null,
  originalCurrency: string | null = null,
  convertedCurrency = "",
  fxRate: string | null = null,
): string | null => {
  const parts = buildDocumentFieldsCalculationHintParts(
    frequency,
    documentFields,
    amount,
    documentType,
    numOfPayslips,
    maxPeriods,
    originalCurrency,
    convertedCurrency,
    fxRate,
  );

  if (parts == null) return null;

  return `${parts.prefix}${parts.conversion}`;
};

/** Ensures the current value is always selectable, even if the enum list hasn't loaded yet. */
export const resolveTypeOptions = <T extends string>(currentValue: T, options: T[]): T[] =>
  options.includes(currentValue) ? options : [currentValue, ...options];

const BANK_STATEMENT_DOCUMENT_TYPE = "BANK_STATEMENT";
const PAYSLIP_DOCUMENT_TYPE = "PAYSLIP";
const SALARY_CERTIFICATE_DOCUMENT_TYPE = "SALARY_CERTIFICATE";

export const isUncountedStatementSalary = (earning: Earning): boolean =>
  earning.documentType === BANK_STATEMENT_DOCUMENT_TYPE && earning.allocation === 0;

/** Shown for context only; the backend never counts it toward eligible income. */
export const isReferenceOnlyEarning = (earning: Earning): boolean =>
  earning.documentType === SALARY_CERTIFICATE_DOCUMENT_TYPE;

export const hasPayslipEarnings = (earnings: Earning[]): boolean =>
  earnings.some((earning) => earning.documentType === PAYSLIP_DOCUMENT_TYPE);

export const needsPayslipsForSalary = (earnings: Earning[]): boolean =>
  earnings.some(isUncountedStatementSalary) && !hasPayslipEarnings(earnings);
