import { useState, type FC } from "react";

import { Modal, ModalFooter, PillButton } from "@/components";
import { useRemoveFileFromBankApplication } from "@/api";
import type { FileItem } from "@/types";

type Props = {
  isOpen: boolean;
  onOpenChange: (open: boolean) => void;
  bankApplicationId: string;
  file: FileItem | null;
};

export const RemoveFileModal: FC<Props> = ({ isOpen, onOpenChange, bankApplicationId, file }) => {
  const removeFile = useRemoveFileFromBankApplication();
  const [submitError, setSubmitError] = useState<string | null>(null);

  const handleOpenChange = (open: boolean) => {
    if (!open) {
      setSubmitError(null);
      removeFile.reset();
    }
    onOpenChange(open);
  };

  const handleRemove = () => {
    if (!file) return;

    setSubmitError(null);

    removeFile.mutate(
      {
        bankApplicationId,
        documentId: file.id,
      },
      {
        onSuccess: () => handleOpenChange(false),
        onError: (err) => {
          setSubmitError(err instanceof Error ? err.message : "Could not remove file.");
        },
      },
    );
  };

  return (
    <Modal
      isOpen={isOpen}
      onOpenChange={handleOpenChange}
      className="sm:max-w-md!"
      title="Remove file?"
      description="The file attached to this document will be removed."
    >
      <div className="min-h-0 flex-1 space-y-4 overflow-y-auto px-6 py-5">
        <p className="truncate font-mono text-sm text-foreground">{file?.fileName}</p>

        {submitError && (
          <p role="alert" className="text-sm text-destructive">
            {submitError}
          </p>
        )}
      </div>

      <ModalFooter className="justify-between">
        <PillButton
          type="button"
          buttonRole="secondary"
          onClick={() => handleOpenChange(false)}
          disabled={removeFile.isPending}
        >
          Cancel
        </PillButton>
        <PillButton
          type="button"
          buttonRole="destructive"
          onClick={handleRemove}
          disabled={!file || removeFile.isPending}
        >
          Remove
        </PillButton>
      </ModalFooter>
    </Modal>
  );
};
