import type {
  Applicant,
  ApplicantDocumentGroup,
  BankApplication,
  DocumentChecklistRow,
  FileItemWithDocumentId,
  ProcessingStatus,
} from "@/types";

/**
 * Dev-only checklist overlays for manually verifying row status icons and tooltips.
 *
 * Enable on a real bank application page:
 *   /bank-applications/:id?mockChecklistStatuses=1
 */
export const CHECKLIST_STATUS_MOCK_PARAM = "mockChecklistStatuses";

export const isChecklistStatusMockEnabled = (): boolean => {
  if (typeof window === "undefined") return false;
  return new URLSearchParams(window.location.search).get(CHECKLIST_STATUS_MOCK_PARAM) === "1";
};

const makeMockFile = (
  id: string,
  fileName: string,
  processingStatus: ProcessingStatus,
): FileItemWithDocumentId => ({
  id: `mock-file-${id}`,
  documentId: `mock-doc-${id}`,
  docServiceDocumentId: `mock-svc-${id}`,
  fileName,
  createdAt: "2026-01-01T00:00:00Z",
  updatedAt: "2026-01-01T00:00:00Z",
  processingStatus,
});

const makeCaseRow = (
  type: string,
  isRequired: boolean,
  matchedFile: FileItemWithDocumentId | null,
): DocumentChecklistRow => ({
  type,
  isRequired,
  matchedFile,
});

/** Classified checklist rows only — classification states live in unclassifiedFiles. */
const CLASSIFIED_IN_PROGRESS_STATUSES: ProcessingStatus[] = [
  "MERGE_IN_PROGRESS",
  "SPLIT_IN_PROGRESS",
  "EXTRACTION_IN_PROGRESS",
  "ROTATION_IN_PROGRESS",
];

/** Merge failures surface on child rows, not on the merge parent document. */
const CLASSIFIED_FAILED_STATUSES: ProcessingStatus[] = [
  "SPLIT_FAILED",
  "EXTRACTION_FAILED",
  "ROTATION_FAILED",
];

const mockCaseDocuments = (): DocumentChecklistRow[] => [
  makeCaseRow("MOCK_ROW_MISSING", true, null),
  makeCaseRow("MOCK_ROW_RECEIVED", true, makeMockFile("received", "received.pdf", "READY")),
  makeCaseRow(
    "MOCK_ROW_OPTIONAL_PROVIDED",
    false,
    makeMockFile("optional-provided", "optional.pdf", "READY"),
  ),
  ...CLASSIFIED_IN_PROGRESS_STATUSES.map((status) =>
    makeCaseRow(
      `MOCK_ROW_${status}`,
      true,
      makeMockFile(status.toLowerCase(), `${status}.pdf`, status),
    ),
  ),
  ...CLASSIFIED_FAILED_STATUSES.map((status) =>
    makeCaseRow(
      `MOCK_ROW_${status}`,
      true,
      makeMockFile(status.toLowerCase(), `${status}.pdf`, status),
    ),
  ),
];

const mockUnclassifiedFiles = (): FileItemWithDocumentId[] => [
  makeMockFile("unclassified-ready", "unclassified-ready.pdf", "READY"),
  makeMockFile(
    "unclassified-classifying",
    "unclassified-classifying.pdf",
    "CLASSIFICATION_IN_PROGRESS",
  ),
  makeMockFile("unclassified-failed", "unclassified-failed.pdf", "CLASSIFICATION_FAILED"),
];

const mockApplicantGroups = (applicant: Applicant): ApplicantDocumentGroup[] => [
  {
    type: "MOCK_MERGE_PARENT_IN_PROGRESS",
    applicant,
    isRequired: true,
    matchedFile: makeMockFile("merge-parent-out-progress", "kyc-merging.pdf", "READY"),
    processingStatus: "MERGE_IN_PROGRESS",
    documents: [
      {
        type: "MOCK_CHILD_READY",
        applicant,
        isRequired: true,
        matchedFile: makeMockFile("merge-child-ready", "passport.pdf", "READY"),
      },
    ],
  },
  {
    type: "MOCK_MERGE_PARENT_FAILED",
    applicant,
    isRequired: true,
    matchedFile: null,
    processingStatus: "MERGE_FAILED",
    documents: [
      {
        type: "MOCK_CHILD_MERGE_FAILED",
        applicant,
        isRequired: true,
        matchedFile: makeMockFile("merge-child-ready", "passport.pdf", "MERGE_FAILED"),
      },
    ],
  },
  {
    type: "MOCK_MERGE_PARENT_READY",
    applicant,
    isRequired: true,
    matchedFile: makeMockFile("merge-parent-out-ready", "kyc-merged.pdf", "READY"),
    processingStatus: "READY",
    documents: [
      {
        type: "MOCK_CHILD_MERGE_FAILED",
        applicant,
        isRequired: true,
        matchedFile: makeMockFile("merge-child-failed", "payslip.pdf", "MERGE_FAILED"),
      },
      {
        type: "MOCK_CHILD_SPLIT_IN_PROGRESS",
        applicant,
        isRequired: true,
        matchedFile: makeMockFile(
          "merge-child-split-progress",
          "bank-statement.pdf",
          "SPLIT_IN_PROGRESS",
        ),
      },
      {
        type: "MOCK_CHILD_EXTRACTION_FAILED",
        applicant,
        isRequired: true,
        matchedFile: makeMockFile("merge-child-extraction-failed", "visa.pdf", "EXTRACTION_FAILED"),
      },
    ],
  },
];

export const applyChecklistStatusMocks = (
  data: BankApplication,
  enabled = isChecklistStatusMockEnabled(),
): BankApplication => {
  if (!enabled) return data;

  const applicant = data.applicants[0];
  if (!applicant) return data;

  const { checklist } = data;

  return {
    ...data,
    checklist: {
      ...checklist,
      caseDocuments: [...mockCaseDocuments(), ...checklist.caseDocuments],
      applicantDocuments: [...mockApplicantGroups(applicant), ...checklist.applicantDocuments],
      unclassifiedFiles: [...mockUnclassifiedFiles(), ...checklist.unclassifiedFiles],
    },
  };
};
