import { type FC, type MouseEvent } from "react";

import { RotateCcw } from "@huspy/shared-icons";
import { Button, cn, Tooltip, TooltipContent, TooltipTrigger } from "@huspy/shared-ui";

type Props = {
  disabled?: boolean;
  onClear: () => void;
  className?: string;
  ariaLabel?: string;
  tooltip?: string;
};

export const OverrideClearButton: FC<Props> = ({
  disabled = false,
  onClear,
  className,
  ariaLabel = "Reset to calculated value",
  tooltip = "Manually overridden. Click to reset to the calculated value.",
}) => {
  const handleClear = (event: MouseEvent<HTMLButtonElement>) => {
    event.preventDefault();
    event.stopPropagation();
    if (disabled) return;

    onClear();
  };

  return (
    <Tooltip>
      <TooltipTrigger asChild>
        <Button
          type="button"
          variant="ghost"
          size="icon"
          onClick={handleClear}
          disabled={disabled}
          className={cn(
            "size-7 shrink-0 px-0 text-muted-foreground hover:text-foreground",
            className,
          )}
          aria-label={ariaLabel}
        >
          <RotateCcw className="size-3.5" />
        </Button>
      </TooltipTrigger>
      <TooltipContent>{tooltip}</TooltipContent>
    </Tooltip>
  );
};
