import type { FC } from "react";

import { RotateCcw, RotateCw } from "@huspy/shared-icons";
import { Button, cn, Tooltip, TooltipContent, TooltipTrigger } from "@huspy/shared-ui";

type Props = {
  canSave: boolean;
  isSaving: boolean;
  onRotateLeft: () => void;
  onRotateRight: () => void;
  onResetRotation: () => void;
  onSave: () => void;
  className?: string;
  /** Blocks rotating (but not the reset/save on an already-pending rotation) while true. */
  disabled?: boolean;
  /** Shown on hover when `disabled` is true, explaining why rotation is unavailable. */
  disabledTooltip?: string;
};

export const PdfPreviewRotateControls: FC<Props> = ({
  canSave,
  isSaving,
  onRotateLeft,
  onRotateRight,
  onResetRotation,
  onSave,
  className,
  disabled,
  disabledTooltip,
}) => {
  const rotateButtonsDisabled = isSaving || disabled;

  const rotateButtons = (
    <div className="flex items-center gap-1">
      <Button
        type="button"
        variant="ghost"
        onClick={onRotateLeft}
        disabled={rotateButtonsDisabled}
        className="size-8 flex-1 px-0"
        aria-label="Rotate left 90 degrees"
      >
        <RotateCcw className="size-4" />
      </Button>
      <Button
        type="button"
        variant="ghost"
        onClick={onRotateRight}
        disabled={rotateButtonsDisabled}
        className="size-8 flex-1 px-0"
        aria-label="Rotate right 90 degrees"
      >
        <RotateCw className="size-4" />
      </Button>
    </div>
  );

  return (
    <div
      className={cn(
        "flex flex-col items-stretch gap-1 rounded-lg border border-border bg-popover/95 p-1 shadow-md",
        className,
      )}
    >
      {disabled && disabledTooltip ? (
        <Tooltip>
          <TooltipTrigger asChild>
            <span className="inline-flex">{rotateButtons}</span>
          </TooltipTrigger>
          <TooltipContent>{disabledTooltip}</TooltipContent>
        </Tooltip>
      ) : (
        rotateButtons
      )}
      <div className="h-px w-full bg-border" />
      <Button
        type="button"
        variant="ghost"
        onClick={onResetRotation}
        disabled={!canSave || isSaving}
        className="h-8 w-full px-2 text-xs"
      >
        Reset
      </Button>
      <Button
        type="button"
        onClick={onSave}
        disabled={!canSave || isSaving}
        className="h-8 w-full px-2 text-xs"
      >
        Save
      </Button>
    </div>
  );
};
