import type { FC } from "react";

import { cn, Tooltip, TooltipContent, TooltipTrigger } from "@huspy/shared-ui";

import type { DocumentField, EarningType, EligibilityFrequency } from "@/types";

import { FX_CONVERSION_HINT_TRIGGER_CLASSNAME } from "../../constants";
import {
  buildDocumentFieldsCalculationHintParts,
  buildDocumentFieldsTimeline,
  formatDecimalAmount,
  formatDocumentFieldMonthYear,
  getExcludedFromPeriodWindowTooltipText,
  getPeriodWindowCountedFieldDates,
} from "../../utils";

type Props = {
  documentFields: DocumentField[];
  documentType: string;
  frequency: EligibilityFrequency | null;
  amount: string;
  originalCurrency: string | null;
  currency: string;
  fxRate: string | null;
  numOfPayslips?: number | null;
  maxPeriods?: number | null;
  earningType?: EarningType;
};

export const DocumentFieldsPanel: FC<Props> = ({
  documentFields,
  documentType,
  frequency,
  amount,
  originalCurrency,
  currency,
  fxRate,
  numOfPayslips,
  maxPeriods,
  earningType,
}) => {
  const timeline = buildDocumentFieldsTimeline(documentFields);
  const countedFieldDates = getPeriodWindowCountedFieldDates(documentFields, maxPeriods);
  const calculationHintParts = buildDocumentFieldsCalculationHintParts(
    frequency,
    documentFields,
    amount,
    documentType,
    numOfPayslips,
    maxPeriods,
    originalCurrency,
    currency,
    fxRate,
    earningType,
  );

  return (
    <div className="-mx-2 mt-1.5 border-t border-border/40 px-2 pt-1.5">
      {calculationHintParts && (
        <p className="mb-2 text-[11px] tabular-nums text-muted-foreground">
          {calculationHintParts.prefix}
          {calculationHintParts.conversion &&
            (calculationHintParts.fxRateTooltip ? (
              <Tooltip>
                <TooltipTrigger asChild>
                  <span className={FX_CONVERSION_HINT_TRIGGER_CLASSNAME}>
                    {calculationHintParts.conversion}
                  </span>
                </TooltipTrigger>
                <TooltipContent>{calculationHintParts.fxRateTooltip}</TooltipContent>
              </Tooltip>
            ) : (
              calculationHintParts.conversion
            ))}
        </p>
      )}

      <div className="flex flex-wrap items-center gap-2">
        {timeline.map((item, index) => {
          if (item.type === "gap") {
            return (
              <div
                key={`gap-${item.label}-${item.year}-${index}`}
                className={cn(
                  "flex min-w-20 flex-col items-center rounded-md border border-dashed border-muted-foreground/40",
                  "bg-transparent px-3 py-1",
                )}
              >
                <span className="text-[10px] text-muted-foreground">
                  {`${item.label} ${item.year}`}
                </span>
                <span className="text-[11px] text-muted-foreground">—</span>
              </div>
            );
          }

          const isExcludedFromPeriodWindow =
            countedFieldDates != null && !countedFieldDates.has(item.field.date);
          const fieldKey = `${item.field.date}-${item.field.amount.value}-${index}`;
          const fieldCellClassName = cn(
            "flex min-w-16 flex-col items-center rounded-md border px-2 py-1 cursor-default border-border",
            isExcludedFromPeriodWindow
              ? "border-muted-foreground/40 bg-transparent opacity-75"
              : "bg-card",
          );

          const fieldCell = (
            <div className={fieldCellClassName}>
              <span className="text-[10px] text-muted-foreground">
                {item.field.date ? formatDocumentFieldMonthYear(item.field.date) : "—"}
              </span>
              <span
                className={cn(
                  "text-[11px] tabular-nums",
                  isExcludedFromPeriodWindow && "text-muted-foreground",
                )}
              >
                {formatDecimalAmount(String(item.field.amount.value))}
              </span>
            </div>
          );

          if (isExcludedFromPeriodWindow && maxPeriods != null && maxPeriods > 0) {
            return (
              <Tooltip key={fieldKey}>
                <TooltipTrigger asChild>{fieldCell}</TooltipTrigger>
                <TooltipContent>
                  {getExcludedFromPeriodWindowTooltipText(maxPeriods, documentType)}
                </TooltipContent>
              </Tooltip>
            );
          }

          return <div key={fieldKey}>{fieldCell}</div>;
        })}
      </div>
    </div>
  );
};
