import type { ReactNode } from "react";

import { cn } from "@huspy/shared-ui";

import { DocumentUploadRemoveButton } from "./DocumentUploadRemoveButton";

type Props = {
  leadingIcon: ReactNode;
  fileName: string;
  fileNameClassName?: string;
  onRemove?: () => void;
  removeAriaLabel?: string;
  removeDisabled?: boolean;
  trailing?: ReactNode;
};

export function DocumentUploadFileRow({
  leadingIcon,
  fileName,
  fileNameClassName,
  onRemove,
  removeAriaLabel,
  removeDisabled = false,
  trailing,
}: Props) {
  return (
    <div className="flex items-center gap-2">
      {leadingIcon}
      <span className={cn("min-w-0 flex-1 truncate text-[13px] font-medium", fileNameClassName)}>
        {fileName}
      </span>
      {trailing ??
        (onRemove ? (
          <DocumentUploadRemoveButton
            onClick={onRemove}
            disabled={removeDisabled}
            ariaLabel={removeAriaLabel}
          />
        ) : null)}
    </div>
  );
}
