import type { FC } from "react";

import type { NestedGroup } from "../utils/buildGroupSections";

import { ChildRowsSection } from "./ChildRowsSection";
import { ParentRowCard } from "./ParentRowCard";

type Props = {
  section: NestedGroup;
};

export const NestedGroupSection: FC<Props> = ({ section }) => (
  <section className="space-y-4">
    <h3 className="text-md font-medium text-foreground">{section.group.label}</h3>

    {section.parentRows.length === 0 && (
      <p className="text-sm text-muted-foreground">No rows extracted yet.</p>
    )}

    {section.parentRows.length > 0 && (
      <div className="space-y-4">
        {section.parentRows.map((parentRow, index) => (
          <ParentRowCard
            key={parentRow.row.index}
            groupLabel={section.group.label}
            position={index + 1}
            template={section.group.template}
            parentRow={parentRow}
          />
        ))}
      </div>
    )}

    {section.orphanRows.length > 0 && (
      <section className="space-y-4 rounded-lg border border-dashed border-border p-4">
        <h4 className="text-sm font-medium text-foreground">Unassigned rows</h4>

        {section.orphanRows.map((childRows) => (
          <ChildRowsSection
            key={childRows.group.name}
            group={childRows.group}
            rows={childRows.rows}
            showJoinColumns
            useLocalRowNumbers={false}
          />
        ))}
      </section>
    )}
  </section>
);
