import { createContext, type FC, type ReactNode, useContext, useMemo } from "react";

import type { FileItem } from "@/types";

export type RemoveFileTarget = {
  file: FileItem;
};

type RemoveFileContextValue = {
  beginRemove: (target: RemoveFileTarget) => void;
};

const RemoveFileContext = createContext<RemoveFileContextValue | null>(null);

type ProviderProps = {
  children: ReactNode;
  onBeginRemove: (target: RemoveFileTarget) => void;
};

export const RemoveFileProvider: FC<ProviderProps> = ({ children, onBeginRemove }) => {
  const value = useMemo(
    () => ({
      beginRemove: onBeginRemove,
    }),
    [onBeginRemove],
  );

  return <RemoveFileContext.Provider value={value}>{children}</RemoveFileContext.Provider>;
};

export const useRemoveFile = (): RemoveFileContextValue => {
  const ctx = useContext(RemoveFileContext);
  if (!ctx) {
    throw new Error("useRemoveFile must be used within RemoveFileProvider");
  }
  return ctx;
};
