import type { FC } from "react";

import { cn, Tooltip, TooltipContent, TooltipTrigger } from "@huspy/shared-ui";

import { CURRENCY_NOT_EXTRACTED_TOOLTIP } from "../../constants";

type Props = {
  currency: string;
  isUndetected: boolean;
};

export const LineCurrencyLabel: FC<Props> = ({ currency, isUndetected }) => {
  const labelClassName = cn(
    "text-xs tabular-nums cursor-default",
    isUndetected
      ? "rounded-md bg-warning/14 px-1 py-0.5 font-semibold text-warning"
      : "text-muted-foreground",
  );

  if (isUndetected) {
    return (
      <Tooltip>
        <TooltipTrigger asChild>
          <span className={labelClassName}>{currency}</span>
        </TooltipTrigger>
        <TooltipContent>{CURRENCY_NOT_EXTRACTED_TOOLTIP}</TooltipContent>
      </Tooltip>
    );
  }

  return <span className={labelClassName}>{currency}</span>;
};
