import { createContext, type FC, type ReactNode, useContext, useMemo } from "react";

type AddDocumentContextValue = {
  beginAddDocument: (documentType?: string) => void;
};

const AddDocumentContext = createContext<AddDocumentContextValue | null>(null);

type ProviderProps = {
  children: ReactNode;
  onBeginAddDocument: (documentType?: string) => void;
};

export const AddDocumentProvider: FC<ProviderProps> = ({ children, onBeginAddDocument }) => {
  const value = useMemo(
    () => ({
      beginAddDocument: onBeginAddDocument,
    }),
    [onBeginAddDocument],
  );

  return <AddDocumentContext.Provider value={value}>{children}</AddDocumentContext.Provider>;
};

export const useAddDocument = (): AddDocumentContextValue => {
  const ctx = useContext(AddDocumentContext);
  if (!ctx) {
    throw new Error("useAddDocument must be used within AddDocumentProvider");
  }
  return ctx;
};
