import { createContext, type FC, type ReactNode, useContext, useMemo } from "react";

export type RemoveEligibilityLineTarget = {
  kind: "earning" | "liability";
  lineId: string;
  description: string;
};

type RemoveEligibilityLineContextValue = {
  beginRemove: (target: RemoveEligibilityLineTarget) => void;
};

const RemoveEligibilityLineContext = createContext<RemoveEligibilityLineContextValue | null>(null);

type ProviderProps = {
  children: ReactNode;
  onBeginRemove: (target: RemoveEligibilityLineTarget) => void;
};

export const RemoveEligibilityLineProvider: FC<ProviderProps> = ({ children, onBeginRemove }) => {
  const value = useMemo(
    () => ({
      beginRemove: onBeginRemove,
    }),
    [onBeginRemove],
  );

  return (
    <RemoveEligibilityLineContext.Provider value={value}>
      {children}
    </RemoveEligibilityLineContext.Provider>
  );
};

export const useRemoveEligibilityLine = (): RemoveEligibilityLineContextValue => {
  const ctx = useContext(RemoveEligibilityLineContext);
  if (!ctx) {
    throw new Error("useRemoveEligibilityLine must be used within RemoveEligibilityLineProvider");
  }
  return ctx;
};
