import type { FC } from "react";

import { FloatingLabelSelect } from "@huspy/shared-agents";
import { Trash2, Undo2, X } from "@huspy/shared-icons";

import { shouldShowAssignToSelect } from "@/routes/BankApplication/utils";
import {
  formatPageRange,
  pagesInSegment,
} from "@/routes/BankApplication/components/ChecklistWorkspace/components/SplitDocumentModal/utils";
import type {
  PageSegment,
  SelectOption,
} from "@/routes/BankApplication/components/ChecklistWorkspace/components/SplitDocumentModal/types";
import { SplitBetweenPagesButton } from "@/routes/BankApplication/components/ChecklistWorkspace/components/SplitDocumentModal/components/SplitBetweenPagesButton";
import { SplitPageRow } from "@/routes/BankApplication/components/ChecklistWorkspace/components/SplitDocumentModal/components/SplitPageRow";
import { DocumentTypeCode } from "@/types";

type Props = {
  segment: PageSegment;
  segmentIndex: number;
  focusedPage: number;
  selectedType: string;
  selectedAssignee: string;
  typeOptions: SelectOption[];
  assignToOptions: SelectOption[];
  documentTypeCodes: DocumentTypeCode[];
  applicantCount: number;
  isRemoved: boolean;
  onTypeChange: (startPage: number, documentType: string) => void;
  onAssigneeChange: (startPage: number, applicantId: string) => void;
  onFocusPage: (page: number) => void;
  onAddCut: (afterPage: number) => void;
  onRemoveCut: (afterPage: number) => void;
  onToggleRemoved: (startPage: number) => void;
  showValidationErrors?: boolean;
};

export const SplitSegmentGroup: FC<Props> = ({
  segment,
  segmentIndex,
  focusedPage,
  selectedType,
  selectedAssignee,
  typeOptions,
  assignToOptions,
  documentTypeCodes,
  applicantCount,
  isRemoved,
  onTypeChange,
  onAssigneeChange,
  onFocusPage,
  onAddCut,
  onRemoveCut,
  onToggleRemoved,
  showValidationErrors = false,
}) => {
  const segmentPages = pagesInSegment(segment);
  const hasTypeError = showValidationErrors && !isRemoved && !selectedType;
  const showAssignTo = shouldShowAssignToSelect(selectedType, documentTypeCodes, applicantCount);
  const hasAssigneeError = showValidationErrors && showAssignTo && !isRemoved && !selectedAssignee;

  return (
    <div className="overflow-hidden rounded-lg border border-border">
      <div className="flex items-center justify-between gap-2 bg-muted/30 px-3 py-2">
        <span className="text-xs font-semibold text-foreground">
          Document {segmentIndex + 1}
          <span className="ml-1.5 font-normal text-muted-foreground">
            ({formatPageRange(segment)})
          </span>
          {isRemoved && (
            <span className="ml-1.5 font-normal text-destructive">Will be discarded</span>
          )}
        </span>
        <div className="flex items-center gap-1">
          <button
            type="button"
            onClick={() => onToggleRemoved(segment.start)}
            className="inline-flex items-center gap-1 rounded px-1.5 py-0.5 text-[10px] text-muted-foreground hover:bg-muted hover:text-foreground"
          >
            {isRemoved ? (
              <>
                <Undo2 className="size-3" aria-hidden />
                Restore
              </>
            ) : (
              <>
                <Trash2 className="size-3" aria-hidden />
                Remove
              </>
            )}
          </button>
          {segmentIndex > 0 && !isRemoved && (
            <button
              type="button"
              onClick={() => onRemoveCut(segment.start - 1)}
              className="inline-flex items-center gap-1 rounded px-1.5 py-0.5 text-[10px] text-muted-foreground hover:bg-muted hover:text-foreground"
            >
              <X className="size-3" aria-hidden />
              Merge into previous
            </button>
          )}
        </div>
      </div>

      <div className={isRemoved ? "px-3 py-2 opacity-50" : "px-3 py-2"}>
        {!isRemoved && (
          <div className="mb-2 grid grid-cols-1 gap-2">
            <FloatingLabelSelect
              label="Document type"
              value={selectedType}
              onValueChange={(value) => onTypeChange(segment.start, value)}
              options={typeOptions}
              error={hasTypeError}
              errorMessage={hasTypeError ? "Select a document type" : undefined}
            />
            {showAssignTo && (
              <FloatingLabelSelect
                label="Assign to"
                placeholder="Select applicant"
                value={selectedAssignee}
                onValueChange={(value) => onAssigneeChange(segment.start, value)}
                options={assignToOptions}
                error={hasAssigneeError}
                errorMessage={hasAssigneeError ? "Select an applicant" : undefined}
              />
            )}
          </div>
        )}

        {segmentPages.map((page, pageIndex) => (
          <div key={page}>
            <SplitPageRow page={page} isFocused={focusedPage === page} onFocus={onFocusPage} />
            {!isRemoved && pageIndex < segmentPages.length - 1 && (
              <SplitBetweenPagesButton afterPage={page} onAddCut={onAddCut} />
            )}
          </div>
        ))}
      </div>
    </div>
  );
};
