import { useMemo } from "react";

import { useParams } from "@huspy/fe";

import { useBankApplication, useDocumentExtractedFields, useEligibilityChecks } from "@/api";

import { getAdibHomeFinanceDocumentId, pickAdibApplicantContactFields } from "../utils";
import { getMainApplicant } from "../utils/applicantUtils";
import { useEmailTemplateDraft } from "./useEmailTemplateDraft";

export const useEmailTemplateTabRoute = () => {
  const { id: bankApplicationId } = useParams<{ id: string }>();
  const bankApplicationQuery = useBankApplication(bankApplicationId);
  const eligibilityChecksQuery = useEligibilityChecks(bankApplicationId);

  const adibFormDocumentId = getAdibHomeFinanceDocumentId(bankApplicationQuery.data);
  const adibFormFieldsQuery = useDocumentExtractedFields(adibFormDocumentId);
  const isAdibFormFieldsPending = !!adibFormDocumentId && adibFormFieldsQuery.isPending;

  const adibFormGroups = adibFormFieldsQuery.data?.groups;
  const passportName = bankApplicationQuery.data
    ? getMainApplicant(bankApplicationQuery.data.applicants)?.nameAsPerPassport
    : undefined;
  const adibApplicantContact = useMemo(
    () =>
      adibFormGroups ? pickAdibApplicantContactFields(adibFormGroups, passportName) : undefined,
    [adibFormGroups, passportName],
  );

  const isReadyForEmailGeneration =
    bankApplicationQuery.isSuccess &&
    bankApplicationQuery.data != null &&
    !eligibilityChecksQuery.isPending &&
    !isAdibFormFieldsPending;

  const emailTemplateDraft = useEmailTemplateDraft({
    bankApplicationId,
    bankApplication: bankApplicationQuery.data,
    eligibilityChecks: eligibilityChecksQuery.data,
    adibApplicantContact,
    isReadyForEmailGeneration,
  });

  return {
    isPendingBankApplication: bankApplicationQuery.isPending,
    isPendingEligibilityChecks: eligibilityChecksQuery.isPending,
    isErrorBankApplication: bankApplicationQuery.isError,
    ...emailTemplateDraft,
  };
};
