import { useEffect, useRef, useState, type FC } from "react";

import { copyToClipboard } from "@huspy/shared-lib";
import { Button } from "@huspy/shared-ui";

const COPIED_FEEDBACK_MS = 2_000;

type Props = {
  value: string;
  fieldLabel: string;
};

export const EmailTemplateCopyButton: FC<Props> = ({ value, fieldLabel }) => {
  const [copied, setCopied] = useState(false);
  const copiedTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(
    () => () => {
      if (copiedTimeoutRef.current) clearTimeout(copiedTimeoutRef.current);
    },
    [],
  );

  const handleCopy = async () => {
    if (!value) return;

    await copyToClipboard(value);
    setCopied(true);
    if (copiedTimeoutRef.current) clearTimeout(copiedTimeoutRef.current);
    copiedTimeoutRef.current = setTimeout(() => setCopied(false), COPIED_FEEDBACK_MS);
  };

  return (
    <Button
      type="button"
      variant="secondary"
      size="sm"
      className="min-w-16"
      aria-label={copied ? `${fieldLabel} copied` : `Copy ${fieldLabel}`}
      disabled={!value}
      onClick={() => void handleCopy()}
    >
      {copied ? "Copied" : "Copy"}
    </Button>
  );
};
