import { useEffect, useRef, useState, type ChangeEventHandler, type ReactNode } from "react";

import { FileArchive } from "@huspy/shared-icons";
import { cn } from "@huspy/shared-ui";

import { useUploadDocumentFile, type DocumentDetailResponse } from "@/api";
import {
  DocumentUploadDropzoneButton,
  DocumentUploadFileCard,
  DocumentUploadFileRow,
} from "../DocumentUpload";

import {
  getDocumentUploadErrorMessage,
  getOversizedFilesValidationMessage,
  partitionFilesByMaxSize,
} from "../utils";

type Props = {
  /** `accept` on the hidden file input */
  accept: string;
  /** Uploaded doc-service id, or null when empty */
  value: string | null;
  /** Called after doc-service upload succeeds */
  onUploaded: (doc: DocumentDetailResponse) => void;
  /** Called when the user removes the file or upload fails */
  onClear: () => void;
  /** e.g. clear react-hook-form field errors when picking or clearing a file */
  onClearValidation?: () => void;
  helperText?: string;
  uploadPrompt?: string;
  uploadingPrompt?: string;
  pickAriaLabel?: string;
  removeAriaLabel?: string;
  validationError?: string;
  className?: string;
  /** Icon beside the filename row (default: archive, e.g. for zip bundles) */
  uploadedLeadingIcon?: ReactNode;
  /** Disables picking / clearing (e.g. while parent mutation runs) */
  disabled?: boolean;
  /** Rejects files larger than this before upload (doc-service bulk limit). */
  maxFileSizeBytes?: number;
  /** Human-readable size for validation errors (e.g. "100 MB"). */
  maxFileSizeLabel?: string;
};

export function DocumentFileUploadDropzone({
  accept,
  value,
  onUploaded,
  onClear,
  onClearValidation,
  helperText,
  uploadPrompt = "Upload documents",
  uploadingPrompt = "Uploading…",
  pickAriaLabel,
  removeAriaLabel = "Remove uploaded file",
  validationError,
  className,
  uploadedLeadingIcon = (
    <FileArchive aria-hidden className="size-4 shrink-0 text-muted-foreground" strokeWidth={2} />
  ),
  disabled = false,
  maxFileSizeBytes,
  maxFileSizeLabel,
}: Props) {
  const uploadDocumentFile = useUploadDocumentFile();
  const inputRef = useRef<HTMLInputElement>(null);
  const prevValueRef = useRef<string | null>(null);
  const [displayFileName, setDisplayFileName] = useState<string | null>(null);
  const [clientValidationError, setClientValidationError] = useState<string | null>(null);

  useEffect(() => {
    const prev = prevValueRef.current;
    prevValueRef.current = value;

    /** Parent cleared `value` (e.g. form reset); reset mutation without redundant work on first paint. */
    if (!!prev && value === null) {
      uploadDocumentFile.reset();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps -- mutation identity omitted on purpose
  }, [value]);

  const handleFilesChange: ChangeEventHandler<HTMLInputElement> = (e) => {
    if (disabled) return;
    const file = e.target.files?.[0];
    e.target.value = "";
    if (!file) return;

    onClearValidation?.();
    uploadDocumentFile.reset();
    setClientValidationError(null);

    const { validFiles, oversizedCount } = partitionFilesByMaxSize([file], maxFileSizeBytes);
    const oversizedMessage = getOversizedFilesValidationMessage(oversizedCount, maxFileSizeLabel);
    if (oversizedMessage) {
      setClientValidationError(oversizedMessage);
      return;
    }

    const validFile = validFiles[0];
    if (!validFile) return;

    setDisplayFileName(validFile.name);
    uploadDocumentFile.mutate(validFile, {
      onSuccess: (doc) => {
        setDisplayFileName(doc.name);
        onUploaded(doc);
      },
      onError: () => {
        setDisplayFileName(null);
        onClear();
      },
    });
  };

  const handleClear = () => {
    if (disabled) return;
    onClearValidation?.();
    uploadDocumentFile.reset();
    setClientValidationError(null);
    setDisplayFileName(null);
    onClear();
    if (inputRef.current) inputRef.current.value = "";
  };

  const isUploading = uploadDocumentFile.isPending;
  const isInteractionDisabled = disabled || isUploading;
  const hasUploadedDocument = !!value;
  const isShowFileRow = hasUploadedDocument && !isUploading;
  const hasDropzoneError = !!(
    validationError ||
    clientValidationError ||
    uploadDocumentFile.isError
  );

  return (
    <div className={cn("space-y-2", className)}>
      <input
        ref={inputRef}
        type="file"
        accept={accept}
        disabled={disabled}
        className="sr-only"
        onChange={handleFilesChange}
        aria-hidden
      />

      {isShowFileRow ? (
        <DocumentUploadFileCard>
          <DocumentUploadFileRow
            leadingIcon={uploadedLeadingIcon}
            fileName={displayFileName ?? value ?? ""}
            onRemove={handleClear}
            removeAriaLabel={removeAriaLabel}
            removeDisabled={disabled}
          />
        </DocumentUploadFileCard>
      ) : (
        <DocumentUploadDropzoneButton
          onClick={() => inputRef.current?.click()}
          disabled={isInteractionDisabled}
          isUploading={isUploading}
          prompt={uploadPrompt}
          uploadingPrompt={uploadingPrompt}
          helperText={helperText}
          pickAriaLabel={pickAriaLabel}
          hasError={hasDropzoneError}
        />
      )}

      {!!validationError && (
        <p role="alert" className="text-sm text-destructive">
          {validationError}
        </p>
      )}

      {uploadDocumentFile.isError && (
        <p role="alert" className="text-sm text-destructive">
          {getDocumentUploadErrorMessage(uploadDocumentFile.error)}
        </p>
      )}

      {!!clientValidationError && (
        <p role="alert" className="text-sm text-destructive">
          {clientValidationError}
        </p>
      )}
    </div>
  );
}
