const PARENT_REFERENCE_SUFFIX = "_index";

/**
 * Backend naming convention: a `<singular>_index` column points at the `<singular>s` group,
 * so `statement_index` makes the group a child of `statements`.
 */
export const getParentGroupName = (fieldKey: string): string | null => {
  if (!fieldKey.endsWith(PARENT_REFERENCE_SUFFIX)) return null;

  const singular = fieldKey.slice(0, -PARENT_REFERENCE_SUFFIX.length);
  return singular.length > 0 ? `${singular}s` : null;
};
