import { useMemo, type FC } from "react";

import { RefreshCw } from "@huspy/shared-icons";
import { Button, toast } from "@huspy/shared-ui";

import { LoadErrorMessage } from "@/components";
import { RowActionButton } from "@/routes/BankApplication/components/ChecklistWorkspace/components/RowActionButton";
import { getEligibilityPatchErrorMessage, useCalculateEligibilityChecks } from "@/api";
import { useSessionStorage } from "@/hooks";
import { bankApplicationCardTitleClassName } from "@/routes/BankApplication/constants";

import { bankApplicationSessionStorageKeys, getMainApplicant } from "../../utils";
import { BankApplicationCard } from "../BankApplicationCard";
import { AffordabilitySummaryCard } from "./components/AffordabilitySummaryCard";
import { IncomeAndLiabilitiesCard } from "./components/IncomeAndLiabilitiesCard";
import { EligibilityChecksTabSkeleton } from "./EligibilityChecksTabSkeleton";
import { useEligibilityChecksRoute } from "./hooks/useEligibilityChecksRoute";

export const EligibilityChecksTab: FC = () => {
  const {
    bankApplicationId,
    bankApplication,
    currency,
    eligibilityChecks,
    eligibilityChecksError,
    isPendingEligibilityChecks,
    isErrorEligibilityChecks,
    isFetchingEligibilityChecks,
    refetchEligibilityChecks,
  } = useEligibilityChecksRoute();
  const calculateEligibilityChecks = useCalculateEligibilityChecks();

  const runCalculation = () => {
    if (!bankApplicationId) return;

    calculateEligibilityChecks.mutate(bankApplicationId, {
      onError: () => toast.error("Failed to calculate eligibility checks."),
    });
  };
  const [activeApplicantId, setActiveApplicantId] = useSessionStorage<string | null>(
    bankApplicationSessionStorageKeys.eligibilityChecksActiveApplicant(bankApplicationId ?? ""),
    null,
  );

  const activeApplicant = useMemo(() => {
    if (!eligibilityChecks?.applicants.length) return null;

    if (activeApplicantId) {
      const storedApplicant = eligibilityChecks.applicants.find(
        (applicant) => applicant.id === activeApplicantId,
      );
      if (storedApplicant) return storedApplicant;
    }

    const mainApplicant = getMainApplicant(
      eligibilityChecks.applicants.map((applicant) => ({
        id: applicant.id,
        fullName: applicant.name,
        role: applicant.role,
      })),
    );

    return (
      eligibilityChecks.applicants.find((applicant) => applicant.id === mainApplicant.id) ??
      eligibilityChecks.applicants[0]
    );
  }, [activeApplicantId, eligibilityChecks]);

  if (isPendingEligibilityChecks && !isErrorEligibilityChecks) {
    return <EligibilityChecksTabSkeleton />;
  }

  if (isErrorEligibilityChecks || !eligibilityChecks || !bankApplication || !currency) {
    const errorMessage = isErrorEligibilityChecks
      ? getEligibilityPatchErrorMessage(
          eligibilityChecksError,
          "Could not load eligibility checks.",
        )
      : "Could not load eligibility checks.";

    return (
      <BankApplicationCard>
        <div className="flex flex-col items-center gap-3">
          <LoadErrorMessage>{errorMessage}</LoadErrorMessage>
          {isErrorEligibilityChecks && (
            <RowActionButton
              label="Refresh"
              icon={RefreshCw}
              iconClassName={isFetchingEligibilityChecks ? "animate-spin" : undefined}
              onClick={() => void refetchEligibilityChecks()}
              disabled={isFetchingEligibilityChecks}
            />
          )}
        </div>
      </BankApplicationCard>
    );
  }

  if (eligibilityChecks.applicants.length === 0 || !activeApplicant) {
    return (
      <BankApplicationCard padding="empty">
        <p className={bankApplicationCardTitleClassName}>No eligibility data yet</p>
        <p className="max-w-100 text-xs text-muted-foreground">
          Calculate eligibility to derive income and liabilities from the attached documents.
        </p>
        <Button
          type="button"
          variant="secondary"
          size="sm"
          className="mt-1"
          onClick={runCalculation}
          disabled={calculateEligibilityChecks.isPending}
        >
          Calculate eligibility
        </Button>
      </BankApplicationCard>
    );
  }

  return (
    <div className="flex flex-col gap-5">
      <IncomeAndLiabilitiesCard
        applicants={eligibilityChecks.applicants}
        activeApplicant={activeApplicant}
        activeApplicantId={activeApplicant.id}
        onActiveApplicantIdChange={setActiveApplicantId}
      />
      <AffordabilitySummaryCard />
    </div>
  );
};
