import type { FC } from "react";

import { Modal, ModalFooter, PillButton } from "@/components";

type Props = {
  isOpen: boolean;
  onOpenChange: (open: boolean) => void;
  onConfirm: () => void;
};

export const ResetCalculationModal: FC<Props> = ({ isOpen, onOpenChange, onConfirm }) => (
  <Modal
    isOpen={isOpen}
    onOpenChange={onOpenChange}
    className="sm:max-w-md!"
    title="Reset calculation?"
    description={
      <span className="text-sm">
        This resets all values to their original state and removes any manually added incomes and
        liabilities.
      </span>
    }
  >
    <ModalFooter className="justify-between">
      <PillButton type="button" buttonRole="secondary" onClick={() => onOpenChange(false)}>
        Cancel
      </PillButton>
      <PillButton type="button" buttonRole="destructive" onClick={onConfirm}>
        Reset
      </PillButton>
    </ModalFooter>
  </Modal>
);
