import { useLayoutEffect, useRef, useState, type FC } from "react";

import { cn, Input, Tooltip, TooltipContent, TooltipTrigger } from "@huspy/shared-ui";

import { ELIGIBILITY_LINE_DESCRIPTION_MAX_LENGTH } from "../../constants";

type Props = {
  value: string;
  disabled: boolean;
  onCommit: (description: string) => void | Promise<void>;
};

const descriptionButtonClassName = "max-w-full truncate text-[13px] font-medium text-foreground";
const descriptionInputClassName =
  "h-7 w-full min-w-0 text-[13px] selection:bg-revert selection:text-revert";

/** Inline description editor for manual lines: click text to edit, commit on blur. */
export const DescriptionInput: FC<Props> = ({ value, disabled, onCommit }) => {
  const inputRef = useRef<HTMLInputElement>(null);
  const [isEditing, setIsEditing] = useState(false);
  const [draft, setDraft] = useState(value);
  const [prevValue, setPrevValue] = useState(value);

  if (value !== prevValue) {
    setPrevValue(value);
    setDraft(value);
    setIsEditing(false);
  }

  const beginEdit = () => {
    if (disabled) return;

    setDraft(value);
    setIsEditing(true);
  };

  const revertToSaved = () => {
    setDraft(value);
    setIsEditing(false);
  };

  useLayoutEffect(() => {
    if (!isEditing) return;

    inputRef.current?.focus();
  }, [isEditing]);

  const handleBlur = async () => {
    const trimmed = draft.trim();
    if (!trimmed || trimmed === value) {
      revertToSaved();
      return;
    }

    try {
      await onCommit(trimmed);
      setIsEditing(false);
    } catch {
      revertToSaved();
    }
  };

  if (!isEditing) {
    return (
      <Tooltip>
        <TooltipTrigger asChild>
          <button
            type="button"
            disabled={disabled}
            onClick={beginEdit}
            className={cn(
              descriptionButtonClassName,
              "h-7 w-fit cursor-pointer text-left disabled:cursor-not-allowed disabled:opacity-50",
            )}
          >
            {value}
          </button>
        </TooltipTrigger>
        <TooltipContent>Click to edit description</TooltipContent>
      </Tooltip>
    );
  }

  return (
    <Input
      ref={inputRef}
      value={draft}
      disabled={disabled}
      maxLength={ELIGIBILITY_LINE_DESCRIPTION_MAX_LENGTH}
      onChange={(event) => setDraft(event.target.value)}
      onBlur={() => {
        void handleBlur();
      }}
      onKeyDown={(event) => {
        if (event.key === "Enter") {
          event.currentTarget.blur();
        }
        if (event.key === "Escape") revertToSaved();
      }}
      className={descriptionInputClassName}
    />
  );
};
