import { cva, type VariantProps } from "class-variance-authority";
import * as React from "react";

import { cn } from "../../lib/utils";

const bannerVariants = cva(
  "relative flex w-full items-center rounded-xl px-3 py-3 text-sm leading-[1.4] font-normal",
  {
    variants: {
      variant: {
        alert: "bg-[#ed991726] text-[#ed9917]",
        error: "bg-[#f6445c26] text-[#f6445c]",
        success: "bg-[#10b18926] text-[#10b189]",
        information: "bg-[#0045C526] text-[#0045C5]",
      },
    },
    defaultVariants: {
      variant: "alert",
    },
  },
);

export type BannerVariant = NonNullable<VariantProps<typeof bannerVariants>["variant"]>;

type BannerProps = React.ComponentProps<"div"> &
  VariantProps<typeof bannerVariants> & {
    icon?: Exclude<React.ReactNode, boolean>;
  };

function Banner({ className, variant, icon, children, ...props }: BannerProps) {
  const hasIcon = icon != null;
  const iconNode = hasIcon ? (
    <span data-slot="banner-icon" className="mt-[1px] shrink-0 [&_svg]:size-4 [&_svg]:text-current">
      {icon}
    </span>
  ) : null;

  return (
    <div
      data-slot="banner"
      role="status"
      className={cn(bannerVariants({ variant }), hasIcon ? "gap-2" : "gap-0", className)}
      {...props}
    >
      {iconNode}
      <div data-slot="banner-content" className="min-w-0 flex-1">
        {children}
      </div>
    </div>
  );
}

export { Banner, bannerVariants };
