import { FC } from "react";

import { FileItemWithDocumentId } from "@/types";
import { bankApplicationCardTitleClassName } from "@/routes/BankApplication/constants";

import { BankApplicationCard } from "../../../BankApplicationCard";
import { NeedsAttentionFileRow } from "./NeedsAttentionFileRow";

type Props = {
  unclassifiedFiles: FileItemWithDocumentId[];
};

export const NeedsAttentionCard: FC<Props> = ({ unclassifiedFiles }) => {
  if (unclassifiedFiles.length === 0) return null;
  return (
    <BankApplicationCard>
      <div className="mb-4 flex items-center gap-2">
        <p className={bankApplicationCardTitleClassName}>Needs Attention</p>
        <span className="rounded-full bg-warning/14 px-2 py-0.5 text-[10px] font-semibold text-warning tabular-nums">
          {unclassifiedFiles.length}
        </span>
      </div>

      <div className="space-y-2">
        {unclassifiedFiles.map((file) => (
          <NeedsAttentionFileRow key={file.id} file={file} />
        ))}
      </div>
    </BankApplicationCard>
  );
};
