import type { Applicant, DocumentTypeCode } from "@/types";
import { isApplicantLevelDocumentType } from "@/routes/BankApplication/utils";

export const resolveApplicantIdForDocumentLink = (
  applicants: Applicant[],
  selectedApplicantId: string,
  selectedDocumentType: string,
  documentTypeCodes: DocumentTypeCode[],
): string | undefined => {
  if (!isApplicantLevelDocumentType(selectedDocumentType, documentTypeCodes)) {
    return undefined;
  }

  if (applicants.length === 1) {
    return applicants[0]?.id;
  }

  return selectedApplicantId || undefined;
};

type ResolveDocumentApplicantIdPayloadOptions = {
  applicants: Applicant[];
  selectedApplicantId: string;
  selectedDocumentType: string;
  documentTypeCodes: DocumentTypeCode[];
  /** When false, returns {} (edit document when assignment is unchanged). Defaults to true. */
  includeApplicantId?: boolean;
};

/** Resolves applicantId for link/update document API payloads. */
export const resolveDocumentApplicantIdPayload = ({
  applicants,
  selectedApplicantId,
  selectedDocumentType,
  documentTypeCodes,
  includeApplicantId = true,
}: ResolveDocumentApplicantIdPayloadOptions): { applicantId?: string | null } => {
  if (!includeApplicantId) {
    return {};
  }

  const resolvedApplicantId = resolveApplicantIdForDocumentLink(
    applicants,
    selectedApplicantId,
    selectedDocumentType,
    documentTypeCodes,
  );
  const isCaseLevelDocumentType = !isApplicantLevelDocumentType(
    selectedDocumentType,
    documentTypeCodes,
  );

  if (isCaseLevelDocumentType) {
    return { applicantId: null };
  }

  return resolvedApplicantId !== undefined ? { applicantId: resolvedApplicantId } : {};
};
