import { useCallback } from "react";

import { useLocation, useSearchParams } from "@huspy/fe";

import {
  BANK_APPLICATION_TABS,
  DEFAULT_BANK_APPLICATION_TAB,
  type BankApplicationTab,
} from "./constants";

const TAB_PARAM = "tab";

const isBankApplicationTab = (value: string | null): value is BankApplicationTab =>
  BANK_APPLICATION_TABS.some((tab) => tab === value);

/**
 * Mirrors the active tab into `?tab=`, keeping any other query params and the
 * `returnTo` location state that the Ops Queue back link relies on.
 */
export const useBankApplicationTab = (): [
  BankApplicationTab,
  (tab: BankApplicationTab) => void,
] => {
  const location = useLocation();
  const [searchParams, setSearchParams] = useSearchParams();

  const rawTab = searchParams.get(TAB_PARAM);
  const activeTab = isBankApplicationTab(rawTab) ? rawTab : DEFAULT_BANK_APPLICATION_TAB;

  const setActiveTab = useCallback(
    (tab: BankApplicationTab) => {
      setSearchParams(
        (prev) => {
          const next = new URLSearchParams(prev);
          if (tab === DEFAULT_BANK_APPLICATION_TAB) next.delete(TAB_PARAM);
          else next.set(TAB_PARAM, tab);
          return next;
        },
        { replace: true, state: location.state },
      );
    },
    [location.state, setSearchParams],
  );

  return [activeTab, setActiveTab];
};
