import {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
  type ComponentRef,
  type FC,
} from "react";
import { Document, Page, type PageProps } from "react-pdf";

import { cn } from "@huspy/shared-ui";
import { PdfPreviewZoomControls } from "@/routes/BankApplication/components/ChecklistWorkspace/components/PdfPreviewZoomControls";
import { PdfPreviewRotateControls } from "@/routes/BankApplication/components/ChecklistWorkspace/components/PdfPreviewRotateControls";
import {
  DEFAULT_ZOOM_LEVEL,
  DOCUMENT_PREVIEW_BASE_WIDTH,
  INITIAL_FOCUSED_PAGE,
  MAX_ZOOM_LEVEL,
  MIN_ZOOM_LEVEL,
  ZOOM_STEP,
} from "@/routes/BankApplication/components/ChecklistWorkspace/components/pdfPreviewConstants";
import { useKeyboardNavigation } from "@/routes/BankApplication/components/ChecklistWorkspace/hooks/useKeyboardNavigation";

import { DocumentPreviewThumbnailList } from "./DocumentPreviewThumbnailList";
import { combinePdfRotation, type PendingRotation } from "./utils";

type RotateControlsProps = {
  canSave: boolean;
  isSaving: boolean;
  onRotateLeft: () => void;
  onRotateRight: () => void;
  onResetRotation: () => void;
  onSave: () => void;
  disabled?: boolean;
  disabledTooltip?: string;
};

type Props = {
  previewUrl: string;
  rotation: PendingRotation;
  onPdfLoadingChange?: (isLoading: boolean) => void;
  rotateControls: RotateControlsProps;
};

export const PdfDocumentPreview: FC<Props> = ({
  previewUrl,
  rotation,
  onPdfLoadingChange,
  rotateControls,
}) => {
  const [pageCount, setPageCount] = useState(0);
  const [intrinsicRotate, setIntrinsicRotate] = useState<number | null>(null);
  const [isPdfLoading, setIsPdfLoading] = useState(false);
  const [isPdfError, setIsPdfError] = useState(false);
  const [focusedPage, setFocusedPage] = useState(INITIAL_FOCUSED_PAGE);
  const [zoomLevel, setZoomLevel] = useState(DEFAULT_ZOOM_LEVEL);
  const documentRef = useRef<ComponentRef<typeof Document>>(null);

  const pageRotate = useMemo(() => {
    if (intrinsicRotate === null) return undefined;
    return combinePdfRotation(intrinsicRotate, rotation);
  }, [intrinsicRotate, rotation]);

  const handlePageLoadSuccess: NonNullable<PageProps["onLoadSuccess"]> = useCallback((page) => {
    setIntrinsicRotate((current) => current ?? page.rotate);
  }, []);

  const pageNumbers = useMemo(
    () => Array.from({ length: pageCount }, (_, index) => index + 1),
    [pageCount],
  );
  const previewWidth = Math.round(DOCUMENT_PREVIEW_BASE_WIDTH * zoomLevel);
  const isZoomedIn = zoomLevel > DEFAULT_ZOOM_LEVEL;
  const isPdfReady = !isPdfLoading && !isPdfError && pageCount > 0;

  const scrollToPage = useCallback((pageNumber: number) => {
    documentRef.current?.viewer.current?.scrollPageIntoView({ pageNumber });
  }, []);

  const focusedPageRef = useRef(focusedPage);

  useEffect(() => {
    focusedPageRef.current = focusedPage;
  }, [focusedPage]);

  const handleZoomIn = useCallback(() => {
    setZoomLevel((currentZoom) => Math.min(currentZoom + ZOOM_STEP, MAX_ZOOM_LEVEL));
  }, []);

  const handleZoomOut = useCallback(() => {
    setZoomLevel((currentZoom) => Math.max(currentZoom - ZOOM_STEP, MIN_ZOOM_LEVEL));
  }, []);

  const handleZoomReset = useCallback(() => {
    setZoomLevel(DEFAULT_ZOOM_LEVEL);
  }, []);

  useEffect(() => {
    if (pageCount === 0) return;

    requestAnimationFrame(() => {
      scrollToPage(focusedPageRef.current);
    });
  }, [zoomLevel, pageCount, scrollToPage]);

  const handleFocusPage = useCallback(
    (pageNumber: number) => {
      setFocusedPage(pageNumber);
      scrollToPage(pageNumber);
    },
    [scrollToPage],
  );

  useKeyboardNavigation({
    isEnabled: isPdfReady,
    currentPage: focusedPage,
    maxPage: pageCount,
    onNavigate: handleFocusPage,
  });

  return (
    <Document
      ref={documentRef}
      file={previewUrl}
      className="flex min-h-0 flex-1 flex-col overflow-hidden"
      loading={null}
      onLoadStart={() => {
        setIsPdfLoading(true);
        setIsPdfError(false);
        setIntrinsicRotate(null);
      }}
      onLoadSuccess={({ numPages }) => {
        setPageCount(numPages);
        setIsPdfLoading(false);
        onPdfLoadingChange?.(false);
      }}
      onLoadError={() => {
        setIsPdfLoading(false);
        setIsPdfError(true);
        onPdfLoadingChange?.(false);
      }}
    >
      <div className="grid min-h-0 flex-1 grid-cols-1 overflow-hidden md:grid-cols-[minmax(0,1fr)_13rem]">
        <div className="relative flex min-h-0 flex-col overflow-hidden">
          {isPdfReady && (
            <PdfPreviewZoomControls
              className="absolute bottom-2 left-2 z-10"
              canZoomIn={zoomLevel < MAX_ZOOM_LEVEL}
              canZoomOut={zoomLevel > MIN_ZOOM_LEVEL}
              onZoomIn={handleZoomIn}
              onZoomOut={handleZoomOut}
              onReset={handleZoomReset}
            />
          )}

          {isPdfReady && (
            <PdfPreviewRotateControls
              className="absolute bottom-2 right-2 z-10"
              {...rotateControls}
            />
          )}

          <div
            className={cn(
              "flex min-h-0 flex-1 flex-col gap-4 py-4",
              isZoomedIn ? "overflow-auto" : "overflow-y-auto overflow-x-hidden",
            )}
          >
            {pageNumbers.map((pageNumber) => (
              <Page
                key={pageNumber}
                pageNumber={pageNumber}
                width={previewWidth}
                rotate={pageRotate}
                className="mx-auto scroll-mt-4"
                renderTextLayer={false}
                renderAnnotationLayer={false}
                onLoadSuccess={handlePageLoadSuccess}
                loading={null}
              />
            ))}
          </div>
        </div>

        <div className="flex items-center min-h-0 flex-col overflow-y-auto border-l border-border p-4">
          <DocumentPreviewThumbnailList
            pageCount={pageCount}
            isPdfError={isPdfError}
            focusedPage={focusedPage}
            pageRotate={pageRotate}
            onFocusPage={handleFocusPage}
          />
        </div>
      </div>
    </Document>
  );
};
