import type { UseFormClearErrors, UseFormSetValue } from "react-hook-form";

import type { PropertyStatus } from "@/types";
import type { GetBanksResponse, GetOpportunityResponse, OpportunityApplicant } from "@/api";

import type {
  CreateMortgageApplicationFormApplicant,
  CreateMortgageApplicationFormValues,
} from "@/routes/OpsQueue/components/CreateMortgageApplicationModal/CreateMortgageApplicationForm/types";

import { getAllowedPropertyStatuses } from "./getAllowedPropertyStatuses";
import { getSinglePropertyStatus } from "./getSinglePropertyStatus";
import { resolveMortgageTypeForBank } from "./resolveMortgageTypeForBank";
import { DEFAULT_TENOR_MONTHS, MAX_TENOR_MONTHS } from "../constants";

const normalizeBankName = (value: string) => value.trim().toLowerCase();

const toFormApplicant = (
  applicant: OpportunityApplicant,
): CreateMortgageApplicationFormApplicant => ({
  applicantRole: applicant.applicantRole,
  firstName: applicant.firstName,
  lastName: applicant.lastName,
  employmentType: applicant.employmentType,
  residencyType: applicant.residencyType,
  relationshipType: null,
});

export const applyGetOpportunityResponseToForm = (
  getOpportunityResponse: GetOpportunityResponse,
  getBanksResponse: GetBanksResponse,
  setValue: UseFormSetValue<CreateMortgageApplicationFormValues>,
  clearErrors: UseFormClearErrors<CreateMortgageApplicationFormValues>,
) => {
  clearErrors();

  const {
    opportunityDetails: salesForceDetails,
    applicant: salesForceApplicant,
    applicants: salesForceApplicants,
    banks: salesForceBanks,
  } = getOpportunityResponse;

  const { transactionType, propertyStatus: salesForcePropertyStatus } = salesForceDetails;
  setValue("opportunityDetails.transactionType", transactionType, {
    shouldDirty: true,
    shouldValidate: true,
  });
  setValue("opportunityDetails.propertyType", salesForceDetails.propertyType, {
    shouldDirty: true,
    shouldValidate: true,
  });
  let propertyStatus: PropertyStatus | null = null;
  if (transactionType) {
    const allowedPropertyStatuses = getAllowedPropertyStatuses(transactionType);
    propertyStatus =
      salesForcePropertyStatus && allowedPropertyStatuses.includes(salesForcePropertyStatus)
        ? salesForcePropertyStatus
        : getSinglePropertyStatus(transactionType);
  }
  setValue("opportunityDetails.propertyStatus", propertyStatus, {
    shouldDirty: true,
    shouldValidate: true,
  });
  setValue("opportunityDetails.loanAmount", salesForceDetails.loanAmount?.toString() ?? "", {
    shouldDirty: true,
    shouldValidate: true,
  });

  const applicants = salesForceApplicants?.length
    ? salesForceApplicants.map(toFormApplicant)
    : [
        {
          applicantRole: salesForceDetails.applicantRole,
          firstName: salesForceApplicant.firstName,
          lastName: salesForceApplicant.lastName,
          employmentType: salesForceApplicant.employmentType,
          residencyType: salesForceDetails.residencyType,
          relationshipType: null,
        },
      ];

  setValue("applicants", applicants, {
    shouldDirty: true,
    shouldValidate: true,
  });

  const { data: banksCatalog } = getBanksResponse;
  const banksValue: CreateMortgageApplicationFormValues["banks"] = salesForceBanks
    .map((salesForceBank) => {
      const matchedCatalogBank = banksCatalog.find(
        (catalogBank) =>
          normalizeBankName(catalogBank.name) === normalizeBankName(salesForceBank.name),
      );
      if (!matchedCatalogBank) return null;

      return {
        id: matchedCatalogBank.id,
        mortgageType: resolveMortgageTypeForBank(
          salesForceBank.mortgageType,
          matchedCatalogBank.supportedMortgageTypes,
        ),
        incomeVerificationType: null,
        tenorMonths:
          salesForceBank.tenorMonths != null
            ? String(Math.min(MAX_TENOR_MONTHS, salesForceBank.tenorMonths))
            : String(DEFAULT_TENOR_MONTHS),
      };
    })
    .filter((bank): bank is NonNullable<typeof bank> => bank !== null);

  setValue("banks", banksValue, { shouldDirty: true, shouldValidate: true });
};
