import type { EligibilityChecks } from "@/types";
import { formatMoneyAmount } from "@/utils";

import { getEffectiveTenorMonths } from "../../EligibilityChecksTab/utils";
import { resolveEmailTemplateCurrency } from "../utils/resolveEmailTemplateCurrency";

export const formatLoanTenorMonths = (eligibilityChecks: EligibilityChecks | undefined): string => {
  const tenor = eligibilityChecks?.summary.affordability?.tenor;
  if (!tenor) return "";

  return String(getEffectiveTenorMonths(tenor));
};

export const formatTotalIncome = (
  eligibilityChecks: EligibilityChecks | undefined,
  bankCurrency: string | null,
): string => {
  const currency = resolveEmailTemplateCurrency(bankCurrency, eligibilityChecks);
  const totalEarnings = eligibilityChecks?.summary.totalEarnings;

  return totalEarnings != null && currency != null
    ? formatMoneyAmount(totalEarnings, currency)
    : "";
};

export const formatEligibilityBlock = (
  eligibilityChecks: EligibilityChecks | undefined,
  bankCurrency: string | null,
): string =>
  [
    "Eligibility",
    `Income: ${formatTotalIncome(eligibilityChecks, bankCurrency)}`,
    "Liabilities: As per AECB",
  ].join("\n");
