import type { FC } from "react";

import { Modal, ModalFooter, PillButton } from "@/components";
import { useDocumentExtractedFields } from "@/api";
import type { FileItemWithDocumentId } from "@/types";

import { ExtractedFieldsForm, ExtractedFieldsStatusView } from "./components";
import { getExtractedFieldsViewState } from "./utils/getExtractedFieldsViewState";
type Props = {
  isOpen: boolean;
  onOpenChange: (open: boolean) => void;
  bankApplicationId: string;
  file: FileItemWithDocumentId | null;
};

export const ExtractedFieldsModal: FC<Props> = ({
  isOpen,
  onOpenChange,
  bankApplicationId,
  file,
}) => {
  const documentId = isOpen ? file?.documentId : undefined;
  const { data, isError } = useDocumentExtractedFields(documentId);

  const viewState = getExtractedFieldsViewState({
    data,
    isError,
  });
  const handleClose = () => onOpenChange(false);

  return (
    <Modal
      isOpen={isOpen}
      onOpenChange={onOpenChange}
      className="sm:max-w-4xl!"
      title="Extracted fields"
      description={file?.fileName}
    >
      {viewState.kind === "form" && !!documentId && (
        <ExtractedFieldsForm
          documentId={documentId}
          bankApplicationId={bankApplicationId}
          data={viewState.data}
          onClose={handleClose}
        />
      )}

      {viewState.kind !== "form" && (
        <>
          <ExtractedFieldsStatusView state={viewState} />

          <ModalFooter>
            <PillButton type="button" buttonRole="secondary" onClick={handleClose}>
              Close
            </PillButton>
          </ModalFooter>
        </>
      )}
    </Modal>
  );
};
