import { Check as CheckIcon } from "huspy-icons/react";
import * as React from "react";

import {
  cn,
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
  SelectItemIndicator,
  SelectItemText,
  SelectItemPrimitive,
} from "@huspy/shared-ui";

import { useFloatingLabelState, FloatingLabel, FieldError } from "../FloatingLabel";

type FloatingLabelSelectOption = {
  value: string;
  label: string;
  description?: string;
  disabled?: boolean;
};

type FloatingLabelSelectProps = {
  label: string;
  value: string;
  onValueChange: (value: string) => void;
  options: FloatingLabelSelectOption[];
  required?: boolean;
  placeholder?: string;
  /** Values that should render as empty (placeholder) rather than a selected floating label. */
  emptyValues?: string[];
  /**
   * Option to land on when `value` is empty and the menu opens.
   * The trigger stays empty until the user picks a value.
   */
  highlightedValue?: string;
  error?: boolean;
  errorMessage?: string;
  disabled?: boolean;
  className?: string;
  /** Applied to the dropdown panel, so callers can restyle its width, radius and padding. */
  contentClassName?: string;
  /** Applied to each option row. */
  itemClassName?: string;
};

function focusHighlightedOption(node: HTMLElement) {
  const viewport = node.closest<HTMLElement>("[data-radix-select-viewport]");
  if (viewport) {
    const nextScrollTop = node.offsetTop - viewport.clientHeight / 2 + node.offsetHeight / 2;
    viewport.scrollTop = Math.max(0, nextScrollTop);
  }
  node.focus({ preventScroll: true });
}

const FloatingLabelSelect = React.forwardRef<HTMLButtonElement, FloatingLabelSelectProps>(
  (
    {
      label,
      value,
      onValueChange,
      options,
      required,
      placeholder,
      emptyValues,
      highlightedValue,
      error,
      errorMessage,
      disabled,
      className,
      contentClassName,
      itemClassName,
    },
    ref,
  ) => {
    const isEmptyValue = value === "" || (emptyValues?.includes(value) ?? false);
    const { setIsFocused, hasValue, isFloating } = useFloatingLabelState({
      value: isEmptyValue ? "" : value,
    });
    const [isOpen, setIsOpen] = React.useState(false);
    const highlightedItemRef = React.useRef<HTMLDivElement>(null);
    const highlightCommitRef = React.useRef<string | null>(null);
    const selectValue = isEmptyValue ? (highlightedValue ?? "") : value;

    React.useEffect(() => {
      if (!isOpen || !isEmptyValue || !highlightedValue) return;
      const node = highlightedItemRef.current;
      if (!node) return;

      const frame = window.requestAnimationFrame(() => {
        focusHighlightedOption(node);
      });
      return () => window.cancelAnimationFrame(frame);
    }, [isOpen, isEmptyValue, highlightedValue]);

    const commitHighlight = (optionValue: string) => {
      if (!isEmptyValue || highlightedValue !== optionValue) return;
      if (highlightCommitRef.current === optionValue) return;
      highlightCommitRef.current = optionValue;
      onValueChange(optionValue);
    };

    const highlightItemProps = (optionValue: string) => {
      const isHighlight = isEmptyValue && highlightedValue === optionValue;
      if (!isHighlight) return {};

      return {
        ref: highlightedItemRef,
        className: "[&_svg]:hidden",
        onPointerUp: (event: React.PointerEvent) => {
          if (event.pointerType === "mouse") commitHighlight(optionValue);
        },
        onClick: () => commitHighlight(optionValue),
        onKeyDown: (event: React.KeyboardEvent) => {
          if (event.key === "Enter" || event.key === " ") commitHighlight(optionValue);
        },
      };
    };

    return (
      <div className="w-full">
        <div className="relative">
          <FloatingLabel
            label={label}
            required={required}
            isFloating={isFloating}
            error={error}
            variant="center"
            as="div"
          />

          {/* Select */}
          <Select
            value={selectValue}
            onValueChange={onValueChange}
            disabled={disabled || false}
            onOpenChange={(open) => {
              setIsFocused(open);
              setIsOpen(open);
              if (open) highlightCommitRef.current = null;
            }}
          >
            <SelectTrigger
              ref={ref}
              className={cn(
                "bg-muted relative !h-14 w-full cursor-pointer rounded-lg px-4 text-base font-medium transition-all duration-200",
                // !pt/!pb beat SelectTrigger's base `py-2` when another Tailwind
                // bundle loads later; items-end keeps the value under the label.
                hasValue ? "items-end !pt-6 !pb-2" : "py-2",
                "data-[state=open]:border-black",
                "[&_svg]:absolute [&_svg]:top-1/2 [&_svg]:right-3 [&_svg]:-translate-y-1/2",
                error ? "border-destructive" : "hover:border-muted-foreground/50",
                className,
              )}
            >
              {hasValue ? <SelectValue placeholder={placeholder} /> : <span />}
            </SelectTrigger>
            <SelectContent
              className={cn("max-w-[var(--radix-select-trigger-width)]", contentClassName)}
            >
              {options.map((option) => {
                const highlightProps = highlightItemProps(option.value);

                return option.description ? (
                  <SelectItemPrimitive
                    key={option.value}
                    value={option.value}
                    disabled={option.disabled}
                    ref={highlightProps.ref}
                    className={cn(
                      "focus:bg-accent focus:text-accent-foreground relative flex w-full cursor-pointer items-center gap-2 rounded-sm py-2.5 pr-8 pl-2 text-sm outline-hidden select-none data-[disabled]:pointer-events-none data-[disabled]:opacity-50",
                      itemClassName,
                      highlightProps.className,
                    )}
                    onPointerUp={highlightProps.onPointerUp}
                    onClick={highlightProps.onClick}
                    onKeyDown={highlightProps.onKeyDown}
                  >
                    <span className="absolute right-2 flex size-3.5 items-center justify-center">
                      <SelectItemIndicator>
                        <CheckIcon className="size-4" />
                      </SelectItemIndicator>
                    </span>
                    <div className="min-w-0 pr-2">
                      <SelectItemText>{option.label}</SelectItemText>
                      <p className="text-muted-foreground mt-0.5 text-xs font-normal text-wrap">
                        {option.description}
                      </p>
                    </div>
                  </SelectItemPrimitive>
                ) : (
                  <SelectItem
                    key={option.value}
                    value={option.value}
                    disabled={option.disabled}
                    ref={highlightProps.ref}
                    className={cn(itemClassName, highlightProps.className)}
                    onPointerUp={highlightProps.onPointerUp}
                    onClick={highlightProps.onClick}
                    onKeyDown={highlightProps.onKeyDown}
                  >
                    {option.label}
                  </SelectItem>
                );
              })}
            </SelectContent>
          </Select>
        </div>

        {errorMessage && <FieldError message={errorMessage} />}
      </div>
    );
  },
);

FloatingLabelSelect.displayName = "FloatingLabelSelect";

export { FloatingLabelSelect };
export type { FloatingLabelSelectProps, FloatingLabelSelectOption };
