import { sortDocumentTypeCodesByScope } from "@/api/utils";
import { DocumentTypeCode } from "@/types";

export type DocumentTypeSelectOption = { label: string; value: string };

/** Selectable document types for classification pickers, sorted by scope then label. */
export const getDocumentTypeSelectOptions = (
  documentTypeCodes: DocumentTypeCode[],
): DocumentTypeSelectOption[] =>
  sortDocumentTypeCodesByScope(documentTypeCodes).map(({ label, type }) => ({
    label,
    value: type,
  }));
