import { useParams } from "@huspy/fe";

import { useBankApplication, useEligibilityChecks } from "@/api";

export const useEligibilityChecksRoute = () => {
  const { id: bankApplicationId } = useParams<{ id: string }>();
  const { data: bankApplication } = useBankApplication(bankApplicationId);
  const eligibilityChecksQuery = useEligibilityChecks(bankApplicationId);
  const requestedLoan = eligibilityChecksQuery.data?.summary.affordability?.requestedLoan;

  return {
    bankApplicationId,
    bankApplication,
    currency: bankApplication?.currency ?? null,
    requestedAmount:
      requestedLoan?.overriddenRequestedLoanAmount ??
      requestedLoan?.requestedLoanAmount ??
      bankApplication?.amount ??
      null,
    eligibilityChecks: eligibilityChecksQuery.data,
    eligibilityChecksError: eligibilityChecksQuery.error,
    isPendingEligibilityChecks: eligibilityChecksQuery.isPending,
    isErrorEligibilityChecks: eligibilityChecksQuery.isError,
    isFetchingEligibilityChecks: eligibilityChecksQuery.isFetching,
    refetchEligibilityChecks: eligibilityChecksQuery.refetch,
  };
};
