import * as React from "react";

import { cn } from "@huspy/shared-ui";

import { useFloatingLabelState, FloatingLabel, FieldError, SupportingText } from "../FloatingLabel";

type FloatingLabelInputProps = {
  label: string;
  trailingText?: string;
  trailingIcon?: React.ReactNode;
  supportingText?: string;
  error?: boolean;
  errorMessage?: string;
} & Omit<React.InputHTMLAttributes<HTMLInputElement>, "placeholder">;

const FloatingLabelInput = React.forwardRef<HTMLInputElement, FloatingLabelInputProps>(
  (
    {
      className,
      type = "text",
      label,
      required,
      trailingText,
      trailingIcon,
      supportingText,
      error,
      errorMessage,
      value,
      ...props
    },
    ref,
  ) => {
    const { isFocused, setIsFocused, hasValue, isFloating } = useFloatingLabelState({ value });

    return (
      <div className="w-full">
        <div className="relative">
          <FloatingLabel
            label={label}
            required={required}
            isFloating={isFloating}
            error={error}
            variant="center"
          />

          {/* Input */}
          <input
            type={type}
            ref={ref}
            value={value}
            className={cn(
              "border-input bg-muted flex w-full rounded-xl border px-4 pt-6 pb-2 text-base font-medium transition-colors duration-200",
              "file:text-foreground file:border-0 file:bg-transparent file:text-sm file:font-medium",
              "shadow-none ring-0 ring-offset-0 outline-none",
              "focus:border-primary focus:shadow-none focus:ring-0 focus:ring-offset-0 focus:outline-none",
              "focus-visible:ring-0 focus-visible:ring-offset-0 focus-visible:outline-none",
              "disabled:cursor-not-allowed disabled:opacity-50",
              "h-16",
              trailingText && "pr-16",
              trailingIcon && "pr-12",
              error && "border-destructive",
              // Hide native date icon but keep it clickable
              type === "date" &&
                "[&::-webkit-calendar-picker-indicator]:absolute [&::-webkit-calendar-picker-indicator]:inset-0 [&::-webkit-calendar-picker-indicator]:h-full [&::-webkit-calendar-picker-indicator]:w-full [&::-webkit-calendar-picker-indicator]:cursor-pointer [&::-webkit-calendar-picker-indicator]:opacity-0",
              type === "date" &&
                !hasValue &&
                !isFocused &&
                "[color-scheme:light] [&::-webkit-datetime-edit]:text-transparent",
              // Hide number input spinner buttons
              type === "number" &&
                "[&::-moz-appearance:textfield] [&::-webkit-inner-spin-button]:hidden [&::-webkit-outer-spin-button]:hidden",
              className,
            )}
            {...props}
            onFocus={(e) => {
              setIsFocused(true);
              props.onFocus?.(e);
            }}
            onBlur={(e) => {
              setIsFocused(false);
              props.onBlur?.(e);
            }}
          />

          {/* Trailing Text */}
          {trailingText && (
            <span className="text-muted-foreground pointer-events-none absolute top-1/2 right-4 -translate-y-1/2">
              {trailingText}
            </span>
          )}

          {/* Trailing Icon */}
          {trailingIcon && !trailingText && (
            <span className="text-muted-foreground pointer-events-none absolute top-1/2 right-4 -translate-y-1/2">
              {trailingIcon}
            </span>
          )}
        </div>

        {supportingText && !errorMessage && <SupportingText text={supportingText} />}

        {errorMessage && <FieldError message={errorMessage} />}
      </div>
    );
  },
);
FloatingLabelInput.displayName = "FloatingLabelInput";
export { FloatingLabelInput };
export type { FloatingLabelInputProps };
