import type { Location } from "@huspy/fe";

import { ROUTE_BUILDERS } from "@/constants";

export type BankApplicationLocationState = {
  returnTo?: string;
};

export const buildReturnToPath = (location: Location): string =>
  location.pathname + location.search;

export const buildBankApplicationNavigationState = (
  location: Location,
): BankApplicationLocationState => ({
  returnTo: buildReturnToPath(location),
});

export const getReturnToPath = (location: Location): string => {
  const state = location.state as BankApplicationLocationState | null;
  return state?.returnTo ?? ROUTE_BUILDERS.toOpsQueue();
};
