import { formatDecimal } from "@huspy/shared-lib";

const MONEY_FORMAT_OPTIONS = {
  minimumFractionDigits: 2,
  maximumFractionDigits: 2,
} as const;

const WHOLE_MONEY_FORMAT_OPTIONS = {
  minimumFractionDigits: 0,
  maximumFractionDigits: 0,
} as const;

/** Formats a major-unit amount with currency prefix (AE locale). */
export const formatMoneyAmount = (amountMajor: number, currency: string): string =>
  `${currency} ${formatDecimal(amountMajor, "en-AE", MONEY_FORMAT_OPTIONS)}`;

/** Converts minor units to major and formats with currency prefix. */
export const formatMoneyAmountFromMinor = (amountMinor: number, currency: string): string =>
  formatMoneyAmount(Math.round(amountMinor / 100), currency);

/** Whole-unit variant: ops reads exact figures without trailing decimals. */
export const formatWholeMoneyAmountFromMinor = (amountMinor: number, currency: string): string =>
  `${currency} ${formatDecimal(Math.round(amountMinor / 100), "en-AE", WHOLE_MONEY_FORMAT_OPTIONS)}`;
