import { toMajorUnits } from "@/utils/minorUnits";
import type {
  Earning as EarningApi,
  EligibilityApplicant as EligibilityApplicantApi,
  EligibilitySummary as EligibilitySummaryApi,
  GetEligibilityChecksResponse,
  Liability as LiabilityApi,
} from "@/api/types";
import type {
  DocumentField,
  AffordabilityCalculationSummary,
  Earning,
  EligibilityApplicant,
  EligibilityChecks,
  EligibilityLineSource,
  Liability,
} from "@/types";

/** Manual lines sort after document-derived lines; remaining ties use document type then id. */
const sortEligibilityLines = <
  T extends { id: string; documentType: string; source: EligibilityLineSource },
>(
  items: T[],
): T[] =>
  [...items].sort((left, right) => {
    const leftIsManual = left.source === "MANUAL";
    const rightIsManual = right.source === "MANUAL";
    if (leftIsManual !== rightIsManual) return leftIsManual ? 1 : -1;

    const byDocumentType = left.documentType.localeCompare(right.documentType);
    if (byDocumentType !== 0) return byDocumentType;

    return left.id.localeCompare(right.id);
  });

const toAmountString = (amount: string | number): string =>
  typeof amount === "number" ? String(amount) : amount;

const toAmountOverride = (amountOverride: { value: number } | null | undefined): string | null =>
  amountOverride ? `${amountOverride.value}` : null;

const toFxRate = (fxRate: string | number | null | undefined): string | null =>
  fxRate == null ? null : toAmountString(fxRate);

type DocumentFieldApi = NonNullable<EarningApi["documentFields"]>[number];

const toDocumentField = (field: DocumentFieldApi): DocumentField => ({
  amount: field.amount,
  date: field.date,
});

export const toEligibilityChecks = (dto: GetEligibilityChecksResponse): EligibilityChecks => ({
  applicants: dto.applicants.map(toApplicant),
  summary: toSummary(dto.summary),
});

const toSummary = (summary: EligibilitySummaryApi): EligibilityChecks["summary"] => {
  const affordability = toAffordabilitySummary(summary);

  return {
    totalEarnings: summary.totalEarnings,
    totalLiabilities: summary.totalLiabilities,
    currency: summary.currency ?? null,
    dbr: summary.dbr,
    ...(affordability ? { affordability } : {}),
  };
};

const toNullableMajorUnits = (amountMinor: number | null): number | null =>
  amountMinor == null ? null : toMajorUnits(amountMinor);

const toAffordabilitySummary = (
  summary: EligibilitySummaryApi,
): AffordabilityCalculationSummary | undefined => {
  if (
    summary.maxDbrPercent == null ||
    summary.dbrWithinCap == null ||
    summary.effectiveTenorBoundBy == null ||
    summary.tenor == null ||
    summary.stressRate == null ||
    summary.emiCapacity == null ||
    summary.maxLoanAnnuity == null ||
    summary.centralBankCap == null ||
    summary.maxPermissibleLoan == null ||
    summary.affordable == null
  ) {
    return undefined;
  }

  return {
    maxDbrPercent: summary.maxDbrPercent,
    dbrWithinCap: summary.dbrWithinCap,
    effectiveTenorBoundBy: summary.effectiveTenorBoundBy,
    tenor: summary.tenor,
    ...(summary.effectiveTenorApplicant
      ? {
          effectiveTenorApplicant: {
            role: summary.effectiveTenorApplicant.role,
            currentAge: summary.effectiveTenorApplicant.currentAge,
          },
        }
      : {}),
    stressRate: summary.stressRate,
    ...(summary.requestedLoan
      ? {
          requestedLoan: {
            requestedLoanAmount: toNullableMajorUnits(summary.requestedLoan.requestedLoanAmount),
            overriddenRequestedLoanAmount: toNullableMajorUnits(
              summary.requestedLoan.overriddenRequestedLoanAmount,
            ),
          },
        }
      : {}),
    ...(summary.requestedLoanEmi != null ? { requestedLoanEmi: summary.requestedLoanEmi } : {}),
    ...(summary.newDbr != null ? { newDbr: summary.newDbr } : {}),
    ...(summary.newDbrWithinCap != null ? { newDbrWithinCap: summary.newDbrWithinCap } : {}),
    ...(summary.maxPermissibleLoanSource != null
      ? { maxPermissibleLoanSource: summary.maxPermissibleLoanSource }
      : {}),
    emiCapacity: summary.emiCapacity,
    maxLoanAnnuity: summary.maxLoanAnnuity,
    centralBankCap: summary.centralBankCap,
    maxPermissibleLoan: summary.maxPermissibleLoan,
    affordable: summary.affordable,
  };
};

const toApplicant = (applicant: EligibilityApplicantApi): EligibilityApplicant => ({
  id: applicant.id,
  name: applicant.name,
  role: applicant.role,
  earnings: sortEligibilityLines(applicant.earnings.map(toEarning)),
  liabilities: sortEligibilityLines(applicant.liabilities.map(toLiability)),
  totalEarnings: applicant.totalEarnings,
  totalLiabilities: applicant.totalLiabilities,
});

export const toEarning = (earning: EarningApi): Earning => ({
  id: earning.id,
  earningType: earning.earningType,
  amount: earning.amount,
  ...(earning.originalAmount ? { originalAmount: earning.originalAmount } : {}),
  fxRate: toFxRate(earning.fxRate),
  amountOverride: toAmountOverride(earning.amountOverride),
  eligibleAmount: earning.eligibleAmount,
  documentType: earning.documentType ?? "",
  allocation: earning.allocation,
  frequency: earning.frequency,
  description: earning.description,
  source: earning.source,
  numOfPayslips: earning.numOfPayslips ?? null,
  maxPeriods: earning.maxPeriods ?? null,
  documentFields: (earning.documentFields ?? []).map(toDocumentField),
});

export const toLiability = (liability: LiabilityApi): Liability => ({
  id: liability.id,
  liabilityType: liability.liabilityType,
  amount: liability.amount,
  ...(liability.originalAmount ? { originalAmount: liability.originalAmount } : {}),
  fxRate: toFxRate(liability.fxRate),
  amountOverride: toAmountOverride(liability.amountOverride),
  eligibleAmount: liability.eligibleAmount,
  documentType: liability.documentType ?? "",
  allocation: liability.allocation,
  frequency: liability.frequency,
  description: liability.description,
  source: liability.source,
  documentFields: (liability.documentFields ?? []).map(toDocumentField),
});
