import { useState } from "react";

import { FloatingLabelTextarea } from "@huspy/shared-agents";

import { Modal, ModalFooter, PillButton } from "@/components";

type SubmitCallbacks = {
  onSuccess: () => void;
  onError: (message: string) => void;
};

type Props = {
  isOpen: boolean;
  onOpenChange: (open: boolean) => void;
  /** Title of the check being waived; undefined while the modal is closing. */
  checkTitle?: string;
  isPending: boolean;
  /** Domain wrapper triggers its own waive mutation and reports the outcome via callbacks. */
  onSubmit: (reason: string, callbacks: SubmitCallbacks) => void;
  /** Called when the modal closes, so the wrapper can reset its mutation state. */
  onReset: () => void;
};

/** Headless waive-reason modal; domains wrap this with their own waive mutation. */
export function WaiveCheckModal({
  isOpen,
  onOpenChange,
  checkTitle,
  isPending,
  onSubmit,
  onReset,
}: Props) {
  const [reason, setReason] = useState("");
  const [submitError, setSubmitError] = useState<string | null>(null);

  const handleOpenChange = (open: boolean) => {
    if (!open) {
      setReason("");
      setSubmitError(null);
      onReset();
    }
    onOpenChange(open);
  };

  const handleWaive = () => {
    const trimmedReason = reason.trim();
    if (!trimmedReason) return;

    setSubmitError(null);

    onSubmit(trimmedReason, {
      onSuccess: () => handleOpenChange(false),
      onError: setSubmitError,
    });
  };

  return (
    <Modal
      isOpen={isOpen}
      onOpenChange={handleOpenChange}
      className="sm:max-w-md!"
      title="Waive check?"
      description={checkTitle}
    >
      <div className="min-h-0 flex-1 space-y-3 overflow-y-auto px-6 py-5">
        <FloatingLabelTextarea
          label="Reason for waiving this check"
          value={reason}
          onChange={(event) => setReason(event.target.value)}
          rows={3}
          disabled={isPending}
          maxLength={140}
        />

        {submitError && (
          <p role="alert" className="text-sm text-destructive">
            {submitError}
          </p>
        )}
      </div>

      <ModalFooter className="justify-between">
        <PillButton
          type="button"
          buttonRole="secondary"
          onClick={() => handleOpenChange(false)}
          disabled={isPending}
        >
          Cancel
        </PillButton>
        <PillButton type="button" onClick={handleWaive} disabled={!reason.trim() || isPending}>
          Waive check
        </PillButton>
      </ModalFooter>
    </Modal>
  );
}
