import type { FC } from "react";

import {
  cn,
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@huspy/shared-ui";

import { ghostSelectTriggerClassName } from "../../constants";

type Props = {
  value: string;
  options: string[];
  labels: Record<string, string>;
  disabled: boolean;
  onValueChange: (value: string) => void;
};

export const TypeSelect: FC<Props> = ({ value, options, labels, disabled, onValueChange }) => (
  <Select value={value} onValueChange={onValueChange} disabled={disabled}>
    <SelectTrigger size="sm" className={cn(ghostSelectTriggerClassName, "min-w-0")}>
      <SelectValue />
    </SelectTrigger>
    <SelectContent>
      {options.map((option) => (
        <SelectItem key={option} value={option} className="text-xs">
          {labels[option]}
        </SelectItem>
      ))}
    </SelectContent>
  </Select>
);
