import { useFormContext, useWatch } from "react-hook-form";

import { FloatingLabelInput, FloatingLabelSelect } from "@huspy/shared-agents";

import type { PropertyStatus, PropertyType, TransactionType } from "@/types";
import { TRANSACTION_TYPE_OPTIONS, PROPERTY_TYPE_OPTIONS } from "@/constants";
import { SectionHeader } from "@/routes/OpsQueue/components/CreateMortgageApplicationModal/CreateMortgageApplicationForm/components";
import { CreateMortgageApplicationFormValues } from "@/routes/OpsQueue/components/CreateMortgageApplicationModal/CreateMortgageApplicationForm/types";
import {
  getPropertyStatusOptionsForTransactionType,
  getSinglePropertyStatus,
} from "@/routes/OpsQueue/components/CreateMortgageApplicationModal/CreateMortgageApplicationForm/utils";

export function CaseDetailsSection() {
  const {
    control,
    setValue,
    clearErrors,
    formState: { errors },
  } = useFormContext<CreateMortgageApplicationFormValues>();

  const transactionType = useWatch({ control, name: "opportunityDetails.transactionType" });
  const transactionTypeError = errors.opportunityDetails?.transactionType;

  const propertyType = useWatch({ control, name: "opportunityDetails.propertyType" });
  const propertyTypeError = errors.opportunityDetails?.propertyType;

  const propertyStatus = useWatch({ control, name: "opportunityDetails.propertyStatus" });
  const propertyStatusError = errors.opportunityDetails?.propertyStatus;

  const loanAmount = useWatch({ control, name: "opportunityDetails.loanAmount" });
  const loanAmountError = errors.opportunityDetails?.loanAmount;
  return (
    <div>
      <SectionHeader title="Case Details" number={1} />
      <div className="grid grid-cols-2 gap-3">
        <FloatingLabelSelect
          label="Transaction type"
          options={TRANSACTION_TYPE_OPTIONS}
          value={transactionType ?? ""}
          onValueChange={(value) => {
            const nextTransactionType = value as TransactionType;
            clearErrors("opportunityDetails.transactionType");
            setValue("opportunityDetails.transactionType", nextTransactionType, {
              shouldDirty: true,
              shouldValidate: true,
            });
            clearErrors("opportunityDetails.propertyStatus");
            setValue(
              "opportunityDetails.propertyStatus",
              getSinglePropertyStatus(nextTransactionType),
              {
                shouldDirty: true,
                shouldValidate: true,
              },
            );
          }}
          error={!!transactionTypeError}
          errorMessage={transactionTypeError?.message}
        />
        <FloatingLabelSelect
          label="Property type"
          options={PROPERTY_TYPE_OPTIONS}
          value={propertyType ?? ""}
          onValueChange={(value) => {
            clearErrors("opportunityDetails.propertyType");
            setValue("opportunityDetails.propertyType", value as PropertyType, {
              shouldDirty: true,
              shouldValidate: true,
            });
          }}
          error={!!propertyTypeError}
          errorMessage={propertyTypeError?.message}
        />
        <FloatingLabelSelect
          key={transactionType ?? "no-transaction-type"}
          label="Property status"
          options={getPropertyStatusOptionsForTransactionType(transactionType)}
          value={propertyStatus ?? ""}
          onValueChange={(value) => {
            clearErrors("opportunityDetails.propertyStatus");
            setValue("opportunityDetails.propertyStatus", value as PropertyStatus, {
              shouldDirty: true,
              shouldValidate: true,
            });
          }}
          error={!!propertyStatusError}
          errorMessage={propertyStatusError?.message}
        />
        <FloatingLabelInput
          label="Loan amount"
          inputMode="numeric"
          trailingText="AED"
          className="h-14"
          value={loanAmount}
          onChange={(e) => {
            clearErrors("opportunityDetails.loanAmount");
            const nextValue = e.target.value.replace(/\D/g, "");
            setValue("opportunityDetails.loanAmount", nextValue, {
              shouldDirty: true,
              shouldValidate: true,
            });
          }}
          error={!!loanAmountError}
          errorMessage={loanAmountError?.message}
        />
      </div>
    </div>
  );
}
