import type { ProcessingStatus } from "@/types";
import { isProcessingInProgress } from "@/utils";

import { getProcessingInProgressMessage } from "./getProcessingInProgressMessage";

/**
 * Document-level actions gated by `processingStatus`.
 * `editDocumentType` covers the document-type field inside the edit modal only —
 * `editAssigneeOrName` covers the rest of that same modal (assignee, file name).
 */
export type DocumentAction =
  | "rotate"
  | "editDocumentType"
  | "editAssigneeOrName"
  | "split"
  | "reorder"
  | "extractedFields"
  | "remove";

/** Blocks edit (type/assignee/name), split, reorder, and remove alike. */
const EDIT_BLOCKING_STATUSES: readonly ProcessingStatus[] = [
  "CLASSIFICATION_IN_PROGRESS",
  "MERGE_IN_PROGRESS",
  "SPLIT_IN_PROGRESS",
  "ROTATION_IN_PROGRESS",
];

const EXTRACTED_FIELDS_BLOCKING_STATUSES: readonly ProcessingStatus[] = [
  "EXTRACTION_IN_PROGRESS",
  "SPLIT_IN_PROGRESS",
];

const ACTION_BLOCKING_STATUSES: Record<
  Exclude<DocumentAction, "rotate">,
  readonly ProcessingStatus[]
> = {
  editDocumentType: [...EDIT_BLOCKING_STATUSES, "EXTRACTION_IN_PROGRESS"],
  editAssigneeOrName: EDIT_BLOCKING_STATUSES,
  split: EDIT_BLOCKING_STATUSES,
  reorder: EDIT_BLOCKING_STATUSES,
  remove: EDIT_BLOCKING_STATUSES,
  extractedFields: EXTRACTED_FIELDS_BLOCKING_STATUSES,
};

export type ActionAvailability = { disabled: false } | { disabled: true; tooltip: string };

const DEFAULT_DISABLED_TOOLTIP = "Document is being processed";

/**
 * Whether `action` is available for a document/file currently in `processingStatus`.
 * `rotate` is blocked by any in-progress status; the rest follow the per-action matrix.
 */
export const getDocumentActionAvailability = (
  action: DocumentAction,
  processingStatus: ProcessingStatus | null | undefined,
): ActionAvailability => {
  if (!processingStatus) return { disabled: false };

  const isBlocked =
    action === "rotate"
      ? isProcessingInProgress(processingStatus)
      : ACTION_BLOCKING_STATUSES[action].includes(processingStatus);

  if (!isBlocked) return { disabled: false };

  return {
    disabled: true,
    tooltip: getProcessingInProgressMessage(processingStatus) ?? DEFAULT_DISABLED_TOOLTIP,
  };
};
