// shared-ui is bundled into the space and into every entity separately, so anything it
// keeps at module scope gets a private copy per bundle. Pinning the value on a global
// symbol makes the first bundle to load win and every other bundle reuse its instance.
const globalStore = globalThis as unknown as Record<symbol, unknown>;

export function globalSingleton<T>(key: string, create: () => T): T {
  const symbol = Symbol.for(`@huspy/shared-ui/${key}`);
  globalStore[symbol] ??= create();
  return globalStore[symbol] as T;
}
