import { useLayoutEffect, useRef, useState, type FC } from "react";

import { Check, X } from "@huspy/shared-icons";
import { cn, Input } from "@huspy/shared-ui";

import { RowActionButton } from "@/routes/BankApplication/components/ChecklistWorkspace/components/RowActionButton";

import {
  CALCULATION_ROW_GRID,
  CALCULATION_TABLE_ACTION_SLOT,
  CALCULATION_TABLE_ROW_GRID_CLASSNAME,
  CALCULATION_TABLE_ROW_SHELL,
  CALCULATION_TABLE_ROW_SURFACE_SHELL_CLASSNAME,
  calculationTableNumberInputNoSpinnerClassName,
  EARNING_TYPE_LABELS,
  ELIGIBILITY_LINE_DESCRIPTION_MAX_LENGTH,
  LINE_SOURCE_BADGE_CLASSNAME,
  MANUAL_LINE_SOURCE_LABEL,
} from "../../constants";
import { isMonthlyAmountDraft, parseAllocationPercent, parseMonthlyAmount } from "../../utils";
import { FrequencySelect } from "./FrequencySelect";
import { TypeSelect } from "./TypeSelect";

type Props = {
  currency: string;
  isPending: boolean;
  onSubmit: (fields: {
    description: string;
    amount: number;
    allocation: number;
  }) => void | Promise<void>;
  onCancel: () => void;
};

/** Inline row for creating a custom (manually added) earning or liability line. */
export const AddLineRow: FC<Props> = ({ currency, isPending, onSubmit, onCancel }) => {
  const descriptionInputRef = useRef<HTMLInputElement>(null);
  const [description, setDescription] = useState("");
  const [amountDraft, setAmountDraft] = useState("");
  const [allocationDraft, setAllocationDraft] = useState("100");
  const [error, setError] = useState<string | null>(null);

  useLayoutEffect(() => {
    descriptionInputRef.current?.focus();
  }, []);

  const handleSubmit = async () => {
    const trimmedDescription = description.trim();
    const amount = parseMonthlyAmount(amountDraft);
    const allocation = parseAllocationPercent(allocationDraft);

    if (!trimmedDescription) {
      setError("Description is required.");
      return;
    }

    if (amount === null) {
      setError("Enter a valid amount.");
      return;
    }

    if (allocation === null) {
      setError("Enter a valid allocation.");
      return;
    }

    setError(null);
    await onSubmit({ description: trimmedDescription, amount, allocation });
  };

  const handleKeyDown = (event: { key: string }) => {
    if (event.key === "Enter") void handleSubmit();
    if (event.key === "Escape") onCancel();
  };

  return (
    <div>
      <div className={CALCULATION_TABLE_ROW_SHELL}>
        <div className={CALCULATION_TABLE_ROW_SURFACE_SHELL_CLASSNAME}>
          <div className={cn(CALCULATION_TABLE_ROW_GRID_CLASSNAME, CALCULATION_ROW_GRID)}>
            <div className="flex min-w-0 items-center gap-2">
              <span className="size-5 shrink-0" aria-hidden />
              <div className="min-w-0 flex-1">
                <Input
                  ref={descriptionInputRef}
                  placeholder="Description"
                  value={description}
                  disabled={isPending}
                  maxLength={ELIGIBILITY_LINE_DESCRIPTION_MAX_LENGTH}
                  aria-invalid={!!error || undefined}
                  onChange={(event) => setDescription(event.target.value)}
                  onKeyDown={handleKeyDown}
                  className="h-7 w-full min-w-0 text-[13px] selection:bg-revert selection:text-revert"
                />
                <span className={LINE_SOURCE_BADGE_CLASSNAME}>{MANUAL_LINE_SOURCE_LABEL}</span>
              </div>
            </div>

            <TypeSelect
              value="OTHER"
              options={["OTHER"]}
              labels={EARNING_TYPE_LABELS}
              disabled
              onValueChange={() => {}}
            />
            <FrequencySelect value="MONTHLY" disabled onValueChange={() => {}} />

            <div className="flex items-center justify-center gap-1">
              <span className="text-xs text-muted-foreground">{currency}</span>
              <Input
                type="text"
                inputMode="decimal"
                placeholder="0.00"
                value={amountDraft}
                disabled={isPending}
                aria-invalid={!!error || undefined}
                onChange={(event) => {
                  if (!isMonthlyAmountDraft(event.target.value)) return;
                  setAmountDraft(event.target.value);
                }}
                onKeyDown={handleKeyDown}
                className="h-7 w-24 px-2 text-center text-[11px] tabular-nums selection:bg-revert selection:text-revert"
              />
            </div>

            <div className="flex items-center justify-center gap-1">
              <Input
                type="text"
                inputMode="numeric"
                value={allocationDraft}
                disabled={isPending}
                aria-invalid={!!error || undefined}
                onChange={(event) => {
                  const next = event.target.value;

                  if (next === "") {
                    setAllocationDraft("");
                    return;
                  }

                  if (!/^\d+$/.test(next)) return;

                  const parsed = Number.parseInt(next, 10);
                  if (parsed > 100) return;

                  setAllocationDraft(next);
                }}
                onKeyDown={(event) => {
                  if (["-", "+", "e", "E", "."].includes(event.key)) {
                    event.preventDefault();
                    return;
                  }

                  if (event.key === "Enter") void handleSubmit();
                  if (event.key === "Escape") onCancel();
                }}
                className={cn(
                  "ml-4 h-7 w-16 px-2 text-center text-[11px] tabular-nums selection:bg-revert selection:text-revert",
                  calculationTableNumberInputNoSpinnerClassName,
                )}
              />
              <span className="text-xs text-muted-foreground">%</span>
            </div>

            <div className="flex items-center justify-center gap-1">
              <RowActionButton
                label="Save"
                icon={Check}
                disabled={isPending}
                onClick={() => void handleSubmit()}
              />
              <RowActionButton label="Cancel" icon={X} disabled={isPending} onClick={onCancel} />
            </div>
          </div>

          {/* Spacer matching the remove button width on saved rows, so edges stay aligned. */}
          <span className={CALCULATION_TABLE_ACTION_SLOT} aria-hidden />
        </div>
      </div>

      {error && <p className="px-3 pt-1 text-xs text-destructive">{error}</p>}
    </div>
  );
};
