import { useState, type FC } from "react";

import { Input } from "@huspy/shared-ui";

import { isMonthlyAmountDraft, parseMonthlyAmount } from "../../utils";

type Props = {
  value: number;
  currency: string;
  disabled: boolean;
  onCommit: (requestedAmount: number) => void | Promise<void>;
};

export const RequestedAmountInput: FC<Props> = ({ value, currency, disabled, onCommit }) => {
  const [draft, setDraft] = useState(() => String(value));
  const [invalid, setInvalid] = useState(false);
  const [prevValue, setPrevValue] = useState(value);

  if (value !== prevValue) {
    setPrevValue(value);
    setDraft(String(value));
    setInvalid(false);
  }

  const revertToSaved = () => {
    setDraft(String(value));
    setInvalid(false);
  };

  const handleBlur = async () => {
    const parsed = parseMonthlyAmount(draft);
    if (parsed === null) {
      revertToSaved();
      setInvalid(draft.trim() !== "");
      return;
    }

    if (parsed === value) {
      revertToSaved();
      return;
    }

    setInvalid(false);
    setDraft(String(parsed));

    try {
      await onCommit(parsed);
    } catch {
      revertToSaved();
    }
  };

  return (
    <div className="flex items-center justify-end gap-1">
      <Input
        type="text"
        inputMode="decimal"
        value={draft}
        disabled={disabled}
        aria-label="Requested amount"
        aria-invalid={invalid || undefined}
        onChange={(event) => {
          const next = event.target.value;
          if (!isMonthlyAmountDraft(next)) return;

          setDraft(next);
          setInvalid(false);
        }}
        onBlur={() => {
          void handleBlur();
        }}
        onKeyDown={(event) => {
          if (["-", "+", "e", "E"].includes(event.key)) {
            event.preventDefault();
            return;
          }

          if (event.key === "Enter") {
            event.currentTarget.blur();
          }
        }}
        className="h-8 w-24 px-1.5 text-right text-sm font-semibold tabular-nums selection:bg-revert selection:text-revert"
      />
      <span className="text-xs text-muted-foreground">{currency}</span>
    </div>
  );
};
