import { DocumentTypeCode } from "@/types";

export const isApplicantLevelDocumentType = (
  documentType: string,
  documentTypeCodes: DocumentTypeCode[],
): boolean => {
  const documentTypeCode = documentTypeCodes.find(({ type }) => type === documentType);
  if (!documentTypeCode) {
    return true;
  }

  return documentTypeCode.level === "APPLICANT";
};

export const shouldShowAssignToSelect = (
  documentType: string,
  documentTypeCodes: DocumentTypeCode[],
  applicantCount?: number,
): boolean => {
  if (applicantCount !== undefined && applicantCount <= 1) {
    return false;
  }

  return isApplicantLevelDocumentType(documentType, documentTypeCodes);
};
