import { cn } from "@huspy/shared-ui";

type Props = {
  label: string;
  value: string;
  /** Grow weight and floor, sized to the longest label the field can hold. */
  className?: string;
};

export const Field = ({ label, value, className }: Props) => (
  <div className={cn("flex min-w-0 shrink flex-col gap-0.5", className)}>
    <span className="truncate text-[11px] text-muted-foreground">{label}</span>
    <span title={value} className="truncate text-[13px] font-medium tabular-nums text-foreground">
      {value}
    </span>
  </div>
);
