export const getDocumentUploadErrorMessage = (error: unknown): string => {
  return error instanceof Error ? error.message : "Upload failed. Try again.";
};

export const partitionFilesByMaxSize = (
  files: File[],
  maxFileSizeBytes?: number,
): { validFiles: File[]; oversizedCount: number } => {
  if (maxFileSizeBytes === undefined) {
    return { validFiles: files, oversizedCount: 0 };
  }

  const validFiles: File[] = [];
  let oversizedCount = 0;

  for (const file of files) {
    if (file.size > maxFileSizeBytes) {
      oversizedCount++;
    } else {
      validFiles.push(file);
    }
  }

  return { validFiles, oversizedCount };
};

export const getOversizedFilesValidationMessage = (
  oversizedCount: number,
  maxFileSizeLabel?: string,
): string | null => {
  if (oversizedCount === 0) return null;

  const limitLabel = maxFileSizeLabel ?? "maximum";
  return oversizedCount === 1
    ? `File exceeds the ${limitLabel} upload limit.`
    : `${oversizedCount} files exceed the ${limitLabel} upload limit.`;
};
