import type { FC } from "react";

import { cn } from "@huspy/shared-ui";
import { FloatingLabelInput, FloatingLabelSelect } from "@huspy/shared-agents";

import type { ExtractedFieldDataType } from "@/types";

import { getTextInputMode } from "../utils/getTextInputMode";

const BOOLEAN_OPTIONS = [
  { value: "true", label: "Yes" },
  { value: "false", label: "No" },
] as const;

/** Match FloatingLabelInput (h-16) — shared FloatingLabelSelect defaults to h-14. */
const SELECT_TRIGGER_CLASS_NAME = "!h-16 rounded-xl pt-6 pb-2";
const CHANGED_FIELD_CLASS_NAME = "border-warning focus:border-warning border-2";

type Props = {
  label: string;
  dataType: ExtractedFieldDataType;
  options: string[] | null;
  value: string;
  onChange: (value: string) => void;
  onValidate: (value: string) => void;
  disabled?: boolean;
  changed?: boolean;
  error?: boolean;
  errorMessage?: string;
};

export const ExtractedFieldInput: FC<Props> = ({
  label,
  dataType,
  options,
  value,
  onChange,
  onValidate,
  disabled = false,
  changed = false,
  error = false,
  errorMessage,
}) => {
  const handleSelectChange = (nextValue: string) => {
    onChange(nextValue);
    onValidate(nextValue);
  };

  const changedClassName = changed && !error ? CHANGED_FIELD_CLASS_NAME : undefined;

  if (dataType === "BOOLEAN") {
    return (
      <FloatingLabelSelect
        label={label}
        value={value}
        onValueChange={handleSelectChange}
        options={[...BOOLEAN_OPTIONS]}
        emptyValues={[""]}
        disabled={disabled}
        error={error}
        errorMessage={errorMessage}
        className={cn(SELECT_TRIGGER_CLASS_NAME, changedClassName)}
      />
    );
  }

  if (dataType === "ENUM") {
    if (!options?.length) {
      return (
        <FloatingLabelInput
          label={label}
          value={value}
          disabled
          error={error}
          errorMessage={errorMessage ?? "No options configured for this field."}
          className={changedClassName}
        />
      );
    }

    return (
      <FloatingLabelSelect
        label={label}
        value={value}
        onValueChange={handleSelectChange}
        options={options.map((option) => ({ value: option, label: option }))}
        emptyValues={[""]}
        disabled={disabled}
        error={error}
        errorMessage={errorMessage}
        className={cn(SELECT_TRIGGER_CLASS_NAME, changedClassName)}
      />
    );
  }

  return (
    <FloatingLabelInput
      label={label}
      type={dataType === "DATE" ? "date" : "text"}
      value={value}
      onChange={(event) => onChange(event.target.value)}
      onBlur={(event) => onValidate(event.currentTarget.value)}
      disabled={disabled}
      error={error}
      errorMessage={errorMessage}
      inputMode={getTextInputMode(dataType)}
      className={changedClassName}
    />
  );
};
