export const GMAIL_COMPOSE_CC = "ops@huspy.io";
export const GMAIL_COMPOSE_URL_MAX_LENGTH = 2000;

export const buildGmailComposeUrl = ({
  subject,
  body,
}: {
  subject: string;
  body: string;
}): string => {
  const params = new URLSearchParams({
    view: "cm",
    fs: "1",
    cc: GMAIL_COMPOSE_CC,
    su: subject,
    body,
  });

  return `https://mail.google.com/mail/?${params.toString()}`;
};
