import type { Option } from "@/types/option";

import {
  APPLICANT_ROLE_ORDER,
  APPLICANT_ROLE_TO_LABEL,
  EMPLOYMENT_TYPE_ORDER,
  EMPLOYMENT_TYPE_TO_LABEL,
  MORTGAGE_TYPE_ORDER,
  MORTGAGE_TYPE_TO_LABEL,
  PROPERTY_STATUS_ORDER,
  PROPERTY_STATUS_TO_LABEL,
  PROPERTY_TYPE_ORDER,
  PROPERTY_TYPE_TO_LABEL,
  RESIDENCY_TYPE_ORDER,
  RESIDENCY_TYPE_TO_LABEL,
  RELATIONSHIP_TYPE_ORDER,
  RELATIONSHIP_TYPE_TO_LABEL,
  TRANSACTION_TYPE_ORDER,
  TRANSACTION_TYPE_TO_LABEL,
  INCOME_VERIFICATION_TYPE_CREATE_FORM_TO_LABEL,
  INCOME_VERIFICATION_TYPE_ORDER,
  INCOME_VERIFICATION_TYPE_TO_LABEL,
} from "./labelMappings";

const toOptions = <const TValue extends string, const TLabelMap extends Record<TValue, string>>(
  order: readonly TValue[],
  labels: TLabelMap,
): Option<TValue, TLabelMap[TValue]>[] => order.map((value) => ({ value, label: labels[value] }));

export const RESIDENCY_TYPE_OPTIONS = toOptions(RESIDENCY_TYPE_ORDER, RESIDENCY_TYPE_TO_LABEL);

export const TRANSACTION_TYPE_OPTIONS = toOptions(
  TRANSACTION_TYPE_ORDER,
  TRANSACTION_TYPE_TO_LABEL,
);

export const PROPERTY_TYPE_OPTIONS = toOptions(PROPERTY_TYPE_ORDER, PROPERTY_TYPE_TO_LABEL);

export const PROPERTY_STATUS_OPTIONS = toOptions(PROPERTY_STATUS_ORDER, PROPERTY_STATUS_TO_LABEL);

export const MORTGAGE_TYPE_OPTIONS = toOptions(MORTGAGE_TYPE_ORDER, MORTGAGE_TYPE_TO_LABEL);

export const APPLICANT_ROLE_OPTIONS = toOptions(APPLICANT_ROLE_ORDER, APPLICANT_ROLE_TO_LABEL);

export const EMPLOYMENT_TYPE_OPTIONS = toOptions(EMPLOYMENT_TYPE_ORDER, EMPLOYMENT_TYPE_TO_LABEL);

export const RELATIONSHIP_TYPE_OPTIONS = toOptions(
  RELATIONSHIP_TYPE_ORDER,
  RELATIONSHIP_TYPE_TO_LABEL,
);

export const INCOME_VERIFICATION_TYPE_OPTIONS = toOptions(
  INCOME_VERIFICATION_TYPE_ORDER,
  INCOME_VERIFICATION_TYPE_TO_LABEL,
);

export const INCOME_VERIFICATION_TYPE_CREATE_FORM_OPTIONS = toOptions(
  INCOME_VERIFICATION_TYPE_ORDER,
  INCOME_VERIFICATION_TYPE_CREATE_FORM_TO_LABEL,
);
