/**
 * Copy text in a user gesture. Pass a Promise when the value is not ready yet
 * so Safari can keep the click activation (writeText after await is dropped).
 */
export async function copyToClipboard(text: string | Promise<string>): Promise<void> {
  if (typeof text === "string") {
    await navigator.clipboard.writeText(text);
    return;
  }

  const blobPromise = text.then((value) => new Blob([value], { type: "text/plain" }));
  void text.catch(() => undefined);
  void blobPromise.catch(() => undefined);

  if (typeof ClipboardItem === "undefined") {
    await navigator.clipboard.writeText(await text);
    return;
  }

  await navigator.clipboard.write([new ClipboardItem({ "text/plain": blobPromise })]);
  await text;
}
