import { type ChangeEventHandler, type ReactNode, useEffect, useRef, useState } from "react";

import { FileArchive } from "@huspy/shared-icons";
import { cn } from "@huspy/shared-ui";

import {
  DocumentUploadDropzoneButton,
  DocumentUploadFileCard,
  DocumentUploadFileRow,
  DocumentUploadPendingFileRow,
} from "../DocumentUpload";

import { UploadedDocumentFile } from "./types";
import { useUploadDocumentFiles } from "./useUploadDocumentFiles";
import { getOversizedFilesValidationMessage, partitionFilesByMaxSize } from "../utils";

type UploadedFileRowActions = {
  onRemove: () => void;
};

type Props = {
  accept: string;
  value: UploadedDocumentFile[];
  onUploaded: (file: UploadedDocumentFile) => void;
  onRemove: (documentId: string) => void;
  onUploadingChange?: (isUploading: boolean) => void;
  helperText?: string;
  uploadPrompt?: string;
  uploadingPrompt?: string;
  pickAriaLabel?: string;
  removeAriaLabel?: string;
  className?: string;
  uploadedLeadingIcon?: ReactNode;
  renderUploadedFile?: (file: UploadedDocumentFile, actions: UploadedFileRowActions) => ReactNode;
  disabled?: boolean;
  maxFileSizeBytes?: number;
  maxFileSizeLabel?: string;
};

export function DocumentMultiFileUploadDropzone({
  accept,
  value,
  onUploaded,
  onRemove,
  onUploadingChange,
  helperText,
  uploadPrompt = "Upload files",
  uploadingPrompt = "Uploading…",
  pickAriaLabel,
  removeAriaLabel = "Remove uploaded file",
  className,
  uploadedLeadingIcon = (
    <FileArchive aria-hidden className="size-4 shrink-0 text-muted-foreground" strokeWidth={2} />
  ),
  renderUploadedFile,
  disabled = false,
  maxFileSizeBytes,
  maxFileSizeLabel,
}: Props) {
  const inputRef = useRef<HTMLInputElement>(null);
  const { pendingUploads, uploadErrors, isUploading, uploadFiles, clearUploadErrors } =
    useUploadDocumentFiles();
  const [clientValidationError, setClientValidationError] = useState<string | null>(null);

  useEffect(() => {
    onUploadingChange?.(isUploading);
  }, [isUploading, onUploadingChange]);

  const handleFilesChange: ChangeEventHandler<HTMLInputElement> = (e) => {
    if (disabled) return;
    const files = Array.from(e.target.files ?? []);
    e.target.value = "";
    if (files.length === 0) return;

    setClientValidationError(null);
    clearUploadErrors();

    const { validFiles, oversizedCount } = partitionFilesByMaxSize(files, maxFileSizeBytes);
    const oversizedMessage = getOversizedFilesValidationMessage(oversizedCount, maxFileSizeLabel);
    if (oversizedMessage) {
      setClientValidationError(oversizedMessage);
    }

    if (validFiles.length === 0) return;

    uploadFiles(validFiles, onUploaded);
  };

  const handleRemoveUploaded = (documentId: string) => {
    if (disabled) return;
    onRemove(documentId);
  };

  const isInteractionDisabled = disabled;
  const hasFileRows = value.length > 0 || pendingUploads.length > 0;
  const hasDropzoneError = !!(clientValidationError || uploadErrors.length > 0);
  const dropzonePrompt = isUploading && !hasFileRows ? uploadingPrompt : uploadPrompt;

  return (
    <div className={cn("space-y-2", className)}>
      <input
        ref={inputRef}
        type="file"
        accept={accept}
        multiple
        disabled={disabled}
        className="sr-only"
        onChange={handleFilesChange}
        aria-hidden
      />

      {hasFileRows ? (
        <div className="space-y-1.5">
          {value.map((file) =>
            renderUploadedFile ? (
              <div key={file.documentId}>
                {renderUploadedFile(file, {
                  onRemove: () => handleRemoveUploaded(file.documentId),
                })}
              </div>
            ) : (
              <DocumentUploadFileCard key={file.documentId}>
                <DocumentUploadFileRow
                  leadingIcon={uploadedLeadingIcon}
                  fileName={file.fileName}
                  onRemove={() => handleRemoveUploaded(file.documentId)}
                  removeAriaLabel={removeAriaLabel}
                  removeDisabled={disabled}
                />
              </DocumentUploadFileCard>
            ),
          )}

          {pendingUploads.map((pending) => (
            <DocumentUploadPendingFileRow
              key={pending.clientId}
              fileName={pending.fileName}
              uploadingPrompt={uploadingPrompt}
            />
          ))}
        </div>
      ) : null}

      <DocumentUploadDropzoneButton
        onClick={() => inputRef.current?.click()}
        disabled={isInteractionDisabled}
        isUploading={isUploading && !hasFileRows}
        prompt={dropzonePrompt}
        uploadingPrompt={uploadingPrompt}
        helperText={helperText}
        pickAriaLabel={pickAriaLabel}
        hasError={hasDropzoneError}
      />

      {uploadErrors.map((error) => (
        <p key={error.id} role="alert" className="text-sm text-destructive">
          {error.message}
        </p>
      ))}

      {!!clientValidationError && (
        <p role="alert" className="text-sm text-destructive">
          {clientValidationError}
        </p>
      )}
    </div>
  );
}
