import type { UseFormClearErrors, UseFormSetError } from "react-hook-form";

import type { ApplicantRole } from "@/types";
import type { Bank } from "@/api";
import {
  MAX_ADDITIONAL_APPLICANTS,
  MAX_TENOR_MONTHS,
} from "@/routes/OpsQueue/components/CreateMortgageApplicationModal/CreateMortgageApplicationForm/constants";
import { getAdditionalApplicantCount } from "@/routes/OpsQueue/components/CreateMortgageApplicationModal/CreateMortgageApplicationForm/components/ApplicantsSection/utils";

import type {
  CreateMortgageApplicationFormIssue,
  CreateMortgageApplicationFormValues,
} from "@/routes/OpsQueue/components/CreateMortgageApplicationModal/CreateMortgageApplicationForm/types";

import { collectCrossFieldIssues } from "./crossFieldResolver";
import { isCreateCaseDocLevelRequired } from "./isCreateCaseDocLevelRequired";
import { normalizeCreateMortgageApplicationFormValues } from "./normalizeCreateMortgageApplicationFormValues";

const isCoApplicantRole = (applicantRole: ApplicantRole | null) =>
  applicantRole === "CO_APPLICANT" || applicantRole === "CO_BORROWER";

const collectRequiredFieldIssues = (
  values: CreateMortgageApplicationFormValues,
  isCreateCaseDocLevelEnabled: boolean,
): CreateMortgageApplicationFormIssue[] => {
  const { opportunityDetails, applicants, banks, documentId } =
    normalizeCreateMortgageApplicationFormValues(values);
  const issues: CreateMortgageApplicationFormIssue[] = [];

  if (!opportunityDetails.transactionType) {
    issues.push({
      name: "opportunityDetails.transactionType",
      message: "Select a transaction type",
    });
  }
  if (!opportunityDetails.propertyType) {
    issues.push({
      name: "opportunityDetails.propertyType",
      message: "Select a property type",
    });
  }
  if (!opportunityDetails.propertyStatus) {
    issues.push({
      name: "opportunityDetails.propertyStatus",
      message: "Select a property status",
    });
  }
  if (!opportunityDetails.loanAmount) {
    issues.push({
      name: "opportunityDetails.loanAmount",
      message: "Enter a loan amount",
    });
  }

  if (applicants.length === 0) {
    issues.push({ name: "applicants", message: "Add at least one applicant" });
  }

  if (getAdditionalApplicantCount(applicants) > MAX_ADDITIONAL_APPLICANTS) {
    issues.push({
      name: "applicants",
      message: `Maximum of ${MAX_ADDITIONAL_APPLICANTS} co-applicants`,
    });
  }

  applicants.forEach((applicant, idx) => {
    if (!applicant.applicantRole) {
      issues.push({
        name: `applicants.${idx}.applicantRole`,
        message: "Select an applicant role",
      });
    }

    if (!applicant.firstName) {
      issues.push({ name: `applicants.${idx}.firstName`, message: "Enter first name" });
    }

    if (!applicant.lastName) {
      issues.push({ name: `applicants.${idx}.lastName`, message: "Enter last name" });
    }

    if (!applicant.employmentType) {
      issues.push({
        name: `applicants.${idx}.employmentType`,
        message: "Select an employment type",
      });
    }

    if (!applicant.residencyType) {
      issues.push({
        name: `applicants.${idx}.residencyType`,
        message: "Select residency",
      });
    }

    if (isCoApplicantRole(applicant.applicantRole) && !applicant.relationshipType) {
      issues.push({
        name: `applicants.${idx}.relationshipType`,
        message: "Select a relationship",
      });
    }
  });

  if (banks.length === 0) {
    issues.push({ name: "banks", message: "Add at least one bank" });
  }

  banks.forEach((bank, idx) => {
    if (!bank.id) {
      issues.push({ name: `banks.${idx}.id`, message: "Select a bank" });
    }
    if (!bank.mortgageType) {
      issues.push({ name: `banks.${idx}.mortgageType`, message: "Select a mortgage type" });
    }
    if (!bank.tenorMonths || Number(bank.tenorMonths) <= 0) {
      issues.push({ name: `banks.${idx}.tenorMonths`, message: "Enter a tenor" });
    } else if (Number(bank.tenorMonths) > MAX_TENOR_MONTHS) {
      issues.push({
        name: `banks.${idx}.tenorMonths`,
        message: `Tenor cannot exceed ${MAX_TENOR_MONTHS} months`,
      });
    }

    if (
      isCreateCaseDocLevelRequired(applicants, isCreateCaseDocLevelEnabled) &&
      !bank.incomeVerificationType
    ) {
      issues.push({
        name: `banks.${idx}.incomeVerificationType`,
        message: "Select a doc level",
      });
    }
  });

  if (!documentId) {
    issues.push({ name: "documentId", message: "Upload a document package" });
  }

  return issues;
};

const collectCreateMortgageApplicationFormIssues = (
  values: CreateMortgageApplicationFormValues,
  bankCatalog: Bank[] = [],
  isCreateCaseDocLevelEnabled = false,
): CreateMortgageApplicationFormIssue[] => [
  ...collectRequiredFieldIssues(values, isCreateCaseDocLevelEnabled),
  ...collectCrossFieldIssues(values, bankCatalog, isCreateCaseDocLevelEnabled),
];

export const isCreateMortgageApplicationFormComplete = (
  values: CreateMortgageApplicationFormValues,
  banks: Bank[] = [],
  isCreateCaseDocLevelEnabled = false,
): boolean =>
  collectCreateMortgageApplicationFormIssues(values, banks, isCreateCaseDocLevelEnabled).length ===
  0;

export const validateCreateMortgageApplicationForm = (
  values: CreateMortgageApplicationFormValues,
  setError: UseFormSetError<CreateMortgageApplicationFormValues>,
  clearErrors: UseFormClearErrors<CreateMortgageApplicationFormValues>,
  banks: Bank[] = [],
  isCreateCaseDocLevelEnabled = false,
) => {
  clearErrors();

  const issues = collectCreateMortgageApplicationFormIssues(
    values,
    banks,
    isCreateCaseDocLevelEnabled,
  );

  for (const issue of issues) {
    setError(issue.name, { message: issue.message });
  }

  return issues.length === 0;
};
