import { ApiError } from "@/api/client";

type DocServiceErrorBody = {
  "doc-service"?: {
    code?: string;
    message?: string;
  };
};

export const getDocumentPreviewErrorMessage = (error: unknown): string => {
  if (error instanceof ApiError) {
    const data = error.data as DocServiceErrorBody | undefined;
    const docServiceError = data?.["doc-service"];

    if (docServiceError?.code === "DOCUMENT_NOT_UPLOADED") {
      return "This file isn't ready to preview yet. Try again in a moment.";
    }

    if (docServiceError?.message) {
      return docServiceError.message;
    }

    if (error.message) {
      return error.message;
    }
  }

  if (error instanceof Error) {
    return error.message;
  }

  return "Failed to load document preview.";
};
