export const formatPassportDisplayName = (name: string | null | undefined): string => {
  const trimmed = name?.trim();
  if (!trimmed) return "";

  return trimmed
    .split(/\s+/)
    .map((word) => {
      const lower = word.toLocaleLowerCase("en");
      return lower.charAt(0).toLocaleUpperCase("en") + lower.slice(1);
    })
    .join(" ");
};
