import { FC } from "react";

import type { BankApplication } from "@/types";
import { formatMoneyAmount } from "@/utils";

import {
  INCOME_VERIFICATION_TYPE_TO_LABEL,
  MORTGAGE_TYPE_TO_LABEL,
  PROPERTY_STATUS_TO_LABEL,
  PROPERTY_TYPE_TO_LABEL,
  TRANSACTION_TYPE_TO_LABEL,
} from "@/constants";

import { BankApplicationCard } from "../../BankApplicationCard";
import { Field } from "./Field";

type Props = {
  bankApplication: BankApplication;
};

export const CaseSummaryCard: FC<Props> = ({ bankApplication }) => {
  const {
    bank,
    type,
    amount,
    currency,
    transactionType,
    propertyType,
    propertyStatus,
    opportunityId,
    incomeVerificationType,
    applicants,
  } = bankApplication;

  const showDocLevel = applicants.some((applicant) => applicant.employmentType === "SELF_EMPLOYED");
  const docLevelLabel = incomeVerificationType
    ? INCOME_VERIFICATION_TYPE_TO_LABEL[incomeVerificationType]
    : "-";

  return (
    <BankApplicationCard padding="compact" className="flex flex-wrap gap-x-6 gap-y-3">
      <Field label="Bank" value={bank.name} className="min-w-27 flex-1" />
      <Field label="Opportunity" value={opportunityId ?? "-"} className="min-w-34 flex-[1.2]" />
      <Field
        label="Mortgage type"
        value={MORTGAGE_TYPE_TO_LABEL[type]}
        className="min-w-22 flex-[0.8]"
      />
      {showDocLevel ? (
        <Field label="Doc level" value={docLevelLabel} className="min-w-22 flex-[0.8]" />
      ) : null}
      {transactionType && (
        <Field
          label="Transaction type"
          value={TRANSACTION_TYPE_TO_LABEL[transactionType]}
          className="min-w-50 flex-[1.7]"
        />
      )}
      {propertyType && (
        <Field
          label="Property type"
          value={PROPERTY_TYPE_TO_LABEL[propertyType]}
          className="min-w-22 flex-[0.8]"
        />
      )}
      {propertyStatus && (
        <Field
          label="Property status"
          value={PROPERTY_STATUS_TO_LABEL[propertyStatus]}
          className="min-w-31 flex-1"
        />
      )}
      <Field
        label="Loan amount"
        value={amount !== null && currency ? formatMoneyAmount(amount, currency) : "-"}
        className="min-w-31 flex-[1.1]"
      />
    </BankApplicationCard>
  );
};
