import { useFormContext, useWatch } from "react-hook-form";

import { DocumentFileUploadDropzone } from "@/components";

import { CreateMortgageApplicationFormValues } from "@/routes/OpsQueue/components/CreateMortgageApplicationModal/CreateMortgageApplicationForm/types";
import { SectionHeader } from "@/routes/OpsQueue/components/CreateMortgageApplicationModal/CreateMortgageApplicationForm/components";

export function DocumentsSection() {
  const {
    control,
    setValue,
    clearErrors,
    formState: { errors },
  } = useFormContext<CreateMortgageApplicationFormValues>();

  const documentId = useWatch({ control, name: "documentId" });
  const documentIdError = errors.documentId;

  return (
    <div className="pt-5">
      <SectionHeader title="Documents" number={4} />
      <div className="mt-3">
        <DocumentFileUploadDropzone
          accept=".zip,application/zip"
          value={documentId}
          onUploaded={(doc) => {
            setValue("documentId", doc.documentId, {
              shouldDirty: true,
              shouldValidate: true,
            });
          }}
          onClear={() => {
            setValue("documentId", null, { shouldDirty: true, shouldValidate: true });
          }}
          onClearValidation={() => clearErrors("documentId")}
          validationError={documentIdError?.message}
          uploadPrompt="Upload files"
          helperText="Drop a .zip file here or click to browse"
          pickAriaLabel="Upload documents (.zip)"
        />
      </div>
    </div>
  );
}
