import type { DragEvent } from "react";

import type { ApplicantDocumentGroup, FileItemWithDocumentId } from "@/types";
import type { DocumentRename } from "@/utils/checklistFileReorder";
import { getReorderGroupKey } from "@/utils/checklistFileReorder";

import type { DropEdge } from "@/routes/BankApplication/components/ChecklistWorkspace/components/DocumentRow/types";

const ORDER_PREFIX_PATTERN = /^\d+_/;

export type { DocumentRename };

export const stripOrderPrefix = (fileName: string) => fileName.replace(ORDER_PREFIX_PATTERN, "");

/**
 * Zero-padded numeric prefixes make the backend's lexicographic filename sort reproduce
 * `files` order, which drives both the checklist display and the merged PDF page order (M2-160).
 * Returns only the renames that actually change a file name.
 */
export const computeOrderRenames = (
  files: FileItemWithDocumentId[],
  applicantId: string,
): DocumentRename[] => {
  const width = Math.max(2, String(files.length).length);
  return files
    .map((file, index) => ({
      documentId: file.id,
      fileName: `${String(index + 1).padStart(width, "0")}_${stripOrderPrefix(file.fileName)}`,
      previousFileName: file.fileName,
      applicantId,
    }))
    .filter(({ fileName }, index) => fileName !== files[index].fileName);
};

export type ReorderGroup = {
  files: FileItemWithDocumentId[];
  applicantId: string;
};

/** Sibling files that can be reordered against each other (same parent, type and applicant). */
export { getReorderGroupKey };

export const buildReorderGroups = (documents: ApplicantDocumentGroup[]) => {
  const groups = new Map<string, ReorderGroup>();

  for (const parent of documents) {
    for (const child of parent.documents) {
      if (!child.matchedFile) continue;
      const key = getReorderGroupKey(parent.type, child);
      const group = groups.get(key) ?? { files: [], applicantId: child.applicant.id };
      // Parents with several matched files repeat the same children; count each file once.
      if (!group.files.some((file) => file.id === child.matchedFile!.id)) {
        group.files.push(child.matchedFile);
      }
      groups.set(key, group);
    }
  }

  return groups;
};

export const getDropEdge = (e: DragEvent<HTMLDivElement>): DropEdge => {
  const rect = e.currentTarget.getBoundingClientRect();
  return e.clientY < rect.top + rect.height / 2 ? "before" : "after";
};

/**
 * Returns the insertion index after removing the dragged item, or null when the drop is a no-op.
 */
export const computeInsertionIndex = (
  fromIndex: number,
  targetIndex: number,
  dropEdge: DropEdge | undefined,
  isTargetDrop: boolean,
): number | null => {
  let toIndex = isTargetDrop && dropEdge === "after" ? targetIndex + 1 : targetIndex;
  if (fromIndex < toIndex) toIndex -= 1;
  if (fromIndex === toIndex) return null;
  return toIndex;
};

export const reorderFileList = <T>(files: T[], fromIndex: number, toIndex: number): T[] => {
  const reordered = [...files];
  const [moved] = reordered.splice(fromIndex, 1);
  reordered.splice(toIndex, 0, moved);
  return reordered;
};

/**
 * Identifies a checklist group among its siblings. `groupKey` tells apart groups of one type
 * that have no merged file yet (several unmerged bank statement groups, say).
 */
export const getDocumentGroupKey = (scope: string, group: ApplicantDocumentGroup) =>
  `${scope}-${group.type}-${group.groupKey ?? "ungrouped"}-${group.matchedFile?.id ?? "unmerged"}`;

/**
 * Makes sibling React keys unique by suffixing repeats with `#n`. With duplicate keys React can
 * keep the DOM of a row it no longer updates, which shows up as a stuck loader.
 */
export const getUniqueKeys = <T>(items: T[], getKey: (item: T) => string): string[] => {
  const seen = new Map<string, number>();

  return items.map((item) => {
    const key = getKey(item);
    const repeats = seen.get(key) ?? 0;
    seen.set(key, repeats + 1);
    return repeats === 0 ? key : `${key}#${repeats}`;
  });
};
