import type { CreateMortgageApplicationFormValues } from "@/routes/OpsQueue/components/CreateMortgageApplicationModal/CreateMortgageApplicationForm/types";

export const normalizeCreateMortgageApplicationFormValues = (
  values: CreateMortgageApplicationFormValues,
): CreateMortgageApplicationFormValues => {
  return {
    ...values,
    opportunityDetails: {
      ...values.opportunityDetails,
      loanAmount: values.opportunityDetails.loanAmount.trim(),
    },
    applicants: values.applicants.map((applicant) => ({
      ...applicant,
      firstName: applicant.firstName.trim(),
      lastName: applicant.lastName.trim(),
    })),
  };
};
