import { ProcessingStatus } from "@/types";

export const isProcessingInProgress = (
  processingStatus: ProcessingStatus | null | undefined,
): boolean => {
  if (!processingStatus) return false;
  return processingStatus.endsWith("_IN_PROGRESS");
};

export const isProcessingFailed = (
  processingStatus: ProcessingStatus | null | undefined,
): boolean => {
  if (!processingStatus) return false;
  return processingStatus.endsWith("_FAILED");
};
