const DATE_ONLY_PATTERN = /^\d{4}-\d{2}-\d{2}$/;

export const isDateOnlyValue = (value: string): boolean => DATE_ONLY_PATTERN.test(value);

export const toCreatedAtFromIso = (date: string): string => `${date}T00:00:00.000Z`;

export const toCreatedAtToIso = (date: string): string => `${date}T23:59:59.999Z`;

export const toCreatedAtFromApiParam = (value: string | undefined): string | undefined => {
  const trimmed = value?.trim();
  if (!trimmed || !isDateOnlyValue(trimmed)) return undefined;

  return toCreatedAtFromIso(trimmed);
};

export const toCreatedAtToApiParam = (value: string | undefined): string | undefined => {
  const trimmed = value?.trim();
  if (!trimmed || !isDateOnlyValue(trimmed)) return undefined;

  return toCreatedAtToIso(trimmed);
};
