import { createContext, type FC, type ReactNode, useContext } from "react";

import type { ExtractedFieldsFieldBindings } from "../types";

const ExtractedFieldsFieldContext = createContext<ExtractedFieldsFieldBindings | null>(null);

type ProviderProps = {
  children: ReactNode;
  value: ExtractedFieldsFieldBindings;
};

export const ExtractedFieldsFieldProvider: FC<ProviderProps> = ({ children, value }) => (
  <ExtractedFieldsFieldContext.Provider value={value}>
    {children}
  </ExtractedFieldsFieldContext.Provider>
);

export const useExtractedFieldsFieldBindings = (): ExtractedFieldsFieldBindings => {
  const context = useContext(ExtractedFieldsFieldContext);
  if (!context) {
    throw new Error(
      "useExtractedFieldsFieldBindings must be used within ExtractedFieldsFieldProvider",
    );
  }
  return context;
};
