import * as React from "react";

type FieldErrorProps = {
  message: string;
  id?: string;
};

export const FieldError: React.FC<FieldErrorProps> = ({ message, id }) => {
  return (
    <p id={id} className="text-destructive mt-1.5 px-1 text-sm" role="alert">
      {message}
    </p>
  );
};

type SupportingTextProps = {
  text: string;
};

export const SupportingText: React.FC<SupportingTextProps> = ({ text }) => {
  return <p className="text-muted-foreground mt-1.5 px-1 text-sm">{text}</p>;
};
