import type {
  ApplicantDocumentGroup,
  ApplicantDocumentRow,
  Checklist,
  DocumentChecklistRow,
} from "@/types";

export type ChecklistCounts = {
  mandatory: number;
  received: number;
  missing: number;
  optional: number;
};

type ChecklistLeaf = DocumentChecklistRow | ApplicantDocumentRow;

const EMPTY_COUNTS: ChecklistCounts = {
  mandatory: 0,
  received: 0,
  missing: 0,
  optional: 0,
};

const isApplicantLeaf = (leaf: ChecklistLeaf): leaf is ApplicantDocumentRow => "applicant" in leaf;

const toLeafKey = (groupType: string, leaf: ChecklistLeaf): string => {
  const applicantId = isApplicantLeaf(leaf) ? leaf.applicant.id : "";
  const fileId = leaf.matchedFile?.id ?? "missing";

  return `${applicantId}|${groupType}|${leaf.type}|${fileId}`;
};

const toGroupLeaf = (group: ApplicantDocumentGroup): ApplicantDocumentRow => {
  const { documents: _documents, ...leaf } = group;
  return leaf;
};

const getGroupLeaves = (group: ApplicantDocumentGroup): ApplicantDocumentRow[] =>
  group.documents.length > 0 ? group.documents : [toGroupLeaf(group)];

const collectApplicantLeaves = (groups: ApplicantDocumentGroup[]): ApplicantDocumentRow[] => {
  const leavesByKey = new Map<string, ApplicantDocumentRow>();

  for (const group of groups) {
    for (const leaf of getGroupLeaves(group)) {
      leavesByKey.set(toLeafKey(group.type, leaf), leaf);
    }
  }

  return Array.from(leavesByKey.values());
};

const countLeaves = (leaves: readonly ChecklistLeaf[]): ChecklistCounts =>
  leaves.reduce<ChecklistCounts>((counts, { isRequired, matchedFile }) => {
    const hasFile = matchedFile !== null;

    return {
      mandatory: counts.mandatory + (isRequired ? 1 : 0),
      received: counts.received + (isRequired && hasFile ? 1 : 0),
      missing: counts.missing + (isRequired && !hasFile ? 1 : 0),
      optional: counts.optional + (!isRequired && hasFile ? 1 : 0),
    };
  }, EMPTY_COUNTS);

export const getGroupCounts = (groups: ApplicantDocumentGroup[]): ChecklistCounts =>
  countLeaves(collectApplicantLeaves(groups));

export const getChecklistCounts = (checklist: Checklist): ChecklistCounts =>
  countLeaves([
    ...checklist.caseDocuments,
    ...collectApplicantLeaves(checklist.applicantDocuments),
  ]);
