import type { FC } from "react";

import { cn } from "@huspy/shared-ui";

import type { ExtractedFieldGroup, ExtractedFieldGroupRow } from "@/types";

import { useExtractedFieldsFieldBindings } from "../context/ExtractedFieldsFieldContext";
import {
  extractedFieldsGridClassName,
  extractedFieldsGridItemClassName,
} from "../utils/extractedFieldsGridClassName";
import { isJoinFieldKey } from "../utils/isJoinFieldKey";

import { ExtractedFieldInput } from "./ExtractedFieldInput";

type Props = {
  group: ExtractedFieldGroup;
  items?: ExtractedFieldGroupRow[];
  showJoinColumns?: boolean;
  showRowNumbers?: boolean;
  /** When true, row # uses 1-based position within `items` instead of global `item.index`. */
  useLocalRowNumbers?: boolean;
};

export const GroupTable: FC<Props> = ({
  group,
  items,
  showJoinColumns = false,
  showRowNumbers = true,
  useLocalRowNumbers = false,
}) => {
  const { draft, setFieldValue, validateField, fieldErrors, isSaving, isFieldChanged } =
    useExtractedFieldsFieldBindings();

  const columns = group.template.filter(
    (column) => showJoinColumns || !isJoinFieldKey(column.fieldKey),
  );
  const rows = items ?? group.items;

  if (columns.length === 0) return null;

  return (
    <div className="divide-y divide-border rounded-lg border border-border">
      {rows.map((item, rowIndex) => (
        <div key={item.index} className="flex items-center gap-4 p-4">
          {showRowNumbers && (
            <span className="w-6 shrink-0 text-center text-xs text-muted-foreground">
              {(useLocalRowNumbers ? rowIndex : item.index) + 1}
            </span>
          )}
          <div className={cn("min-w-0 flex-1", extractedFieldsGridClassName)}>
            {columns.map((column) => {
              const field = item.fields.find((entry) => entry.fieldKey === column.fieldKey);
              if (!field) return null;

              return (
                <div key={field.key} className={extractedFieldsGridItemClassName}>
                  <ExtractedFieldInput
                    label={column.label}
                    dataType={column.dataType}
                    options={column.options}
                    value={draft[field.key] ?? ""}
                    onChange={(value) => setFieldValue(field.key, value)}
                    onValidate={(value) => validateField(field.key, value)}
                    disabled={isSaving}
                    changed={isFieldChanged(field.key)}
                    error={!!fieldErrors[field.key]}
                    errorMessage={fieldErrors[field.key]}
                  />
                </div>
              );
            })}
          </div>
        </div>
      ))}
    </div>
  );
};
