import { useCallback, useMemo, useState } from "react";

import { segmentsFromCuts } from "@/routes/BankApplication/components/ChecklistWorkspace/components/SplitDocumentModal/utils";
import type { PageSegment } from "@/routes/BankApplication/components/ChecklistWorkspace/components/SplitDocumentModal/types";

type UseSplitStateResult = {
  cuts: Set<number>;
  segments: PageSegment[];
  removedStarts: Set<number>;
  addCut: (afterPage: number) => void;
  removeCut: (afterPage: number) => void;
  toggleSegmentRemoved: (startPage: number) => void;
  reset: () => void;
};

export const useSplitState = (pageCount: number): UseSplitStateResult => {
  const [cuts, setCuts] = useState<Set<number>>(() => new Set());
  const [removedStartsRaw, setRemovedStartsRaw] = useState<Set<number>>(() => new Set());

  const segments = useMemo(() => segmentsFromCuts(pageCount, cuts), [pageCount, cuts]);

  const removedStarts = useMemo(
    () =>
      new Set(
        segments.map((segment) => segment.start).filter((start) => removedStartsRaw.has(start)),
      ),
    [segments, removedStartsRaw],
  );

  const addCut = useCallback((afterPage: number) => {
    setCuts((prev) => new Set(prev).add(afterPage));
  }, []);

  const removeCut = useCallback((afterPage: number) => {
    setCuts((prev) => {
      const next = new Set(prev);
      next.delete(afterPage);
      return next;
    });
  }, []);

  const toggleSegmentRemoved = useCallback((startPage: number) => {
    setRemovedStartsRaw((prev) => {
      const next = new Set(prev);
      if (next.has(startPage)) {
        next.delete(startPage);
      } else {
        next.add(startPage);
      }
      return next;
    });
  }, []);

  const reset = useCallback(() => {
    setCuts(new Set());
    setRemovedStartsRaw(new Set());
  }, []);

  return { cuts, segments, removedStarts, addCut, removeCut, toggleSegmentRemoved, reset };
};
