import { useEffect } from "react";

import { useEventListener } from "@huspy/fe";

import { clearAllEmailTemplateDraftsFromSessionStorage } from "../utils";

export const useEmailTemplateDraftLogoutCleanup = (): void => {
  useEventListener("forcedLogout", clearAllEmailTemplateDraftsFromSessionStorage);

  useEffect(() => {
    const auth = window.huspy.auth;
    const originalLogout = auth.logout.bind(auth);

    auth.logout = () => {
      clearAllEmailTemplateDraftsFromSessionStorage();
      originalLogout();
    };

    return () => {
      auth.logout = originalLogout;
    };
  }, []);
};
