import { ApiError } from "@/api/client";

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === "object" && value !== null;

export const getEligibilityPatchErrorMessage = (error: unknown, fallback: string): string => {
  if (!(error instanceof ApiError)) {
    return error instanceof Error ? error.message : fallback;
  }

  if (error.status === 422 && isRecord(error.data) && Array.isArray(error.data.validationErrors)) {
    for (const item of error.data.validationErrors) {
      if (isRecord(item) && typeof item.message === "string" && item.message !== "") {
        return item.message;
      }
    }
  }

  if (error.message) return error.message;

  return fallback;
};
