import { api, ApiError } from "./client";
import type {
  DocumentBulkUploadPayload,
  DocumentBulkUploadResponse,
  DocumentDetailResponse,
  GenerateDocumentDownloadUrlResponse,
  GenerateDocumentPreviewUrlResponse,
  ZipJobResponse,
} from "./types";
import { createBankApplicationZipPackage } from "./requests";
import { sleep, getAxiosConfig, Options } from "./utils";

export const postDocumentsUploadBulk = async (
  body: DocumentBulkUploadPayload,
  options?: Options,
): Promise<DocumentBulkUploadResponse> => {
  const { data } = await api.post<DocumentBulkUploadResponse>(
    "/documents/upload/bulk",
    body,
    getAxiosConfig({
      baseURL: window.huspy?.services?.doc?.v1,
      ...options,
    }),
  );
  return data;
};

export const getDocument = async (
  documentId: string,
  options?: Options,
): Promise<DocumentDetailResponse> => {
  const { data } = await api.get<DocumentDetailResponse>(
    `/documents/${documentId}`,
    getAxiosConfig({
      baseURL: window.huspy?.services?.doc?.v1,
      ...options,
    }),
  );
  return data;
};

/** Upload bytes to the presigned URL (S3). Uses `fetch` so axios does not overwrite required headers. */
export const putFileToPresignedUrl = async (params: {
  uploadUrl: string;
  file: File;
  headers?: Record<string, string>;
  signal?: AbortSignal;
}): Promise<void> => {
  const { uploadUrl, file, headers, signal } = params;
  const res = await fetch(uploadUrl, {
    method: "PUT",
    body: file,
    headers: headers && Object.keys(headers).length > 0 ? headers : undefined,
    signal,
  });
  if (!res.ok) {
    throw new ApiError(`Could not upload file to storage (${res.status})`, res.status);
  }
};

const POLL_INTERVAL_MS = 1000;
const POLL_MAX_ATTEMPTS = 120;

export const waitForDocumentUploaded = async (
  documentId: string,
  options?: Options,
): Promise<DocumentDetailResponse> => {
  const signal = options?.signal;

  for (let i = 0; i < POLL_MAX_ATTEMPTS; i++) {
    if (signal?.aborted) throw new ApiError("Aborted");
    const doc = await getDocument(documentId, options);
    if (doc.isUploaded) return doc;
    await sleep(POLL_INTERVAL_MS, signal);
  }

  throw new ApiError("Timed out waiting for document upload to complete");
};

/**
 * Upload any file to doc-service: bulk presign → PUT to storage → poll until `isUploaded`.
 * Format-agnostic. UI layers choose accepted MIME types/extensions.
 */
export const uploadDocumentFile = async (params: {
  file: File;
  options?: Options;
}): Promise<DocumentDetailResponse> => {
  const { file, options } = params;

  const bulkUploadResponse = await postDocumentsUploadBulk(
    {
      files: [
        {
          name: file.name,
          sizeInBytes: file.size,
          isPublic: false,
          metadata: null,
          workflow: null,
        },
      ],
    },
    options,
  );

  const slot = bulkUploadResponse.files[0];

  if (!slot) {
    throw new ApiError("Bulk upload returned no file entries");
  }

  await putFileToPresignedUrl({
    uploadUrl: slot.uploadUrl,
    file,
    headers: slot.headers,
    signal: options?.signal,
  });

  return waitForDocumentUploaded(slot.documentId, options);
};

const isZipJobFailed = (status: string) => status.toUpperCase() === "FAILED";

const ZIP_JOB_SUCCESS_STATUSES = new Set(["COMPLETED", "SUCCESS", "SUCCEEDED", "READY"]);

const isZipJobSucceeded = (status: string) => ZIP_JOB_SUCCESS_STATUSES.has(status.toUpperCase());

export const getZipJob = async (zipId: string, options?: Options): Promise<ZipJobResponse> => {
  const { data } = await api.get<ZipJobResponse>(
    `/zips/${zipId}`,
    getAxiosConfig({
      baseURL: window.huspy?.services?.doc?.v1,
      ...options,
    }),
  );
  return data;
};

export const waitForZipJobCompleted = async (
  zipId: string,
  options?: Options,
): Promise<ZipJobResponse> => {
  const signal = options?.signal;

  for (let i = 0; i < POLL_MAX_ATTEMPTS; i++) {
    if (signal?.aborted) throw new ApiError("Aborted");
    const job = await getZipJob(zipId, options);
    if (isZipJobFailed(job.status)) {
      throw new ApiError(`Zip job failed (${job.status})`);
    }
    if (isZipJobSucceeded(job.status)) return job;
    await sleep(POLL_INTERVAL_MS, signal);
  }

  throw new ApiError("Timed out waiting for zip creation to finish");
};

