/**
 * Starts bank-application zip generation, polls doc service until the job completes,
 * then fetches a presigned download URL. Caller opens the URL in the UI when ready.
 */
export const prepareBankApplicationZipDownload = async (params: {
  bankApplicationId: string;
  options?: Options;
}): Promise<{ zipId: string; zipJob: ZipJobResponse; downloadUrl: string }> => {
  const { bankApplicationId, options } = params;

  const { zipId } = await createBankApplicationZipPackage(bankApplicationId, options);
  const zipJob = await waitForZipJobCompleted(zipId, options);
  await sleep(1000); // wait for download URL to be available. To be resolved by doc service.
  const { downloadUrl } = await generateDocumentDownloadUrl(zipJob.generatedDocumentId, options);
  return { zipId, zipJob, downloadUrl };
};
