import { ApplicantDocumentGroup } from "@/types";

export const getDocumentGroupsForApplicant = (
  applicantDocumentGroup: ApplicantDocumentGroup[],
  applicantId: string,
): ApplicantDocumentGroup[] =>
  applicantDocumentGroup.filter((group) =>
    group.applicant ? group.applicant.id === applicantId : true,
  );
