import type { ManualDocumentSplitPayload } from "@/api";
import type { Applicant, DocumentTypeCode } from "@/types";
import {
  resolveApplicantIdForDocumentLink,
  resolveDocumentApplicantIdPayload,
} from "@/routes/BankApplication/components/ChecklistWorkspace/utils";
import { shouldShowAssignToSelect } from "@/routes/BankApplication/utils";

import type { PageSegment } from "@/routes/BankApplication/components/ChecklistWorkspace/components/SplitDocumentModal/types";

import type {
  BuildManualDocumentSplitPayloadInput,
  SplitValidation,
  SplitValidationInput,
} from "./types";

/** Cuts are "a new document starts after page N". */
export const segmentsFromCuts = (pageCount: number, cuts: Set<number>): PageSegment[] => {
  if (pageCount < 1) return [];

  const sorted = Array.from(cuts)
    .filter((cut) => cut >= 1 && cut < pageCount)
    .sort((a, b) => a - b);

  const segments: PageSegment[] = [];
  let start = 1;

  for (const cut of sorted) {
    segments.push({ start, end: cut });
    start = cut + 1;
  }

  segments.push({ start, end: pageCount });
  return segments;
};

export const pagesInSegment = ({ start, end }: PageSegment): number[] =>
  Array.from({ length: end - start + 1 }, (_, index) => start + index);

export const formatPageRange = ({ start, end }: PageSegment): string =>
  start === end ? `Page ${start}` : `Pages ${start}–${end}`;

const segmentNeedsAssignee = (
  segment: PageSegment,
  typeFor: (startPage: number) => string,
  assigneeFor: (startPage: number) => string,
  applicants: Applicant[],
  documentTypeCodes: DocumentTypeCode[],
): boolean => {
  const documentType = typeFor(segment.start);
  if (!shouldShowAssignToSelect(documentType, documentTypeCodes, applicants.length)) {
    return false;
  }

  return !resolveApplicantIdForDocumentLink(
    applicants,
    assigneeFor(segment.start),
    documentType,
    documentTypeCodes,
  );
};

export const validateSplitConfiguration = ({
  isPdfReady,
  cutCount,
  segments,
  typeFor,
  assigneeFor,
  applicants,
  documentTypeCodes,
  removedStarts,
}: SplitValidationInput): SplitValidation => {
  if (!isPdfReady) {
    return { canConfirm: false, footerMessage: "" };
  }

  if (cutCount < 1) {
    return {
      canConfirm: false,
      footerMessage: "Split at least one page to create separate documents",
    };
  }

  const keptSegments = segments.filter((segment) => !removedStarts.has(segment.start));

  if (keptSegments.length < 1) {
    return {
      canConfirm: false,
      footerMessage: "Keep at least 1 document",
    };
  }

  const allTyped = keptSegments.every((segment) => !!typeFor(segment.start));

  if (!allTyped) {
    return {
      canConfirm: false,
      footerMessage: "Set a document type for each",
    };
  }

  const allAssigned = keptSegments.every(
    (segment) =>
      !segmentNeedsAssignee(segment, typeFor, assigneeFor, applicants, documentTypeCodes),
  );

  if (!allAssigned) {
    return {
      canConfirm: false,
      footerMessage: "Assign each applicant document to an applicant",
    };
  }

  const removedPageCount = segments
    .filter((segment) => removedStarts.has(segment.start))
    .reduce((total, segment) => total + segment.end - segment.start + 1, 0);

  return {
    canConfirm: true,
    footerMessage:
      `Will create ${keptSegments.length} ${keptSegments.length === 1 ? "document" : "documents"}` +
      (removedPageCount > 0
        ? `, discarding ${removedPageCount} ${removedPageCount === 1 ? "page" : "pages"}`
        : ""),
  };
};

export const buildManualDocumentSplitPayload = ({
  segments,
  typeFor,
  assigneeFor,
  applicants,
  documentTypeCodes,
  removedStarts,
}: BuildManualDocumentSplitPayloadInput): ManualDocumentSplitPayload => ({
  segments: segments
    .filter((segment) => !removedStarts.has(segment.start))
    .map((segment) => {
      const type = typeFor(segment.start);
      const { applicantId } = resolveDocumentApplicantIdPayload({
        applicants,
        selectedApplicantId: assigneeFor(segment.start),
        selectedDocumentType: type,
        documentTypeCodes,
      });

      return {
        startPage: segment.start,
        endPage: segment.end,
        type,
        ...(applicantId !== undefined ? { applicantId } : {}),
      };
    }),
});
