import type { MortgageType } from "@/types";

/**
 * Keeps the candidate type when the bank supports it, otherwise falls back to
 * the bank's only supported type so single-option banks fill themselves in.
 */
export const resolveMortgageTypeForBank = (
  candidate: MortgageType | null,
  supportedMortgageTypes: MortgageType[],
): MortgageType | null => {
  if (candidate && supportedMortgageTypes.includes(candidate)) return candidate;
  return supportedMortgageTypes.length === 1 ? supportedMortgageTypes[0] : null;
};
