import { FC, useLayoutEffect, useRef, useState } from "react";

import { ChevronRight, RefreshCw } from "@huspy/shared-icons";
import { Button, cn, toast } from "@huspy/shared-ui";

import { LoadErrorMessage, CustomSkeleton } from "@/components";
import { useBankPolicyChecks, useCalculateBankPolicyChecks } from "@/api";
import type { Applicant, BankPolicyCheck, CheckCategoryCode } from "@/types";
import { formatShortDateTime } from "@/utils";
import { useSessionStorage } from "@/hooks";
import { BankApplicationCard } from "@/routes/BankApplication/components/BankApplicationCard";
import { RowActionButton } from "@/routes/BankApplication/components/ChecklistWorkspace/components/RowActionButton";

import {
  CHECK_CATEGORY_LABELS,
  scrollElementToViewUnderSticky,
  SummaryBadges,
  useRuleCheckFilters,
  type RuleCheckGroup,
} from "../RuleChecksCard";
import { BankPolicyCheckRow } from "./BankPolicyCheckRow";
import { WaiveCheckModal } from "./WaiveCheckModal";
import { bankPolicySessionStorageKeys } from "./constants";

type BankPolicyCheckGroup = RuleCheckGroup<BankPolicyCheck>;

type Props = {
  bankApplicationId: string;
  applicants: Applicant[];
};

export const BankPolicyChecksCard: FC<Props> = ({ bankApplicationId, applicants }) => {
  const [waiveTarget, setWaiveTarget] = useState<BankPolicyCheck | null>(null);
  /** Explicit user toggles. Absent categories fall back to expanded. */
  const [expandedCategories, setExpandedCategories] = useSessionStorage<
    Partial<Record<CheckCategoryCode, boolean>>
  >(bankPolicySessionStorageKeys.expandedCategories(bankApplicationId), {});
  const groupRefs = useRef<Partial<Record<CheckCategoryCode, HTMLDivElement | null>>>({});
  const scrollToCategory = useRef<CheckCategoryCode | null>(null);
  const { data, isPending, isError } = useBankPolicyChecks(bankApplicationId);
  const calculateChecks = useCalculateBankPolicyChecks();

  const runChecks = () => {
    calculateChecks.mutate(bankApplicationId, {
      onError: () => toast.error("Failed to run bank policy checks."),
    });
  };

  const isCategoryExpanded = (group: BankPolicyCheckGroup) =>
    expandedCategories[group.category] ?? true;

  const toggleCategory = (group: BankPolicyCheckGroup) => {
    const willExpand = !isCategoryExpanded(group);
    if (willExpand) scrollToCategory.current = group.category;
    setExpandedCategories((prev) => ({ ...prev, [group.category]: willExpand }));
  };

  useLayoutEffect(() => {
    const category = scrollToCategory.current;
    if (!category) return;

    scrollToCategory.current = null;
    if (groupRefs.current[category]) scrollElementToViewUnderSticky(groupRefs.current[category]);
  }, [expandedCategories]);

  const checks = data?.checks ?? [];
  const { summary, activeFilters, groups, toggleFilter } = useRuleCheckFilters(checks);

  if (isPending) {
    return (
      <CustomSkeleton className="h-16.5 w-full rounded-2xl" aria-busy aria-label="Loading checks" />
    );
  }

  if (isError) {
    return (
      <BankApplicationCard>
        <LoadErrorMessage>Could not load bank policy checks.</LoadErrorMessage>
      </BankApplicationCard>
    );
  }

  if (checks.length === 0) {
    return (
      <BankApplicationCard padding="empty">
        <p className="text-sm font-semibold text-foreground">No policy results yet</p>
        <p className="max-w-100 text-xs text-muted-foreground">
          Run policy checks to see how this application compares to the bank&apos;s lending rules.
        </p>
        <Button
          type="button"
          variant="secondary"
          size="sm"
          className="mt-1"
          onClick={runChecks}
          disabled={calculateChecks.isPending}
        >
          Run policy checks
        </Button>
      </BankApplicationCard>
    );
  }

  return (
    <>
      <BankApplicationCard padding="none">
        <div className="flex w-full items-center justify-between gap-3 px-5 py-4.5">
          <SummaryBadges
            summary={summary}
            activeFilters={activeFilters}
            onToggleFilter={toggleFilter}
          />

          <div className="flex shrink-0 items-center gap-2">
            {data?.calculatedAt && (
              <p className="text-xs text-muted-foreground">
                Last run: {formatShortDateTime(data.calculatedAt)}
              </p>
            )}
            <RowActionButton
              label="Recalculate checks"
              icon={RefreshCw}
              iconClassName={calculateChecks.isPending ? "animate-spin" : undefined}
              onClick={runChecks}
              disabled={calculateChecks.isPending}
            />
          </div>
        </div>

        <div className="flex flex-col gap-4 px-5 pb-4.5">
          {groups.length === 0 && (
            <p className="text-xs text-muted-foreground">No checks match the selected filters.</p>
          )}
          {groups.map((group) => {
            const isGroupExpanded = isCategoryExpanded(group);

            return (
              <div
                key={group.category}
                ref={(node) => {
                  groupRefs.current[group.category] = node;
                }}
              >
                <button
                  type="button"
                  onClick={() => toggleCategory(group)}
                  aria-expanded={isGroupExpanded}
                  className="mb-2 flex w-full cursor-pointer items-center gap-1.5 text-left text-sm font-semibold text-muted-foreground hover:text-foreground"
                >
                  <ChevronRight
                    className={cn(
                      "size-3.5 shrink-0 transition-transform duration-160 ease-out",
                      isGroupExpanded && "rotate-90",
                    )}
                    aria-hidden
                  />
                  {CHECK_CATEGORY_LABELS[group.category]}
                </button>

                {isGroupExpanded && (
                  <div className="space-y-1">
                    {group.checks.map((check) => (
                      <BankPolicyCheckRow
                        key={check.id}
                        check={check}
                        applicants={applicants}
                        bankApplicationId={bankApplicationId}
                        onWaive={() => setWaiveTarget(check)}
                      />
                    ))}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      </BankApplicationCard>

      <WaiveCheckModal
        key={waiveTarget?.id ?? "idle"}
        isOpen={waiveTarget !== null}
        onOpenChange={(open) => {
          if (!open) setWaiveTarget(null);
        }}
        bankApplicationId={bankApplicationId}
        check={waiveTarget}
      />
    </>
  );
};
