import { api } from "./client";
import { GetBankApplicationsResponse, GetBankApplicationsParams } from "./types";
import { getAxiosConfig, Options, toCreatedAtFromApiParam, toCreatedAtToApiParam } from "./utils";

const getBffConfig = (options?: Options) =>
  getAxiosConfig({
    baseURL: window.huspy?.services?.bff?.v1,
    ...options,
  });

export const getCreditOpsBankApplications = async (
  {
    page,
    size,
    applicantName,
    bankId,
    createdAtFrom,
    createdAtTo,
    createdById,
  }: GetBankApplicationsParams,
  options?: Options,
): Promise<GetBankApplicationsResponse> => {
  const trimmedApplicantName = applicantName?.trim();
  const trimmedBankId = bankId?.trim();
  const trimmedCreatedById = createdById?.trim();
  const createdAtFromIso = toCreatedAtFromApiParam(createdAtFrom);
  const createdAtToIso = toCreatedAtToApiParam(createdAtTo);

  const { data } = await api.get<GetBankApplicationsResponse>("credit-ops/bank-applications", {
    ...getBffConfig(options),
    params: {
      page,
      size,
      ...(trimmedApplicantName ? { applicantName: trimmedApplicantName } : {}),
      ...(trimmedBankId ? { bankId: trimmedBankId } : {}),
      ...(createdAtFromIso ? { createdAtFrom: createdAtFromIso } : {}),
      ...(createdAtToIso ? { createdAtTo: createdAtToIso } : {}),
      ...(trimmedCreatedById ? { createdById: trimmedCreatedById } : {}),
    },
  });

  return data;
};
