import { EMPLOYMENT_TYPE_TO_LABEL, RESIDENCY_TYPE_TO_LABEL } from "@/constants";
import type { Applicant, EmploymentType, ResidencyType } from "@/types";

import { getApplicantsByRole, getMainApplicant } from "./applicantUtils";

const formatProfileSegment = (
  employmentType: EmploymentType | null | undefined,
  residencyType: ResidencyType | null | undefined,
): string => {
  const employment = employmentType ? EMPLOYMENT_TYPE_TO_LABEL[employmentType] : "";
  const residency = residencyType ? RESIDENCY_TYPE_TO_LABEL[residencyType] : "";
  return [employment, residency].filter(Boolean).join(" ");
};

const formatRoleProfileLine = (label: string, applicant: Applicant | undefined): string | null => {
  if (!applicant) return null;

  const segment = formatProfileSegment(applicant.employmentType, applicant.residencyType);
  return `${label} - ${segment}`;
};

export const formatMainApplicantArchetypeForSubject = (applicants: Applicant[]): string => {
  const main = getMainApplicant(applicants);
  if (!main) return "";

  return formatProfileSegment(main.employmentType, main.residencyType);
};

export const formatCustomerProfileLine = (applicants: Applicant[]): string => {
  const mainLine = formatRoleProfileLine("Main", getMainApplicant(applicants));
  const coBorrowers = getApplicantsByRole(applicants, "CO_BORROWER");
  const coBorrowerLine =
    coBorrowers.length > 0 ? formatRoleProfileLine("Co-borrower", coBorrowers[0]) : null;

  return [mainLine, coBorrowerLine].filter(Boolean).join(", ");
};
