import { api } from "./client";
import type { GetInternalUserResponse, GetInternalUsersResponse } from "./types";
import { getAxiosConfig, Options } from "./utils";

const getUserServiceConfig = (options?: Options) =>
  getAxiosConfig({
    baseURL: window.huspy?.services?.user?.v1,
    ...options,
  });

export const formatInternalUserDisplayName = (
  user: Pick<GetInternalUserResponse, "firstName" | "lastName">,
) => `${user.firstName} ${user.lastName}`.trim();

export const getInternalUsers = async (
  search: string,
  options?: Options,
): Promise<GetInternalUsersResponse> => {
  const { data } = await api.get<GetInternalUsersResponse>("backoffice/internal-users", {
    ...getUserServiceConfig(options),
    params: {
      fullName: search,
      page: 0,
      limit: 20,
      status: "APPROVED",
    },
  });

  return data;
};

export const getInternalUserById = async (
  id: string,
  options?: Options,
): Promise<GetInternalUserResponse> => {
  const { data } = await api.get<GetInternalUserResponse>(
    `backoffice/internal-users/${id}`,
    getUserServiceConfig(options),
  );

  return data;
};
