import type { FC } from "react";

import { useDocumentValidationChecks } from "@/api";

import { CheckTabBadge, summarizeChecks } from "../RuleChecksCard";

type Props = {
  bankApplicationId: string;
};

/** Unresolved-failure count for the Document Validation tab; renders nothing when everything is clear. */
export const DocumentValidationTabBadge: FC<Props> = ({ bankApplicationId }) => {
  const { data } = useDocumentValidationChecks(bankApplicationId);
  return <CheckTabBadge summary={summarizeChecks(data?.checks ?? [])} />;
};
