import { useEffect, useState } from "react";
import { useFormContext } from "react-hook-form";

import { FloatingLabelInput } from "@huspy/shared-agents";
import { Button, Card } from "@huspy/shared-ui";

import { useBanks, useOpportunity } from "@/api";
import type { CreateMortgageApplicationFormValues } from "@/routes/OpsQueue/components/CreateMortgageApplicationModal/CreateMortgageApplicationForm/types";
import { applyGetOpportunityResponseToForm } from "@/routes/OpsQueue/components/CreateMortgageApplicationModal/CreateMortgageApplicationForm/utils";

export function OpportunityLookupSection() {
  const { setValue, clearErrors } = useFormContext<CreateMortgageApplicationFormValues>();
  const [draftId, setDraftId] = useState("");
  const [lookupId, setLookupId] = useState("");
  const {
    data: opportunityData,
    dataUpdatedAt,
    isError,
    error,
    isFetching,
    refetch,
  } = useOpportunity(lookupId);
  const { data: banksData } = useBanks();
  const trimmedDraftId = draftId.trim();

  const handleLookup = () => {
    if (!trimmedDraftId) return;
    if (trimmedDraftId === lookupId) {
      void refetch();
      return;
    }
    setLookupId(trimmedDraftId);
  };

  useEffect(() => {
    if (!opportunityData || !banksData || !lookupId || !dataUpdatedAt) return;
    applyGetOpportunityResponseToForm(opportunityData, banksData, setValue, clearErrors);
    setValue("opportunityDetails.opportunityId", lookupId, { shouldDirty: true });
  }, [opportunityData, banksData, dataUpdatedAt, lookupId, setValue, clearErrors]);

  const lookupErrorMessage =
    isError && error instanceof Error
      ? error.message
      : isError
        ? "Could not load opportunity."
        : null;

  return (
    <Card className="border-border bg-muted/30 mb-4 gap-0 rounded-xl border shadow-none">
      <div className="flex items-end gap-2">
        <div className="min-w-0 flex-1">
          <FloatingLabelInput
            label="Opportunity / Case ID"
            autoComplete="off"
            value={draftId}
            onChange={(e) => setDraftId(e.target.value)}
            className="h-14 bg-background font-mono"
          />
        </div>
        <Button
          type="button"
          variant="outline"
          className="h-14 shrink-0 px-5 font-semibold"
          disabled={!trimmedDraftId || isFetching}
          onClick={handleLookup}
        >
          Lookup
        </Button>
      </div>

      {lookupErrorMessage && (
        <p role="alert" className="text-destructive mt-2 text-sm">
          {lookupErrorMessage}
        </p>
      )}

      <p className="text-muted-foreground mt-2 text-xs">
        Optional. Enter an opportunity ID and click Lookup to prefill the form.
      </p>
    </Card>
  );
}
