import { APPLICANT_ROLE_TO_LABEL } from "@/constants";
import type { ApplicantRole } from "@/types";
import { MAX_ADDITIONAL_APPLICANTS } from "@/routes/OpsQueue/components/CreateMortgageApplicationModal/CreateMortgageApplicationForm/constants";
import type { CreateMortgageApplicationFormApplicant } from "@/routes/OpsQueue/components/CreateMortgageApplicationModal/CreateMortgageApplicationForm/types";

export const getAdditionalApplicantLabel = (
  applicantRole: ApplicantRole | null,
  displayNumber: number,
) => {
  if (applicantRole === "CO_APPLICANT" || applicantRole === "CO_BORROWER") {
    return `${APPLICANT_ROLE_TO_LABEL[applicantRole]} ${displayNumber}`;
  }

  return `Additional applicant ${displayNumber}`;
};

export const getAdditionalApplicantDisplayNumber = (
  applicants: CreateMortgageApplicationFormApplicant[],
  idx: number,
) => applicants.slice(1, idx + 1).length;

export const getAdditionalApplicantCount = (
  applicants: readonly CreateMortgageApplicationFormApplicant[],
) => Math.max(0, applicants.length - 1);

export const canAddAdditionalApplicant = (
  applicants: readonly CreateMortgageApplicationFormApplicant[],
) => getAdditionalApplicantCount(applicants) < MAX_ADDITIONAL_APPLICANTS;
