import type { Earning, EarningType, EligibilityChecks } from "@/types";
import { formatMoneyAmount } from "@/utils";

import { resolveEmailTemplateCurrency } from "../utils/resolveEmailTemplateCurrency";

const CASE_NOTE_EARNING_TYPES = [
  "EDUCATION_ALLOWANCE",
  "AIRFARE_ALLOWANCE",
  "HOUSING_ALLOWANCE",
  "RENTAL",
  "INCENTIVE",
  "FLYING_ALLOWANCE",
] as const satisfies readonly EarningType[];

type CaseNoteEarningType = (typeof CASE_NOTE_EARNING_TYPES)[number];

const isCaseNoteEarningType = (earningType: EarningType): earningType is CaseNoteEarningType =>
  (CASE_NOTE_EARNING_TYPES as readonly EarningType[]).includes(earningType);

const sumEligibleMonthlyAmount = (earnings: Earning[]): number =>
  earnings.reduce((total, earning) => {
    const value = earning.eligibleAmount.value;
    return Number.isFinite(value) ? total + value : total;
  }, 0);

const collectEarningsByType = (
  eligibilityChecks: EligibilityChecks | undefined,
): Map<CaseNoteEarningType, Earning[]> => {
  const byType = new Map<CaseNoteEarningType, Earning[]>();

  for (const applicant of eligibilityChecks?.applicants ?? []) {
    for (const earning of applicant.earnings) {
      if (!isCaseNoteEarningType(earning.earningType)) continue;

      const existing = byType.get(earning.earningType) ?? [];
      existing.push(earning);
      byType.set(earning.earningType, existing);
    }
  }

  return byType;
};

const formatCaseNoteLine = (
  earningType: CaseNoteEarningType,
  earnings: Earning[],
  currency: string,
): string => {
  const amount = formatMoneyAmount(sumEligibleMonthlyAmount(earnings), currency);

  switch (earningType) {
    case "EDUCATION_ALLOWANCE":
      return `- Education allowance - ${amount} education allowance considered for the case`;
    case "AIRFARE_ALLOWANCE":
      return `- Airfare allowance - ${amount} airfare allowance considered for the case`;
    case "HOUSING_ALLOWANCE":
      return `- Housing allowance - ${amount} housing advance received`;
    case "RENTAL":
      return `- Rental - ${amount} rental income considered`;
    case "INCENTIVE":
      return `- Incentives - ${amount} incentive considered for the case`;
    case "FLYING_ALLOWANCE":
      return `- Flying allowance - ${amount} flying allowance considered for the case`;
  }
};

export const formatCaseNoteLines = (
  eligibilityChecks: EligibilityChecks | undefined,
  bankCurrency: string | null,
): string[] => {
  const currency = resolveEmailTemplateCurrency(bankCurrency, eligibilityChecks);
  if (!currency) return [];

  const earningsByType = collectEarningsByType(eligibilityChecks);

  return CASE_NOTE_EARNING_TYPES.flatMap((earningType) => {
    const earnings = earningsByType.get(earningType);
    if (!earnings?.length) return [];

    if (sumEligibleMonthlyAmount(earnings) === 0) return [];

    return [formatCaseNoteLine(earningType, earnings, currency)];
  });
};
