import { toMajorUnits } from "@/utils/minorUnits";
import { Document, GetBankApplicationResponse } from "@/api";
import {
  BankApplication,
  Applicant,
  ApplicantDocumentGroup,
  ApplicantDocumentRow,
  DocumentChecklistRow,
} from "@/types";

export const toBankApplication = (response: GetBankApplicationResponse): BankApplication => {
  const { checklist, amount, status: _status, ...rest } = response;
  const { applicantDocuments, unclassifiedFiles } = checklist;

  return {
    ...rest,
    amount: amount != null ? toMajorUnits(amount) : null,
    applicants: applicantDocuments.map(({ applicant }) => applicant),
    checklist: {
      stats: applicantDocuments.reduce(
        (acc, { stats }) => ({
          total: acc.total + stats.total,
          received: acc.received + stats.received,
        }),
        { total: 0, received: 0 },
      ),
      applicantDocuments: applicantDocuments.flatMap(({ applicant, documents }) =>
        documents.flatMap((document) => toApplicantDocumentGroups(document, applicant)),
      ),
      caseDocuments: checklist.caseDocuments.flatMap((document) => toCaseDocumentRows(document)),
      unclassifiedFiles,
    },
  };
};

const toApplicantDocumentGroups = (
  document: Document,
  applicant: Applicant,
): ApplicantDocumentGroup[] => {
  const rows = document.documents.flatMap((child) => toApplicantDocumentRows(child, applicant));

  return (document.matchedFiles.length ? document.matchedFiles : [null]).map((file, idx) => ({
    type: document.type ?? "",
    applicant,
    isRequired: document.isRequired,
    matchedFile: file,
    processingStatus: document.processingStatus,
    groupKey: document.groupKey,
    documents: idx === 0 ? rows : [],
  }));
};

const toApplicantDocumentRows = (child: Document, applicant: Applicant): ApplicantDocumentRow[] =>
  (child.matchedFiles.length ? child.matchedFiles : [null]).map((file) => ({
    type: child.type ?? "",
    applicant,
    isRequired: child.isRequired,
    matchedFile: file,
  }));

/** Case documents (bank forms) are never merge targets, so they never have nested children. */
const toCaseDocumentRows = (document: Document): DocumentChecklistRow[] =>
  (document.matchedFiles.length ? document.matchedFiles : [null]).map((file) => ({
    type: document.type ?? "",
    isRequired: document.isRequired,
    matchedFile: file,
  }));
