import { type FC } from "react";

import {
  usePatchEligibilityCheckEarning,
  useDropEligibilityCheckEarningAmountOverride,
} from "@/api";
import type { PatchEligibilityCheckEarningPayload } from "@/api";
import type {
  DocumentField,
  EarningType,
  EligibilityFrequency,
  EligibilityLineSource,
  Money,
} from "@/types";

import { CalculationRow } from "./CalculationRow";
import { TypeSelect } from "./TypeSelect";
import {
  EARNING_TYPE_LABELS,
  getEarningAllocationTooltipText,
  isEarningAllocationEditable,
} from "../../constants";
import { useRemoveEligibilityLine } from "../../context/RemoveEligibilityLineContext";
import { useEligibilityChecksRoute } from "../../hooks/useEligibilityChecksRoute";
import { resolveTypeOptions } from "../../utils";

type Props = {
  earningId: string;
  description: string;
  documentType: string;
  earningType: EarningType;
  frequency: EligibilityFrequency | null;
  allocation: number;
  amount: Money;
  originalAmount?: Money;
  fxRate: string | null;
  amountOverride: string | null;
  eligibleAmount: Money;
  numOfPayslips: number | null;
  maxPeriods: number | null;
  documentFields: DocumentField[];
  statusLabel?: string;
  statusTooltipText?: string;
  referenceOnly?: boolean;
  source: EligibilityLineSource;
  typeOptions: EarningType[];
};

export const EarningCalculationRow: FC<Props> = ({
  earningId,
  description,
  documentType,
  earningType,
  frequency,
  allocation,
  amount,
  originalAmount,
  fxRate,
  amountOverride,
  eligibleAmount,
  numOfPayslips,
  maxPeriods,
  documentFields,
  statusLabel,
  statusTooltipText,
  referenceOnly = false,
  source,
  typeOptions,
}) => {
  const { bankApplication } = useEligibilityChecksRoute();
  const { beginRemove } = useRemoveEligibilityLine();
  const { mutateAsync, isPending, variables } = usePatchEligibilityCheckEarning();
  const {
    mutateAsync: dropAmountOverride,
    isPending: isDroppingOverride,
    variables: dropVariables,
  } = useDropEligibilityCheckEarningAmountOverride();
  const isSaving =
    (isPending && variables?.earningId === earningId) ||
    (isDroppingOverride && dropVariables?.earningId === earningId);
  const isManual = source === "MANUAL";
  const isOther = earningType === "OTHER" && !referenceOnly;
  const hasAmountOverride = amountOverride != null;

  if (!bankApplication) return null;

  const patch = async (payload: PatchEligibilityCheckEarningPayload) => {
    await mutateAsync({
      bankApplicationId: bankApplication.id,
      earningId,
      payload,
    });
  };

  const clearAmountOverride = async () => {
    await dropAmountOverride({ bankApplicationId: bankApplication.id, earningId });
  };

  return (
    <CalculationRow
      description={description}
      descriptionEditable={isManual}
      onDescriptionChange={
        isManual ? (nextDescription) => patch({ description: nextDescription }) : undefined
      }
      documentType={documentType}
      source={source}
      documentFields={documentFields}
      emptyDocumentFieldsMessage="No transaction details available for this income."
      statusLabel={statusLabel}
      statusTooltipText={statusTooltipText}
      disabled={isSaving}
      referenceOnly={referenceOnly}
      typeSelect={
        <TypeSelect
          value={earningType}
          options={resolveTypeOptions(earningType, typeOptions)}
          labels={EARNING_TYPE_LABELS}
          disabled={isSaving || isManual}
          onValueChange={(value) => {
            if (value !== earningType) void patch({ earningType: value as EarningType });
          }}
        />
      }
      frequency={isManual ? "MONTHLY" : hasAmountOverride ? null : frequency}
      frequencyEditable={!isManual && !hasAmountOverride && earningType !== "FIXED_ITEM"}
      onFrequencyChange={(value) => {
        if (frequency !== null && value !== frequency) void patch({ frequency: value });
      }}
      allocation={hasAmountOverride ? 100 : allocation}
      allocationEditable={isEarningAllocationEditable(
        earningType,
        hasAmountOverride,
        frequency,
        source,
      )}
      allocationTooltipText={getEarningAllocationTooltipText(
        earningType,
        hasAmountOverride,
        frequency,
        source,
      )}
      onAllocationChange={(value) => patch({ allocation: value })}
      amount={amountOverride ?? String(amount.value)}
      amountEditable={isOther}
      onAmountChange={isOther ? (amount) => patch({ amount }) : undefined}
      amountOverridden={hasAmountOverride}
      onClearAmountOverride={hasAmountOverride ? clearAmountOverride : undefined}
      eligibleAmount={eligibleAmount}
      originalCurrency={originalAmount?.currency ?? null}
      amountCurrency={amount.currency}
      fxRate={fxRate}
      numOfPayslips={numOfPayslips}
      maxPeriods={maxPeriods}
      earningType={earningType}
      onRemove={
        source === "MANUAL"
          ? () => beginRemove({ kind: "earning", lineId: earningId, description })
          : undefined
      }
    />
  );
};
