import type { Bank } from "@/api";
import { INCOME_VERIFICATION_TYPE_CREATE_FORM_OPTIONS } from "@/constants";

import { getSupportedDocLevelsForBankId } from "./getSupportedDocLevelsForBankId";

export const getIncomeVerificationTypeOptionsForBankId = (bankId: string, banks: Bank[]) => {
  const supportedDocLevels = getSupportedDocLevelsForBankId(bankId, banks);
  return INCOME_VERIFICATION_TYPE_CREATE_FORM_OPTIONS.filter((option) =>
    supportedDocLevels.includes(option.value),
  );
};
