import {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
  type ComponentRef,
  type FC,
} from "react";
import { Document, Page } from "react-pdf";

import { Modal } from "@/components";
import { cn } from "@huspy/shared-ui";
import { FileItemWithDocumentId, type Applicant } from "@/types";
import {
  useDocumentPreviewUrl,
  useDocumentTypeCodesForBankApplication,
  useSplitDocument,
} from "@/api";

import {
  getAssignToSelectOptions,
  getDocumentTypeSelectOptions,
  isApplicantLevelDocumentType,
} from "@/routes/BankApplication/utils";
import { buildManualDocumentSplitPayload, validateSplitConfiguration } from "./utils";
import { CenteredStatus, SplitPageList, SplitModalFooter } from "./components";
import { PdfPreviewZoomControls } from "@/routes/BankApplication/components/ChecklistWorkspace/components/PdfPreviewZoomControls";
import {
  DEFAULT_ZOOM_LEVEL,
  INITIAL_FOCUSED_PAGE,
  MAX_ZOOM_LEVEL,
  MIN_ZOOM_LEVEL,
  SPLIT_PREVIEW_BASE_WIDTH,
  ZOOM_STEP,
} from "@/routes/BankApplication/components/ChecklistWorkspace/components/pdfPreviewConstants";
import { useKeyboardNavigation } from "@/routes/BankApplication/components/ChecklistWorkspace/hooks/useKeyboardNavigation";
import { useSplitState } from "./hooks/useSplitState";
import { useSplitDocumentTypes } from "./hooks/useSplitDocumentTypes";
import { useSplitDocumentAssignees } from "./hooks/useSplitDocumentAssignees";
import { MODAL_CLASS, MODAL_TITLE } from "./constants";

type Props = {
  isOpen: boolean;
  onOpenChange: (open: boolean) => void;
  bankApplicationId: string;
  applicants: Applicant[];
  file: FileItemWithDocumentId | null;
  initialDocumentType?: string;
  initialAssignTo?: string;
};

export const SplitDocumentModal: FC<Props> = ({
  isOpen,
  onOpenChange,
  bankApplicationId,
  applicants,
  file,
  initialDocumentType,
  initialAssignTo,
}) => {
  const [pageCount, setPageCount] = useState(0);
  const [isPdfLoading, setIsPdfLoading] = useState(false);
  const [isPdfError, setIsPdfError] = useState(false);
  const [focusedPage, setFocusedPage] = useState(INITIAL_FOCUSED_PAGE);
  const [zoomLevel, setZoomLevel] = useState(DEFAULT_ZOOM_LEVEL);
  const documentRef = useRef<ComponentRef<typeof Document>>(null);
  const {
    cuts,
    segments,
    removedStarts,
    addCut,
    removeCut,
    toggleSegmentRemoved,
    reset: resetSplitState,
  } = useSplitState(pageCount);
  const splitDocument = useSplitDocument();
  const previewId = file?.docServiceDocumentId ?? file?.id;
  const isFileOpen = isOpen && !!file;
  const {
    data: previewUrl,
    isLoading: isPreviewLoading,
    isError: isPreviewError,
    error: previewError,
  } = useDocumentPreviewUrl(previewId, isFileOpen);
  const { data: documentTypeCodes = [] } = useDocumentTypeCodesForBankApplication(
    isFileOpen ? bankApplicationId : undefined,
  );

  const segmentStarts = useMemo(() => segments.map((segment) => segment.start), [segments]);
  const {
    typeFor,
    setTypeForSegment,
    reset: resetDocumentTypes,
  } = useSplitDocumentTypes({
    segmentStarts,
    initialDocumentType,
  });
  const soleApplicantId = applicants.length === 1 ? applicants[0]?.id : undefined;
  const {
    assigneeFor,
    setAssigneeForSegment,
    reset: resetAssignees,
  } = useSplitDocumentAssignees({
    segmentStarts,
    initialAssignTo,
  });

  const documentTypeOptions = useMemo(
    () => getDocumentTypeSelectOptions(documentTypeCodes),
    [documentTypeCodes],
  );
  const assignToOptions = useMemo(() => getAssignToSelectOptions(applicants), [applicants]);
  const pageNumbers = useMemo(
    () => Array.from({ length: pageCount }, (_, index) => index + 1),
    [pageCount],
  );
  const previewWidth = Math.round(SPLIT_PREVIEW_BASE_WIDTH * zoomLevel);
  const isZoomedIn = zoomLevel > DEFAULT_ZOOM_LEVEL;
  const isPdfReady = !isPdfLoading && !isPdfError && pageCount > 0;

  const scrollToPage = useCallback((pageNumber: number) => {
    documentRef.current?.viewer.current?.scrollPageIntoView({ pageNumber });
  }, []);

  const focusedPageRef = useRef(focusedPage);

  useEffect(() => {
    focusedPageRef.current = focusedPage;
  }, [focusedPage]);

  const handleZoomIn = useCallback(() => {
    setZoomLevel((currentZoom) => Math.min(currentZoom + ZOOM_STEP, MAX_ZOOM_LEVEL));
  }, []);

  const handleZoomOut = useCallback(() => {
    setZoomLevel((currentZoom) => Math.max(currentZoom - ZOOM_STEP, MIN_ZOOM_LEVEL));
  }, []);

  const handleZoomReset = useCallback(() => {
    setZoomLevel(DEFAULT_ZOOM_LEVEL);
  }, []);

  useEffect(() => {
    if (pageCount === 0) return;

    requestAnimationFrame(() => {
      scrollToPage(focusedPageRef.current);
    });
  }, [zoomLevel, pageCount, scrollToPage]);

  const handleFocusPage = useCallback(
    (pageNumber: number) => {
      setFocusedPage(pageNumber);
      scrollToPage(pageNumber);
    },
    [scrollToPage],
  );

  const isPreviewReady = !isPreviewLoading && !isPreviewError;
  const previewErrorMessage =
    previewError instanceof Error ? previewError.message : "Could not load document preview.";

  const { canConfirm, footerMessage } = validateSplitConfiguration({
    isPdfReady,
    cutCount: cuts.size,
    segments,
    typeFor,
    assigneeFor,
    applicants,
    documentTypeCodes,
    removedStarts,
  });

  useKeyboardNavigation({
    isEnabled: isPreviewReady && pageCount > 0,
    currentPage: focusedPage,
    maxPage: pageCount,
    onNavigate: handleFocusPage,
  });

  const handleOpenChange = (open: boolean) => {
    if (!open) {
      resetSplitState();
      resetDocumentTypes();
      resetAssignees();
      setFocusedPage(INITIAL_FOCUSED_PAGE);
      setZoomLevel(DEFAULT_ZOOM_LEVEL);
      setPageCount(0);
      setIsPdfLoading(false);
      setIsPdfError(false);
      splitDocument.reset();
    }
    onOpenChange(open);
  };

  const handleTypeChange = (startPage: number, documentType: string) => {
    setTypeForSegment(startPage, documentType);
    if (!isApplicantLevelDocumentType(documentType, documentTypeCodes)) {
      setAssigneeForSegment(startPage, "");
    } else if (soleApplicantId) {
      setAssigneeForSegment(startPage, soleApplicantId);
    }
  };

  const handleConfirm = () => {
    if (!canConfirm || !file) return;

    const payload = buildManualDocumentSplitPayload({
      segments,
      typeFor,
      assigneeFor,
      applicants,
      documentTypeCodes,
      removedStarts,
    });

    splitDocument.mutate(
      { documentId: file.documentId, payload, bankApplicationId },
      {
        onSuccess: () => {
          handleOpenChange(false);
        },
      },
    );
  };

  const showValidationErrors = cuts.size >= 1;
  return (
    <Modal
      isOpen={isOpen}
      onOpenChange={handleOpenChange}
      title={MODAL_TITLE}
      description={file?.fileName || undefined}
      className={MODAL_CLASS}
    >
      <div className="flex min-h-0 flex-1 flex-col overflow-hidden">
        {isPreviewLoading && <CenteredStatus label="Loading document…" />}

        {isPreviewError && <CenteredStatus label={previewErrorMessage} isError />}

        {isPreviewReady && (
          <Document
            ref={documentRef}
            file={previewUrl}
            className="flex min-h-0 flex-1 flex-col overflow-hidden"
            loading={<CenteredStatus label="Reading pages…" />}
            onLoadStart={() => {
              setIsPdfLoading(true);
              setIsPdfError(false);
            }}
            onLoadSuccess={({ numPages }) => {
              setPageCount(numPages);
              setIsPdfLoading(false);
            }}
            onLoadError={() => {
              setIsPdfLoading(false);
              setIsPdfError(true);
            }}
          >
            <div className="grid min-h-0 flex-1 grid-cols-1 gap-3 overflow-hidden md:grid-cols-2 px-6">
              <div className="relative flex min-h-0 flex-col overflow-hidden">
                {isPdfReady && (
                  <PdfPreviewZoomControls
                    className="absolute bottom-2 left-2 z-10"
                    canZoomIn={zoomLevel < MAX_ZOOM_LEVEL}
                    canZoomOut={zoomLevel > MIN_ZOOM_LEVEL}
                    onZoomIn={handleZoomIn}
                    onZoomOut={handleZoomOut}
                    onReset={handleZoomReset}
                  />
                )}

                <div
                  className={cn(
                    "flex min-h-0 flex-1 flex-col gap-4 py-4",
                    isZoomedIn ? "overflow-auto" : "overflow-y-auto overflow-x-hidden",
                  )}
                >
                  {pageNumbers.map((pageNumber) => (
                    <Page
                      key={pageNumber}
                      pageNumber={pageNumber}
                      width={previewWidth}
                      className="mx-auto scroll-mt-4"
                      loading={null}
                      renderTextLayer={false}
                      renderAnnotationLayer={false}
                    />
                  ))}
                </div>
              </div>

              <div className="flex min-h-0 flex-col overflow-y-auto py-4">
                <SplitPageList
                  pageCount={pageCount}
                  isPdfLoading={isPdfLoading}
                  isPdfError={isPdfError}
                  segments={segments}
                  focusedPage={focusedPage}
                  typeOptions={documentTypeOptions}
                  assignToOptions={assignToOptions}
                  documentTypeCodes={documentTypeCodes}
                  applicantCount={applicants.length}
                  typeFor={typeFor}
                  assigneeFor={assigneeFor}
                  removedStarts={removedStarts}
                  onTypeChange={handleTypeChange}
                  onAssigneeChange={setAssigneeForSegment}
                  onFocusPage={handleFocusPage}
                  onAddCut={addCut}
                  onRemoveCut={removeCut}
                  onToggleRemoved={toggleSegmentRemoved}
                  showValidationErrors={showValidationErrors}
                />
              </div>
            </div>
          </Document>
        )}

        <SplitModalFooter
          statusMessage={isPreviewReady ? footerMessage : undefined}
          errorMessage={
            splitDocument.isError
              ? splitDocument.error instanceof Error
                ? splitDocument.error.message
                : "Failed to split document. Please try again."
              : undefined
          }
          onCancel={() => handleOpenChange(false)}
          showConfirm={isPreviewReady}
          canConfirm={canConfirm}
          isSubmitting={splitDocument.isPending}
          onConfirm={handleConfirm}
        />
      </div>
    </Modal>
  );
};
