import { generateFabEmailDraft } from "./generateFabEmailDraft";
import {
  generateStandardEmailDraft,
  type GenerateStandardEmailDraftInput,
} from "./generateStandardEmailDraft";
import type { EmailTemplateDraft } from "./types";

export const generateEmailDraft = (input: GenerateStandardEmailDraftInput): EmailTemplateDraft =>
  input.bankApplication.bank.name === "FAB"
    ? generateFabEmailDraft(input)
    : generateStandardEmailDraft(input);
