import type { FC } from "react";

import { CircleCheck, CircleX } from "@huspy/shared-icons";
import { Banner, type BannerVariant, cn } from "@huspy/shared-ui";

import type { AffordabilityVerdict } from "../../utils";

const BANNER_VARIANT_BY_VERDICT: Record<AffordabilityVerdict["variant"], BannerVariant> = {
  success: "success",
  error: "alert",
};

const BANNER_ICON_BY_VERDICT: Record<
  AffordabilityVerdict["variant"],
  typeof CircleCheck | typeof CircleX
> = {
  success: CircleCheck,
  error: CircleX,
};

type Props = {
  verdict: AffordabilityVerdict;
};

export const AffordabilitySummaryBanner: FC<Props> = ({ verdict }) => {
  const Icon = BANNER_ICON_BY_VERDICT[verdict.variant];

  return (
    <Banner variant={BANNER_VARIANT_BY_VERDICT[verdict.variant]} icon={<Icon aria-hidden />}>
      <p className={cn("text-sm font-semibold leading-snug", verdict.description && "mb-0.5")}>
        {verdict.title}
      </p>
      {verdict.description && (
        <p className="text-[13px] font-medium leading-snug">{verdict.description}</p>
      )}
    </Banner>
  );
};
