import { FC } from "react";

import { Pencil, ScanText, Trash2, Upload } from "@huspy/shared-icons";

import type { DocumentChecklistRow } from "@/types";
import { getDocumentAssignment } from "@/routes/BankApplication/components/ChecklistWorkspace/components/EditDocumentModal/constants";
import { RowActionButton } from "@/routes/BankApplication/components/ChecklistWorkspace/components/RowActionButton";
import { useAddDocument } from "@/routes/BankApplication/components/ChecklistWorkspace/context/AddDocumentContext";
import { useEditDocument } from "@/routes/BankApplication/components/ChecklistWorkspace/context/EditDocumentContext";
import { useExtractedFields } from "@/routes/BankApplication/components/ChecklistWorkspace/context/ExtractedFieldsContext";
import { useRemoveFile } from "@/routes/BankApplication/components/ChecklistWorkspace/context/RemoveFileContext";
import { getDocumentActionAvailability } from "@/routes/BankApplication/components/ChecklistWorkspace/utils/getDocumentActionAvailability";
import { ignoreRowClickProps } from "@/routes/BankApplication/components/ChecklistWorkspace/utils/rowClick";

type Props = {
  data: DocumentChecklistRow;
};

export const DocumentRowActions: FC<Props> = ({ data }) => {
  const { beginAddDocument } = useAddDocument();
  const { beginEdit } = useEditDocument();
  const { beginRemove } = useRemoveFile();
  const { beginExtractedFields } = useExtractedFields();
  const { matchedFile } = data;
  const processingStatus = matchedFile?.processingStatus;
  // The edit icon opens the whole modal; granular field-level gating (e.g. the document-type
  // select during extraction) happens inside EditDocumentModal itself.
  const editAvailability = getDocumentActionAvailability("editAssigneeOrName", processingStatus);
  const removeAvailability = getDocumentActionAvailability("remove", processingStatus);
  const extractedFieldsAvailability = getDocumentActionAvailability(
    "extractedFields",
    processingStatus,
  );

  if (!matchedFile) {
    return (
      <div {...ignoreRowClickProps} className="flex items-center justify-end">
        <RowActionButton
          label="Upload document"
          icon={Upload}
          onClick={() => beginAddDocument(data.type || undefined)}
        />
      </div>
    );
  }

  return (
    <div {...ignoreRowClickProps} className="flex items-center justify-end gap-0.5">
      <RowActionButton
        label="View extracted fields"
        icon={ScanText}
        disabled={extractedFieldsAvailability.disabled}
        disabledTooltip={
          extractedFieldsAvailability.disabled ? extractedFieldsAvailability.tooltip : undefined
        }
        onClick={() => beginExtractedFields({ file: matchedFile })}
      />

      <RowActionButton
        label="Edit document"
        icon={Pencil}
        disabled={editAvailability.disabled}
        disabledTooltip={editAvailability.disabled ? editAvailability.tooltip : undefined}
        onClick={() =>
          beginEdit({
            kind: "classified",
            document: { ...data, matchedFile },
            assignment: getDocumentAssignment(data),
          })
        }
      />

      <RowActionButton
        label="Remove file"
        icon={Trash2}
        variant="destructive"
        disabled={removeAvailability.disabled}
        disabledTooltip={removeAvailability.disabled ? removeAvailability.tooltip : undefined}
        onClick={() => beginRemove({ file: matchedFile })}
      />
    </div>
  );
};
