import type { FC, ReactNode } from "react";

import { UserAvatar } from "@huspy/shared-ui";
import { ArrowLeft } from "@huspy/shared-icons";
import { useLocation, useNavigate } from "@huspy/fe";

import { getReturnToPath } from "@/utils";
import type { BankApplication } from "@/types";

import { CaseSummaryCard } from "./CaseSummaryCard";
import { joinApplicantNames } from "./utils/joinApplicantNames";
import { HeaderActions } from "./HeaderActions";
import { getMainApplicant } from "../../utils";

type Props = {
  bankApplicationData: BankApplication;
  onAddDocuments: () => void;
  tabs?: ReactNode;
};

export const Header: FC<Props> = ({ bankApplicationData, onAddDocuments, tabs }) => {
  const location = useLocation();
  const navigate = useNavigate();

  const mainApplicant = getMainApplicant(bankApplicationData.applicants);
  return (
    <>
      <button
        type="button"
        onClick={() => navigate(getReturnToPath(location))}
        className="-ml-2 flex h-8 w-fit cursor-pointer items-center gap-1.5 rounded-full px-3 text-[13px] text-foreground hover:bg-grey-60"
      >
        <ArrowLeft className="size-4 text-muted-foreground" aria-hidden />
        Ops Queue
      </button>

      <div className="sticky top-0 z-20 -mx-6 flex flex-col gap-3 bg-grey-45 px-6 pt-3">
        <div className="flex min-w-0 items-center gap-3">
          <UserAvatar
            name={mainApplicant?.fullName ?? ""}
            className="size-10"
            fallbackClassName="bg-input text-[13px] font-semibold text-grey-700"
          />
          <h1 className="truncate text-[22px] font-semibold text-foreground">
            {joinApplicantNames(bankApplicationData.applicants)}
          </h1>
        </div>

        <CaseSummaryCard bankApplication={bankApplicationData} />

        <div className="flex flex-wrap items-center gap-3 border-b border-border pb-3">
          {tabs}

          <div className="ml-auto flex items-center gap-3">
            <HeaderActions
              bankApplicationId={bankApplicationData.id}
              onAddDocuments={onAddDocuments}
            />
          </div>
        </div>
      </div>
    </>
  );
};
