import { Button, cn } from "@huspy/shared-ui";

import { formatShortDateTime } from "@/utils";

import { ROW_HOVER, STATUS_ICON } from "./constants";
import type { CheckVisualState, RuleCheckWaiver } from "./types";

type Props = {
  title: string;
  /** Rendered as a pill next to the title; omit when there is nothing to disambiguate. */
  applicantName?: string;
  visualState: CheckVisualState;
  comparisonText: string | null;
  waiver: RuleCheckWaiver | null;
  isWaivable: boolean;
  onWaive: () => void;
  onUnwaive: () => void;
  isUnwaivePending: boolean;
};

/** Presentational row shared by Document Validation and Bank Policy checks; each domain supplies its own comparison text. */
export function CheckRowShell({
  title,
  applicantName,
  visualState,
  comparisonText,
  waiver,
  isWaivable,
  onWaive,
  onUnwaive,
  isUnwaivePending,
}: Props) {
  const { Icon, className: iconClassName } = STATUS_ICON[visualState];
  const waiveSummary = waiver
    ? waiver.reason
      ? `Waive reason: ${waiver.reason} (waived at ${formatShortDateTime(waiver.waivedAt)})`
      : `Waived at ${formatShortDateTime(waiver.waivedAt)}`
    : null;

  return (
    <div className={cn("flex items-center gap-3 rounded-lg px-2 py-2", ROW_HOVER[visualState])}>
      <Icon className={cn("size-4 shrink-0", iconClassName)} aria-hidden />

      <div className="min-w-0 flex-1">
        <div className="flex flex-wrap items-center gap-1.5">
          <span
            className={cn(
              "text-[13px]",
              visualState === "waived" ? "text-muted-foreground line-through" : "text-foreground",
            )}
          >
            {title}
          </span>
          {applicantName && (
            <span className="rounded-full bg-muted ml-1 px-2 py-0.5 text-[10px] text-foreground-secondary">
              {applicantName}
            </span>
          )}
        </div>

        {comparisonText && visualState !== "waived" && (
          <p className="mt-0.5 truncate text-xs text-muted-foreground" title={comparisonText}>
            {comparisonText}
          </p>
        )}

        {waiveSummary && (
          <p className="mt-0.5 truncate text-xs text-muted-foreground" title={waiveSummary}>
            {waiveSummary}
          </p>
        )}
      </div>

      {isWaivable &&
        (waiver ? (
          <Button
            type="button"
            variant="ghost"
            size="xs"
            onClick={onUnwaive}
            disabled={isUnwaivePending}
            className="shrink-0 text-muted-foreground hover:bg-muted hover:text-foreground"
          >
            Unwaive
          </Button>
        ) : (
          <Button
            type="button"
            variant="ghost"
            size="xs"
            onClick={onWaive}
            className="shrink-0 text-muted-foreground hover:bg-muted hover:text-foreground"
          >
            Waive
          </Button>
        ))}
    </div>
  );
}
