import type {
  DocumentValidationCheckWaiver as DocumentValidationCheckWaiverApi,
  DocumentValidationComparison as DocumentValidationComparisonApi,
  DocumentValidationOperand as DocumentValidationOperandApi,
  DocumentValidationResponse,
} from "@/api/types";
import type {
  DocumentValidationCheckWaiver,
  DocumentValidationChecks,
  DocumentValidationComparison,
  DocumentValidationOperand,
} from "@/types";

export const toDocumentValidationChecks = (
  dto: DocumentValidationResponse,
): DocumentValidationChecks => ({
  calculatedAt: dto.calculatedAt ?? null,
  checks: dto.data.map((check) => ({
    id: check.id,
    ruleCode: check.ruleCode,
    title: check.title,
    failTitle: check.failTitle ?? check.title,
    category: check.category,
    severity: check.severity,
    status: check.status,
    ordinal: check.ordinal ?? null,
    applicantId: check.applicantId ?? null,
    comparison: toComparison(check.comparison),
    waiver: toWaiver(check.waiver),
  })),
  skipped: (dto.skipped ?? []).map((skipped) => ({
    ruleCode: skipped.ruleCode,
    title: skipped.title,
    ordinal: skipped.ordinal ?? null,
    applicantId: skipped.applicantId ?? null,
    reason: skipped.reason,
  })),
});

const toComparison = (
  comparison: DocumentValidationComparisonApi | null | undefined,
): DocumentValidationComparison | null =>
  comparison
    ? {
        subject: toOperand(comparison.subject),
        target: toOperand(comparison.target),
      }
    : null;

const toOperand = (
  operand: DocumentValidationOperandApi | null | undefined,
): DocumentValidationOperand | null =>
  operand
    ? {
        documentType: operand.documentType,
        documentId: operand.documentId ?? null,
        field: operand.field ?? null,
        value: operand.value ?? null,
      }
    : null;

const toWaiver = (
  waiver: DocumentValidationCheckWaiverApi | null | undefined,
): DocumentValidationCheckWaiver | null =>
  waiver
    ? {
        id: waiver.id,
        reason: waiver.reason ?? "",
        waivedBy: waiver.waivedById,
        waivedAt: waiver.waivedAt,
      }
    : null;
