import type { ExtractedFieldGroup, ExtractedFieldGroupRow } from "@/types";

import { getCellValue } from "./getCellValue";
import { getParentGroupName } from "./getParentGroupName";

export type ChildRows = {
  group: ExtractedFieldGroup;
  rows: ExtractedFieldGroupRow[];
};

export type ParentRow = {
  row: ExtractedFieldGroupRow;
  /** One entry per child group, empty rows included, so every card lists the same sections. */
  childRows: ChildRows[];
};

export type FlatGroup = {
  kind: "flat";
  group: ExtractedFieldGroup;
};

export type NestedGroup = {
  kind: "nested";
  group: ExtractedFieldGroup;
  parentRows: ParentRow[];
  /** Child rows pointing at a parent index that does not exist. */
  orphanRows: ChildRows[];
};

export type GroupSection = FlatGroup | NestedGroup;

type ParentReference = {
  parentGroupName: string;
  joinFieldKey: string;
};

type ChildGroup = ParentReference & {
  group: ExtractedFieldGroup;
};

/** A group is a child when one of its columns names another group in the payload. */
const findParentReference = (
  group: ExtractedFieldGroup,
  groupNames: Set<string>,
): ParentReference | null => {
  for (const column of group.template) {
    const parentGroupName = getParentGroupName(column.fieldKey);
    if (parentGroupName && parentGroupName !== group.name && groupNames.has(parentGroupName)) {
      return { parentGroupName, joinFieldKey: column.fieldKey };
    }
  }

  return null;
};

/** Child rows carry their parent's row index as the value of the join column. */
const getParentRowIndex = (row: ExtractedFieldGroupRow, joinFieldKey: string): number | null => {
  const value = getCellValue(row, joinFieldKey)?.trim();
  if (!value) return null;

  const parentRowIndex = Number.parseInt(value, 10);
  return Number.isNaN(parentRowIndex) ? null : parentRowIndex;
};

/**
 * A parent row is identified by its own `index` column, not by its position in the array: the
 * backend numbers payslips and statements from 1, so joining on position attaches every child row
 * to the wrong parent and orphans the last one.
 */
const getParentRowKey = (row: ExtractedFieldGroupRow): number => {
  const value = getCellValue(row, "index")?.trim();
  if (!value) return row.index;

  const parentRowKey = Number.parseInt(value, 10);
  return Number.isNaN(parentRowKey) ? row.index : parentRowKey;
};

const partitionByParentRow = (child: ChildGroup, parentRowIndexes: Set<number>) => {
  const rowsByParentIndex = new Map<number, ExtractedFieldGroupRow[]>();
  const orphans: ExtractedFieldGroupRow[] = [];

  for (const row of child.group.items) {
    const parentRowIndex = getParentRowIndex(row, child.joinFieldKey);
    if (parentRowIndex === null || !parentRowIndexes.has(parentRowIndex)) {
      orphans.push(row);
      continue;
    }

    const bucket = rowsByParentIndex.get(parentRowIndex) ?? [];
    bucket.push(row);
    rowsByParentIndex.set(parentRowIndex, bucket);
  }

  return { group: child.group, rowsByParentIndex, orphans };
};

const buildNestedGroup = (
  parentGroup: ExtractedFieldGroup,
  children: ChildGroup[],
): NestedGroup => {
  const parentRowIndexes = new Set(parentGroup.items.map(getParentRowKey));
  const partitions = children.map((child) => partitionByParentRow(child, parentRowIndexes));

  return {
    kind: "nested",
    group: parentGroup,
    parentRows: parentGroup.items.map((parentRow) => ({
      row: parentRow,
      childRows: partitions.map((partition) => ({
        group: partition.group,
        rows: partition.rowsByParentIndex.get(getParentRowKey(parentRow)) ?? [],
      })),
    })),
    orphanRows: partitions
      .filter((partition) => partition.orphans.length > 0)
      .map((partition) => ({ group: partition.group, rows: partition.orphans })),
  };
};

/**
 * Derives the parent/child layout from the payload alone: a group is a child when one of its
 * columns names another group, and its rows nest under the parent row with the matching index.
 */
export const buildGroupSections = (groups: ExtractedFieldGroup[]): GroupSection[] => {
  const groupNames = new Set(groups.map((group) => group.name));
  const parentGroups: ExtractedFieldGroup[] = []; // technically not necessarily parent groups. topLevelGroups is a more suitable name
  const childGroups: ChildGroup[] = [];

  for (const group of groups) {
    const parentReference = findParentReference(group, groupNames);
    if (parentReference) {
      childGroups.push({ group, ...parentReference });
    } else {
      parentGroups.push(group);
    }
  }

  return parentGroups.map((parentGroup) => {
    const children = childGroups.filter((child) => child.parentGroupName === parentGroup.name);
    if (!children.length) return { kind: "flat", group: parentGroup };
    return buildNestedGroup(parentGroup, children);
  });
};
