import type { BankApplicationRow } from "@/types";

/**
 * The amount, creation date and creator are the same across a case's bank
 * applications in practice; the oldest one is the case's own creation.
 */
export const getCaseSummaryValues = (bankApplications: BankApplicationRow[]) => {
  const oldest = bankApplications.reduce((earliest, row) =>
    new Date(row.createdAt) < new Date(earliest.createdAt) ? row : earliest,
  );

  return {
    loanAmount: oldest.amount,
    loanCurrency: oldest.currency,
    createdAt: oldest.createdAt,
    creatorName: oldest.creatorName,
  };
};
