import type { FC, KeyboardEvent } from "react";
import { Thumbnail } from "react-pdf";

import { cn } from "@huspy/shared-ui";

const THUMBNAIL_WIDTH = 64; // matches w-16

type Props = {
  page: number;
  isFocused: boolean;
  onFocus: (page: number) => void;
};

export const SplitPageRow: FC<Props> = ({ page, isFocused, onFocus }) => {
  const handleKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      onFocus(page);
    }
  };

  return (
    <div
      role="button"
      tabIndex={0}
      onClick={() => onFocus(page)}
      onKeyDown={handleKeyDown}
      className={cn(
        "flex w-full cursor-pointer items-center gap-3 rounded-md p-1.5 text-left",
        isFocused ? "bg-primary/10" : "hover:bg-muted/60",
      )}
    >
      <span
        className={cn(
          "pointer-events-none flex w-fit shrink-0 overflow-hidden rounded border bg-white p-px",
          isFocused ? "border-primary" : "border-border",
        )}
      >
        <Thumbnail
          pageNumber={page}
          width={THUMBNAIL_WIDTH}
          loading={null}
          className="block leading-none [&_canvas]:block"
        />
      </span>
      <span className="flex flex-col">
        <span
          className={cn(
            "text-xs",
            isFocused ? "font-medium text-foreground" : "text-muted-foreground",
          )}
        >
          Page {page}
        </span>
        {isFocused && <span className="text-[10px] text-primary">Viewing</span>}
      </span>
    </div>
  );
};
