import type { Applicant, DocumentChecklistRow } from "@/types";

export type DocumentAssignment = { scope: "case" } | { scope: "applicant"; applicantId: string };

export const getInitialAssignToApplicantId = (
  assignment: DocumentAssignment,
): string | undefined => (assignment.scope === "applicant" ? assignment.applicantId : undefined);

export const getDocumentAssignment = (
  document: DocumentChecklistRow & { applicant?: Applicant },
): DocumentAssignment => {
  if (document.applicant) {
    return { scope: "applicant", applicantId: document.applicant.id };
  }

  return { scope: "case" };
};
