import { toast } from "@huspy/shared-ui";

import type { Applicant, BankPolicyCheck } from "@/types";
import { useUndoBankPolicyCheckWaiver } from "@/api";

import { CheckRowShell, getCheckVisualState, isCheckWaivable } from "../RuleChecksCard";

import { formatCheckComparison, formatCheckTitle } from "./utils";

type Props = {
  check: BankPolicyCheck;
  applicants: Applicant[];
  bankApplicationId: string;
  onWaive: () => void;
};

export function BankPolicyCheckRow({ check, applicants, bankApplicationId, onWaive }: Props) {
  const undoWaiver = useUndoBankPolicyCheckWaiver();
  const applicant = applicants.find(({ id }) => id === check.applicantId);

  return (
    <CheckRowShell
      title={formatCheckTitle(check)}
      applicantName={applicants.length > 1 ? applicant?.fullName : undefined}
      visualState={getCheckVisualState(check)}
      comparisonText={formatCheckComparison(check)}
      waiver={check.waiver}
      isWaivable={isCheckWaivable(check)}
      onWaive={onWaive}
      onUnwaive={() =>
        undoWaiver.mutate(
          { bankApplicationId, checkId: check.id },
          { onError: () => toast.error("Failed to unwaive the check.") },
        )
      }
      isUnwaivePending={undoWaiver.isPending}
    />
  );
}
